class ToolTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)

    def tearDown(self):
        self.temp.cleanup()

    def test_write_then_read_file(self):
        result = execute_tool("write_file", {"path": "src/demo.txt", "content": "hello forge"}, str(self.root))
        self.assertIn("Wrote src/demo.txt", result)
        self.assertEqual(execute_tool("read_file", {"path": "src/demo.txt"}, str(self.root)), "hello forge")

    def test_list_directory(self):
        (self.root / "folder").mkdir()
        (self.root / "a.txt").write_text("a")
        result = execute_tool("list_directory", {"path": "."}, str(self.root))
        self.assertIn("[DIR] folder", result)
        self.assertIn("[FILE] a.txt", result)

    def test_path_escape_rejected(self):
        with self.assertRaises(ToolError):
            execute_tool("read_file", {"path": "../outside.txt"}, str(self.root))


class ValidationTests(unittest.TestCase):
    """F1: broken tool calls are refused before approval is ever asked."""

    def test_dot_path_rejected(self):
        self.assertIsNotNone(validate_tool_args("write_file", {"path": ".", "content": "x"}))

    def test_empty_path_rejected(self):
        self.assertIsNotNone(validate_tool_args("read_file", {"path": "  "}))

    def test_missing_content_rejected(self):
        self.assertIsNotNone(validate_tool_args("write_file", {"path": "a.txt"}))

    def test_empty_command_rejected(self):
        self.assertIsNotNone(validate_tool_args("run_command", {"command": " "}))

    def test_good_calls_pass(self):
        self.assertIsNone(validate_tool_args("write_file", {"path": "a/b.txt", "content": "x"}))
        self.assertIsNone(validate_tool_args("run_command", {"command": "ls"}))
        self.assertIsNone(validate_tool_args("list_directory", {"path": "."}))


class ReadFilePagingTests(unittest.TestCase):
    """Audit B18, leg 1: read_file pages long files by line window
    instead of pouring a whole file into the prompt. A file that
    fits the window reads byte-identical to the old whole-file
    read; a truncating window (or a start past line 1) earns a
    footer naming the total and the offset that continues it."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)

    def tearDown(self):
        self.temp.cleanup()

    def _write_lines(self, name, count):
        text = "".join(f"line {i}\n" for i in range(1, count + 1))
        (self.root / name).write_text(text, encoding="utf-8")
        return text

    def test_small_file_reads_byte_identically(self):
        text = self._write_lines("small.txt", 3)
        self.assertEqual(
            execute_tool("read_file", {"path": "small.txt"}, str(self.root)),
            text)

    def test_long_file_pages_with_footer(self):
        self._write_lines("big.txt", 5000)
        result = execute_tool("read_file", {"path": "big.txt"}, str(self.root))
        body, _, footer = result.partition("\n[read_file: ")
        lines = body.split("\n")
        self.assertEqual(len(lines), 2000)
        self.assertEqual(lines[0], "line 1")
        self.assertEqual(lines[-1], "line 2000")
        self.assertEqual(
            footer,
            "showing lines 1–2000 of 5000 "
            "— call read_file with offset=2001 to continue]")

    def test_offset_and_limit_read_a_later_window(self):
        self._write_lines("big.txt", 5000)
        result = execute_tool(
            "read_file",
            {"path": "big.txt", "offset": 2001, "limit": 1000},
            str(self.root))
        body, _, footer = result.partition("\n[read_file: ")
        lines = body.split("\n")
        self.assertEqual(len(lines), 1000)
        self.assertEqual(lines[0], "line 2001")
        self.assertEqual(lines[-1], "line 3000")
        self.assertEqual(
            footer,
            "showing lines 2001–3000 of 5000 "
            "— call read_file with offset=3001 to continue]")

    def test_offset_window_reaching_eof_still_footers(self):
        self._write_lines("big.txt", 5000)
        result = execute_tool(
            "read_file",
            {"path": "big.txt", "offset": 4999, "limit": 10},
            str(self.root))
        self.assertIn("line 4999", result)
        self.assertIn("line 5000", result)
        self.assertIn("[read_file: showing lines 4999–5000 of 5000",
                      result)

    def test_non_numeric_offset_is_a_validation_problem(self):
        self.assertIsNotNone(validate_tool_args(
            "read_file", {"path": "x.txt", "offset": "abc"}))
        self.assertIsNotNone(validate_tool_args(
            "read_file", {"path": "x.txt", "limit": "many"}))

    def test_numeric_string_offset_is_coerced(self):
        args = {"path": "x.txt", "offset": "2001"}
        self.assertIsNone(validate_tool_args("read_file", args))
        self.assertEqual(args["offset"], 2001)
        # Execution coerces too (direct callers skip validation).
        self._write_lines("big.txt", 5000)
        result = execute_tool(
            "read_file",
            {"path": "big.txt", "offset": "4001", "limit": 5},
            str(self.root))
        self.assertIn("line 4001", result)
        self.assertIn("showing lines 4001–4005 of 5000", result)


class StorageTests(unittest.TestCase):
    def test_conversation_round_trip(self):
        with tempfile.TemporaryDirectory() as tmp:
            store = ConversationStore(Path(tmp) / "history.sqlite3")
            messages = [{"role": "system", "content": "system"}, {"role": "user", "content": "hello"}, {"role": "assistant", "content": "world"}]
            cid = store.save(None, messages)
            self.assertEqual(store.load(cid), messages)
            self.assertEqual(store.recent()[0]["title"], "hello")

    def test_model_and_project_remembered(self):
        """F6: a conversation keeps the model + project it belongs to."""
        with tempfile.TemporaryDirectory() as tmp:
            store = ConversationStore(Path(tmp) / "history.sqlite3")
            messages = [{"role": "user", "content": "hi"}, {"role": "assistant", "content": "yo"}]
            cid = store.save(None, messages, model="bonsai2b-test", project="/tmp/proj")
            self.assertEqual(store.meta(cid), ("bonsai2b-test", "/tmp/proj"))

    def test_title_skips_blank_and_nonstring_first_messages(self):
        """Audit C35: the old title derivation indexed splitlines()[0]
        on the first user message whatever it held — a blank first
        message crashed the save with IndexError, and None / list
        contents crashed it too. Now non-text contents are skipped."""
        with tempfile.TemporaryDirectory() as tmp:
            store = ConversationStore(Path(tmp) / "history.sqlite3")
            # Blank first message: the title comes from the next real
            # user message, and the save itself succeeds.
            store.save(None, [
                {"role": "user", "content": "   \n  "},
                {"role": "assistant", "content": "hi"},
                {"role": "user", "content": "the real question\nsecond line"},
            ])
            self.assertEqual(store.recent()[0]["title"], "the real question")
            # None and list contents are skipped the same way.
            store.save(None, [
                {"role": "user", "content": None},
                {"role": "user", "content": ["a", "list"]},
                {"role": "user", "content": "after the list"},
            ])
            self.assertEqual(store.recent()[0]["title"], "after the list")
            # Nothing qualifies anywhere: the fallback title.
            store.save(None, [{"role": "user", "content": ""},
                              {"role": "assistant", "content": "only"}])
            self.assertEqual(store.recent()[0]["title"], "New conversation")

    def test_delete_removes_the_row(self):
        """Audit C35: delete() reports whether a row actually went
        away, and a deleted conversation no longer loads."""
        with tempfile.TemporaryDirectory() as tmp:
            store = ConversationStore(Path(tmp) / "history.sqlite3")
            cid = store.save(None, [{"role": "user", "content": "gone soon"}])
            keep = store.save(None, [{"role": "user", "content": "stays"}])
            self.assertTrue(store.delete(cid))
            self.assertIsNone(store.load(cid))
            self.assertEqual([r["id"] for r in store.recent()], [keep])
            self.assertFalse(store.delete(cid))      # already gone
            self.assertFalse(store.delete(999999))   # never existed

    def test_search_matches_title_and_body_case_insensitively(self):
        """Audit C35: search hits a word in the title OR one that only
        appears inside a message body, case-insensitively, newest
        first; a blank query is exactly recent()."""
        with tempfile.TemporaryDirectory() as tmp:
            store = ConversationStore(Path(tmp) / "history.sqlite3")
            older = store.save(None, [
                {"role": "user", "content": "Needle in the title"},
                {"role": "assistant", "content": "ok"}])
            newer = store.save(None, [
                {"role": "user", "content": "a plain opener"},
                {"role": "assistant", "content": "the needle hides in the body"}])
            store.save(None, [{"role": "user", "content": "unrelated chat"}])
            self.assertEqual([r["id"] for r in store.search("NEEDLE")], [newer, older])
            self.assertEqual([r["id"] for r in store.search("plain opener")], [newer])
            self.assertEqual(store.search("absent word"), [])
            self.assertEqual([r["id"] for r in store.search("   ")],
                             [r["id"] for r in store.recent(200)])

    def test_search_treats_wildcards_literally(self):
        """Audit C35: % and _ in a query are text, not LIKE wildcards —
        searching "%" finds only conversations containing a percent."""
        with tempfile.TemporaryDirectory() as tmp:
            store = ConversationStore(Path(tmp) / "history.sqlite3")
            cid = store.save(None, [{"role": "user", "content": "100% certain"}])
            store.save(None, [{"role": "user", "content": "plain"}])
            self.assertEqual([r["id"] for r in store.search("%")], [cid])
            self.assertEqual([r["id"] for r in store.search("100%")], [cid])

    def test_export_text_renders_a_markdown_transcript(self):
        """Audit C35: export is a Markdown transcript — title header,
        the recorded model/project line, then one headed section per
        message. An unknown id exports as None."""
        with tempfile.TemporaryDirectory() as tmp:
            store = ConversationStore(Path(tmp) / "history.sqlite3")
            cid = store.save(None, [
                {"role": "system", "content": "be brief"},
                {"role": "user", "content": "export me please"},
                {"role": "assistant", "content": "here is the answer"},
            ], model="some-model", project="/tmp/proj")
            text = store.export_text(cid)
            self.assertIn("# export me please", text)
            self.assertIn("Model: some-model", text)
            self.assertIn("Project: /tmp/proj", text)
            self.assertIn("## System", text)
            self.assertIn("be brief", text)
            self.assertLess(text.index("## You"), text.index("## Forge"))
            self.assertIn("export me please", text)
            self.assertIn("here is the answer", text)
            self.assertIsNone(store.export_text(424242))

    def test_export_text_handles_nonstring_content(self):
        """Audit C35: a stored message whose content is not a string
        (a tool payload list) exports as JSON under its role heading
        instead of crashing the export."""
        with tempfile.TemporaryDirectory() as tmp:
            store = ConversationStore(Path(tmp) / "history.sqlite3")
            cid = store.save(None, [
                {"role": "user", "content": "run it"},
                {"role": "tool", "content": [{"name": "echo", "ok": True}]},
            ])
            text = store.export_text(cid)
            self.assertIn("## Tool", text)
            self.assertIn('"name": "echo"', text)


class ConversationHistoryWindowTests(unittest.TestCase):
    """Audit C35 (window half): the conversations list gains a search
    box — typing re-renders the list from store.search instead of
    recent() — and a confirmed delete path: deleting a chat removes
    it from the store and the list, and deleting the OPEN chat resets
    the window to a fresh conversation. Declining the confirm is a
    no-op."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        self.win.conversation_id = None
        self.win.messages = []
        # new_chat (reached when the open chat is deleted) syncs plan
        # state to the deck; satisfy its gate like the other window
        # test classes do while the deck server is off.
        self._real_server = self.win.deck._server
        self.win.deck._server = object()
        self.win.history_search.setText("")
        self.alpha = self.win.store.save(None, [
            {"role": "user", "content": "alpha widget plans"},
            {"role": "assistant", "content": "drawn up"}])
        self.beta = self.win.store.save(None, [
            {"role": "user", "content": "beta soup recipe"},
            {"role": "assistant", "content": "simmer gently"}])
        self.win.refresh_history()

    def tearDown(self):
        self.win.history_search.setText("")
        self.win.deck._server = self._real_server
        self.win.worker = None
        self.temp.cleanup()

    def _history_button_texts(self):
        texts = []
        for i in range(self.win.history_list.count()):
            widget = self.win.history_list.itemAt(i).widget()
            if widget is not None:
                texts.append(widget.text())
        return texts

    def test_search_box_filters_the_history_list(self):
        texts = self._history_button_texts()
        self.assertEqual(len(texts), 2)
        self.assertTrue(any("alpha widget plans" in t for t in texts))
        self.assertTrue(any("beta soup recipe" in t for t in texts))
        # Typing a query leaves only the matching chat's button.
        self.win.history_search.setText("alpha")
        texts = self._history_button_texts()
        self.assertEqual(len(texts), 1)
        self.assertIn("alpha widget plans", texts[0])
        # A word that only appears in a message body matches too.
        self.win.history_search.setText("simmer")
        texts = self._history_button_texts()
        self.assertEqual(len(texts), 1)
        self.assertIn("beta soup recipe", texts[0])
        # Clearing the box restores the full list.
        self.win.history_search.setText("")
        self.assertEqual(len(self._history_button_texts()), 2)

    def test_delete_confirmed_removes_from_store_and_list(self):
        from unittest import mock
        import forge.main as main_mod
        with mock.patch.object(main_mod.QMessageBox, "question",
                               return_value=main_mod.QMessageBox.Yes):
            self.win.delete_conversation(self.beta)
        self.assertIsNone(self.win.store.load(self.beta))
        texts = self._history_button_texts()
        self.assertEqual(len(texts), 1)
        self.assertIn("alpha widget plans", texts[0])

    def test_delete_declined_keeps_everything(self):
        from unittest import mock
        import forge.main as main_mod
        with mock.patch.object(main_mod.QMessageBox, "question",
                               return_value=main_mod.QMessageBox.No):
            self.win.delete_conversation(self.beta)
        self.assertIsNotNone(self.win.store.load(self.beta))
        self.assertEqual(len(self._history_button_texts()), 2)

    def test_delete_open_conversation_resets_the_window(self):
        from unittest import mock
        import forge.main as main_mod
        self.win.conversation_id = self.alpha
        self.win.messages = self.win.store.load(self.alpha)
        with mock.patch.object(main_mod.QMessageBox, "question",
                               return_value=main_mod.QMessageBox.Yes):
            self.win.delete_conversation(self.alpha)
        self.assertIsNone(self.win.store.load(self.alpha))
        # The window fell back to a fresh chat: no open id, and the
        # only message is the new system seed.
        self.assertIsNone(self.win.conversation_id)
        self.assertEqual(len(self.win.messages), 1)
        self.assertEqual(self.win.messages[0]["role"], "system")
        texts = self._history_button_texts()
        self.assertEqual(len(texts), 1)
        self.assertIn("beta soup recipe", texts[0])


class GovernorTests(unittest.TestCase):
    def snap(self, avail=6.0, busy=False, loaded=None):
        return {"avail_gb": avail, "total_gb": 8.0, "load_1min": 0.5 if not busy else 9.0,
                "threads": 4, "cpu_busy": busy, "ollama_running": True,
                "ollama_loaded": loaded or []}

    def test_driver_fits_on_clear_bench(self):
        v = governor.verdict_for("maternion/minicpm5-heretic:2b", self.snap())
        self.assertTrue(v["fits"])
        self.assertEqual(v["roster_key"], "minicpm5")

    def test_tight_ram_rejected(self):
        v = governor.verdict_for("maternion/minicpm5-heretic:2b", self.snap(avail=3.0))
        self.assertFalse(v["fits"])
        self.assertFalse(v["fits_ram"])

    def test_busy_cpu_rejected(self):
        v = governor.verdict_for("eriktonon/bonsai-2-uncensored:2b", self.snap(busy=True))
        self.assertFalse(v["fits"])
        self.assertTrue(v["fits_ram"])

    def test_already_loaded_is_safe(self):
        v = governor.verdict_for("eriktonon/bonsai-2-uncensored:2b",
                                 self.snap(avail=1.2, loaded=["eriktonon/bonsai-2-uncensored:2b"]))
        self.assertTrue(v["already_loaded"])
        self.assertTrue(v["fits"])


class SkillTests(unittest.TestCase):
    def test_scan_index_and_load(self):
        with tempfile.TemporaryDirectory() as tmp:
            folder = Path(tmp) / "demo-skill"
            folder.mkdir()
            (folder / "SKILL.md").write_text(
                "name: demo-skill\ndescription: Does demo things when demoing.\n\n# Body\nSteps here.")
            skills = scan_skills(Path(tmp))
            self.assertEqual([s.name for s in skills], ["demo-skill"])
            self.assertIn("demo-skill: Does demo things", index_text(skills))
            handler = make_load_skill_handler(skills)
            self.assertIn("Steps here", handler({"name": "demo-skill"}))
            self.assertIn("Unknown skill", handler({"name": "nope"}))


class ProjectTests(unittest.TestCase):
    def test_project_area_sources_and_uploads(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            proj.ensure_project(root)
            self.assertTrue((root / ".forge" / "instructions.md").is_file())
            src = root / ".forge" / "sources" / "spec.md"
            src.write_text("# Build spec\nThe real spec line.")
            text = proj.sources_index_text(root)
            self.assertIn("spec.md", text)
            self.assertIn("Build spec", text)
            self.assertEqual(proj.read_source(root, "spec.md"), "# Build spec\nThe real spec line.")
            hand = root / "handed.txt"
            hand.write_text("for the agent")
            dest = proj.add_upload(root, hand)
            self.assertTrue(dest.is_file())
            self.assertEqual(dest.parent.name, "uploads")

    def test_source_escape_rejected(self):
        with tempfile.TemporaryDirectory() as tmp:
            with self.assertRaises(ValueError):
                proj.read_source(Path(tmp), "../secret.txt")


class ReadSourcePagingTests(unittest.TestCase):
    """Audit C29: read_source pages in char slices — content past the
    first 7,000 chars used to be unreachable behind a "[truncated at
    …]" line that named no way forward."""

    def _source(self, root, name, text):
        proj.ensure_project(root)
        (root / ".forge" / "sources" / name).write_text(text, encoding="utf-8")

    def test_long_source_pages_in_char_slices(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            text = "".join(str(i % 10) for i in range(20000))
            self._source(root, "big.txt", text)
            first = proj.read_source(root, "big.txt")
            self.assertEqual(
                first,
                text[:7000] + "\n… [showing chars 0–7000 of 20000"
                              " — call read_source with offset=7000 to continue]")
            second = proj.read_source(root, "big.txt", offset=7000)
            self.assertEqual(
                second,
                text[7000:14000] + "\n… [showing chars 7000–14000 of 20000"
                                   " — call read_source with offset=14000 to continue]")
            third = proj.read_source(root, "big.txt", offset=14000)
            self.assertEqual(
                third,
                text[14000:] + "\n… [showing chars 14000–20000 of 20000"
                               " — the end of the file]")
            # The three content slices stitch back into the whole file.
            self.assertEqual(first[:7000] + second[:7000] + third[:6000], text)

    def test_offset_past_end_and_negative_offset_clamps(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            self._source(root, "big.txt", "x" * 20000)
            self.assertEqual(
                proj.read_source(root, "big.txt", offset=25000),
                "Source big.txt has 20000 chars — offset 20000 is past the end.")
            neg = proj.read_source(root, "big.txt", offset=-50)
            self.assertTrue(neg.startswith("x" * 7000))
            self.assertIn("showing chars 0–7000 of 20000", neg)

    def test_whole_file_slices_carry_no_footer(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            self._source(root, "small.md", "short and whole")
            self.assertEqual(proj.read_source(root, "small.md"), "short and whole")
            exact = "y" * 7000
            self._source(root, "exact.txt", exact)
            self.assertEqual(proj.read_source(root, "exact.txt"), exact)

    def test_missing_source_message_unchanged(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            proj.ensure_project(root)
            self.assertEqual(proj.read_source(root, "nope.md"),
                             "Source not found: nope.md")

    def test_schema_teaches_offset(self):
        fn = proj.READ_SOURCE_SCHEMA["function"]
        props = fn["parameters"]["properties"]
        self.assertEqual(props["offset"]["type"], "integer")
        self.assertNotIn("offset", fn["parameters"]["required"])
        self.assertIn("offset", fn["description"])
        self.assertIn("continue", fn["description"])


class EventLogTests(unittest.TestCase):
    def test_record_and_summary(self):
        with tempfile.TemporaryDirectory() as tmp:
            log = EventLog(Path(tmp))
            log.record("request", prompt="hello")
            log.record("approval", tool="write_file", approved=True, waited_seconds=42.0)
            log.record("tool_call", tool="write_file")
            summary = log.session_summary()
            self.assertIn("1 approved", summary)
            self.assertIn("write_file×1", summary)

    def test_records_roll_into_the_new_days_file_at_midnight(self):
        # Audit item A13 (LEG 1): the log filename used to be frozen
        # at EventLog construction, so a session crossing midnight
        # kept writing into yesterday's file (and the summary read
        # that same stale file). The path now resolves from the
        # current date at each record() and in session_summary().
        from datetime import datetime as real_dt
        from unittest import mock
        from forge import eventlog as ev_mod

        class FakeDateTime:
            current = real_dt(2026, 1, 1, 23, 59, 0)

            @classmethod
            def now(cls, tz=None):
                return cls.current

        with tempfile.TemporaryDirectory() as tmp:
            log = EventLog(Path(tmp))
            with mock.patch.object(ev_mod, "datetime", FakeDateTime):
                log.record("before_midnight")
                FakeDateTime.current = real_dt(2026, 1, 2, 0, 1, 0)
                log.record("after_midnight")
                day1 = (Path(tmp) / "forge-20260101.jsonl").read_text(encoding="utf-8")
                day2 = (Path(tmp) / "forge-20260102.jsonl").read_text(encoding="utf-8")
                self.assertIn("before_midnight", day1)
                self.assertNotIn("after_midnight", day1)
                self.assertIn("after_midnight", day2)
                summary = log.session_summary()
                self.assertIn("forge-20260102.jsonl", summary)
                self.assertIn("after_midnight=1", summary)
                self.assertNotIn("before_midnight", summary)


class PluginTests(unittest.TestCase):
    def test_shipped_plugins_load(self):
        root = Path(__file__).resolve().parent.parent
        ctx = PluginContext(workspace="/tmp", current_model="eriktonon/bonsai-2-uncensored:2b")
        plugins, registry = load_plugins(root / "plugins", ctx)
        names = set(registry)
        self.assertIn("check_resources", names)
        self.assertIn("run_tester", names)
        self.assertIn("hf_search_models", names)
        self.assertIn("github_repo_info", names)
        self.assertTrue(any(p.kind == "connector" for p in plugins))

    def test_check_resources_handler(self):
        root = Path(__file__).resolve().parent.parent
        ctx = PluginContext(workspace="/tmp", current_model="eriktonon/bonsai-2-uncensored:2b")
        _plugins, registry = load_plugins(root / "plugins", ctx)
        schema, handler, needs_approval, _src = registry["check_resources"]
        self.assertFalse(needs_approval)
        self.assertIn("Bench:", handler({}))


class PluginLoadingAuditTests(unittest.TestCase):
    """Audit item A5: plugin loading is metadata-first. Code for a
    disabled or brand-new (unknown) plugin never executes; a manifest
    that parses to a non-object is skipped, never raised; tool-name
    collisions keep the first registration; handlers see only the
    connectors.json keys their manifest declares in config_keys."""

    SENTINEL_CODE = (
        "from pathlib import Path\n"
        "Path(SENTINEL_PATH).write_text('ran')\n"
        "def _go(args, ctx):\n    return 'went'\n"
        "HANDLERS = {'go_now': _go}\n")

    def _plant(self, plugins_dir, folder_name, meta, code):
        folder = plugins_dir / folder_name
        folder.mkdir(parents=True)
        (folder / "plugin.json").write_text(
            meta if isinstance(meta, str) else json.dumps(meta))
        (folder / "plugin.py").write_text(code)
        return folder

    def _sentinel_plugin(self, tmp, pid="sleepy"):
        root = Path(tmp)
        sentinel = root / "ran.txt"
        code = self.SENTINEL_CODE.replace("SENTINEL_PATH", repr(str(sentinel)))
        self._plant(root / "plugins", pid,
                    {"id": pid, "name": pid.title(),
                     "tools": [{"name": "go_now"}]}, code)
        return root / "plugins", sentinel

    def test_disabled_plugin_code_never_runs(self):
        with tempfile.TemporaryDirectory() as tmp:
            pdir, sentinel = self._sentinel_plugin(tmp)
            ctx = PluginContext(workspace=tmp, log=lambda m: None)
            plugins, registry = load_plugins(pdir, ctx, disabled={"sleepy"})
            self.assertFalse(sentinel.exists())
            self.assertNotIn("go_now", registry)
            # …but the plugin is still listed, tools declared, no handlers
            self.assertEqual([p.pid for p in plugins], ["sleepy"])
            self.assertEqual([t["name"] for t in plugins[0].tools], ["go_now"])
            self.assertEqual(plugins[0].handlers, {})

    def test_unknown_plugin_code_never_runs_until_known(self):
        with tempfile.TemporaryDirectory() as tmp:
            pdir, sentinel = self._sentinel_plugin(tmp)
            ctx = PluginContext(workspace=tmp, log=lambda m: None)
            plugins, registry = load_plugins(pdir, ctx, known={"someone-else"})
            self.assertFalse(sentinel.exists())
            self.assertNotIn("go_now", registry)
            self.assertEqual([p.pid for p in plugins], ["sleepy"])
            # grandfathering: no history (known=None) → it loads normally
            plugins, registry = load_plugins(pdir, ctx, known=None)
            self.assertTrue(sentinel.exists())
            self.assertEqual(registry["go_now"][1]({}), "went")

    def test_bad_manifests_skipped_never_raised(self):
        with tempfile.TemporaryDirectory() as tmp:
            pdir = Path(tmp) / "plugins"
            self._plant(pdir, "broken", '["not", "an", "object"]', "HANDLERS = {}\n")
            self._plant(pdir, "garbled", "{oops", "HANDLERS = {}\n")
            self._plant(pdir, "fine",
                        {"id": "fine", "name": "Fine",
                         "tools": [{"name": "fine_tool"}]},
                        "def _f(args, ctx):\n    return 'fine'\n"
                        "HANDLERS = {'fine_tool': _f}\n")
            logs = []
            ctx = PluginContext(workspace=tmp, log=logs.append)
            plugins, registry = load_plugins(pdir, ctx)
            self.assertEqual([p.pid for p in plugins], ["fine"])
            self.assertEqual(registry["fine_tool"][1]({}), "fine")
            self.assertTrue(any("broken" in m and "bad plugin.json" in m
                                for m in logs), logs)
            self.assertTrue(any("garbled" in m and "bad plugin.json" in m
                                for m in logs), logs)

    def test_tool_name_collision_first_registration_wins(self):
        with tempfile.TemporaryDirectory() as tmp:
            pdir = Path(tmp) / "plugins"
            for folder, who in (("aaa", "first"), ("bbb", "second")):
                self._plant(pdir, folder,
                            {"id": folder, "name": folder.title(),
                             "tools": [{"name": "same_tool"}]},
                            f"def _h(args, ctx):\n    return '{who}'\n"
                            "HANDLERS = {'same_tool': _h}\n")
            logs = []
            ctx = PluginContext(workspace=tmp, log=logs.append)
            _plugins, registry = load_plugins(pdir, ctx)
            self.assertEqual(registry["same_tool"][1]({}), "first")
            self.assertEqual(registry["same_tool"][3], "Aaa")
            self.assertTrue(any("same_tool" in m and "already registered" in m
                                for m in logs), logs)

    def test_handlers_see_only_declared_config_keys(self):
        echo = ("def _echo(args, ctx):\n"
                "    return ctx.workspace + '|' + ','.join(sorted((ctx.config or {}).keys()))\n")
        with tempfile.TemporaryDirectory() as tmp:
            pdir = Path(tmp) / "plugins"
            self._plant(pdir, "scoped",
                        {"id": "scoped", "name": "Scoped",
                         "config_keys": ["github_token", "late_key"],
                         "tools": [{"name": "scoped_echo"}]},
                        echo + "HANDLERS = {'scoped_echo': _echo}\n")
            self._plant(pdir, "unscoped",
                        {"id": "unscoped", "name": "Unscoped",
                         "tools": [{"name": "unscoped_echo"}]},
                        echo + "HANDLERS = {'unscoped_echo': _echo}\n")
            ctx = PluginContext(workspace=tmp, config={
                "github_token": "g", "hf_token": "h", "mcp_servers": {"x": 1}})
            _plugins, registry = load_plugins(pdir, ctx)
            # declared keys only; undeclared live keys stay invisible
            self.assertEqual(registry["scoped_echo"][1]({}), tmp + "|github_token")
            # no config_keys declared → empty config
            self.assertEqual(registry["unscoped_echo"][1]({}), tmp + "|")
            # the view reads the LIVE config at call time: a declared
            # key added after load shows up, and workspace delegates
            ctx.config["late_key"] = "now"
            self.assertEqual(registry["scoped_echo"][1]({}),
                             tmp + "|github_token,late_key")


if __name__ == "__main__":
    unittest.main()


class _FakeClient:
    """Streams DISTINCT tool calls (a real long task) for the first N
    requests, then a final answer. Distinct on purpose: the loop guard
    blocks exact repeats, never varied work."""
    def __init__(self, tool_rounds):
        self.tool_rounds = tool_rounds
        self.calls = 0

    def chat_stream(self, model, messages, options, schemas, keep_alive=None):
        self.calls += 1
        if self.calls <= self.tool_rounds:
            yield {"message": {"content": "", "tool_calls": [
                {"function": {"name": "ping_tool", "arguments": {"n": self.calls}}}]}}
        else:
            yield {"message": {"content": "all done", "tool_calls": []}}


class WorkerLoopTests(unittest.TestCase):
    def test_no_tool_cycle_cap(self):
        # Owner's rule (2026-11-06): no artificial tool-call limit. v1/v2
        # stopped after 6 rounds; a turn must run past that until the
        # model itself stops calling tools.
        from forge.worker import AgentWorker
        hits = {"n": 0}

        def handler(args):
            hits["n"] += 1
            return f"result {args.get('n')}"

        schema = {"type": "function",
                  "function": {"name": "ping_tool", "description": "test",
                               "parameters": {"type": "object", "properties": {"n": {"type": "integer"}}}}}
        extra = {"ping_tool": (schema, handler, False, "test")}
        client = _FakeClient(tool_rounds=9)
        worker = AgentWorker(client, "fake", [{"role": "user", "content": "go"}],
                             {}, tempfile.mkdtemp(), extra_tools=extra)
        finished = []
        worker.finished_text.connect(lambda text, msgs: finished.append(text))
        worker.run()
        self.assertEqual(hits["n"], 9)
        self.assertTrue(finished and "all done" in finished[0])


class _BatchClient:
    """One generation carrying a whole BATCH of tool calls at once.
    If the worker ever asks again, it answers with plain text — the
    call count is the proof of whether a second generation happened."""
    def __init__(self, batch):
        self.batch = batch
        self.calls = 0

    def chat_stream(self, model, messages, options, schemas, keep_alive=None):
        self.calls += 1
        if self.calls == 1:
            yield {"message": {"content": "", "tool_calls": [
                {"function": {"name": name, "arguments": args}}
                for name, args in self.batch]}}
        else:
            yield {"message": {"content": "second generation", "tool_calls": []}}


class BatchStopTests(unittest.TestCase):
    """Audit A4: Stop pressed while a batch of tool calls is running
    must skip the calls that have not started yet — not let the whole
    batch finish — and each skipped call still earns a tool result
    saying it was cancelled and not run."""

    def test_stop_mid_batch_skips_remaining_calls(self):
        import forge.worker as worker_mod
        from forge.worker import AgentWorker
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            (root / "alpha").mkdir()
            (root / "beta").mkdir()
            # Distinct paths on purpose: identical repeats would trip
            # the loop guard instead of proving anything about Stop.
            batch = [("list_directory", {"path": "."}),
                     ("list_directory", {"path": "alpha"}),
                     ("list_directory", {"path": "beta"})]
            client = _BatchClient(batch)
            rules = [{"scope": "global", "tool": "list_directory",
                      "pattern": "*", "action": "allow"}]
            worker = AgentWorker(client, "fake",
                                 [{"role": "user", "content": "go"}], {},
                                 str(root),
                                 permissions={"rules": rules, "mode": "code",
                                              "classes": {}})
            real_execute = worker_mod.execute_tool
            invocations = []

            def spy_execute(name, args, workspace, cancel_event=None):
                invocations.append((name, dict(args)))
                if len(invocations) == 1:
                    result = real_execute(name, args, workspace,
                                          cancel_event=cancel_event)
                    worker.cancel()  # the owner presses Stop mid-batch
                    return result
                return "spy: a later call reached execution"

            worker_mod.execute_tool = spy_execute
            try:
                worker.run()
            finally:
                worker_mod.execute_tool = real_execute

            # Only the first call ever reached the tool layer.
            self.assertEqual(invocations, [("list_directory", {"path": "."})])
            # All three calls still earned a tool result, in order.
            tools = [m.get("content", "") for m in worker.messages
                     if m.get("role") == "tool"]
            self.assertEqual(len(tools), 3)
            self.assertNotIn("cancelled", tools[0])  # the real listing ran
            for skipped in tools[1:]:
                self.assertIn("cancelled", skipped)
                self.assertIn("not run", skipped)
            # The cancelled turn ended at the loop-top check — the
            # model was never asked for a second generation.
            self.assertEqual(client.calls, 1)


class ToolResultDigestTests(unittest.TestCase):
    """Audit B18, leg 2: a tool result over 24,000 chars is stored
    in the conversation as a head+tail digest (the model re-reads
    it every cycle — an undigested giant would eat the window),
    while the event log's tool_result record keeps the full text
    and the turn completes normally."""

    def test_oversized_result_digested_in_message_full_in_log(self):
        import forge.worker as worker_mod
        from forge.worker import AgentWorker
        with tempfile.TemporaryDirectory() as td:
            full = "H" * 16000 + "M" * 10000 + "T" * 4000
            client = _BatchClient([("list_directory", {"path": "."})])
            rules = [{"scope": "global", "tool": "list_directory",
                      "pattern": "*", "action": "allow"}]
            log = _FakeEventLog()
            worker = AgentWorker(
                client, "fake", [{"role": "user", "content": "go"}], {},
                td, eventlog=log,
                permissions={"rules": rules, "mode": "code",
                             "classes": {}})
            real_execute = worker_mod.execute_tool
            worker_mod.execute_tool = (
                lambda name, args, workspace, cancel_event=None: full)
            finished = []
            worker.finished_text.connect(
                lambda text, msgs: finished.append(text))
            try:
                worker.run()
            finally:
                worker_mod.execute_tool = real_execute

            tools = [m.get("content", "") for m in worker.messages
                     if m.get("role") == "tool"]
            self.assertEqual(len(tools), 1)
            expected = ("H" * 16000
                        + "\n[… 10000 chars elided — the full output of "
                          "list_directory is recorded in the event log …]\n"
                        + "T" * 4000)
            self.assertEqual(tools[0], expected)
            self.assertLess(len(tools[0]), len(full))
            records = [f for k, f in log.events if k == "tool_result"]
            self.assertEqual(len(records), 1)
            self.assertEqual(records[0]["chars"], 30000)
            self.assertEqual(records[0]["text"], full)
            self.assertTrue(finished)

    def test_small_result_stored_verbatim_and_logged_in_full(self):
        import forge.worker as worker_mod
        from forge.worker import AgentWorker
        with tempfile.TemporaryDirectory() as td:
            client = _BatchClient([("list_directory", {"path": "."})])
            rules = [{"scope": "global", "tool": "list_directory",
                      "pattern": "*", "action": "allow"}]
            log = _FakeEventLog()
            worker = AgentWorker(
                client, "fake", [{"role": "user", "content": "go"}], {},
                td, eventlog=log,
                permissions={"rules": rules, "mode": "code",
                             "classes": {}})
            real_execute = worker_mod.execute_tool
            worker_mod.execute_tool = (
                lambda name, args, workspace, cancel_event=None: "tiny")
            try:
                worker.run()
            finally:
                worker_mod.execute_tool = real_execute
            tools = [m.get("content", "") for m in worker.messages
                     if m.get("role") == "tool"]
            self.assertEqual(tools, ["tiny"])
            records = [f for k, f in log.events if k == "tool_result"]
            self.assertEqual(len(records), 1)
            # Item 45 widened the record: EVERY result's full text
            # is logged now (capped), not just oversized ones — the
            # small result's text is here verbatim.
            self.assertEqual(records[0]["text"], "tiny")
            self.assertEqual(records[0]["chars"], 4)


class ToolLogCaptureTests(unittest.TestCase):
    """Item 45 (item 9's parked remainder): the event log is a
    fully replayable record. tool_call records carry the call's
    FULL arguments — serialized once, capped at 20,000 chars with
    an args_capped marker when cut — and EVERY tool_result record
    carries the result's full text (capped at _TOOL_RESULT_LOG_CAP):
    small results (previously counts-only), oversized results,
    non-string results, and Stop-cancelled calls alike. Only the
    log records widened; what the model sees is unchanged."""

    def _run_batch(self, batch, td, result, rules_tool=None, extra=None):
        """One scripted batch turn whose built-in tool layer is
        monkeypatched to return `result`; returns the fake log."""
        import forge.worker as worker_mod
        from forge.worker import AgentWorker
        client = _BatchClient(batch)
        rules = ([{"scope": "global", "tool": rules_tool,
                   "pattern": "*", "action": "allow"}]
                 if rules_tool else [])
        log = _FakeEventLog()
        worker = AgentWorker(
            client, "fake", [{"role": "user", "content": "go"}], {},
            td, eventlog=log, extra_tools=extra or {},
            permissions={"rules": rules, "mode": "code", "classes": {}},
            skribe_writes=False)
        real_execute = worker_mod.execute_tool
        worker_mod.execute_tool = (
            lambda name, args, workspace, cancel_event=None: result)
        try:
            worker.run()
        finally:
            worker_mod.execute_tool = real_execute
        return log

    def test_call_args_and_small_result_logged_in_full(self):
        with tempfile.TemporaryDirectory() as td:
            log = self._run_batch(
                [("list_directory", {"path": "."})], td, "tiny listing",
                rules_tool="list_directory")
            calls = [f for k, f in log.events if k == "tool_call"]
            self.assertEqual(len(calls), 1)
            self.assertEqual(calls[0]["tool"], "list_directory")
            # The full arguments ride the record and parse back to
            # exactly what the model asked for.
            self.assertEqual(json.loads(calls[0]["args_json"]),
                             {"path": "."})
            self.assertNotIn("args_capped", calls[0])
            # A SMALL result — the previously counts-only case —
            # now logs its full text too.
            records = [f for k, f in log.events if k == "tool_result"]
            self.assertEqual(len(records), 1)
            self.assertEqual(records[0]["text"], "tiny listing")
            self.assertEqual(records[0]["chars"], len("tiny listing"))

    def test_oversized_result_text_capped_in_log(self):
        import forge.worker as worker_mod
        with tempfile.TemporaryDirectory() as td:
            full = "y" * 250_000
            log = self._run_batch(
                [("list_directory", {"path": "."})], td, full,
                rules_tool="list_directory")
            records = [f for k, f in log.events if k == "tool_result"]
            self.assertEqual(len(records), 1)
            self.assertEqual(records[0]["chars"], 250_000)
            self.assertEqual(records[0]["text"],
                             "y" * worker_mod._TOOL_RESULT_LOG_CAP)

    def test_write_args_capped_and_marked_small_write_complete(self):
        with tempfile.TemporaryDirectory() as td:
            small = self._run_batch(
                [("write_file", {"path": "note.txt", "content": "hello"})],
                td, "ok", rules_tool="write_file")
            calls = [f for k, f in small.events if k == "tool_call"]
            self.assertEqual(len(calls), 1)
            self.assertEqual(json.loads(calls[0]["args_json"]),
                             {"path": "note.txt", "content": "hello"})
            self.assertNotIn("args_capped", calls[0])

            big = self._run_batch(
                [("write_file", {"path": "big.txt",
                                 "content": "x" * 25_000})],
                td, "ok", rules_tool="write_file")
            calls = [f for k, f in big.events if k == "tool_call"]
            self.assertEqual(len(calls), 1)
            self.assertTrue(calls[0]["args_capped"])
            self.assertEqual(len(calls[0]["args_json"]),
                             20_000 + len("…[capped]"))
            self.assertTrue(calls[0]["args_json"].endswith("…[capped]"))
            self.assertTrue(
                calls[0]["args_json"].startswith('{"content": "xxxxx'))

    def test_non_string_result_logs_its_str_text(self):
        schema = {"type": "function",
                  "function": {"name": "dict_tool", "description": "test",
                               "parameters": {"type": "object",
                                              "properties": {}}}}
        payload = {"rows": 3, "ok": True}
        extra = {"dict_tool": (schema, lambda args: payload, False, "test")}
        with tempfile.TemporaryDirectory() as td:
            log = self._run_batch([("dict_tool", {"q": 1})], td, "unused",
                                  extra=extra)
            calls = [f for k, f in log.events if k == "tool_call"]
            self.assertEqual(json.loads(calls[0]["args_json"]), {"q": 1})
            records = [f for k, f in log.events if k == "tool_result"]
            self.assertEqual(len(records), 1)
            self.assertEqual(records[0]["text"], str(payload))
            self.assertEqual(records[0]["chars"], len(str(payload)))

    def test_cancelled_calls_log_the_cancellation_text(self):
        import forge.worker as worker_mod
        from forge.worker import AgentWorker
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            (root / "alpha").mkdir()
            (root / "beta").mkdir()
            batch = [("list_directory", {"path": "."}),
                     ("list_directory", {"path": "alpha"}),
                     ("list_directory", {"path": "beta"})]
            client = _BatchClient(batch)
            rules = [{"scope": "global", "tool": "list_directory",
                      "pattern": "*", "action": "allow"}]
            log = _FakeEventLog()
            worker = AgentWorker(
                client, "fake", [{"role": "user", "content": "go"}], {},
                str(root), eventlog=log,
                permissions={"rules": rules, "mode": "code",
                             "classes": {}})
            real_execute = worker_mod.execute_tool
            invocations = []

            def spy_execute(name, args, workspace, cancel_event=None):
                invocations.append(name)
                if len(invocations) == 1:
                    result = real_execute(name, args, workspace,
                                          cancel_event=cancel_event)
                    worker.cancel()  # the owner presses Stop mid-batch
                    return result
                return "spy: a later call reached execution"

            worker_mod.execute_tool = spy_execute
            try:
                worker.run()
            finally:
                worker_mod.execute_tool = real_execute
            records = [f for k, f in log.events if k == "tool_result"]
            self.assertEqual(len(records), 3)
            # The executed call logs its real result text…
            self.assertTrue(records[0]["text"])
            self.assertNotIn("cancelled", records[0]["text"])
            # …and each Stop-skipped call's record carries the
            # actual cancellation text, not just a char count.
            for skipped in records[1:]:
                self.assertIn("Tool cancelled", skipped["text"])
                self.assertIn("not run", skipped["text"])
                self.assertEqual(skipped["chars"], len(skipped["text"]))


class _BudgetClient:
    """Asks for the big tool whenever tools are offered; answers in
    text the moment a generation arrives with NO schemas (what a
    real model must do in wrap-up mode), or once max_tool_rounds
    tool rounds have run (the control case)."""

    def __init__(self, max_tool_rounds=99):
        self.calls = 0
        self.tool_rounds = 0
        self.max_tool_rounds = max_tool_rounds
        self.schemas_seen = []

    def chat_stream(self, model, messages, options, schemas, keep_alive=None):
        self.calls += 1
        self.schemas_seen.append(list(schemas or []))
        if schemas and self.tool_rounds < self.max_tool_rounds:
            self.tool_rounds += 1
            yield {"message": {"content": "", "tool_calls": [
                {"function": {"name": "big_tool",
                               "arguments": {"n": self.tool_rounds}}}]}}
        else:
            yield {"message": {"content": "settled in text",
                               "tool_calls": []}}


class _GradingClient:
    """The SKRIBE script — write a file, answer quietly (which arms
    the gate), then return a verdict — recording the schemas and
    the estimated payload of every generation it serves."""

    def __init__(self):
        self.calls = 0
        self.schemas_seen = []
        self.estimates = []

    def chat_stream(self, model, messages, options, schemas, keep_alive=None):
        from forge import context as context_mod
        self.calls += 1
        self.schemas_seen.append(list(schemas or []))
        self.estimates.append(context_mod.total_estimate(messages, schemas))
        if self.calls == 1:
            yield {"message": {"content": "", "tool_calls": [
                {"function": {"name": "write_file",
                              "arguments": {"path": "graded.py",
                                            "content": "x = 1\n"}}}]}}
        elif self.calls == 2:
            yield {"message": {"content": "written", "tool_calls": []}}
        else:
            yield {"message": {"content":
                               "SKRIBE-VERDICT file=graded.py fzi=90 "
                               "decision=finalize",
                               "tool_calls": []}}


class ContextBudgetTests(unittest.TestCase):
    """Audit B18, leg 3: when the estimated payload reaches 90% of
    the window mid-turn, the turn wraps up — later generations are
    offered NO tools and the model settles in text. Sizes are
    estimator-driven (deterministic): schemas + a short prompt are
    ~530 estimated tokens; one 20,000-char tool result adds ~5,700.
    A 2,000-token window therefore trips exactly after the first
    tool round, and a 100,000-token window never does."""

    def _worker(self, client, num_ctx, td, log):
        from forge.worker import AgentWorker
        schema = {"type": "function",
                  "function": {"name": "big_tool", "description": "test",
                               "parameters": {"type": "object",
                                              "properties": {
                                                  "n": {"type": "integer"}}}}}
        extra = {"big_tool": (schema, lambda args: "R" * 20000,
                              False, "test")}
        return AgentWorker(client, "fake",
                           [{"role": "user", "content": "go"}],
                           {"num_ctx": num_ctx}, td,
                           extra_tools=extra, eventlog=log)

    def test_budget_trip_strips_tools_and_turn_settles(self):
        with tempfile.TemporaryDirectory() as td:
            log = _FakeEventLog()
            client = _BudgetClient()
            worker = self._worker(client, 2000, td, log)
            finished = []
            worker.finished_text.connect(
                lambda text, msgs: finished.append(text))
            worker.run()
            # The first generation had its tools; the giant result
            # blew the budget, so the next generation was offered
            # none — and the turn settled on its text answer.
            self.assertTrue(client.schemas_seen[0])
            self.assertEqual(client.schemas_seen[1], [])
            self.assertEqual(client.calls, 2)
            self.assertIn("context_budget_stop", log.kinds())
            stop = next(f for k, f in log.events
                        if k == "context_budget_stop")
            self.assertEqual(stop["num_ctx"], 2000)
            self.assertGreaterEqual(stop["estimate"], 1800)
            self.assertTrue(finished)

    def test_generous_window_never_trips(self):
        with tempfile.TemporaryDirectory() as td:
            log = _FakeEventLog()
            client = _BudgetClient(max_tool_rounds=3)
            worker = self._worker(client, 100000, td, log)
            worker.run()
            self.assertEqual(client.calls, 4)
            self.assertTrue(all(client.schemas_seen))
            self.assertNotIn("context_budget_stop", log.kinds())

    def test_skribe_grading_generation_keeps_its_tools(self):
        # The exemption: the pending SKRIBE grading generation keeps
        # its tools even when the payload is already past the stop
        # fraction. Measured fixture: with this script the estimated
        # payloads are 1227 (write), 1285 (quiet answer), 1507
        # (grading) — a 1550-token window stays under 90% for the
        # first two generations (0.79, 0.83) and crosses it only at
        # the grading generation (0.97), which is exactly the one
        # the exemption protects. The client records the estimate of
        # every call so the fixture cannot silently drift under the
        # threshold: the test asserts the crossing really happened.
        # (Recalibrated 2026-11-09: the Write/Research file kit
        # added four built-in schemas, ~620 estimated tokens of
        # schema payload on every generation — the window moved
        # from 850 to 1550 to keep the same three relationships.)
        from forge.worker import AgentWorker
        with tempfile.TemporaryDirectory() as td:
            log = _FakeEventLog()
            client = _GradingClient()
            worker = AgentWorker(
                client, "maternion/minicpm5-heretic:2b",
                [{"role": "user", "content": "go"}], {"num_ctx": 1550},
                td, eventlog=log)
            worker.approval_needed.connect(
                lambda *a: worker.resolve_approval(True))
            finished = []
            worker.finished_text.connect(
                lambda text, msgs: finished.append(text))
            worker.run()
            self.assertEqual(client.calls, 3)
            # The first two generations were under the fraction…
            self.assertLess(client.estimates[0], 0.90 * 1550)
            self.assertLess(client.estimates[1], 0.90 * 1550)
            # …the grading generation was over it…
            self.assertGreaterEqual(client.estimates[2], 0.90 * 1550)
            # …and still kept its tools, with no budget trip logged.
            self.assertTrue(client.schemas_seen[2])
            self.assertNotIn("context_budget_stop", log.kinds())
            verdicts = [f for k, f in log.events
                        if k == "skribe_verdict"]
            self.assertEqual(len(verdicts), 1)
            self.assertEqual(verdicts[0]["decision"], "finalize")
            self.assertTrue(finished)


class _ContinuityClient:
    """Context-continuity script: fold-summary requests (detected by
    the summarizer system prompt, exactly as forge/context.py builds
    them) are answered with a configured summary; main generations
    ask for the big tool while tools are offered (up to
    max_tool_rounds), then settle in text."""

    def __init__(self, summary_text="Compact summary of the earlier exchanges.",
                 max_tool_rounds=1):
        self.calls = 0
        self.fold_calls = 0
        self.tool_rounds = 0
        self.max_tool_rounds = max_tool_rounds
        self.summary_text = summary_text
        self.main_schemas = []

    def chat_stream(self, model, messages, options, schemas, keep_alive=None):
        from forge import context as context_mod
        self.calls += 1
        if messages and messages[0].get("content") == context_mod.SUMMARIZER_SYSTEM:
            self.fold_calls += 1
            yield {"message": {"content": self.summary_text,
                               "tool_calls": []}}
        elif schemas and self.tool_rounds < self.max_tool_rounds:
            self.main_schemas.append(list(schemas))
            self.tool_rounds += 1
            yield {"message": {"content": "", "tool_calls": [
                {"function": {"name": "big_tool",
                              "arguments": {"n": self.tool_rounds}}}]}}
        else:
            self.main_schemas.append(list(schemas or []))
            yield {"message": {"content": "settled in text",
                               "tool_calls": []}}


class ContextContinuityTests(unittest.TestCase):
    """Context continuity (the owner's order, 2026-11-09): at the
    B18 stop fraction a turn folds mid-flight and CONTINUES with
    its tools — the wrap-up survives only when no fold can free
    the turn. Sizes are estimator-driven like ContextBudgetTests:
    a fat exchange of 16,000 chars estimates ~4,600 tokens, one
    20,000-char tool result ~5,700, the schemas ~530. An 8,000-token
    window (stop line 7,200) with three fat older exchanges trips
    on the fat, folds it away in two passes, and finishes."""

    def _worker(self, client, td, log, messages=None, num_ctx=8000):
        from forge.worker import AgentWorker
        schema = {"type": "function",
                  "function": {"name": "big_tool", "description": "test",
                               "parameters": {"type": "object",
                                              "properties": {
                                                  "n": {"type": "integer"}}}}}
        hits = {"n": 0}

        def handler(args):
            hits["n"] += 1
            return "R" * 20000

        extra = {"big_tool": (schema, handler, False, "test")}
        worker = AgentWorker(client, "fake",
                             messages or [{"role": "user", "content": "go"}],
                             {"num_ctx": num_ctx}, td,
                             extra_tools=extra, eventlog=log)
        return worker, hits

    def _fat_history(self):
        msgs = []
        for i in range(3):
            msgs.append({"role": "user", "content": f"earlier request {i}"})
            msgs.append({"role": "assistant", "content": "A" * 16000})
        for i in range(3, 6):
            msgs.append({"role": "user", "content": f"recent request {i}"})
            msgs.append({"role": "assistant", "content": "done"})
        msgs.append({"role": "user", "content": "go"})
        return msgs

    def test_mid_turn_fold_lets_the_turn_finish_its_work(self):
        with tempfile.TemporaryDirectory() as td:
            log = _FakeEventLog()
            client = _ContinuityClient()
            worker, hits = self._worker(client, td, log,
                                        messages=self._fat_history())
            finished = []
            worker.finished_text.connect(
                lambda text, msgs: finished.append(text))
            worker.run()
            folds = [f for k, f in log.events
                     if k == "context_fold_mid_turn"]
            self.assertEqual(len(folds), 2)
            self.assertTrue(all(f["estimate"] < 7200 for f in folds))
            self.assertNotIn("context_budget_stop", log.kinds())
            self.assertEqual(hits["n"], 1)
            self.assertTrue(any(m.get("summary") for m in worker.messages))
            # Tools were on the table at every main generation — the
            # turn never entered wrap-up mode.
            self.assertTrue(all(client.main_schemas))
            self.assertTrue(finished)

    def test_unfoldable_history_still_wraps_up(self):
        # One exchange: nothing is foldable, the fold attempt finds
        # no span (plan_fold is pure — not even a generation is
        # spent), and the classic B18 wrap-up lands unchanged.
        with tempfile.TemporaryDirectory() as td:
            log = _FakeEventLog()
            client = _BudgetClient()
            worker, _hits = self._worker(client, td, log, num_ctx=2000)
            worker.run()
            self.assertEqual(client.calls, 2)
            self.assertEqual(client.schemas_seen[1], [])
            self.assertIn("context_budget_stop", log.kinds())
            self.assertNotIn("context_fold_mid_turn", log.kinds())

    def test_a_fold_that_would_not_shrink_still_wraps_up(self):
        with tempfile.TemporaryDirectory() as td:
            log = _FakeEventLog()
            client = _ContinuityClient(summary_text="S" * 40000)
            worker, hits = self._worker(client, td, log,
                                        messages=self._fat_history())
            worker.run()
            self.assertEqual(client.fold_calls, 1)
            self.assertEqual(hits["n"], 0)
            self.assertNotIn("context_fold_mid_turn", log.kinds())
            self.assertIn("context_budget_stop", log.kinds())
            self.assertFalse(any(m.get("summary")
                                 for m in worker.messages))

    def test_fold_cap_falls_back_without_spending_a_generation(self):
        from forge import worker as worker_mod
        with tempfile.TemporaryDirectory() as td:
            log = _FakeEventLog()
            client = _ContinuityClient()
            worker, _hits = self._worker(client, td, log,
                                         messages=self._fat_history())
            worker._mid_turn_folds = worker_mod.MAX_MID_TURN_FOLDS
            self.assertFalse(worker._try_mid_turn_fold(8000, []))
            self.assertEqual(client.calls, 0)


class ContainmentTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)

    def tearDown(self):
        self.temp.cleanup()

    def test_symlink_escape_refused(self):
        outside = self.root.parent / "outside_secret.txt"
        outside.write_text("not yours")
        (self.root / "innocent_link").symlink_to(outside)
        with self.assertRaises(ToolError):
            execute_tool("read_file", {"path": "innocent_link"}, str(self.root))

    def test_protected_path_refused(self):
        (self.root / ".ssh").mkdir()
        (self.root / ".ssh" / "config").write_text("x")
        with self.assertRaises(ToolError):
            execute_tool("read_file", {"path": ".ssh/config"}, str(self.root))

    def test_timed_out_command_group_killed(self):
        import time as _time
        marker = self.root / "orphan_marker"
        result = execute_tool(
            "run_command",
            {"command": f"(sleep 2; touch {marker.name}) & sleep 10", "_timeout": 1},
            str(self.root))
        self.assertIn("killed", result)
        _time.sleep(2.5)
        self.assertFalse(marker.exists(), "background child survived the timeout kill")

    def test_workspace_danger(self):
        from forge.tools import workspace_danger
        self.assertIsNotNone(workspace_danger(str(Path.home())))
        self.assertIsNone(workspace_danger(str(self.root)))


class ContainedRunTests(unittest.TestCase):
    """Contained run (2026-11-09): the opt-in cage at the tool layer.
    OFF (no containment argument at all) must behave exactly as
    before; ON confines file paths and commands to the project root,
    with the FULL resolved path as the thing checked."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name).resolve()
        self.outside_temp = tempfile.TemporaryDirectory()
        self.outside = Path(self.outside_temp.name).resolve()
        from forge.tools import Containment
        self.cage = Containment(str(self.root))

    def tearDown(self):
        self.temp.cleanup()
        self.outside_temp.cleanup()

    def test_inside_path_allowed(self):
        result = execute_tool(
            "write_file", {"path": "src/demo.txt", "content": "caged"},
            str(self.root), containment=self.cage)
        self.assertIn("Wrote src/demo.txt", result)
        self.assertEqual(
            execute_tool("read_file", {"path": "src/demo.txt"},
                         str(self.root), containment=self.cage),
            "caged")
        # An ABSOLUTE path that still lands inside the root is fine.
        self.assertEqual(
            execute_tool(
                "read_file",
                {"path": str(self.root / "src" / "demo.txt")},
                str(self.root), containment=self.cage),
            "caged")

    def test_outside_absolute_path_denied(self):
        target = self.outside / "escape.txt"
        with self.assertRaises(ToolError) as ctx:
            execute_tool(
                "write_file", {"path": str(target), "content": "x"},
                str(self.root), containment=self.cage)
        self.assertIn("Contained run is ON", str(ctx.exception))
        self.assertFalse(target.exists())

    def test_dotdot_escape_denied(self):
        import os
        rel = os.path.relpath(self.outside / "escape2.txt", self.root)
        self.assertTrue(rel.startswith(".."))
        with self.assertRaises(ToolError) as ctx:
            execute_tool(
                "write_file", {"path": rel, "content": "x"},
                str(self.root), containment=self.cage)
        self.assertIn("Contained run is ON", str(ctx.exception))
        self.assertFalse((self.outside / "escape2.txt").exists())

    def test_symlink_escape_denied(self):
        secret = self.outside / "secret.txt"
        secret.write_text("not yours")
        (self.root / "link.txt").symlink_to(secret)
        with self.assertRaises(ToolError) as ctx:
            execute_tool("read_file", {"path": "link.txt"},
                         str(self.root), containment=self.cage)
        # The cage's own refusal — the realpath check saw through the
        # link before the workspace jail was even consulted.
        self.assertIn("Contained run is ON", str(ctx.exception))

    def test_run_command_cwd_locked_to_root(self):
        result = execute_tool("run_command", {"command": "pwd"},
                              str(self.root), containment=self.cage)
        self.assertIn("Exit code: 0", result)
        self.assertIn(str(self.root), result)

    def test_run_command_outside_references_blocked(self):
        for command in ("cat /etc/hostname",
                        "cd /tmp && pwd",
                        "cd .. && pwd",
                        "cp src.txt ../stolen.txt"):
            with self.assertRaises(ToolError, msg=command) as ctx:
                execute_tool("run_command", {"command": command},
                             str(self.root), containment=self.cage)
            self.assertIn("not an OS sandbox", str(ctx.exception),
                          msg=command)

    def test_run_command_dev_null_idiom_still_runs(self):
        result = execute_tool(
            "run_command", {"command": "echo caged 2>/dev/null"},
            str(self.root), containment=self.cage)
        self.assertIn("caged", result)

    def test_off_means_old_behavior(self):
        # File tools: the pre-existing workspace jail answers with
        # its OWN message — no contained-run refusal appears.
        with self.assertRaises(ToolError) as ctx:
            execute_tool(
                "write_file",
                {"path": str(self.outside / "x.txt"), "content": "x"},
                str(self.root))
        self.assertNotIn("Contained run", str(ctx.exception))
        self.assertIn("outside the active workspace", str(ctx.exception))
        self.assertFalse((self.outside / "x.txt").exists())
        # Commands: no cage — leaving the folder works, as before.
        result = execute_tool("run_command",
                              {"command": "cd /tmp && pwd"}, str(self.root))
        self.assertIn("Exit code: 0", result)
        self.assertIn("/tmp", result)

    def test_docker_unavailable_falls_back_with_note(self):
        from unittest import mock
        from forge import tools as tools_mod
        cage = tools_mod.Containment(str(self.root), docker=True)
        with mock.patch.object(tools_mod, "_docker_available",
                               return_value=False):
            result = execute_tool("run_command", {"command": "pwd"},
                                  str(self.root), containment=cage)
        self.assertIn("Docker was requested but", result)
        # ...and the command still ran, locally, cwd locked to root.
        self.assertIn(str(self.root), result)

    def test_docker_argv_mounts_only_the_project(self):
        from forge.tools import _docker_argv
        argv = _docker_argv("/some/project", "python:3-slim", "make thing")
        self.assertEqual(argv[:3], ["docker", "run", "--rm"])
        self.assertEqual(argv[argv.index("-v") + 1], "/some/project:/work")
        self.assertEqual(argv[argv.index("-w") + 1], "/work")
        self.assertEqual(argv[-4:], ["python:3-slim", "sh", "-c", "make thing"])
        # Exactly one mount in the whole invocation — the cage.
        self.assertEqual(argv.count("-v"), 1)

    def test_plugin_path_args_cage(self):
        from forge.tools import contained_args_refusal
        self.assertIsNone(contained_args_refusal(
            str(self.root), {"path": "inside.txt"}))
        self.assertIsNone(contained_args_refusal(
            str(self.root), {"word": "no path argument here"}))
        refusal = contained_args_refusal(
            str(self.root), {"path": str(self.outside / "x.txt")})
        self.assertIn("Contained run is ON", refusal)

    def test_settings_dialog_round_trips_contained_keys(self):
        from PySide6.QtWidgets import QApplication
        app = QApplication.instance() or QApplication([])
        from forge.main import SettingsDialog
        dlg = SettingsDialog(None, {})
        try:
            values = dlg.values()
            self.assertFalse(values["contained_run"])       # default OFF
            self.assertFalse(values["contained_docker"])    # default OFF
            self.assertEqual(values["contained_docker_image"],
                             "python:3-slim")
            dlg.contained_run.setChecked(True)
            dlg.contained_docker.setChecked(True)
            dlg.contained_docker_image.setText("debian:bookworm-slim")
            values = dlg.values()
            self.assertTrue(values["contained_run"])
            self.assertTrue(values["contained_docker"])
            self.assertEqual(values["contained_docker_image"],
                             "debian:bookworm-slim")
        finally:
            dlg.close()
        dlg2 = SettingsDialog(None, {"contained_run": True,
                                     "contained_docker": True,
                                     "contained_docker_image": "alpine:3"})
        try:
            self.assertTrue(dlg2.contained_run.isChecked())
            self.assertTrue(dlg2.contained_docker.isChecked())
            self.assertEqual(dlg2.contained_docker_image.text(), "alpine:3")
        finally:
            dlg2.close()


class _ScriptedClient:
    """Plays a fixed script of assistant responses, one per request."""
    def __init__(self, script):
        self.script = list(script)
        self.calls = 0

    def chat_stream(self, model, messages, options, schemas, keep_alive=None):
        self.calls += 1
        item = self.script.pop(0) if self.script else {"content": "end"}
        if "tool" in item:
            yield {"message": {"content": "", "tool_calls": [
                {"function": {"name": item["tool"], "arguments": item.get("args", {})}}]}}
        else:
            yield {"message": {"content": item["content"], "tool_calls": []}}


def _ping_schema():
    return {"type": "function",
            "function": {"name": "ping_tool", "description": "test",
                         "parameters": {"type": "object",
                                        "properties": {"word": {"type": "string"}},
                                        "required": ["word"]}}}


class HardeningTests(unittest.TestCase):
    def _run(self, script, handler):
        from forge.worker import AgentWorker
        extra = {"ping_tool": (_ping_schema(), handler, False, "test")}
        worker = AgentWorker(_ScriptedClient(script), "fake",
                             [{"role": "user", "content": "go"}], {},
                             tempfile.mkdtemp(), extra_tools=extra)
        worker.run()
        return [m.get("content", "") for m in worker.messages if m.get("role") == "tool"]

    def test_identical_repeats_blocked(self):
        hits = {"n": 0}
        def handler(args):
            hits["n"] += 1
            return "pong"
        script = [{"tool": "ping_tool", "args": {"word": "a"}}] * 5 + [{"content": "done"}]
        results = self._run(script, handler)
        self.assertEqual(hits["n"], 2)  # executed twice, then refused as a loop
        self.assertTrue(any("already run this exact" in r for r in results))

    def test_missing_arg_gets_schema_hint(self):
        hits = {"n": 0}
        def handler(args):
            hits["n"] += 1
            return "pong"
        script = [{"tool": "ping_tool", "args": {}},
                  {"tool": "ping_tool", "args": {"word": "ok"}},
                  {"content": "done"}]
        results = self._run(script, handler)
        self.assertEqual(hits["n"], 1)
        self.assertIn("missing required argument", results[0])
        self.assertIn("word (string, required)", results[0])


class HookTests(unittest.TestCase):
    def _worker(self, script, workspace, **kw):
        from forge.worker import AgentWorker
        extra = {"ping_tool": (_ping_schema(), kw.pop("handler", lambda a: "pong"), False, "test")}
        worker = AgentWorker(_ScriptedClient(script), "fake",
                             [{"role": "user", "content": "go"}], {},
                             str(workspace), extra_tools=extra, **kw)
        worker.approval_needed.connect(lambda *a: worker.resolve_approval(True))
        return worker

    def test_pre_tool_hook_blocks(self):
        hits = {"n": 0}
        def handler(args):
            hits["n"] += 1
            return "pong"
        ws = Path(tempfile.mkdtemp())
        w = self._worker([{"tool": "ping_tool", "args": {"word": "a"}}, {"content": "done"}],
                         ws, handler=handler,
                         hooks=[{"event": "pre_tool", "command": "echo nope; exit 1"}])
        w.run()
        self.assertEqual(hits["n"], 0)
        tools = [m["content"] for m in w.messages if m.get("role") == "tool"]
        self.assertIn("Blocked by your pre_tool hook", tools[0])

    def test_verify_loop_reports_failure_then_pass(self):
        ws = Path(tempfile.mkdtemp())
        (ws / "check.py").write_text("import sys; print('boom'); sys.exit(1)")
        script = [{"tool": "write_file", "args": {"path": "a.py", "content": "x = 1"}},
                  {"content": "done"}]
        w = self._worker(script, ws, verify_commands=[f"python3 check.py"])
        # write_file is a builtin; swap the script tool name mapping: the
        # scripted client emits any tool name, builtins included.
        w.run()
        tools = [m["content"] for m in w.messages if m.get("role") == "tool"]
        self.assertTrue(any("[verify FAILED]" in t and "boom" in t for t in tools))
        (ws / "check.py").write_text("print('fine')")
        w2 = self._worker(script, ws, verify_commands=["python3 check.py"])
        w2.run()
        tools2 = [m["content"] for m in w2.messages if m.get("role") == "tool"]
        self.assertTrue(any("all project checks passed" in t for t in tools2))

    def test_stop_hook_bounces_until_bound(self):
        ws = Path(tempfile.mkdtemp())
        script = [{"content": f"try{i}"} for i in range(6)]
        w = self._worker(script, ws, hooks=[{"event": "stop", "command": "exit 1"}])
        w.run()
        self.assertEqual(w.client.calls, 4)  # initial + 3 bounces, then it may end
        self.assertTrue(any("stop hook" in m.get("content", "")
                            for m in w.messages if m.get("role") == "user"))


class MechanicalCheckTests(unittest.TestCase):
    """Audit D40 (unit half): mechanical_check is parse-level only —
    the standard parsers judge, so a clean verdict cannot be a
    false positive, and anything unjudgeable comes back (None, "")."""

    def setUp(self):
        self.ws = Path(tempfile.mkdtemp())

    def _put(self, name, content):
        target = self.ws / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")

    def test_valid_python_parses(self):
        from forge.worker import mechanical_check
        self._put("ok.py", "x = 1\n")
        self.assertEqual(mechanical_check(str(self.ws), "ok.py"), (True, ""))

    def test_invalid_python_names_the_line(self):
        from forge.worker import mechanical_check
        self._put("bad.py", "x = 1\ndef broken(:\n")
        ok, err = mechanical_check(str(self.ws), "bad.py")
        self.assertFalse(ok)
        self.assertTrue(err.startswith("SyntaxError"), err)
        self.assertIn("line 2", err)

    def test_json_valid_and_invalid(self):
        from forge.worker import mechanical_check
        self._put("ok.json", '{"a": 1}\n')
        self.assertEqual(mechanical_check(str(self.ws), "ok.json"), (True, ""))
        self._put("bad.json", '{"a": }\n')
        ok, err = mechanical_check(str(self.ws), "bad.json")
        self.assertFalse(ok)
        self.assertTrue(err.startswith("JSONDecodeError"), err)
        self.assertIn("line 1", err)

    def test_toml_valid_and_invalid(self):
        import importlib.util
        if importlib.util.find_spec("tomllib") is None:
            self.skipTest("tomllib is not available on this Python")
        from forge.worker import mechanical_check
        self._put("ok.toml", 'title = "x"\n')
        self.assertEqual(mechanical_check(str(self.ws), "ok.toml"), (True, ""))
        self._put("bad.toml", "title = \n")
        ok, err = mechanical_check(str(self.ws), "bad.toml")
        self.assertFalse(ok)
        self.assertIn("TOMLDecodeError", err)

    def test_unchecked_extension_and_missing_file(self):
        from forge.worker import mechanical_check
        self._put("notes.txt", "anything at all (:\n")
        self.assertEqual(mechanical_check(str(self.ws), "notes.txt"), (None, ""))
        self.assertEqual(mechanical_check(str(self.ws), "ghost.py"), (None, ""))

    def test_path_outside_workspace_is_not_judged(self):
        from forge.worker import mechanical_check
        # The read goes through the tools' jail: an escaping path is
        # "nothing to judge", never a read of the outside file.
        self.assertEqual(mechanical_check(str(self.ws), "../outside.py"), (None, ""))


def _edit_file_schema():
    return {"type": "function",
            "function": {"name": "edit_file", "description": "test edit tool",
                         "parameters": {"type": "object",
                                        "properties": {"path": {"type": "string"},
                                                       "old_text": {"type": "string"},
                                                       "new_text": {"type": "string"}},
                                        "required": ["path", "old_text", "new_text"]}}}


class MechanicalVerifyWorkerTests(unittest.TestCase):
    """Audit D40 (worker half): the mechanical verdict rides the
    tool result in the same turn; strikes accumulate on mechanical
    failures alone (no verify commands configured); appends earn a
    note, never a strike; edit_file joins the post-edit feedback
    path it used to skip."""

    def _worker(self, script, workspace, **kw):
        from forge.worker import AgentWorker
        worker = AgentWorker(_ScriptedClient(script), "fake",
                             [{"role": "user", "content": "go"}], {},
                             str(workspace), **kw)
        worker.approval_needed.connect(lambda *a: worker.resolve_approval(True))
        return worker

    def _tools(self, worker):
        return [m["content"] for m in worker.messages if m.get("role") == "tool"]

    def test_broken_write_then_fixed_write(self):
        ws = Path(tempfile.mkdtemp())
        script = [{"tool": "write_file", "args": {"path": "a.py", "content": "def broken(:\n"}},
                  {"tool": "write_file", "args": {"path": "a.py", "content": "x = 1\n"}},
                  {"content": "done"}]
        w = self._worker(script, ws)  # no verify_commands: mechanical alone
        w.run()
        tools = self._tools(w)
        self.assertIn("[syntax FAILED]", tools[0])
        self.assertIn("a.py", tools[0])
        self.assertIn("[syntax] a.py parses cleanly.", tools[1])
        self.assertEqual(w._verify_fails.get("a.py"), 0)

    def test_three_broken_writes_hit_the_strike_line(self):
        ws = Path(tempfile.mkdtemp())
        script = [{"tool": "write_file", "args": {"path": "a.py", "content": "x = (\n"}},
                  {"tool": "write_file", "args": {"path": "a.py", "content": "y = )\n"}},
                  {"tool": "write_file", "args": {"path": "a.py", "content": "def nope(:\n"}},
                  {"content": "done"}]
        w = self._worker(script, ws)
        w.run()
        tools = self._tools(w)
        self.assertIn("[syntax FAILED]", tools[0])
        self.assertNotIn("times in a row", tools[0])
        self.assertNotIn("times in a row", tools[1])
        self.assertIn("has failed verification 3 times in a row", tools[2])
        self.assertIn("summarize the failure for the owner", tools[2])
        self.assertEqual(w._verify_fails.get("a.py"), 3)

    def test_edit_file_landing_a_broken_edit_gets_syntax_feedback(self):
        # Write/Research modes (2026-11-09): edit_file is a built-in
        # now, so the D40 behavior is asserted against the real
        # tool. (It used to ride a plugin-registered stand-in, from
        # the era when no built-in edit_file existed — the built-in
        # shadows any same-named plugin registration by design.)
        ws = Path(tempfile.mkdtemp())
        (ws / "a.py").write_text("x = 1\n", encoding="utf-8")
        script = [{"tool": "edit_file",
                   "args": {"path": "a.py", "old_text": "x = 1", "new_text": "x = ("}},
                  {"content": "done"}]
        w = self._worker(script, ws)
        w.run()
        tools = self._tools(w)
        self.assertTrue(tools[0].startswith("Edited a.py"), tools[0])
        self.assertIn("[syntax FAILED]", tools[0])
        self.assertIn("a.py", tools[0])
        self.assertEqual(w._verify_fails.get("a.py"), 1)

    def test_append_mid_build_earns_a_note_never_a_strike(self):
        ws = Path(tempfile.mkdtemp())
        script = [{"tool": "append_file",
                   "args": {"path": "a.py", "content": "def f():\n    return (\n"}},
                  {"tool": "append_file",
                   "args": {"path": "a.py", "content": "        1)\n"}},
                  {"content": "done"}]
        w = self._worker(script, ws)
        w.run()
        tools = self._tools(w)
        self.assertIn("[syntax note] a.py does not parse yet:", tools[0])
        self.assertNotIn("[syntax FAILED]", tools[0])
        # The completing chunk parses — and appends stay quiet on success.
        self.assertNotIn("[syntax", tools[1])
        self.assertEqual(w._verify_fails, {})


class HookSubstitutionTests(unittest.TestCase):
    """Audit item A13 (LEG 6): {path} used to be substituted into
    shell=True hook commands UNQUOTED — a path with spaces or a
    $()/backtick payload was interpreted by the shell — and a
    non-numeric hook timeout raised inside run_hook, faulting the
    turn. The path is now shlex-quoted and a bad timeout falls back
    to the module default."""

    def test_path_placeholder_is_shell_quoted(self):
        from forge.hooks import run_event
        with tempfile.TemporaryDirectory() as tmp:
            ws = Path(tmp)
            evil = "sub dir/$(touch PWNED)file.txt"
            hooks = [{"event": "post_edit",
                      "command": "printf '%s' {path} > quoted_out.txt"}]
            results = run_event(hooks, "post_edit", str(ws),
                                tool="write_file", path=evil)
            self.assertEqual(len(results), 1)
            self.assertEqual(results[0][1], 0)
            # The command received the path as literal data...
            self.assertEqual((ws / "quoted_out.txt").read_text(encoding="utf-8"), evil)
            # ...and the $() bait never executed.
            self.assertFalse((ws / "PWNED").exists())

    def test_non_numeric_timeout_falls_back_to_default(self):
        from forge.hooks import run_event
        with tempfile.TemporaryDirectory() as tmp:
            hooks = [{"event": "session_start", "command": "echo hi",
                      "timeout": "abc"}]
            results = run_event(hooks, "session_start", tmp)
            self.assertEqual(len(results), 1)
            self.assertEqual(results[0][1], 0)
            self.assertEqual(results[0][2], "hi")


class HookLoadProblemsTests(unittest.TestCase):
    """Audit C30 (half B): load_hooks used to swallow every problem —
    a malformed hooks.json yielded no project hooks, forever, with
    no trace. It now returns (hooks, problems) so the caller can
    surface what is broken. A missing file stays a non-problem, and
    merging keeps the old later-sources-win-by-order semantics."""

    def _write(self, root, name, text):
        p = Path(root) / name
        p.write_text(text, encoding="utf-8")
        return p

    def test_garbage_json_reports_a_problem_naming_the_path(self):
        from forge.hooks import load_hooks
        with tempfile.TemporaryDirectory() as tmp:
            p = self._write(tmp, "hooks.json", "{not json")
            hooks, problems = load_hooks(p)
            self.assertEqual(hooks, [])
            self.assertEqual(len(problems), 1)
            self.assertIn(str(p), problems[0])
            self.assertIn("could not be read as JSON", problems[0])

    def test_non_list_top_level_reports_a_problem(self):
        from forge.hooks import load_hooks
        with tempfile.TemporaryDirectory() as tmp:
            p = self._write(tmp, "hooks.json", json.dumps({"event": "stop"}))
            hooks, problems = load_hooks(p)
            self.assertEqual(hooks, [])
            self.assertEqual(len(problems), 1)
            self.assertIn(str(p), problems[0])
            self.assertIn("expected a JSON list of hooks", problems[0])

    def test_bad_entries_are_counted_and_good_ones_kept(self):
        from forge.hooks import load_hooks
        good = {"event": "stop", "command": "echo ok"}
        with tempfile.TemporaryDirectory() as tmp:
            p = self._write(tmp, "hooks.json",
                            json.dumps([good, "junk", {"event": "stop"}]))
            hooks, problems = load_hooks(p)
            self.assertEqual(hooks, [good])
            self.assertEqual(len(problems), 1)
            self.assertIn(str(p), problems[0])
            self.assertIn("2 hook entries skipped", problems[0])

    def test_valid_file_has_no_problems(self):
        from forge.hooks import load_hooks
        good = {"event": "stop", "command": "echo ok"}
        with tempfile.TemporaryDirectory() as tmp:
            p = self._write(tmp, "hooks.json", json.dumps([good]))
            hooks, problems = load_hooks(p)
            self.assertEqual(hooks, [good])
            self.assertEqual(problems, [])

    def test_missing_file_is_not_a_problem(self):
        from forge.hooks import load_hooks
        with tempfile.TemporaryDirectory() as tmp:
            hooks, problems = load_hooks(Path(tmp) / "nope.json")
            self.assertEqual(hooks, [])
            self.assertEqual(problems, [])

    def test_multiple_sources_merge_and_each_reports(self):
        from forge.hooks import load_hooks
        h1 = {"event": "stop", "command": "echo one"}
        h2 = {"event": "stop", "command": "echo two"}
        with tempfile.TemporaryDirectory() as tmp:
            a = self._write(tmp, "a.json", json.dumps([h1]))
            bad = self._write(tmp, "bad.json", "nope")
            b = self._write(tmp, "b.json", json.dumps([h2]))
            hooks, problems = load_hooks(a, bad, b)
            self.assertEqual(hooks, [h1, h2])
            self.assertEqual(len(problems), 1)
            self.assertIn(str(bad), problems[0])


class HookProblemsWindowTests(unittest.TestCase):
    """Audit C30 (window half): _turn_config surfaces project hook
    config problems in the log — once per distinct problem for the
    life of the window, not once per turn (it runs every turn) — and
    the settings hooks still reach the turn unchanged."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        forge_dir = root / ".forge"
        forge_dir.mkdir(parents=True)
        (forge_dir / "hooks.json").write_text("{broken json", encoding="utf-8")
        self._old_workspace = self.win.workspace
        self.win.workspace = str(root)
        self._had_hooks = "hooks" in self.win.settings
        self._old_hooks = self.win.settings.get("hooks")
        self.global_hook = {"event": "stop", "command": "echo global"}
        self.win.settings["hooks"] = [self.global_hook]
        self.hooks_path = str(forge_dir / "hooks.json")

    def tearDown(self):
        if self._had_hooks:
            self.win.settings["hooks"] = self._old_hooks
        else:
            self.win.settings.pop("hooks", None)
        self.win.save_settings()
        self.win.workspace = self._old_workspace
        self.win.worker = None
        self.temp.cleanup()

    def _problem_lines(self):
        return [line for line in self.win._log_lines
                if "Hooks:" in line and self.hooks_path in line]

    def test_broken_project_hooks_logged_once_and_settings_hooks_kept(self):
        hooks, _verify = self.win._turn_config()
        self.assertEqual(hooks, [self.global_hook])
        self.assertEqual(len(self._problem_lines()), 1)
        # A second turn does not log the same problem again.
        hooks2, _verify2 = self.win._turn_config()
        self.assertEqual(hooks2, [self.global_hook])
        self.assertEqual(len(self._problem_lines()), 1)


class RepoMapTests(unittest.TestCase):
    def test_map_lists_symbols_and_ranks_referenced_first(self):
        from forge import repomap
        ws = Path(tempfile.mkdtemp())
        (ws / "core.py").write_text("class Engine:\n    def start(self):\n        pass\n\ndef helper(x, y):\n    return x + y\n")
        (ws / "app.py").write_text("from core import Engine\n\ndef main():\n    pass\n")
        (ws / ".venv").mkdir()
        (ws / ".venv" / "junk.py").write_text("def junk():\n    pass\n")
        text = repomap.build_map(str(ws))
        self.assertIn("class Engine: start", text)
        self.assertIn("def helper(x, y)", text)
        self.assertIn("def main()", text)
        self.assertNotIn("junk", text)
        self.assertLess(text.index("core.py"), text.index("app.py"))  # referenced file ranks first

    def test_map_respects_budget(self):
        from forge import repomap
        ws = Path(tempfile.mkdtemp())
        for i in range(30):
            (ws / f"f{i:02}.py").write_text("\n".join(f"def fn{i}_{j}():\n    pass" for j in range(10)))
        text = repomap.build_map(str(ws), budget_chars=600)
        self.assertLessEqual(len(text), 900)
        self.assertIn("more file(s) not shown", text)


class ForkTests(unittest.TestCase):
    def test_fork_copies_prefix_and_leaves_original(self):
        store = ConversationStore(Path(tempfile.mkdtemp()) / "c.db")
        msgs = [{"role": "system", "content": "sys"},
                {"role": "user", "content": "first ask"},
                {"role": "assistant", "content": "first answer"},
                {"role": "user", "content": "second ask"}]
        cid = store.save(None, msgs, model="m1", project="/p")
        fid = store.fork(cid, 2)
        self.assertIsNotNone(fid)
        forked = store.load(fid)
        self.assertEqual(len(forked), 3)
        self.assertEqual(forked[-1]["content"], "first answer")
        self.assertEqual(len(store.load(cid)), 4)  # original untouched
        rows = {r["id"]: r for r in store.recent()}
        self.assertIn("(fork)", rows[fid]["title"])
        self.assertEqual(store.meta(fid), ("m1", "/p"))


class PermissionTests(unittest.TestCase):
    def test_rule_precedence(self):
        from forge.permissions import evaluate_rules
        rules = [{"scope": "global", "tool": "*", "pattern": "*", "action": "allow"},
                 {"scope": "global", "tool": "run_command", "pattern": "rm *", "action": "deny"}]
        self.assertEqual(evaluate_rules(rules, "run_command", "rm -rf x"), "deny")
        # H2 narrowing (called out): an old-shape GLOBAL allow no
        # longer auto-approves a command — remembered command rules
        # must be exact + project-scoped (TrustCompletionTests pins
        # the new shape). Deny above and the file-tool allow below
        # are unchanged.
        self.assertEqual(evaluate_rules(rules, "run_command", "ls"), "ask")
        self.assertEqual(evaluate_rules(rules, "write_file", "a.py"), "allow")
        self.assertEqual(evaluate_rules([], "run_command", "ls"), "ask")

    def test_modes(self):
        from forge.permissions import mode_allows, mode_visible_tools
        self.assertFalse(mode_allows("ask", "write_file", {"path": "a.py"})[0])
        self.assertTrue(mode_allows("ask", "read_file", {"path": "a.py"})[0])
        self.assertTrue(mode_allows("architect", "write_file", {"path": "notes.md"})[0])
        self.assertFalse(mode_allows("architect", "write_file", {"path": "a.py"})[0])
        self.assertFalse(mode_allows("architect", "run_command", {"command": "ls"})[0])
        self.assertEqual(mode_visible_tools("ask", ["read_file", "write_file", "run_command"]),
                         ["read_file"])

    def _worker(self, script, **kw):
        from forge.worker import AgentWorker
        extra = {"ping_tool": (_ping_schema(), lambda a: "pong", True, "test")}  # approval-class tool
        worker = AgentWorker(_ScriptedClient(script), "fake",
                             [{"role": "user", "content": "go"}], {},
                             tempfile.mkdtemp(), extra_tools=extra, **kw)
        worker.approval_needed.connect(lambda *a: worker.resolve_approval(True))
        return worker

    def test_rule_allow_skips_dialog_and_deny_blocks(self):
        rules = [{"scope": "global", "tool": "ping_tool", "pattern": "*", "action": "allow"}]
        w = self._worker([{"tool": "ping_tool", "args": {"word": "a"}}, {"content": "done"}],
                         permissions={"rules": rules, "mode": "code", "classes": {"ping_tool": "write"}})
        asked = {"n": 0}
        w.approval_needed.connect(lambda *a: asked.__setitem__("n", asked["n"] + 1))
        w.run()
        self.assertEqual(asked["n"], 0)  # rule allowed it — no dialog
        rules = [{"scope": "global", "tool": "ping_tool", "pattern": "*", "action": "deny"}]
        w2 = self._worker([{"tool": "ping_tool", "args": {"word": "a"}}, {"content": "done"}],
                          permissions={"rules": rules, "mode": "code", "classes": {"ping_tool": "write"}})
        w2.run()
        tools = [m["content"] for m in w2.messages if m.get("role") == "tool"]
        self.assertIn("Denied by your permission rule", tools[0])

    def test_ask_mode_blocks_write_tool(self):
        w = self._worker([{"tool": "ping_tool", "args": {"word": "a"}}, {"content": "done"}],
                         permissions={"rules": [], "mode": "ask", "classes": {"ping_tool": "write"}})
        w.run()
        tools = [m["content"] for m in w.messages if m.get("role") == "tool"]
        self.assertIn("ASK (read-only)", tools[0])


class TrustCompletionTests(unittest.TestCase):
    """H2 — trust completion: the sensitive-file carve-out (never
    auto-approved, never remembered), scoped remembering for
    commands (exact command, exact project), and the approval risk
    label shared by the desktop dialog and the phone deck."""

    # -- the sensitive matcher ---------------------------------------

    def test_sensitive_path_matcher(self):
        from forge.permissions import is_sensitive_path
        for path in (".env", "config/.env", ".env.local", ".env.production",
                     "certs/server.pem", "keys/app.key", "id_rsa",
                     "home/id_ed25519.pub", "id_rsa.pub",
                     "a/b/credentials.json", "credentials", "mysecret.txt",
                     "src/app_secret.py", ".ssh/config",
                     "proj/.aws/credentials", "x/.gnupg/gpg.conf",
                     "connectors.json", "vault.json", "vault.key",
                     "cert.p12", "cert.pfx", ".netrc", "~/.ssh/id_rsa"):
            self.assertTrue(is_sensitive_path(path), path)
        for path in (".env.example", ".env.sample", ".env.template",
                     "src/main.py", "notes.md", "env.py", ".envrc",
                     "keyboard.py", "monkey.txt", "a/key", ""):
            self.assertFalse(is_sensitive_path(path), path)

    def test_command_references_sensitive(self):
        from forge.permissions import command_references_sensitive
        for cmd in ("cat .env", "cp .env .env.bak", "source .env",
                    "openssl rsa -in key.pem", "cat ~/.ssh/id_rsa",
                    "ssh -i ~/.ssh/id_ed25519 host", "cat .env | head",
                    "run --env-file=.env", "less proj/.aws/credentials"):
            self.assertTrue(command_references_sensitive(cmd), cmd)
        for cmd in ("ls -la", "python app.py", "echo .env.example",
                    "cat notes.md", "make test", ""):
            self.assertFalse(command_references_sensitive(cmd), cmd)

    # -- the carve-out at evaluate_rules ------------------------------

    def test_carve_out_beats_remembered_allow(self):
        from forge.permissions import evaluate_rules
        allow_all = [{"scope": "global", "tool": "*", "pattern": "*",
                      "action": "allow"}]
        self.assertEqual(evaluate_rules(allow_all, "write_file", ".env"), "ask")
        self.assertEqual(evaluate_rules(allow_all, "write_file", "src/.env"), "ask")
        self.assertEqual(evaluate_rules(allow_all, "read_file", ".env"), "ask")
        self.assertEqual(evaluate_rules(allow_all, "write_file", "a.py"), "allow")
        # Even a rule naming the sensitive file itself cannot
        # auto-approve it…
        exact = [{"scope": "global", "tool": "write_file", "pattern": ".env",
                  "action": "allow"}]
        self.assertEqual(evaluate_rules(exact, "write_file", ".env"), "ask")
        # …but an owner's deny still denies (deny is not an
        # approval path, and it always won).
        with_deny = exact + [{"scope": "global", "tool": "write_file",
                              "pattern": ".env", "action": "deny"}]
        self.assertEqual(evaluate_rules(with_deny, "write_file", ".env"), "deny")

    def test_command_carve_out_beats_even_exact_rule(self):
        from forge.permissions import evaluate_rules, fnmatch_escape
        rule = {"scope": "/p", "tool": "run_command",
                "pattern": fnmatch_escape("cat .env"),
                "action": "allow", "exact": True}
        self.assertEqual(evaluate_rules([rule], "run_command", "cat .env", "/p"),
                         "ask")
        ok = {"scope": "/p", "tool": "run_command",
              "pattern": fnmatch_escape("cat notes.md"),
              "action": "allow", "exact": True}
        self.assertEqual(evaluate_rules([ok], "run_command", "cat notes.md", "/p"),
                         "allow")

    # -- scoped remembering -------------------------------------------

    def test_command_rule_is_exact_and_project_scoped(self):
        from forge.permissions import evaluate_rules, fnmatch_escape
        rule = {"scope": "/p", "tool": "run_command",
                "pattern": fnmatch_escape("ls -la"),
                "action": "allow", "exact": True}
        self.assertEqual(evaluate_rules([rule], "run_command", "ls -la", "/p"),
                         "allow")
        # A different command in the same project asks.
        self.assertEqual(evaluate_rules([rule], "run_command", "ls -la /tmp", "/p"),
                         "ask")
        # The same command in a different project asks.
        self.assertEqual(evaluate_rules([rule], "run_command", "ls -la", "/q"),
                         "ask")
        # No project named: no remembered command allow can apply.
        self.assertEqual(evaluate_rules([rule], "run_command", "ls -la"), "ask")
        # The glob trap: a remembered 'ls *.py' matches only itself,
        # never the commands the glob would have covered.
        glob_rule = {"scope": "/p", "tool": "run_command",
                     "pattern": fnmatch_escape("ls *.py"),
                     "action": "allow", "exact": True}
        self.assertEqual(evaluate_rules([glob_rule], "run_command", "ls *.py", "/p"),
                         "allow")
        self.assertEqual(evaluate_rules([glob_rule], "run_command", "ls foo.py", "/p"),
                         "ask")

    def test_old_shape_command_rules_stop_approving(self):
        from forge.permissions import evaluate_rules
        old_literal = [{"scope": "global", "tool": "run_command",
                        "pattern": "ls -la", "action": "allow"}]
        self.assertEqual(evaluate_rules(old_literal, "run_command", "ls -la", "/p"),
                         "ask")
        old_wild = [{"scope": "global", "tool": "run_command",
                     "pattern": "*", "action": "allow"}]
        self.assertEqual(evaluate_rules(old_wild, "run_command", "ls -la", "/p"),
                         "ask")
        unmarked = [{"scope": "/p", "tool": "run_command",
                     "pattern": "ls -la", "action": "allow"}]
        self.assertEqual(evaluate_rules(unmarked, "run_command", "ls -la", "/p"),
                         "ask")
        # Old-shape DENY keeps denying — only approval retired.
        old_deny = [{"scope": "global", "tool": "run_command",
                     "pattern": "rm *", "action": "deny"}]
        self.assertEqual(evaluate_rules(old_deny, "run_command", "rm -rf x", "/p"),
                         "deny")

    def test_old_shape_rules_load_without_crashing(self):
        from forge.permissions import evaluate_rules
        for rules in ([{}], [{"action": "allow"}], [{"scope": "global"}],
                      [{"tool": "run_command", "action": "allow", "exact": True}]):
            self.assertEqual(evaluate_rules(rules, "run_command", "ls", "/p"), "ask")
            self.assertEqual(evaluate_rules(rules, "write_file", "a.py", "/p"), "ask")

    def test_file_rules_were_already_exact(self):
        # The verification H2 asked for: a dialog file rule stores
        # the literal path, and fnmatch on a literal path matches
        # that path only — no tree, no siblings, no other root.
        from forge.permissions import evaluate_rules
        rule = [{"scope": "global", "tool": "write_file",
                 "pattern": "src/a.py", "action": "allow"}]
        self.assertEqual(evaluate_rules(rule, "write_file", "src/a.py"), "allow")
        self.assertEqual(evaluate_rules(rule, "write_file", "src/sub/a.py"), "ask")
        self.assertEqual(evaluate_rules(rule, "write_file", "src/a.py.bak"), "ask")
        self.assertEqual(evaluate_rules(rule, "write_file", "other/src/a.py"), "ask")

    def test_fnmatch_escape_round_trip(self):
        import fnmatch
        from forge.permissions import fnmatch_escape
        for text in ("ls *.py", "a?b", "x[0].txt", "plain", "rm -rf /tmp/x"):
            self.assertTrue(fnmatch.fnmatch(text, fnmatch_escape(text)), text)
        self.assertFalse(fnmatch.fnmatch("ls foo.py", fnmatch_escape("ls *.py")))
        self.assertFalse(fnmatch.fnmatch("axb", fnmatch_escape("a?b")))

    # -- the risk classifier -------------------------------------------

    def test_classify_risk_wording(self):
        from forge.permissions import classify_risk
        self.assertEqual(classify_risk("write_file", "src/a.py", "/ws"),
                         ("Reversible · inside this project", "calm"))
        self.assertEqual(classify_risk("append_file", "src/a.py", "/ws"),
                         ("Reversible · inside this project", "calm"))
        self.assertEqual(classify_risk("write_file", "/etc/x.conf", "/ws"),
                         ("Hard to undo · outside this project", "caution"))
        self.assertEqual(classify_risk("write_file", "../x.py", "/ws"),
                         ("Hard to undo · outside this project", "caution"))
        self.assertEqual(classify_risk("run_command", "ls -la", "/ws"),
                         ("Runs a command on this PC", "caution"))
        self.assertEqual(classify_risk("run_command", "cat .env", "/ws"),
                         ("Runs a command on this PC · touches a sensitive file",
                          "caution"))
        self.assertEqual(classify_risk("write_file", ".env", "/ws"),
                         ("Sensitive file · always asks", "caution"))
        self.assertEqual(classify_risk("read_file", "src/a.py", "/ws"),
                         ("Read-only · makes no changes", "calm"))
        self.assertEqual(classify_risk("delete_file", "src/a.py", "/ws"),
                         ("Reversible · deletes a file in this project", "calm"))

    # -- the worker gate itself -----------------------------------------

    def test_worker_gate_prompts_for_sensitive_despite_allow_rule(self):
        from forge.worker import AgentWorker
        ws = Path(tempfile.mkdtemp())
        rules = [{"scope": "global", "tool": "write_file",
                  "pattern": "*", "action": "allow"}]
        perms = {"rules": rules, "mode": "code", "classes": {}}

        def run_one(path):
            worker = AgentWorker(_ScriptedClient([
                {"tool": "write_file", "args": {"path": path, "content": "x"}},
                {"content": "done"}]), "fake",
                [{"role": "user", "content": "go"}], {}, str(ws),
                permissions=perms, skribe_writes=False)
            asked = []
            worker.approval_needed.connect(
                lambda *a: (asked.append(a[0]), worker.resolve_approval(True)))
            worker.run()
            return asked

        # A remembered allow-all exists, yet the .env write still
        # stops at the gate…
        self.assertEqual(run_one(".env"), ["write_file"])
        self.assertEqual((ws / ".env").read_text(), "x")
        # …while an ordinary file rides the same rule silently.
        self.assertEqual(run_one("plain.txt"), [])
        self.assertEqual((ws / "plain.txt").read_text(), "x")

    # -- the dialog ------------------------------------------------------

    def _dialog(self, tool, target, description="Do the thing?", workspace="/ws"):
        from forge.main import ApprovalDialog
        return ApprovalDialog(None, "model-x", tool, target, description,
                              workspace=workspace)

    def test_dialog_sensitive_suppresses_remember(self):
        from PySide6.QtWidgets import QPushButton
        dlg = self._dialog("write_file", ".env", "Write .env inside /ws?")
        try:
            self.assertTrue(dlg.sensitive)
            self.assertIsNone(dlg.remember_btn)
            self.assertIsNotNone(dlg.sensitive_note)
            self.assertEqual(dlg.sensitive_note.text(),
                             "Sensitive files always ask — this can't be remembered.")
            self.assertEqual(dlg.risk_text, "Sensitive file · always asks")
            self.assertIsNotNone(dlg.risk_label)
            texts = [b.text() for b in dlg.findChildren(QPushButton)]
            self.assertFalse(any("remember" in t.lower() for t in texts))
        finally:
            dlg.close()

    def test_dialog_sensitive_command_suppresses_remember(self):
        dlg = self._dialog("run_command", "cat .env", "Run this command in /ws:")
        try:
            self.assertTrue(dlg.sensitive)
            self.assertIsNone(dlg.remember_btn)
            self.assertIsNotNone(dlg.sensitive_note)
            self.assertEqual(
                dlg.risk_text,
                "Runs a command on this PC · touches a sensitive file")
        finally:
            dlg.close()

    def test_dialog_command_remember_copy_and_risk(self):
        dlg = self._dialog("run_command", "ls -la", "Run this command in /ws:")
        try:
            self.assertFalse(dlg.sensitive)
            self.assertIsNotNone(dlg.remember_btn)
            self.assertIn("this exact command in this project",
                          dlg.remember_btn.toolTip())
            self.assertIsNone(dlg.sensitive_note)
            self.assertEqual(dlg.risk_text, "Runs a command on this PC")
        finally:
            dlg.close()

    def test_dialog_risk_labels_for_writes(self):
        inside = self._dialog("write_file", "src/a.py", "Write src/a.py inside /ws?")
        try:
            self.assertEqual(inside.risk_text, "Reversible · inside this project")
            self.assertIsNotNone(inside.remember_btn)
        finally:
            inside.close()
        outside = self._dialog("write_file", "/etc/x.conf", "Write /etc/x.conf?")
        try:
            self.assertEqual(outside.risk_text,
                             "Hard to undo · outside this project")
        finally:
            outside.close()

    def test_dialog_without_workspace_is_the_classic_one(self):
        # The maintenance dialog's shape: no project named, so no
        # risk line and no sensitive handling — the classic dialog,
        # remember button and all, even for a sensitive-looking
        # target.
        from forge.main import ApprovalDialog
        dlg = ApprovalDialog(None, "model-x", "write_file", ".env", "Write .env?")
        try:
            self.assertIsNone(dlg.risk_label)
            self.assertEqual(dlg.risk_text, "")
            self.assertFalse(dlg.sensitive)
            self.assertIsNotNone(dlg.remember_btn)
            self.assertIsNone(dlg.sensitive_note)
        finally:
            dlg.close()

    # -- request_approval: the wiring ------------------------------------

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        import forge.main as main_mod
        self._main = main_mod
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.root = root
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self._old_workspace = self.win.workspace
        self.win.workspace = str(root)
        self.win.worker = None
        _RecordingApprovalDialog.instances = []
        _RecordingApprovalDialog.answer = False
        # Only the two wiring tests below swap the dialog class —
        # the dialog tests in this class construct the REAL
        # ApprovalDialog and must not meet the stand-in.
        self._real_dialog = main_mod.ApprovalDialog

    def tearDown(self):
        self._main.ApprovalDialog = self._real_dialog
        self.win.workspace = self._old_workspace
        self.win.worker = None
        self.temp.cleanup()

    def test_request_approval_passes_workspace_and_deck_risk(self):
        self._main.ApprovalDialog = _RecordingApprovalDialog
        self.win.request_approval(
            "write_file", {"path": "a.txt", "content": "x"}, "Write a.txt?")
        fake = _RecordingApprovalDialog.instances[0]
        self.assertEqual(fake.workspace, str(self.root))
        self.assertEqual(fake.seen_pending["risk"],
                         "Reversible · inside this project")
        self.assertEqual(fake.seen_pending["tool"], "write_file")
        self.win.request_approval(
            "run_command", {"command": "ls -la"}, "Run this command?")
        fake = _RecordingApprovalDialog.instances[1]
        self.assertEqual(fake.seen_pending["risk"], "Runs a command on this PC")

    def test_remembered_command_rule_takes_the_new_shape(self):
        class _RememberingDialog(_RecordingApprovalDialog):
            def exec(self):
                self.remember = True
                return super().exec()

        self._main.ApprovalDialog = _RememberingDialog
        _RecordingApprovalDialog.answer = True
        old_rules = list(self.win.settings.get("permission_rules", []))
        try:
            self.win.request_approval(
                "run_command", {"command": "ls -la"}, "Run this command?")
            rules = self.win.settings.get("permission_rules", [])
            self.assertEqual(len(rules), len(old_rules) + 1)
            self.assertEqual(rules[-1],
                             {"scope": str(self.root), "tool": "run_command",
                              "pattern": "ls -la", "action": "allow",
                              "exact": True})
            # And the saved shape is exactly what evaluate_rules
            # honors — here, and only here.
            from forge.permissions import evaluate_rules
            self.assertEqual(
                evaluate_rules(rules, "run_command", "ls -la", str(self.root)),
                "allow")
            self.assertEqual(
                evaluate_rules(rules, "run_command", "ls -la", "/elsewhere"),
                "ask")
        finally:
            self.win.settings["permission_rules"] = old_rules

    # -- the context-attach guard -----------------------------------------

    def test_mention_of_sensitive_file_is_not_attached(self):
        from forge.mentions import expand_mentions
        ws = Path(tempfile.mkdtemp())
        (ws / ".env").write_text("TOKEN=abc\n")
        (ws / ".env.example").write_text("TOKEN=\n")
        (ws / "notes.txt").write_text("hello\n")
        text, attached, unmatched = expand_mentions(
            "see @.env and @notes.txt", str(ws))
        self.assertEqual(attached, ["notes.txt"])
        self.assertIn(".env", unmatched)
        self.assertNotIn("TOKEN=abc", text)
        self.assertIn("hello", text)
        # The shareable template still attaches — the exemption is
        # the point of it.
        _text2, attached2, _unmatched2 = expand_mentions(
            "use @.env.example", str(ws))
        self.assertEqual(attached2, [".env.example"])


class MacroTests(unittest.TestCase):
    def test_scan_and_expand(self):
        from forge import macros as mm
        d = Path(tempfile.mkdtemp())
        (d / "audit.md").write_text("# /audit — Check everything\n\nRun the checks and report.\n")
        (d / "plain.md").write_text("Just do the thing.\n")
        found = mm.scan_macros(d)
        self.assertEqual(found["audit"][0], "Check everything")
        out = mm.expand(found, "/audit focus on tests")
        self.assertIn("Run the checks and report.", out)
        self.assertIn("focus on tests", out)
        self.assertIsNone(mm.expand(found, "/unknown"))
        self.assertIsNone(mm.expand(found, "not a command"))
        self.assertIn("/audit", mm.index_text(found))


class SchedulerTests(unittest.TestCase):
    def test_interval_due_and_mark_run(self):
        from forge import scheduler as sc
        job = {"name": "sweep", "prompt": "run tests", "enabled": True,
               "every_minutes": 30, "last_run": 1000.0, "next_run": None}
        sc.ensure_next(job, now=1000.0)
        self.assertEqual(job["next_run"], 1000.0 + 1800)
        self.assertEqual(sc.due_jobs([job], now=2000.0), [])
        self.assertEqual(sc.due_jobs([job], now=2800.0), [job])
        sc.mark_run(job, now=2800.0)
        self.assertEqual(job["last_run"], 2800.0)
        self.assertEqual(job["next_run"], 2800.0 + 1800)

    def test_daily_next_is_in_future(self):
        from forge import scheduler as sc
        import time as _t
        job = {"name": "morning", "prompt": "summary", "enabled": True, "daily": "07:30"}
        nxt = sc.compute_next(job, now=_t.time())
        self.assertGreater(nxt, _t.time())
        self.assertLess(nxt, _t.time() + 90000)
        job["enabled"] = False
        self.assertEqual(sc.due_jobs([job], now=_t.time() + 999999), [])

    def test_valid_daily(self):
        from forge import scheduler as sc
        for good in ("7:30", "07:30", "23:59", "0:00", "00:00"):
            self.assertTrue(sc.valid_daily(good), good)
        for bad in ("24:00", "7:60", "730", "", "ab:cd", "24:99",
                    "12:30:45", "-1:30", "7:", ":30", None):
            self.assertFalse(sc.valid_daily(bad), repr(bad))

    def test_invalid_daily_falls_back_without_raising(self):
        # Audit item A9: a hand-edited "24:99" used to raise ValueError
        # from datetime.replace OUTSIDE the parse guard — faulting
        # every scheduler tick forever. Now it takes the same +1 day
        # fallback as an unparseable value, everywhere it is read.
        from forge import scheduler as sc
        job = {"name": "broken", "prompt": "x", "enabled": True, "daily": "24:99"}
        self.assertEqual(sc.compute_next(job, now=5000.0), 5000.0 + 86400)
        due = sc.due_jobs([dict(job)], now=5000.0)  # must not raise
        self.assertEqual(due, [])
        self.assertEqual(sc.mark_run(dict(job), now=5000.0)["next_run"], 5000.0 + 86400)

    def test_bad_every_minutes_treated_as_absent(self):
        # A negative interval used to compute a next_run in the past
        # (fires every tick); a non-numeric one raised. Both now fall
        # through to the daily/default branches.
        from forge import scheduler as sc
        for bad in (-5, "abc", 0):
            job = {"name": "j", "prompt": "x", "enabled": True,
                   "every_minutes": bad, "last_run": 1000.0}
            self.assertEqual(sc.compute_next(job, now=2000.0), 2000.0 + 3600, repr(bad))
        job = {"name": "j", "prompt": "x", "enabled": True,
               "every_minutes": -5, "daily": "07:30", "last_run": 1000.0}
        nxt = sc.compute_next(job, now=2000.0)
        self.assertGreater(nxt, 2000.0)
        self.assertNotEqual(nxt, 2000.0 + 3600)

    def test_valid_inputs_unchanged(self):
        from forge import scheduler as sc
        import time as _t
        from datetime import datetime, timedelta
        # Interval from last_run: +30 min exactly.
        job = {"name": "j", "prompt": "x", "enabled": True,
               "every_minutes": 30, "last_run": 1000.0}
        self.assertEqual(sc.compute_next(job, now=1500.0), 1000.0 + 1800)
        # A string interval that parses behaves as it did before.
        job["every_minutes"] = "30"
        self.assertEqual(sc.compute_next(job, now=1500.0), 1000.0 + 1800)
        # Daily "07:30": the next 07:30 local, today or tomorrow.
        job = {"name": "j", "prompt": "x", "enabled": True, "daily": "07:30"}
        now = _t.time()
        nxt = sc.compute_next(job, now=now)
        local = datetime.fromtimestamp(nxt)
        self.assertEqual((local.hour, local.minute, local.second), (7, 30, 0))
        self.assertGreater(nxt, now)
        self.assertLessEqual(nxt, now + 86400)


class SchedulerTickWindowTests(unittest.TestCase):
    """Audit item A9 (window half): _scheduler_tick used to mark_run
    and persist BEFORE firing, so a send that could not start (no
    model selected, or an exception) still consumed the job's slot —
    the run was silently missed. Now the job is marked only once a
    worker is actually running; otherwise it stays due and retries
    on the next tick."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        import time as _t
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        self.win.messages = []
        self.win.conversation_id = None
        # _deck_sync (reached via new_chat) stands down while the deck
        # server is off; satisfy its gate like WatchTickWindowTests does.
        self._real_server = self.win.deck._server
        self.win.deck._server = object()
        self._had_jobs = "scheduled_jobs" in self.win.settings
        self._old_jobs = self.win.settings.get("scheduled_jobs")
        self.job = {"id": "tick-1", "name": "tickjob", "prompt": "do the thing",
                    "enabled": True, "every_minutes": 30,
                    "last_run": None, "next_run": 1.0}  # long past due
        self.win.settings["scheduled_jobs"] = [self.job]
        self._real_send = self.win.send_message

    def tearDown(self):
        self.win.send_message = self._real_send
        if self._had_jobs:
            self.win.settings["scheduled_jobs"] = self._old_jobs
        else:
            self.win.settings.pop("scheduled_jobs", None)
        self.win.save_settings()
        self.win.deck._server = self._real_server
        self.win.worker = None
        self.temp.cleanup()

    def test_tick_without_a_started_worker_does_not_mark_run(self):
        self.win.send_message = lambda: None  # send starts nothing
        self.win._scheduler_tick()
        self.assertIsNone(self.job["last_run"])
        self.assertEqual(self.job["next_run"], 1.0)  # still due

    def test_tick_with_a_running_worker_marks_run(self):
        import time as _t

        class _FakeWorker:
            def isRunning(self):
                return True

        win = self.win
        win.send_message = lambda: setattr(win, "worker", _FakeWorker())
        before = _t.time()
        self.win._scheduler_tick()
        self.assertIsNotNone(self.job["last_run"])
        self.assertGreaterEqual(self.job["last_run"], before)
        self.assertGreater(self.job["next_run"], _t.time())
        # Persisted into the settings jobs list, as before.
        saved = self.win.settings["scheduled_jobs"]
        self.assertEqual(saved[0]["next_run"], self.job["next_run"])


class ScheduleDialogTests(unittest.TestCase):
    """Audit C28: the schedule dialog gains (1) a real time picker for
    the daily field — a QTimeEdit always holds a valid HH:mm, so adding
    a daily job needs no free-text validation round-trip — and (2) a
    Toggle enabled button flipping the selected job's flag in the
    dialog's working copy, the ●/○ marker updating at once."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    def _dialog(self, jobs=()):
        from forge.main import ScheduleDialog
        return ScheduleDialog(None, list(jobs), "/tmp/ws")

    def test_daily_add_uses_the_time_picker(self):
        from PySide6.QtCore import QTime
        from forge import scheduler as sc
        dlg = self._dialog()
        dlg.daily_edit.setTime(QTime(6, 45))
        dlg.name_edit.setText("morning")
        dlg.prompt_edit.setText("brew the status")
        dlg.every_spin.setValue(0)
        dlg._add()
        self.assertEqual(len(dlg.jobs), 1)
        job = dlg.jobs[0]
        self.assertEqual(job["daily"], "06:45")
        self.assertNotIn("every_minutes", job)
        self.assertTrue(sc.valid_daily(job["daily"]))
        self.assertIsNotNone(job["next_run"])

    def test_daily_add_defaults_to_0730(self):
        dlg = self._dialog()
        dlg.prompt_edit.setText("status please")
        dlg._add()
        self.assertEqual(dlg.jobs[0]["daily"], "07:30")
        self.assertTrue(dlg.jobs[0]["enabled"])

    def test_toggle_flips_flag_and_marker_both_ways(self):
        jobs = [
            {"id": "a-0", "name": "a", "prompt": "pa", "enabled": True, "daily": "07:30"},
            {"id": "b-1", "name": "b", "prompt": "pb", "enabled": False, "daily": "08:00"},
        ]
        dlg = self._dialog(jobs)
        self.assertTrue(dlg.list.item(0).text().startswith("●"))
        self.assertTrue(dlg.list.item(1).text().startswith("○"))
        dlg.list.setCurrentRow(0)
        dlg._toggle_enabled()
        self.assertFalse(dlg.jobs[0]["enabled"])
        self.assertTrue(dlg.list.item(0).text().startswith("○"))
        dlg._toggle_enabled()
        self.assertTrue(dlg.jobs[0]["enabled"])
        self.assertTrue(dlg.list.item(0).text().startswith("●"))
        dlg.list.setCurrentRow(1)
        dlg._toggle_enabled()
        self.assertTrue(dlg.jobs[1]["enabled"])
        self.assertTrue(dlg.list.item(1).text().startswith("●"))

    def test_toggle_without_selection_is_a_noop(self):
        jobs = [{"id": "a-0", "name": "a", "prompt": "pa", "enabled": True, "daily": "07:30"}]
        dlg = self._dialog(jobs)
        dlg.list.setCurrentRow(-1)
        dlg._toggle_enabled()
        self.assertTrue(dlg.jobs[0]["enabled"])

    def test_every_minutes_still_wins_and_delete_still_works(self):
        dlg = self._dialog()
        dlg.prompt_edit.setText("tick")
        dlg.every_spin.setValue(15)
        dlg._add()
        self.assertEqual(dlg.jobs[0]["every_minutes"], 15)
        self.assertNotIn("daily", dlg.jobs[0])
        dlg.list.setCurrentRow(0)
        dlg._delete()
        self.assertEqual(dlg.jobs, [])

    def test_promptless_add_returns_silently(self):
        dlg = self._dialog()
        dlg._add()
        self.assertEqual(dlg.jobs, [])


class WatchTests(unittest.TestCase):
    def test_scan_finds_and_dedupes_markers(self):
        from forge import watch as wm
        ws = Path(tempfile.mkdtemp())
        (ws / "a.py").write_text("# validate this input AI!\n# ordinary comment\nx = 1  # how does this work AI?\n")
        (ws / ".venv").mkdir()
        (ws / ".venv" / "b.py").write_text("# ignore me AI!\n")
        found = wm.scan(str(ws), set())
        self.assertEqual(len(found), 2)
