class WatchIncrementalCacheTests(unittest.TestCase):
    """Audit B17: scan used to re-read every candidate file body on
    every tick. A counting wrapper around Path.read_text proves how
    many bodies a scan actually opens now; the module cache is
    cleared around every case so the tests stay order-independent."""

    def setUp(self):
        from unittest import mock
        from forge import watch as wm
        self.wm = wm
        wm._file_cache.clear()
        self.temp = tempfile.TemporaryDirectory()
        self.ws = Path(self.temp.name)
        self.reads = []
        real_read_text = Path.read_text

        def counting_read_text(path, *args, **kwargs):
            self.reads.append(str(path))
            return real_read_text(path, *args, **kwargs)

        self._patcher = mock.patch.object(Path, "read_text", counting_read_text)
        self._patcher.start()

    def tearDown(self):
        self._patcher.stop()
        self.wm._file_cache.clear()
        self.temp.cleanup()

    def test_stable_tree_second_scan_reads_nothing(self):
        (self.ws / "a.py").write_text("# validate this input AI!\nx = 1\n")
        (self.ws / "b.py").write_text("x = 2  # no marker here\n")
        (self.ws / "notes.md").write_text("prose, nothing to do\n")
        first = self.wm.scan(str(self.ws), set())
        self.assertEqual(len(self.reads), 3)  # every candidate, once
        self.assertEqual(len(first), 1)
        self.reads.clear()
        second = self.wm.scan(str(self.ws), set())
        self.assertEqual(self.reads, [])
        self.assertEqual(second, first)

    def test_edited_file_is_the_only_reread_and_new_marker_surfaces(self):
        a = self.ws / "a.py"
        b = self.ws / "b.py"
        a.write_text("# first task AI!\n")
        b.write_text("# second task AI!\n")
        first = self.wm.scan(str(self.ws), set())
        old_key = first[0]["key"]
        self.reads.clear()
        a.write_text("# first task rewritten, now with more words AI!\n")
        second = self.wm.scan(str(self.ws), set())
        self.assertEqual(len(self.reads), 1)
        self.assertTrue(self.reads[0].endswith("a.py"))
        keys = {m["key"] for m in second}
        self.assertNotIn(old_key, keys)
        texts = {m["text"] for m in second}
        self.assertIn("first task rewritten, now with more words", texts)
        self.assertIn("second task", texts)

    def test_deleted_file_markers_vanish(self):
        a = self.ws / "a.py"
        b = self.ws / "b.py"
        a.write_text("# task in a AI!\n")
        b.write_text("# task in b AI!\n")
        first = self.wm.scan(str(self.ws), set())
        self.assertEqual(len(first), 2)
        b.unlink()
        second = self.wm.scan(str(self.ws), set())
        self.assertEqual([m["text"] for m in second], ["task in a"])
        self.assertNotIn(str(b), self.wm._file_cache)

    def test_seen_filter_applies_on_a_fully_cached_scan(self):
        (self.ws / "a.py").write_text("# task one AI!\n# task two AI!\n")
        first = self.wm.scan(str(self.ws), set())
        self.assertEqual(len(first), 2)
        self.reads.clear()
        second = self.wm.scan(str(self.ws), {first[0]["key"]})
        self.assertEqual(self.reads, [])
        self.assertEqual(second, [first[1]])

    def test_cached_results_equal_cold_results(self):
        a = self.ws / "a.py"
        b = self.ws / "b.py"
        (self.ws / "c.txt").write_text("no markers at all\n")
        a.write_text("# alpha task AI!\n")
        b.write_text("x = 1  # how does this work AI?\n")
        warm = self.wm.scan(str(self.ws), set())
        self.wm._file_cache.clear()
        cold = self.wm.scan(str(self.ws), set())
        self.assertEqual(warm, cold)
        b.write_text("x = 2  # how does this work, exactly, step by step AI?\n")
        warm = self.wm.scan(str(self.ws), set())
        self.wm._file_cache.clear()
        cold = self.wm.scan(str(self.ws), set())
        self.assertEqual(warm, cold)
        self.assertEqual(len(warm), 2)


class WatchTickWindowTests(unittest.TestCase):
    """Audit item A3: the window-level watch tick used to mark EVERY
    scanned marker seen while dispatching only the first — markers
    2..n were silently dropped. Now only the dispatched marker is
    marked seen; the rest stay unseen and dispatch one per idle tick,
    in scan order. These are the first tests of _watch_tick itself
    (WatchTests above covers only the pure scan)."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        self.win.messages = []
        self.win.conversation_id = None
        # _deck_sync (reached via new_chat) stands down while the deck
        # server is off; satisfy its gate like DeckCouncilTests does.
        self._real_server = self.win.deck._server
        self.win.deck._server = object()
        (root / "a_first.py").write_text("# validate the alpha input AI!\nx = 1\n")
        (root / "b_second.py").write_text("# check the beta cache AI!\ny = 2\n")
        self._old_workspace = self.win.workspace
        self.win.workspace = str(root)
        self._old_seen = set(self.win._watch_seen)
        self.win._watch_seen = set()
        self._old_watch_ai = self.win.settings.get("watch_ai", False)
        self._old_watch_seen_setting = self.win.settings.get("watch_seen")
        self.win.settings["watch_ai"] = True
        # The two markers in scan order, for key assertions.
        from forge import watch as wm
        found = wm.scan(str(root), set())
        self.assertEqual(len(found), 2)
        self.key_first, self.key_second = found[0]["key"], found[1]["key"]
        # send_message is replaced with a recorder: the tick's dispatch
        # is the recorded input text, no real turn ever starts. The
        # recorder also installs the stand-in worker a real accepted
        # send leaves behind (already finished, so later ticks still
        # see an idle bench): sweep R35 marks a marker seen only once
        # its turn is confirmed started, and the stand-in is what a
        # confirmed start looks like to the tick.
        self.sent = []
        win = self.win
        self._real_send = win.send_message

        class _StartedWorker:
            def isRunning(self):
                return False

            def cancel(self):
                pass

        def _record_send():
            self.sent.append(win.input.toPlainText())
            win.worker = _StartedWorker()

        win.send_message = _record_send

    def tearDown(self):
        self.win.send_message = self._real_send
        self.win.settings["watch_ai"] = self._old_watch_ai
        if self._old_watch_seen_setting is None:
            self.win.settings.pop("watch_seen", None)
        else:
            self.win.settings["watch_seen"] = self._old_watch_seen_setting
        self.win.save_settings()
        self.win._watch_seen = self._old_seen
        self.win.workspace = self._old_workspace
        self.win.deck._server = self._real_server
        self.win.worker = None
        self.temp.cleanup()

    def test_first_tick_dispatches_only_the_first_marker(self):
        self.win._watch_tick()
        self.assertEqual(len(self.sent), 1)
        self.assertIn("a_first.py", self.sent[0])
        self.assertIn("validate the alpha input", self.sent[0])
        # Only the dispatched marker's key is seen — in memory and in
        # the persisted setting. The second marker is NOT consumed.
        self.assertEqual(self.win._watch_seen, {self.key_first})
        self.assertEqual(self.win.settings["watch_seen"], [self.key_first])

    def test_second_tick_dispatches_the_second_marker(self):
        self.win._watch_tick()
        self.win._watch_tick()
        self.assertEqual(len(self.sent), 2)
        self.assertIn("b_second.py", self.sent[1])
        self.assertIn("check the beta cache", self.sent[1])
        self.assertEqual(self.win._watch_seen, {self.key_first, self.key_second})

    def test_third_tick_dispatches_nothing(self):
        self.win._watch_tick()
        self.win._watch_tick()
        self.win._watch_tick()
        self.assertEqual(len(self.sent), 2)
        self.assertEqual(self.win._watch_seen, {self.key_first, self.key_second})


class PluginOwnerFilterWindowTests(unittest.TestCase):
    """Audit item A5 (window half): reload_extensions used to drop
    tools by NAME (dead_tools) — a disabled plugin that declared the
    same tool name as an enabled one deleted the enabled plugin's
    tool from the live registry. The filter is owner-based now: a
    tool leaves only when its OWNING plugin is disabled."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        win = self.win
        self._saved_attrs = {k: getattr(win, k) for k in
                             ("all_plugins", "_full_registry", "all_skills",
                              "skills", "plugins", "plugin_registry")}
        self._saved_settings = {k: win.settings.get(k)
                                for k in ("disabled_plugins", "disabled_skills",
                                          "known_plugins")}
        from forge.plugins import Plugin
        schema = {"type": "function", "function": {"name": "shared_tool"}}
        handler = lambda args: "ok"  # noqa: E731
        enabled = Plugin(pid="en-one", name="Enabled One", kind="plugin",
                         description="", folder=Path("."),
                         tools=[{"name": "shared_tool"}],
                         handlers={"shared_tool": handler})
        disabled = Plugin(pid="dis-two", name="Disabled Two", kind="plugin",
                          description="", folder=Path("."),
                          tools=[{"name": "shared_tool"}], handlers={})
        win.all_plugins = [enabled, disabled]
        # the full registry holds the ENABLED plugin's registration
        # (it won the name at load); the disabled one merely declares
        # the same tool name in its manifest.
        win._full_registry = {"shared_tool": (schema, handler, True, "Enabled One")}
        win.settings["disabled_plugins"] = ["dis-two"]
        win.settings["disabled_skills"] = []
        win.settings["known_plugins"] = ["en-one", "dis-two"]

    def tearDown(self):
        win = self.win
        for k, v in self._saved_attrs.items():
            setattr(win, k, v)
        for k, v in self._saved_settings.items():
            if v is None:
                win.settings.pop(k, None)
            else:
                win.settings[k] = v
        win.save_settings()
        # leave the window's derived state consistent with the restored data
        win.reload_extensions()

    def test_enabled_tool_survives_name_sharing_disabled_plugin(self):
        self.win.reload_extensions()
        self.assertIn("shared_tool", self.win.plugin_registry)
        self.assertEqual(self.win.plugin_registry["shared_tool"][3], "Enabled One")
        # the disabled plugin itself is filtered from the live list,
        # the enabled one stays
        self.assertEqual([p.pid for p in self.win.plugins], ["en-one"])


class UpdateTests(unittest.TestCase):
    def test_resume_state_round_trip(self):
        from forge import update as upd
        d = Path(tempfile.mkdtemp())
        upd.write_resume_state(d, {"conversation_id": 7, "was_running": True, "last_prompt": "do it"})
        state = upd.read_resume_state(d)
        self.assertEqual(state["conversation_id"], 7)
        upd.clear_resume_state(d)
        self.assertIsNone(upd.read_resume_state(d))

    def test_updater_extracts_safely_and_relaunches(self):
        import subprocess as sp, sys as _sys, time as _time, zipfile as zf
        base = Path(tempfile.mkdtemp())
        app = base / "Linux Forge Agent"
        (app / "forge").mkdir(parents=True)
        (app / "forge" / "__init__.py").write_text('__version__ = "old"\n')
        (app / "forge" / "main.py").write_text("import pathlib; pathlib.Path('relaunched.txt').write_text('yes')\n")
        (app / "requirements.txt").write_text("# nothing\n")
        overlay = base / "overlay.zip"
        with zf.ZipFile(overlay, "w") as z:
            z.writestr("Linux Forge Agent/forge/__init__.py", '__version__ = "new"\n')
            # The updater now installs as a SYNC (audit A7): a file the
            # zip omits is a file the new version deleted. Real update
            # zips carry the full tree, so the fixture zip must too —
            # without main.py here the swap would (correctly) remove it
            # and the relaunch below would have nothing to run.
            z.writestr("Linux Forge Agent/forge/main.py",
                       "import pathlib; pathlib.Path('relaunched.txt').write_text('yes')\n")
            z.writestr("Linux Forge Agent/../evil.txt", "escape")
            z.writestr("Linux Forge Agent/random.txt", "not code")
        data = base / "data"; data.mkdir()
        manifest = {"app_dir": str(app), "data_dir": str(data),
                    "zip": str(overlay), "wait_pid": None, "extra_pip": []}
        mpath = data / "manifest.json"; mpath.write_text(json.dumps(manifest))
        updater = Path(__file__).resolve().parent.parent / "forge_updater.py"
        done = sp.run([_sys.executable, str(updater), "--manifest", str(mpath)],
                      capture_output=True, text=True, timeout=300)
        self.assertEqual(done.returncode, 0, done.stderr[-500:])
        self.assertIn('"new"', (app / "forge" / "__init__.py").read_text())
        self.assertFalse((base / "evil.txt").exists())
        self.assertFalse((app / "random.txt").exists())
        result = json.loads((data / "update_result.json").read_text())
        self.assertTrue(result["ok"], result)
        for _ in range(50):
            if (app / "relaunched.txt").exists():
                break
            _time.sleep(0.2)
        self.assertTrue((app / "relaunched.txt").exists())

    # --- Audit A7: staged install, backup/rollback, honest failures ---

    def _run_updater(self, data, manifest):
        import subprocess as sp, sys as _sys
        mpath = data / "manifest.json"; mpath.write_text(json.dumps(manifest))
        updater = Path(__file__).resolve().parent.parent / "forge_updater.py"
        return sp.run([_sys.executable, str(updater), "--manifest", str(mpath)],
                      capture_output=True, text=True, timeout=300)

    @staticmethod
    def _tree_bytes(root):
        return {str(p.relative_to(root)): p.read_bytes()
                for p in sorted(root.rglob("*")) if p.is_file()}

    def test_updater_zip_with_no_code_files_fails_and_touches_nothing(self):
        import zipfile as zf
        base = Path(tempfile.mkdtemp())
        app = base / "Linux Forge Agent"
        (app / "forge").mkdir(parents=True)
        (app / "forge" / "__init__.py").write_text('__version__ = "old"\n')
        overlay = base / "overlay.zip"
        with zf.ZipFile(overlay, "w") as z:
            z.writestr("Linux Forge Agent/random.txt", "not code")
            z.writestr("Linux Forge Agent/notes/todo.txt", "not code either")
        data = base / "data"; data.mkdir()
        before = self._tree_bytes(app)
        done = self._run_updater(data, {"app_dir": str(app), "data_dir": str(data),
                                        "zip": str(overlay), "wait_pid": None,
                                        "extra_pip": []})
        self.assertNotEqual(done.returncode, 0, done.stderr[-500:])
        result = json.loads((data / "update_result.json").read_text())
        self.assertFalse(result["ok"], result)
        self.assertIn("no code files", result["error"])
        self.assertEqual(self._tree_bytes(app), before)

    def test_updater_rejects_broken_code_before_touching_app(self):
        import zipfile as zf
        base = Path(tempfile.mkdtemp())
        app = base / "Linux Forge Agent"
        (app / "forge").mkdir(parents=True)
        (app / "forge" / "__init__.py").write_text('__version__ = "old"\n')
        overlay = base / "overlay.zip"
        with zf.ZipFile(overlay, "w") as z:
            z.writestr("Linux Forge Agent/forge/broken.py", "def broken(:\n    pass\n")
        data = base / "data"; data.mkdir()
        before = self._tree_bytes(app)
        done = self._run_updater(data, {"app_dir": str(app), "data_dir": str(data),
                                        "zip": str(overlay), "wait_pid": None,
                                        "extra_pip": []})
        self.assertNotEqual(done.returncode, 0, done.stderr[-500:])
        result = json.loads((data / "update_result.json").read_text())
        self.assertFalse(result["ok"], result)
        self.assertIn("compile", result["error"])
        self.assertEqual(self._tree_bytes(app), before)

    def test_updater_happy_path_syncs_deletions_and_backs_up(self):
        import zipfile as zf
        base = Path(tempfile.mkdtemp())
        app = base / "Linux Forge Agent"
        (app / "forge").mkdir(parents=True)
        (app / "forge" / "__init__.py").write_text('__version__ = "old"\n')
        (app / "forge" / "removed.py").write_text("# old helper\n")
        (app / "forge" / "main.py").write_text("import pathlib; pathlib.Path('relaunched.txt').write_text('yes')\n")
        (app / "requirements.txt").write_text("# nothing\n")
        overlay = base / "overlay.zip"
        with zf.ZipFile(overlay, "w") as z:
            z.writestr("Linux Forge Agent/forge/__init__.py", '__version__ = "new"\n')
            z.writestr("Linux Forge Agent/forge/main.py",
                       "import pathlib; pathlib.Path('relaunched.txt').write_text('yes')\n")
            z.writestr("Linux Forge Agent/requirements.txt", "# nothing\n")
        data = base / "data"; data.mkdir()
        done = self._run_updater(data, {"app_dir": str(app), "data_dir": str(data),
                                        "zip": str(overlay), "wait_pid": None,
                                        "extra_pip": []})
        self.assertEqual(done.returncode, 0, done.stderr[-500:])
        result = json.loads((data / "update_result.json").read_text())
        self.assertTrue(result["ok"], result)
        # New code landed…
        self.assertIn('"new"', (app / "forge" / "__init__.py").read_text())
        # …the file the new version deleted is actually gone (sync)…
        self.assertFalse((app / "forge" / "removed.py").exists())
        # …and the backup holds the previous code, deleted file included.
        backup = data / "update_backup"
        self.assertIn('"old"', (backup / "forge" / "__init__.py").read_text())
        self.assertEqual((backup / "forge" / "removed.py").read_text(), "# old helper\n")
        # Staging is cleaned up afterwards.
        self.assertFalse((data / "update_staging").exists())

    def test_updater_corrupt_manifest_still_records_result(self):
        import subprocess as sp, sys as _sys
        data = Path(tempfile.mkdtemp())
        mpath = data / "manifest.json"
        mpath.write_text("{ this is not json")
        updater = Path(__file__).resolve().parent.parent / "forge_updater.py"
        done = sp.run([_sys.executable, str(updater), "--manifest", str(mpath)],
                      capture_output=True, text=True, timeout=60)
        self.assertNotEqual(done.returncode, 0)
        result = json.loads((data / "update_result.json").read_text())
        self.assertFalse(result["ok"], result)
        self.assertIn("manifest", result["error"])


