FAKE_MCP_DEAD_SERVER = '''
import time
time.sleep(3600)
'''


def _load_mcp_client():
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        "mcp_client", Path(__file__).resolve().parent.parent / "plugins" / "mcp" / "mcp_client.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class McpTests(unittest.TestCase):
    def test_list_and_call_against_fake_server(self):
        import importlib.util
        ws = Path(tempfile.mkdtemp())
        server_py = ws / "fake_server.py"
        server_py.write_text(FAKE_MCP_SERVER)
        spec = importlib.util.spec_from_file_location(
            "mcp_client", Path(__file__).resolve().parent.parent / "plugins" / "mcp" / "mcp_client.py")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        server = module.get_server("fake", {"command": "python3", "args": [str(server_py)]})
        tools = server.list_tools()
        self.assertEqual([t["name"] for t in tools], ["echo"])
        self.assertEqual(server.call_tool("echo", {"text": "hello forge"}), "echo: hello forge")
        server.proc.terminate()

    def test_list_tools_follows_pagination(self):
        module = _load_mcp_client()
        ws = Path(tempfile.mkdtemp())
        server_py = ws / "paged_server.py"
        server_py.write_text(FAKE_MCP_PAGED_SERVER)
        server = module.get_server("paged", {"command": "python3", "args": [str(server_py)]})
        try:
            # Page 2 only answers when the follow-up request carries
            # params.cursor == "page2"; anything else errors or repeats
            # page 1, so both tools arriving in order proves the
            # cursor was followed.
            self.assertEqual([t["name"] for t in server.list_tools()],
                             ["first_tool", "second_tool"])
        finally:
            server.proc.terminate()

    def test_dead_server_times_out_fast_and_does_not_poison_cache(self):
        import time
        module = _load_mcp_client()
        self.assertLessEqual(module.CONNECT_TIMEOUT, 15)
        ws = Path(tempfile.mkdtemp())
        dead_py = ws / "dead_server.py"
        dead_py.write_text(FAKE_MCP_DEAD_SERVER)
        good_py = ws / "fake_server.py"
        good_py.write_text(FAKE_MCP_SERVER)
        module.CONNECT_TIMEOUT = 1
        started = time.monotonic()
        with self.assertRaises(module.McpError):
            module.get_server("dead", {"command": "python3", "args": [str(dead_py)]})
        self.assertLess(time.monotonic() - started, 10)
        # The failed start cached nothing: the same name with a
        # working spec starts cleanly instead of reusing the corpse.
        server = module.get_server("dead", {"command": "python3", "args": [str(good_py)]})
        try:
            self.assertEqual([t["name"] for t in server.list_tools()], ["echo"])
        finally:
            server.proc.terminate()

    def test_config_edit_respawns_server(self):
        module = _load_mcp_client()
        ws = Path(tempfile.mkdtemp())
        a_py = ws / "server_a.py"
        a_py.write_text(FAKE_MCP_SERVER)
        b_py = ws / "server_b.py"
        b_py.write_text(FAKE_MCP_ALT_SERVER)
        spec_a = {"command": "python3", "args": [str(a_py)]}
        server_a = module.get_server("cfg", spec_a)
        self.assertIs(module.get_server("cfg", spec_a), server_a)
        self.assertEqual([t["name"] for t in server_a.list_tools()], ["echo"])
        server_b = module.get_server("cfg", {"command": "python3", "args": [str(b_py)]})
        try:
            self.assertIsNot(server_b, server_a)
            self.assertEqual([t["name"] for t in server_b.list_tools()], ["greet"])
            server_a.proc.wait(timeout=5)
            self.assertIsNotNone(server_a.proc.poll())
        finally:
            server_b.proc.terminate()


FAKE_BROWSE_SERVER = '''
import sys, json
log_path = sys.argv[1]
def note(obj):
    with open(log_path, "a") as fh:
        fh.write(json.dumps(obj) + "\\n")
for line in sys.stdin:
    msg = json.loads(line)
    method = msg.get("method", "")
    if "id" not in msg:
        continue
    if method == "initialize":
        result = {"protocolVersion": "2024-11-05", "capabilities": {}, "serverInfo": {"name": "fake-browse", "version": "0"}}
    elif method == "tools/list":
        result = {"tools": [
            {"name": "navigate", "description": "Go to a URL"},
            {"name": "snapshot", "description": "Page snapshot"},
            {"name": "click", "description": "Click"},
            {"name": "type", "description": "Type"},
            {"name": "screenshot", "description": "Screenshot"}]}
    elif method == "tools/call":
        name = msg["params"]["name"]
        arguments = msg["params"].get("arguments", {})
        note({"tool": name, "arguments": arguments})
        url = str(arguments.get("url", ""))
        if name == "navigate" and "paywall" in url:
            text = json.dumps({"handoff": "payment", "detail": "card required"})
        elif name == "navigate" and "loginwall" in url:
            text = "Sign-in required to continue. [browse-handoff: login]"
        else:
            text = "did " + name + " " + json.dumps(arguments, sort_keys=True)
        result = {"content": [{"type": "text", "text": text}]}
    else:
        result = {}
    sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": msg["id"], "result": result}) + "\\n")
    sys.stdout.flush()
'''


class BrowseConnectorTests(unittest.TestCase):
    """Item #55: the Browse connector — ADOPTED OpenCode Browse (an
    external MCP server + Chromium extension), registered as a
    connector with Forge's own fences: the six-verb surface, the
    text-snapshot pin, the per-project site allowlist, and the
    wall hold released only through the worker's approval gate.
    Driven against a FAKE Browse-shaped MCP server that logs every
    tools/call it receives, so a fence refusal is proven by the
    ABSENCE of a call, not by trusting the refusal text."""

    def setUp(self):
        # S5 (audit S1-18) test adaptation, disclosed: check_open now
        # RESOLVES allowlisted names and refuses internal answers, so
        # this class's fictional hosts (example.com, paywall.…,
        # loginwall.…) must not depend on real DNS — which may not
        # exist, may NXDOMAIN them, or may answer with proxy/internal
        # addresses. DNS is stubbed to one public answer for every
        # host; the S5 fence tests override the stub per test.
        import socket as _socket
        from unittest import mock as _mock
        from forge import browse as _browse_mod
        self._dns_patch = _mock.patch.object(
            _browse_mod.socket, "getaddrinfo",
            lambda host, port, *a, **k: [
                (_socket.AF_INET, _socket.SOCK_STREAM, 6, "",
                 ("93.184.216.34", 0))])
        self._dns_patch.start()
        self._tmp = tempfile.TemporaryDirectory()
        self.ws = Path(self._tmp.name)
        (self.ws / ".forge").mkdir()
        self.log_file = self.ws / "calls.jsonl"
        server_py = self.ws / "fake_browse_server.py"
        server_py.write_text(FAKE_BROWSE_SERVER)
        self.config = {
            "mcp_servers": {"browse": {"command": "python3",
                                       "args": [str(server_py),
                                                str(self.log_file)]}},
            "browse": {"server": "browse"}}
        root = Path(__file__).resolve().parent.parent
        ctx = PluginContext(workspace=str(self.ws), config=self.config,
                            log=lambda m: None)
        self.plugins, self.registry = load_plugins(root / "plugins", ctx)

    def tearDown(self):
        from forge import browse as browse_mod
        browse_mod.clear_hold(self.ws)
        self._dns_patch.stop()
        module = sys.modules.get("mcp_client")
        if module is not None:
            for server in list(module._servers.values()):
                try:
                    server.proc.terminate()
                except Exception:
                    pass
            module._servers.clear()
            module._server_fingerprints.clear()
        self._tmp.cleanup()

    def _calls(self):
        if not self.log_file.exists():
            return []
        return [json.loads(line) for line in
                self.log_file.read_text(encoding="utf-8").splitlines()
                if line.strip()]

    def _allow(self, hosts):
        (self.ws / ".forge" / "browse.json").write_text(
            json.dumps({"allowlist": hosts}), encoding="utf-8")

    def _handler(self, name):
        return self.registry[name][1]

    def test_verb_surface_and_approval_flags(self):
        from forge import browse as browse_mod
        found = [p for p in self.plugins if p.pid == "browse"]
        self.assertEqual(len(found), 1)
        self.assertEqual(found[0].kind, "connector")
        for name in browse_mod.VERB_TOOLS:
            self.assertIn(name, self.registry)
        approval = {n: self.registry[n][2] for n in browse_mod.VERB_TOOLS}
        self.assertEqual(approval, {
            "browse_open": True, "browse_read": False,
            "browse_click": True, "browse_type": True,
            "browse_screenshot": False, "browse_hand_back": True})
        # read's text default is a pin in the map, NOT a model knob:
        # the schema the model sees has no arguments at all.
        read_schema = self.registry["browse_read"][0]
        self.assertEqual(
            read_schema["function"]["parameters"]["properties"], {})

    def test_read_pins_text_snapshot(self):
        result = self._handler("browse_read")({})
        self.assertIn("did snapshot", result)
        calls = self._calls()
        self.assertEqual(len(calls), 1)
        self.assertEqual(calls[0]["tool"], "snapshot")
        self.assertEqual(calls[0]["arguments"], {"format": "text"})

    def test_open_allowed_host_reaches_server(self):
        self._allow(["example.com"])
        result = self._handler("browse_open")(
            {"url": "https://example.com/page"})
        self.assertIn("did navigate", result)
        calls = self._calls()
        self.assertEqual([c["tool"] for c in calls], ["navigate"])
        self.assertEqual(calls[0]["arguments"]["url"],
                         "https://example.com/page")

    def test_open_unlisted_host_refused_before_server(self):
        self._allow(["example.com"])
        result = self._handler("browse_open")(
            {"url": "https://evil.example.net/"})
        self.assertIn("not on this project's Browse site allowlist",
                      result)
        self.assertEqual(self._calls(), [])

    def test_no_allowlist_refuses_all_navigation(self):
        result = self._handler("browse_open")(
            {"url": "https://example.com/"})
        self.assertIn("no Browse site allowlist", result)
        self.assertIn(".forge/browse.json", result)
        self.assertEqual(self._calls(), [])

    def test_allowlist_matching_rules(self):
        from forge import browse as browse_mod
        allow = ["example.com", "*.docs.example.org"]
        self.assertIsNone(
            browse_mod.check_open("https://example.com/a", allow))
        # S5 (audit S1-19) test adaptation, disclosed: this line
        # used http:// to exercise wildcard subdomain matching;
        # http to a public host is now refused by the https-only
        # fence, so the matching assertion rides on https instead.
        # The assertion itself (wildcard matches a subdomain) is
        # unchanged.
        self.assertIsNone(
            browse_mod.check_open("https://a.docs.example.org/", allow))
        # "*.": subdomains only, never the bare host or a sibling.
        self.assertIsNotNone(
            browse_mod.check_open("https://docs.example.org/", allow))
        self.assertIsNotNone(
            browse_mod.check_open("https://sub.example.com/", allow))
        # Non-web addresses are not navigable at all.
        self.assertIsNotNone(
            browse_mod.check_open("file:///etc/passwd", allow))
        self.assertIsNotNone(browse_mod.check_open("not a url", allow))

    def test_payment_wall_holds_until_owner_continues(self):
        from forge import browse as browse_mod
        self._allow(["paywall.example.com"])
        result = self._handler("browse_open")(
            {"url": "https://paywall.example.com/checkout"})
        self.assertIn("FORCED HANDOFF", result)
        hold = browse_mod.get_hold(self.ws)
        self.assertIsNotNone(hold)
        self.assertEqual(hold["kind"], "payment")
        calls_before = len(self._calls())
        refused = self._handler("browse_read")({})
        self.assertIn("HELD", refused)
        self.assertIn("browse_hand_back", refused)
        # The server was never touched while the hold stood.
        self.assertEqual(len(self._calls()), calls_before)
        done = self._handler("browse_hand_back")({"reason": "payment wall"})
        self.assertIn("hold is released", done)
        self.assertIsNone(browse_mod.get_hold(self.ws))
        again = self._handler("browse_read")({})
        self.assertIn("did snapshot", again)

    def test_login_marker_wall_also_holds(self):
        from forge import browse as browse_mod
        self._allow(["loginwall.example.com"])
        result = self._handler("browse_open")(
            {"url": "https://loginwall.example.com/"})
        self.assertIn("FORCED HANDOFF", result)
        hold = browse_mod.get_hold(self.ws)
        self.assertIsNotNone(hold)
        self.assertEqual(hold["kind"], "login")

    def test_hand_back_gate_is_the_workers_approval_gate(self):
        from forge import browse as browse_mod
        from forge.worker import AgentWorker
        browse_mod.set_hold(self.ws, "payment")
        extra = {"browse_hand_back": self.registry["browse_hand_back"]}
        asked = []
        client = _BatchClient([("browse_hand_back", {"reason": "payment"})])
        worker = AgentWorker(client, "fake",
                             [{"role": "user", "content": "go"}], {},
                             str(self.ws), extra_tools=extra)
        worker.approval_needed.connect(
            lambda name, args, desc, diff:
                (asked.append(name), worker.resolve_approval(False)))
        worker.run()
        self.assertEqual(asked, ["browse_hand_back"])
        # Denied at the gate → the handler never ran → the hold stands.
        self.assertIsNotNone(browse_mod.get_hold(self.ws))
        # Approved at the same gate → the handler runs and releases.
        client2 = _BatchClient([("browse_hand_back", {"reason": "payment"})])
        worker2 = AgentWorker(client2, "fake",
                              [{"role": "user", "content": "go"}], {},
                              str(self.ws), extra_tools=extra)
        worker2.approval_needed.connect(
            lambda *a: worker2.resolve_approval(True))
        worker2.run()
        self.assertIsNone(browse_mod.get_hold(self.ws))

    def test_registration_preset_round_trips_through_the_store(self):
        from forge import browse as browse_mod
        from forge.plugins import load_connector_config
        app_dir = self.ws / "appdata"
        app_dir.mkdir()
        preset = browse_mod.preset_config()
        (app_dir / "connectors.json").write_text(
            json.dumps(preset), encoding="utf-8")
        loaded = load_connector_config(app_dir)
        self.assertEqual(loaded, preset)
        resolved = browse_mod.resolve_config(loaded)
        self.assertEqual(resolved["server"], "browse")
        self.assertEqual(browse_mod.server_spec(loaded, resolved),
                         {"command": "browse", "args": []})
        tool, args = browse_mod.server_args(resolved, "read", {})
        self.assertEqual(tool, "snapshot")
        self.assertEqual(args, {"format": "text"})
        # An unconfigured store reads as "not set up", never a crash.
        self.assertIsNone(browse_mod.server_spec({}, resolved))
        self.assertIn("mcp_servers", browse_mod.setup_message("browse"))

    def test_tool_map_override_from_config(self):
        # A server whose click tool is named "tap" is a
        # connectors.json edit — no code change.
        root = Path(__file__).resolve().parent.parent
        config = dict(self.config)
        config["browse"] = {"server": "browse",
                            "tool_map": {"click": {"tool": "tap"}}}
        ctx = PluginContext(workspace=str(self.ws), config=config,
                            log=lambda m: None)
        _plugins, registry = load_plugins(root / "plugins", ctx)
        result = registry["browse_click"][1]({"selector": "#go"})
        self.assertIn("did tap", result)
        self.assertEqual(self._calls()[0]["tool"], "tap")

    def test_unconfigured_server_answers_with_setup(self):
        root = Path(__file__).resolve().parent.parent
        ctx = PluginContext(workspace=str(self.ws),
                            config={"browse": {"server": "browse"}},
                            log=lambda m: None)
        _plugins, registry = load_plugins(root / "plugins", ctx)
        result = registry["browse_read"][1]({})
        self.assertIn("not configured yet", result)
        self.assertIn('"mcp_servers"', result)


FAKE_VERIFY_SERVER = '''
import sys, json
log_path = sys.argv[1]
PNG_B64 = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg=="
def note(obj):
    with open(log_path, "a") as fh:
        fh.write(json.dumps(obj) + "\\n")
for line in sys.stdin:
    msg = json.loads(line)
    method = msg.get("method", "")
    if "id" not in msg:
        continue
    if method == "initialize":
        result = {"protocolVersion": "2024-11-05", "capabilities": {}, "serverInfo": {"name": "fake-verify", "version": "0"}}
    elif method == "tools/list":
        result = {"tools": [
            {"name": "navigate", "description": "Go to a URL"},
            {"name": "snapshot", "description": "Page snapshot"},
            {"name": "click", "description": "Click"},
            {"name": "type", "description": "Type"},
            {"name": "screenshot", "description": "Screenshot"}]}
    elif method == "tools/call":
        name = msg["params"]["name"]
        arguments = msg["params"].get("arguments", {})
        note({"tool": name, "arguments": arguments})
        if name == "snapshot":
            text = "VERIFY PAGE TEXT: the rendered page says hello."
        elif name == "screenshot":
            text = PNG_B64
        else:
            text = "did " + name + " " + json.dumps(arguments, sort_keys=True)
        result = {"content": [{"type": "text", "text": text}]}
    else:
        result = {}
    sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": msg["id"], "result": result}) + "\\n")
    sys.stdout.flush()
'''


class VerifyInBrowserTests(unittest.TestCase):
    """Item #65: the verify loop — verify_in_browser composes the
    Browse observation verbs so the agent can look at its own work:
    a project page is served from a throwaway loopback preview (the
    one allowlist exception, alive only for the call), an external
    URL gets no exception at all, and the result is TEXT plus the
    path of the screenshot saved under .forge/artifacts/ — never
    image data, whatever model is driving. Driven against the same
    fake-MCP-server harness as BrowseConnectorTests."""

    def setUp(self):
        # S5-merge adaptation (same disclosed kind as the
        # BrowseConnectorTests stub carried with the S5 port):
        # check_open now RESOLVES allowlisted names and refuses
        # internal answers (audit S1-18), so this class's fictional
        # external host (example.com) must not depend on real DNS —
        # in this sandbox every name answers with an internal
        # 198.18.x.x proxy address and the allowlisted-URL test
        # fails on the sandbox, not the product. One difference
        # from the BrowseConnector stub: IP literals pass through
        # to the real resolver, because this class's local-preview
        # tests fetch a real 127.0.0.1 server through urllib while
        # the stub is up. Setup-only; no assertion changes.
        import ipaddress as _ipaddress
        import socket as _socket
        from unittest import mock as _mock
        from forge import browse as _browse_mod
        _real_getaddrinfo = _socket.getaddrinfo

        def _stub_getaddrinfo(host, port, *a, **k):
            try:
                _ipaddress.ip_address(str(host))
            except ValueError:
                return [(_socket.AF_INET, _socket.SOCK_STREAM, 6, "",
                         ("93.184.216.34", 0))]
            return _real_getaddrinfo(host, port, *a, **k)

        self._dns_patch = _mock.patch.object(
            _browse_mod.socket, "getaddrinfo", _stub_getaddrinfo)
        self._dns_patch.start()
        self._tmp = tempfile.TemporaryDirectory()
        self.ws = Path(self._tmp.name)
        (self.ws / ".forge").mkdir()
        self.log_file = self.ws / "calls.jsonl"
        self._scripts = {}
        for name, text in (("fake_browse_server.py", FAKE_BROWSE_SERVER),
                           ("fake_verify_server.py", FAKE_VERIFY_SERVER)):
            script = self.ws / name
            script.write_text(text)
            self._scripts[name] = script
        self.registry = self._load()

    def tearDown(self):
        from forge import browse as browse_mod
        browse_mod.clear_hold(self.ws)
        self._dns_patch.stop()
        module = sys.modules.get("mcp_client")
        if module is not None:
            for server in list(module._servers.values()):
                try:
                    server.proc.terminate()
                except Exception:
                    pass
            module._servers.clear()
            module._server_fingerprints.clear()
        self._tmp.cleanup()

    def _load(self, script="fake_browse_server.py", config=None,
              current_model=""):
        if config is None:
            config = {
                "mcp_servers": {"browse": {
                    "command": "python3",
                    "args": [str(self._scripts[script]),
                             str(self.log_file)]}},
                "browse": {"server": "browse"}}
        root = Path(__file__).resolve().parent.parent
        ctx = PluginContext(workspace=str(self.ws), config=config,
                            current_model=current_model,
                            log=lambda m: None)
        _plugins, registry = load_plugins(root / "plugins", ctx)
        return registry

    def _calls(self):
        if not self.log_file.exists():
            return []
        return [json.loads(line) for line in
                self.log_file.read_text(encoding="utf-8").splitlines()
                if line.strip()]

    def _allow(self, hosts):
        (self.ws / ".forge" / "browse.json").write_text(
            json.dumps({"allowlist": hosts}), encoding="utf-8")

    def _handler(self, registry=None):
        return (registry or self.registry)["verify_in_browser"][1]

    def _page(self, name="index.html", body="<h1>hi</h1>"):
        (self.ws / name).write_text(body, encoding="utf-8")

    def test_verify_tool_registered_read_class(self):
        from forge import browse as browse_mod
        self.assertIn("verify_in_browser", self.registry)
        schema, _handler, approval, _plugin = \
            self.registry["verify_in_browser"]
        # Read-class exactly as browse_read / browse_screenshot:
        # no approval gate, so modes treat it as a read.
        self.assertFalse(approval)
        self.assertEqual(
            schema["function"]["parameters"]["required"], ["target"])
        for name in browse_mod.VERB_TOOLS:
            self.assertIn(name, self.registry)

    def test_local_page_verified_with_no_allowlist_at_all(self):
        # THE EXCEPTION, pinned: no .forge/browse.json exists, so
        # the allowlist is empty and every external host would be
        # refused — yet the project's own page verifies, because
        # the preview origin exists only for this call.
        import socket
        import urllib.parse
        self._page()
        result = self._handler()({"target": "index.html"})
        self.assertIn("Verified in the browser: index.html", result)
        self.assertIn("did snapshot", result)
        calls = self._calls()
        self.assertEqual([c["tool"] for c in calls],
                         ["navigate", "snapshot", "screenshot"])
        url = calls[0]["arguments"]["url"]
        self.assertTrue(url.startswith("http://127.0.0.1:"))
        self.assertTrue(url.endswith("/index.html"))
        # Read's text pin rides through the composite unchanged.
        self.assertEqual(calls[1]["arguments"], {"format": "text"})
        # The fake server's screenshot reply is prose, not image
        # data — saved as returned, as a text artifact.
        self.assertIn(".forge/artifacts/verify-", result)
        self.assertIn(".txt", result)
        saved = list((self.ws / ".forge" / "artifacts")
                     .glob("verify-*.txt"))
        self.assertEqual(len(saved), 1)
        # The preview is DOWN once the call has ended.
        port = urllib.parse.urlparse(url).port
        with self.assertRaises(OSError):
            socket.create_connection(("127.0.0.1", port), timeout=2)

    def test_local_preview_serves_real_bytes_then_shuts_down(self):
        import urllib.error
        import urllib.request
        from forge import verify as verify_mod
        self._page("page.html", "<h1>real bytes</h1>")
        seen = {}

        def call(key, args):
            if key == "open":
                seen["url"] = args["url"]
                with urllib.request.urlopen(
                        args["url"], timeout=5) as resp:
                    seen["body"] = resp.read().decode("utf-8")
                return "opened"
            if key == "read":
                return "stub page text"
            return ""

        result = verify_mod.run_verify("page.html", str(self.ws), call)
        self.assertEqual(seen["body"], "<h1>real bytes</h1>")
        self.assertIn("stub page text", result)
        self.assertIn("no screenshot", result)
        with self.assertRaises(urllib.error.URLError):
            urllib.request.urlopen(seen["url"], timeout=2)

    def test_traversal_outside_workspace_refused(self):
        self._page()
        for target in ("../outside.html", "sub/../../outside.html"):
            result = self._handler()({"target": target})
            self.assertIn("outside this project", result)
        self.assertEqual(self._calls(), [])

    def test_missing_local_file_refused_in_plain_words(self):
        result = self._handler()({"target": "nope.html"})
        self.assertIn("no 'nope.html' in this project", result)
        self.assertEqual(self._calls(), [])

    def test_non_http_scheme_refused(self):
        result = self._handler()({"target": "file:///etc/passwd"})
        self.assertIn("not an http/https URL", result)
        self.assertEqual(self._calls(), [])

    def test_unlisted_external_url_refused_before_server(self):
        self._allow(["example.com"])
        result = self._handler()({"target": "https://evil.example.net/"})
        self.assertIn("not on this project's Browse site allowlist",
                      result)
        self.assertEqual(self._calls(), [])

    def test_allowlisted_external_url_works(self):
        self._allow(["example.com"])
        result = self._handler()({"target": "https://example.com/page"})
        self.assertIn("Verified in the browser: https://example.com/page",
                      result)
        self.assertIn("did snapshot", result)
        self.assertEqual([c["tool"] for c in self._calls()],
                         ["navigate", "snapshot", "screenshot"])
        self.assertEqual(self._calls()[0]["arguments"]["url"],
                         "https://example.com/page")

    def test_screenshot_saved_as_image_under_artifacts(self):
        registry = self._load("fake_verify_server.py")
        self._page()
        result = self._handler(registry)({"target": "index.html"})
        self.assertIn("VERIFY PAGE TEXT", result)
        saved = list((self.ws / ".forge" / "artifacts")
                     .glob("verify-*.png"))
        self.assertEqual(len(saved), 1)
        self.assertTrue(
            saved[0].read_bytes().startswith(b"\x89PNG\r\n\x1a\n"))
        self.assertIn(f".forge/artifacts/{saved[0].name}", result)
        # The image itself is NOT in the result — no base64 payload
        # rides back into the conversation.
        self.assertNotIn("iVBORw0KGgo", result)

    def test_no_image_payload_whatever_the_model(self):
        # The screenshot rule does not depend on who is driving:
        # a vision-named model and a text-only one get the same
        # text result with the saved file's path, never the image.
        self._page()
        for model in ("llava:latest", "bonsai-2-uncensored"):
            registry = self._load("fake_verify_server.py",
                                  current_model=model)
            result = self._handler(registry)({"target": "index.html"})
            self.assertIn(".forge/artifacts/verify-", result)
            self.assertIn(".png", result)
            self.assertNotIn("iVBORw0KGgo", result)

    def test_wall_hold_refuses_verify(self):
        from forge import browse as browse_mod
        self._page()
        browse_mod.set_hold(self.ws, "payment")
        result = self._handler()({"target": "index.html"})
        self.assertIn("HELD", result)
        self.assertIn("browse_hand_back", result)
        self.assertEqual(self._calls(), [])

    def test_unconfigured_verify_answers_with_setup_words(self):
        registry = self._load(config={"browse": {"server": "browse"}})
        self._page()
        result = self._handler(registry)({"target": "index.html"})
        self.assertIn("not configured yet", result)
        self.assertIn("Customize → Connectors", result)
        self.assertEqual(self._calls(), [])

    def test_disabled_connector_offers_no_verify_tool(self):
        root = Path(__file__).resolve().parent.parent
        ctx = PluginContext(workspace=str(self.ws), config={
            "mcp_servers": {"browse": {"command": "python3", "args": []}},
            "browse": {"server": "browse"}}, log=lambda m: None)
        _plugins, registry = load_plugins(
            root / "plugins", ctx, disabled={"browse"})
        self.assertNotIn("verify_in_browser", registry)
