class DeckProjectResolveTests(unittest.TestCase):
    """Phone-deck project switching: target resolution (deck.resolve_project)."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        (self.root / "alpha").mkdir()
        (self.root / "beta").mkdir()
        (self.root / "afile.txt").write_text("x")
        self.projects = [{"name": "Alpha", "path": str(self.root / "alpha")},
                         {"name": "Beta", "path": str(self.root / "beta")}]

    def tearDown(self):
        self.temp.cleanup()

    def test_name_match_exact(self):
        from forge.deck import resolve_project
        path, err = resolve_project("Beta", self.projects)
        self.assertIsNone(err)
        self.assertEqual(path, str(self.root / "beta"))

    def test_name_match_case_insensitive(self):
        from forge.deck import resolve_project
        path, err = resolve_project("bEtA", self.projects)
        self.assertIsNone(err)
        self.assertEqual(path, str(self.root / "beta"))

    def test_name_match_wins_over_path(self):
        # A relative folder named like a project must not shadow the
        # registered project: the name match resolves first.
        from forge.deck import resolve_project
        path, err = resolve_project("Alpha", self.projects)
        self.assertIsNone(err)
        self.assertEqual(path, str(self.root / "alpha"))

    def test_path_to_directory(self):
        from forge.deck import resolve_project
        path, err = resolve_project(str(self.root / "beta"), [])
        self.assertIsNone(err)
        self.assertEqual(path, str(self.root / "beta"))

    def test_path_to_unregistered_directory(self):
        from forge.deck import resolve_project
        other = self.root / "gamma"
        other.mkdir()
        path, err = resolve_project(str(other), self.projects)
        self.assertIsNone(err)
        self.assertEqual(path, str(other))

    def test_path_expanduser(self):
        from forge.deck import resolve_project
        path, err = resolve_project("~", [])
        self.assertIsNone(err)
        self.assertEqual(path, str(Path.home()))

    def test_missing_path_errors(self):
        from forge.deck import resolve_project
        path, err = resolve_project(str(self.root / "nope"), self.projects)
        self.assertIsNone(path)
        self.assertIn("No project named", err)

    def test_file_is_not_a_project(self):
        from forge.deck import resolve_project
        path, err = resolve_project(str(self.root / "afile.txt"), self.projects)
        self.assertIsNone(path)
        self.assertIn("Not a folder", err)

    def test_empty_target_errors(self):
        from forge.deck import resolve_project
        for bad in ("", "   ", None):
            path, err = resolve_project(bad, self.projects)
            self.assertIsNone(path)
            self.assertIn("No project given", err)

    def test_page_has_project_controls(self):
        from forge.deck import PAGE
        self.assertIn('id="projsel"', PAGE)      # the dropdown
        self.assertIn('id="projtext"', PAGE)     # the typed-path field
        self.assertIn('id="projmsg"', PAGE)      # the visible result line
        self.assertIn("[ 02 ] PROJECT", PAGE)
        self.assertIn("'/project", PAGE)         # endpoint wired in the JS


