class _CouncilRecordingWorker(_GateWorker):
    """_GateWorker that also keeps the kwargs it was constructed
    with, so a test can read the council flag the window handed it."""

    def __init__(self, *args, **kwargs):
        self.kwargs = dict(kwargs)
        super().__init__(*args, **kwargs)


class DeckCouncilTests(unittest.TestCase):
    """Item 10: the deck's Council chip flips the desktop's per-turn
    Council checkbox — the checkbox stays the single source of truth,
    and a phone send rides the same send path as a desktop send."""

    MODEL = "maternion/minicpm5-heretic:2b"

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()
        if cls.win.model_combo.findText(cls.MODEL) < 0:
            cls.win.model_combo.addItem(cls.MODEL)
        cls.win.model_combo.setCurrentIndex(
            cls.win.model_combo.findText(cls.MODEL))

    @classmethod
    def tearDownClass(cls):
        cls.win.council_check.setChecked(False)
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        self.win.messages = []
        self.win.conversation_id = None
        self.win.council_check.setChecked(False)
        # _deck_sync stands down while the deck server is off; satisfy
        # its gate so the real sync -> snapshot chain runs.
        self._real_server = self.win.deck._server
        self.win.deck._server = object()

    def tearDown(self):
        self.win.deck._server = self._real_server
        self.win.worker = None
        self.win.council_check.setChecked(False)
        self.temp.cleanup()

    def _pump_until(self, pred, timeout=5.0):
        import time
        deadline = time.time() + timeout
        while time.time() < deadline:
            self.app.processEvents()
            if pred():
                return
            time.sleep(0.02)
        self.app.processEvents()

    def test_page_has_council_control(self):
        from forge.deck import PAGE
        self.assertIn('id="councilbtn"', PAGE)     # the chip
        self.assertIn('id="councilmodel"', PAGE)   # reviewer name label
        self.assertIn("toggleCouncil", PAGE)
        self.assertIn("'/council", PAGE)           # endpoint wired in the JS

    def test_snapshot_defaults_carry_council(self):
        from forge.deck import DeckServer
        snap = DeckServer().snapshot()
        self.assertIs(snap["council"], False)
        self.assertEqual(snap["council_model"], "")

    def test_snapshot_follows_the_checkbox(self):
        from forge import council as council_mod
        from forge.main import short_model
        expected = short_model(council_mod.resolve_reviewer_model(
            self.win.settings.get("reviewer_model", ""),
            self.win.settings.get("governing_roster", "")))
        self.win._deck_sync()
        snap = self.win.deck.snapshot()
        self.assertIs(snap["council"], False)
        self.assertEqual(snap["council_model"], expected)
        self.assertTrue(snap["council_model"])  # a name, not a blank
        self.win.council_check.setChecked(True)
        self.win._deck_sync()
        self.assertIs(self.win.deck.snapshot()["council"], True)

    def test_signal_flips_checkbox_both_directions(self):
        self.win.deck.council_changed.emit(True)
        self.assertTrue(self.win.council_check.isChecked())
        # The checkbox's own hook ran: the setting the send path and
        # the desktop both read is the flipped one — nothing forked.
        self.assertIs(self.win.settings.get("council"), True)
        self.win.deck.council_changed.emit(True)   # same state: a no-op
        self.assertTrue(self.win.council_check.isChecked())
        self.win.deck.council_changed.emit(False)
        self.assertFalse(self.win.council_check.isChecked())
        self.assertIs(self.win.settings.get("council"), False)

    def test_http_post_council_flips_checkbox(self):
        import json as json_mod
        import urllib.request
        deck = self.win.deck
        deck._server = None  # undo the setUp gate fake; start for real
        deck.start()
        try:
            def post(payload):
                req = urllib.request.Request(
                    f"http://127.0.0.1:{deck.port}/council?k={deck.token}",
                    data=json_mod.dumps(payload).encode(),
                    headers={"Content-Type": "application/json"},
                    method="POST")
                with urllib.request.urlopen(req, timeout=10) as r:
                    return r.status
            self.assertEqual(post({"on": True}), 204)
            self._pump_until(lambda: self.win.council_check.isChecked())
            self.assertTrue(self.win.council_check.isChecked())
            self.assertEqual(post({"on": False}), 204)
            self._pump_until(lambda: not self.win.council_check.isChecked())
            self.assertFalse(self.win.council_check.isChecked())
            # A bare POST toggles against the last synced state.
            self.win._deck_sync()
            self.assertEqual(post({}), 204)
            self._pump_until(lambda: self.win.council_check.isChecked())
            self.assertTrue(self.win.council_check.isChecked())
        finally:
            deck.stop()

    def test_phone_prompt_after_toggle_reaches_worker_with_council(self):
        from unittest import mock
        import forge.main as main_mod
        _GateWorker.instances = []
        with mock.patch.object(main_mod, "AgentWorker", _CouncilRecordingWorker):
            self.win.deck.council_changed.emit(True)
            self.win._on_phone_prompt("review the thing")
            self.assertEqual(len(_GateWorker.instances), 1)
            worker = _GateWorker.instances[0]
            self.assertIs(worker.kwargs.get("council"), True)
            self.assertTrue(worker.started)
            # Chip off: the same phone send path carries False.
            self.win.worker = None
            _GateWorker.instances = []
            self.win.deck.council_changed.emit(False)
            self.win._on_phone_prompt("plain turn")
            self.assertEqual(len(_GateWorker.instances), 1)
            self.assertIs(_GateWorker.instances[0].kwargs.get("council"), False)

    def test_toggle_during_turn_keeps_running_workers_flag(self):
        # Mirror of /mode: a mid-turn flip moves the control, and the
        # running worker keeps the flag it was built with — the new
        # state lands on the next turn.
        from unittest import mock
        import forge.main as main_mod
        _GateWorker.instances = []
        with mock.patch.object(main_mod, "AgentWorker", _CouncilRecordingWorker):
            self.win._on_phone_prompt("first turn")
            running = _GateWorker.instances[0]
            self.assertIs(running.kwargs.get("council"), False)
            self.assertTrue(running.isRunning())   # the turn is live
            self.win.deck.council_changed.emit(True)
            self.assertTrue(self.win.council_check.isChecked())
            self.assertIs(running.kwargs.get("council"), False)
            self.win.worker = None


class DeckPromptDeliveryTests(unittest.TestCase):
    """Phone-deck prompt delivery (owner's field report, 2026-11-07):
    /prompt was a blind 204 and sendPrompt cleared the box without
    reading any answer, so the phone could not show sent vs failed.
    The fix mirrors /project exactly: /prompt answers 200 + JSON from
    a synchronous GUI-thread round trip, and the SEND card shows the
    outcome on a #promptmsg line. Nothing else about the deck moves."""

    MODEL = "maternion/minicpm5-heretic:2b"

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()
        if cls.win.model_combo.findText(cls.MODEL) < 0:
            cls.win.model_combo.addItem(cls.MODEL)
        cls.win.model_combo.setCurrentIndex(
            cls.win.model_combo.findText(cls.MODEL))

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        self.win._phone_queue = []
        self.win.messages = []
        self.win.conversation_id = None

    def tearDown(self):
        self.win.worker = None
        self.win._phone_queue = []
        self.temp.cleanup()

    def _pump_until(self, pred, timeout=5.0):
        import time
        deadline = time.time() + timeout
        while time.time() < deadline:
            self.app.processEvents()
            if pred():
                return True
            time.sleep(0.02)
        return pred()

    def test_page_has_prompt_status_line(self):
        from forge.deck import PAGE
        self.assertIn('id="promptmsg"', PAGE)   # the outcome line
        self.assertIn("postPrompt", PAGE)       # send path reads the answer
        self.assertIn("/prompt?k=", PAGE)       # the endpoint it posts to

    def test_deliver_reports_received_and_starts_the_turn(self):
        from unittest import mock
        import forge.main as main_mod
        _GateWorker.instances = []
        with mock.patch.object(main_mod, "AgentWorker", _CouncilRecordingWorker):
            ok, message = self.win._deliver_phone_prompt("build the thing")
            self.assertTrue(ok)
            self.assertIn("Received", message)
            self.assertEqual(len(_GateWorker.instances), 1)
            self.assertTrue(_GateWorker.instances[0].started)

    def test_deliver_reports_queued_while_a_turn_runs(self):
        from unittest import mock
        import forge.main as main_mod
        _GateWorker.instances = []
        with mock.patch.object(main_mod, "AgentWorker", _CouncilRecordingWorker):
            ok, _msg = self.win._deliver_phone_prompt("first turn")
            self.assertTrue(ok)
            ok, message = self.win._deliver_phone_prompt("second turn")
            self.assertTrue(ok)
            self.assertIn("Queued", message)
            self.assertEqual(self.win._phone_queue, ["second turn"])
            self.assertEqual(len(_GateWorker.instances), 1)  # nothing new started

    def test_two_prompts_during_one_turn_both_stay_queued_in_order(self):
        from unittest import mock
        import forge.main as main_mod
        _GateWorker.instances = []
        with mock.patch.object(main_mod, "AgentWorker", _CouncilRecordingWorker):
            ok, _msg = self.win._deliver_phone_prompt("first turn")
            self.assertTrue(ok)
            ok, message = self.win._deliver_phone_prompt("queued one")
            self.assertTrue(ok)
            self.assertEqual(message,
                             "Queued — it runs when the current turn ends.")
            ok, message = self.win._deliver_phone_prompt("queued two")
            self.assertTrue(ok)
            self.assertIn("#2 in line", message)
            # FIFO: neither prompt overwrote the other.
            self.assertEqual(self.win._phone_queue, ["queued one", "queued two"])
            self.assertEqual(len(_GateWorker.instances), 1)  # nothing new started

    def test_drain_delivers_oldest_first_then_the_next(self):
        from unittest import mock
        import forge.main as main_mod
        _GateWorker.instances = []
        with mock.patch.object(main_mod, "AgentWorker", _CouncilRecordingWorker):
            self.win._deliver_phone_prompt("first turn")
            self.win._deliver_phone_prompt("queued one")
            self.win._deliver_phone_prompt("queued two")
            self.assertEqual(len(_GateWorker.instances), 1)
            # The running turn ends; the drain fires the oldest only.
            self.win.worker = None
            self.win._drain_phone_queue()
            self.assertTrue(self._pump_until(
                lambda: len(_GateWorker.instances) == 2, timeout=3))
            fired = _GateWorker.instances[-1]
            self.assertTrue(any("queued one" in str(m) for m in fired.messages))
            self.assertEqual(self.win._phone_queue, ["queued two"])
            # Draining again delivers the next one.
            self.win.worker = None
            self.win._drain_phone_queue()
            self.assertTrue(self._pump_until(
                lambda: len(_GateWorker.instances) == 3, timeout=3))
            fired = _GateWorker.instances[-1]
            self.assertTrue(any("queued two" in str(m) for m in fired.messages))
            self.assertEqual(self.win._phone_queue, [])

    def test_deliver_project_command_reports_its_result(self):
        ok, message = self.win._deliver_phone_prompt("/project")
        self.assertTrue(ok)
        self.assertIn("Project:", message)
        ok, message = self.win._deliver_phone_prompt(
            "/project /nonexistent-forge-dir-xyz")
        self.assertFalse(ok)
        self.assertTrue(message)

    def test_gui_slot_fills_the_holder(self):
        from unittest import mock
        import forge.main as main_mod
        import threading
        _GateWorker.instances = []
        holder = {"event": threading.Event(), "result": None}
        with mock.patch.object(main_mod, "AgentWorker", _CouncilRecordingWorker):
            self.win._deck_prompt_delivery("hello forge", holder)
        self.assertTrue(holder["event"].is_set())
        ok, message = holder["result"]
        self.assertTrue(ok)
        self.assertIn("Received", message)

    def test_http_prompt_round_trip_answers_json(self):
        import json as json_mod
        import threading
        import urllib.request
        from forge.deck import DeckServer
        server = DeckServer()
        verdict = {"answer": (True, "Received — the Forge is on it.")}

        def slot(text, holder):
            holder["result"] = verdict["answer"]
            holder["event"].set()

        server.prompt_delivery_requested.connect(slot)
        server.start()
        try:
            def post(payload):
                box = {}

                def run():
                    req = urllib.request.Request(
                        f"http://127.0.0.1:{server.port}/prompt?k={server.token}",
                        data=json_mod.dumps(payload).encode(),
                        headers={"Content-Type": "application/json"},
                        method="POST")
                    try:
                        with urllib.request.urlopen(req, timeout=10) as r:
                            box["status"] = r.status
                            box["body"] = r.read().decode()
                    except Exception as exc:  # surfaced by the asserts below
                        box["error"] = exc

                t = threading.Thread(target=run)
                t.start()
                self._pump_until(lambda: not t.is_alive(), timeout=10)
                t.join(timeout=2)
                self.assertNotIn("error", box)
                return box["status"], json_mod.loads(box["body"])

            status, body = post({"text": "hello"})
            self.assertEqual(status, 200)
            self.assertIs(body["ok"], True)
            self.assertIn("Received", body["message"])
            verdict["answer"] = (False, "The bench is mid-turn.")
            status, body = post({"text": "hello again"})
            self.assertEqual(status, 200)
            self.assertIs(body["ok"], False)
            self.assertIn("mid-turn", body["error"])
            status, body = post({"text": "   "})
            self.assertEqual(status, 200)
            self.assertIs(body["ok"], False)
        finally:
            server.stop()


class _PlanRecordingWorker:
    """A live-worker stand-in for plan-gate tests: isRunning() true,
    resolve_plan calls recorded, nothing else."""

    def __init__(self):
        self.calls = []

    def isRunning(self):
        return True

    def resolve_plan(self, action, steps=None):
        self.calls.append((action, steps))


class DeckPlanActionTests(unittest.TestCase):
    """Phone-deck plan gate (audit C25): the [08] PLAN card was
    read-only, so a plan drafted at the owner's request parked the
    turn at the gate while the phone could only watch. POST /plan
    now round-trips like /prompt (200 + JSON from a synchronous
    GUI-thread answer), the card shows Approve/Kill only while the
    synced plan is a draft, and the window answers through the SAME
    _plan_gate_action the desktop buttons call — unchanged."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        self.win.conversation_id = None
        self.win.plan_state = None
        self.win._plan_render()

    def tearDown(self):
        self.win.worker = None
        self.win.plan_state = None
        self.win._plan_render()
        self.temp.cleanup()

    def _pump_until(self, pred, timeout=5.0):
        import time
        deadline = time.time() + timeout
        while time.time() < deadline:
            self.app.processEvents()
            if pred():
                return True
            time.sleep(0.02)
        return pred()

    def _holder(self):
        import threading
        return {"event": threading.Event(), "result": None}

    def test_page_has_plan_gate_controls(self):
        from forge.deck import PAGE
        self.assertIn('id="planbtns"', PAGE)          # the actions row
        self.assertIn('id="planmsg"', PAGE)           # the outcome line
        self.assertIn("✓ Approve plan", PAGE)
        self.assertIn("✗ Kill plan", PAGE)
        self.assertIn("planAction", PAGE)             # the click path
        self.assertIn("/plan?k=", PAGE)               # the endpoint it posts to
        self.assertIn("p.status === 'draft'", PAGE)   # shown only for a draft

    def test_approve_releases_the_gate_with_the_current_steps(self):
        from forge import planning
        self.win.plan_state = planning.new_plan(["Step A", "Step B"])
        worker = _PlanRecordingWorker()
        self.win.worker = worker
        holder = self._holder()
        self.win._deck_plan_action("approve", holder)
        self.assertTrue(holder["event"].is_set())
        self.assertEqual(holder["result"],
                         (True, "Plan approved — working the steps."))
        self.assertEqual(self.win.plan_state["status"], "running")
        self.assertEqual(worker.calls, [("approve", ["Step A", "Step B"])])

    def test_kill_releases_the_gate(self):
        from forge import planning
        self.win.plan_state = planning.new_plan(["Step A"])
        worker = _PlanRecordingWorker()
        self.win.worker = worker
        holder = self._holder()
        self.win._deck_plan_action("kill", holder)
        self.assertTrue(holder["event"].is_set())
        self.assertEqual(holder["result"],
                         (True, "Plan killed — nothing was executed."))
        self.assertEqual(self.win.plan_state["status"], "killed")
        self.assertEqual(worker.calls, [("kill", None)])

    def test_no_draft_refuses_and_never_resolves(self):
        from forge import planning
        worker = _PlanRecordingWorker()
        self.win.worker = worker
        # No plan at all: both actions refused, gate never touched.
        for action in ("approve", "kill"):
            holder = self._holder()
            self.win._deck_plan_action(action, holder)
            self.assertEqual(holder["result"],
                (False, "That plan is no longer waiting for a decision."))
        # A plan that already left the gate: same refusal.
        self.win.plan_state = planning.new_plan(["Step A"])
        self.win.plan_state["status"] = "running"
        for action in ("approve", "kill"):
            holder = self._holder()
            self.win._deck_plan_action(action, holder)
            self.assertEqual(holder["result"],
                (False, "That plan is no longer waiting for a decision."))
        self.assertEqual(worker.calls, [])

    def test_http_plan_round_trip_answers_json(self):
        import json as json_mod
        import threading
        import urllib.request
        from forge.deck import DeckServer
        server = DeckServer()
        seen = []
        verdict = {"answer": (True, "Plan approved — working the steps.")}

        def slot(action, holder):
            seen.append(action)
            holder["result"] = verdict["answer"]
            holder["event"].set()

        server.plan_action_requested.connect(slot)
        server.start()
        try:
            def post(payload):
                box = {}

                def run():
                    req = urllib.request.Request(
                        f"http://127.0.0.1:{server.port}/plan?k={server.token}",
                        data=json_mod.dumps(payload).encode(),
                        headers={"Content-Type": "application/json"},
                        method="POST")
                    try:
                        with urllib.request.urlopen(req, timeout=10) as r:
                            box["status"] = r.status
                            box["body"] = r.read().decode()
                    except Exception as exc:  # surfaced by the asserts below
                        box["error"] = exc

                t = threading.Thread(target=run)
                t.start()
                self._pump_until(lambda: not t.is_alive(), timeout=10)
                t.join(timeout=2)
                self.assertNotIn("error", box)
                return box["status"], json_mod.loads(box["body"])

            status, body = post({"action": "approve"})
            self.assertEqual(status, 200)
            self.assertIs(body["ok"], True)
            self.assertIn("Plan approved", body["message"])
            self.assertEqual(seen, ["approve"])
            # An unknown action is refused WITHOUT reaching the window.
            status, body = post({"action": "bogus"})
            self.assertEqual(status, 200)
            self.assertIs(body["ok"], False)
            self.assertEqual(body["error"], "Unknown plan action.")
            self.assertEqual(seen, ["approve"])  # nothing new emitted
            # The window's own refusal rides back as the error.
            verdict["answer"] = (False,
                "That plan is no longer waiting for a decision.")
            status, body = post({"action": "kill"})
            self.assertEqual(status, 200)
            self.assertIs(body["ok"], False)
            self.assertIn("no longer waiting", body["error"])
            self.assertEqual(seen, ["approve", "kill"])
        finally:
            server.stop()


class _FakeShowClient:
    """Item #71 test double for the window's client: answers
    /api/show from a script (a dict, or an exception to raise) and
    counts the calls, so the capability guard and its cache are
    tested against the show contract — never against assumptions
    about particular models."""

    def __init__(self, info=None, error=None):
        self.info = info
        self.error = error
        self.calls = []
        self.base_url = "http://127.0.0.1:11434"

    def show(self, model):
        self.calls.append(model)
        if self.error is not None:
            raise self.error
        return self.info


class AttachmentManagementTests(unittest.TestCase):
    """Item #71 — attachment management + the multimodal poison
    cure. The trap, from the owner's live report: an image baked
    into a stored message was re-sent with the history on EVERY
    later turn, so one attach to a text-only model failed that
    conversation forever (phone prompts included — the phone
    could not even SEE the attachment). The build: a compose
    attachment strip on desktop + deck (multi-attach appends,
    per-item remove), deck attach by upload, a send-time
    capability guard fed by /api/show, and a self-heal quarantine
    that strips stored images after a real multimodal rejection."""

    MODEL = "attach-test-model"
    MULTIMODAL_400 = ('Ollama returned HTTP 400: {"error":"Multimodal data '
                      'provided, but model does not support multimodal '
                      'requests."}')

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()
        if cls.win.model_combo.findText(cls.MODEL) < 0:
            cls.win.model_combo.addItem(cls.MODEL)

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.proj_dir = root / "proj"
        self.proj_dir.mkdir()
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self._old_client = self.win.client
        self._old_workspace = self.win.workspace
        self.win.workspace = str(self.proj_dir)
        self.win.worker = None
        self.win._fold_thread = None
        self.win.messages = []
        self.win.conversation_id = None
        self.win.pending_attachments = []
        self.win._sync_pending()
        self.win._vision_cache = {}
        self.win._send_refusal = None
        self.win.input.clear()
        self._ensure_model()
        _OptionsRecordingWorker.instances = []

    def tearDown(self):
        self.win.client = self._old_client
        self.win.workspace = self._old_workspace
        self.win.worker = None
        self.win.pending_attachments = []
        self.win._sync_pending()
        self.win.messages = []
        self.win.conversation_id = None
        self.temp.cleanup()

    # -- helpers ---------------------------------------------------
    @staticmethod
    def _png_b64(rgb=(200, 30, 30), size=(4, 4)):
        import base64
        from PySide6.QtCore import QBuffer, QIODevice
        from PySide6.QtGui import QColor, QPixmap
        pix = QPixmap(*size)
        pix.fill(QColor(*rgb))
        buf = QBuffer()
        buf.open(QIODevice.WriteOnly)
        pix.save(buf, "PNG")
        return base64.b64encode(bytes(buf.data())).decode("ascii")

    def _ensure_model(self):
        """The window's async model refresh lands whenever it
        lands — in this VM Ollama is unreachable, so its error
        path clears the combo back to the lone driver entry,
        wiping this class's test model (the deck tests pump the
        event loop, which is exactly when the refresh lands).
        Re-adding + selecting here keeps every send aimed at
        MODEL instead of at send_message's modal No-model box."""
        idx = self.win.model_combo.findText(self.MODEL)
        if idx < 0:
            self.win.model_combo.addItem(self.MODEL)
            idx = self.win.model_combo.findText(self.MODEL)
        self.win.model_combo.setCurrentIndex(idx)

    def _send(self):
        from unittest import mock
        import forge.main as main_mod
        self._ensure_model()
        self.win.worker = None
        _OptionsRecordingWorker.instances = []
        with mock.patch.object(main_mod, "AgentWorker",
                               _OptionsRecordingWorker):
            self.win.send_message()
        return _OptionsRecordingWorker.instances

    def _pump_until(self, pred, timeout=5.0):
        import time
        deadline = time.time() + timeout
        while time.time() < deadline:
            self.app.processEvents()
            if pred():
                return True
            time.sleep(0.02)
        return pred()

    def _log_tail(self, mark):
        return "\n".join(self.win._log_lines[mark:])

    def _deck_server(self):
        from forge.deck import DeckServer
        server = DeckServer()
        server.attachment_remove_requested.connect(
            self.win._deck_attachment_remove)
        server.attachment_upload_requested.connect(
            self.win._deck_attachment_upload)
        server.start()
        return server

    def _post(self, server, path, data=None, raw=None, token=True):
        import threading
        import urllib.request
        box = {}

        def run():
            url = f"http://127.0.0.1:{server.port}{path}"
            if token:
                url += ("&" if "?" in url else "?") + f"k={server.token}"
            body = raw if raw is not None else json.dumps(data or {}).encode()
            req = urllib.request.Request(url, data=body, method="POST")
            try:
                with urllib.request.urlopen(req, timeout=10) as r:
                    box["status"] = r.status
                    box["body"] = r.read().decode()
            except urllib.error.HTTPError as exc:
                box["status"] = exc.code
                box["body"] = exc.read().decode()
            except Exception as exc:  # surfaced by the asserts below
                box["error"] = exc

        t = threading.Thread(target=run)
        t.start()
        self._pump_until(lambda: not t.is_alive(), timeout=10)
        t.join(timeout=2)
        self.assertNotIn("error", box)
        return box["status"], box["body"]

    # -- the strip: append, bake in order, per-item remove ---------
    def test_multi_attach_appends_and_bakes_in_order(self):
        first = self._png_b64((200, 30, 30))
        second = self._png_b64((30, 30, 200))
        self.assertNotEqual(first, second)
        self.win._append_pending_image("first.png", first)
        self.win._append_pending_image("second.png", second)
        # Appended, never replaced — and the send mirror agrees.
        self.assertEqual(self.win.pending_images, [first, second])
        self.win._vision_cache[self.MODEL] = True
        self.win.input.setPlainText("look at these")
        instances = self._send()
        self.assertEqual(len(instances), 1, "send never started a worker")
        baked = instances[0].messages[-1]
        self.assertEqual(baked["content"], "look at these")
        self.assertEqual(baked["images"], [first, second])
        # The send consumed the strip: nothing pending, strip hidden.
        self.assertEqual(self.win.pending_attachments, [])
        self.assertTrue(self.win.attach_strip.isHidden())

    def test_desktop_attach_file_appends(self):
        from unittest import mock
        import forge.main as main_mod
        first = self._png_b64((200, 30, 30))
        second = self._png_b64((30, 200, 30))
        import base64
        p1 = self.proj_dir / "one.png"
        p2 = self.proj_dir / "two.png"
        p1.write_bytes(base64.b64decode(first))
        p2.write_bytes(base64.b64decode(second))
        picks = [(str(p1), ""), (str(p2), "")]
        with mock.patch.object(
                main_mod.QFileDialog, "getOpenFileName",
                side_effect=lambda *a, **k: picks.pop(0)):
            self.win.attach_file()
            self.win.attach_file()
        self.assertEqual(self.win.pending_images, [first, second])
        self.assertEqual(
            [a["name"] for a in self.win.pending_attachments],
            ["one.png", "two.png"])

    def test_remove_by_index_keeps_the_rest(self):
        first = self._png_b64((200, 30, 30))
        second = self._png_b64((30, 30, 200))
        self.win._append_pending_image("first.png", first)
        self.win._append_pending_image("second.png", second)
        self.win._append_pending_upload(
            "notes.txt",
            "[Owner attached a file: notes.txt — saved at "
            ".forge/uploads/notes.txt in this project.]")
        gone = self.win._remove_pending(0)
        self.assertEqual(gone["name"], "first.png")
        self.assertEqual(self.win.pending_images, [second])
        self.assertEqual(
            [a["name"] for a in self.win.pending_attachments],
            ["second.png", "notes.txt"])
        self.assertIn("notes.txt", self.win.pending_upload_note)
        # Removing the file entry clears its note from the send.
        self.win._remove_pending(1)
        self.assertEqual(self.win.pending_upload_note, "")
        # A stale index (the deck a beat behind) is a quiet no-op.
        self.assertIsNone(self.win._remove_pending(9))
        self.assertEqual(self.win.pending_images, [second])

    def test_strip_visibility_follows_pending(self):
        self.assertTrue(self.win.attach_strip.isHidden())
        self.win._append_pending_image("a.png", self._png_b64())
        self.assertFalse(self.win.attach_strip.isHidden())
        # One chip + the trailing stretch.
        self.assertEqual(self.win.attach_strip_layout.count(), 2)
        self.win._remove_pending(0)
        self.assertTrue(self.win.attach_strip.isHidden())

    # -- deck parity ------------------------------------------------
    def test_deck_state_carries_attachments_with_thumbnails(self):
        big = self._png_b64((10, 120, 200), size=(200, 150))
        self.win._append_pending_image("big.png", big)
        self.win._append_pending_upload("notes.txt", "a note")
        snap = self.win.deck.snapshot()
        items = snap["attachments"]
        self.assertEqual([(i["name"], i["kind"]) for i in items],
                         [("big.png", "image"), ("notes.txt", "file")])
        thumb = items[0]["thumb"]
        self.assertTrue(thumb.startswith("data:image/png;base64,"))
        # The thumbnail is a downscale, not the original's bytes.
        import base64
        from PySide6.QtGui import QPixmap
        pix = QPixmap()
        self.assertTrue(pix.loadFromData(base64.b64decode(
            thumb.split(",", 1)[1])))
        self.assertLessEqual(pix.width(), 96)
        self.assertLessEqual(pix.height(), 96)
        self.assertNotIn("thumb", items[1])
        # A removal on the bench reaches the phone's next poll.
        self.win._remove_pending(0)
        snap = self.win.deck.snapshot()
        self.assertEqual([i["name"] for i in snap["attachments"]],
                         ["notes.txt"])

    def test_deck_remove_round_trip(self):
        first = self._png_b64((200, 30, 30))
        second = self._png_b64((30, 30, 200))
        self.win._append_pending_image("first.png", first)
        self.win._append_pending_image("second.png", second)
        server = self._deck_server()
        try:
            status, body = self._post(
                server, "/attach-remove", {"index": 0})
            self.assertEqual(status, 200)
            payload = json.loads(body)
            self.assertIs(payload["ok"], True)
            self.assertIn("first.png", payload["message"])
            self.assertEqual(self.win.pending_images, [second])
            # Out of range: the window's refusal rides back.
            status, body = self._post(
                server, "/attach-remove", {"index": 9})
            self.assertIs(json.loads(body)["ok"], False)
            # No index at all: refused at the server, in JSON.
            status, body = self._post(server, "/attach-remove", {})
            self.assertIs(json.loads(body)["ok"], False)
            self.assertIn("index", json.loads(body)["error"])
            # No token: the gate every deck endpoint shares.
            status, _body = self._post(
                server, "/attach-remove", {"index": 0}, token=False)
            self.assertEqual(status, 403)
            self.assertEqual(self.win.pending_images, [second])
        finally:
            server.stop()

    def test_deck_upload_image_and_file(self):
        import base64
        png = base64.b64decode(self._png_b64((90, 90, 90)))
        server = self._deck_server()
        try:
            status, body = self._post(
                server, "/attach-upload?name=phone.png", raw=png)
            self.assertEqual(status, 200)
            payload = json.loads(body)
            self.assertIs(payload["ok"], True)
            self.assertEqual(self.win.pending_images,
                             [self._png_b64((90, 90, 90))])
            self.assertEqual(
                self.win.pending_attachments[0]["name"], "phone.png")
            # A non-image takes the desktop road into project uploads.
            status, body = self._post(
                server, "/attach-upload?name=notes.txt", raw=b"hello deck")
            self.assertIs(json.loads(body)["ok"], True)
            landed = self.proj_dir / ".forge" / "uploads" / "notes.txt"
            self.assertTrue(landed.exists())
            self.assertEqual(landed.read_bytes(), b"hello deck")
            self.assertEqual(self.win.pending_attachments[-1]["kind"],
                             "file")
            # An empty file is refused in words, nothing attached.
            before = len(self.win.pending_attachments)
            status, body = self._post(
                server, "/attach-upload?name=empty.txt", raw=b"")
            self.assertIs(json.loads(body)["ok"], False)
            self.assertEqual(len(self.win.pending_attachments), before)
            # No token: 403, nothing attached.
            status, _body = self._post(
                server, "/attach-upload?name=x.png", raw=png, token=False)
            self.assertEqual(status, 403)
            self.assertEqual(len(self.win.pending_attachments), before)
            # Over the cap: refused before the body is even read.
            from unittest import mock
            import forge.deck as deck_mod
            with mock.patch.object(deck_mod, "ATTACH_UPLOAD_MAX", 4):
                status, body = self._post(
                    server, "/attach-upload?name=big.png", raw=b"0123456789")
            self.assertIs(json.loads(body)["ok"], False)
            self.assertIn("limit", json.loads(body)["error"])
            self.assertEqual(len(self.win.pending_attachments), before)
        finally:
            server.stop()

    def test_deck_page_has_attachment_surface(self):
        from forge.deck import PAGE
        self.assertIn('id="attachstrip"', PAGE)
        self.assertIn('id="attachfile"', PAGE)
        self.assertIn('id="attachmsg"', PAGE)
        self.assertIn("renderAttach", PAGE)
        self.assertIn("uploadAttach", PAGE)
        self.assertIn("removeAttach", PAGE)
        self.assertIn("/attach-upload?k=", PAGE)
        self.assertIn("/attach-remove?k=", PAGE)
        self.assertIn("a.thumb", PAGE)

    # -- the capability guard ---------------------------------------
    def test_capability_answers_and_cache(self):
        fake = _FakeShowClient({"capabilities": ["vision", "tools"]})
        self.win.client = fake
        self.assertIs(self.win._model_accepts_images(self.MODEL), True)
        self.assertIs(self.win._model_accepts_images(self.MODEL), True)
        self.assertEqual(fake.calls, [self.MODEL])  # cached
        fake2 = _FakeShowClient({"capabilities": ["completion"]})
        self.win.client = fake2
        self.assertIs(self.win._model_accepts_images("other-model"), False)
        # Unknown is never cached: a down server is asked again.
        fake3 = _FakeShowClient(error=RuntimeError("server down"))
        self.win.client = fake3
        self.assertIsNone(self.win._model_accepts_images("third-model"))
        self.assertIsNone(self.win._model_accepts_images("third-model"))
        self.assertEqual(len(fake3.calls), 2)
        # A show with no capabilities field is unknown, not a "no".
        self.win.client = _FakeShowClient({})
        self.assertIsNone(self.win._model_accepts_images("fourth-model"))
        # A cloud model is never introspected at all.
        fake4 = _FakeShowClient({"capabilities": []})
        self.win.client = fake4
        self.assertIsNone(
            self.win._model_accepts_images("groq:openai/gpt-oss-20b"))
        self.assertEqual(fake4.calls, [])

    def test_guard_blocks_text_only_model_before_append(self):
        self.win.client = _FakeShowClient({"capabilities": ["completion"]})
        self.win.messages = [{"role": "user", "content": "earlier"},
                             {"role": "assistant", "content": "hi"}]
        self.win._append_pending_image("shot.png", self._png_b64())
        mark = len(self.win._log_lines)
        self.win.input.setPlainText("and this one?")
        instances = self._send()
        self.assertEqual(instances, [], "a worker started despite the guard")
        # Nothing appended, prompt and attachment left intact.
        self.assertEqual(len(self.win.messages), 2)
        self.assertEqual(self.win.input.toPlainText(), "and this one?")
        self.assertEqual(len(self.win.pending_attachments), 1)
        self.assertIn("can't see images", self.win._send_refusal)
        self.assertIn(self.MODEL, self.win._send_refusal)
        self.assertIn("can't see images", self._log_tail(mark))

    def test_guard_fires_for_history_image_with_nothing_pending(self):
        self.win.client = _FakeShowClient({"capabilities": ["completion"]})
