    # -- the self-heal quarantine ------------------------------------
    def _fail(self, error):
        from unittest import mock
        import forge.main as main_mod
        with mock.patch.object(main_mod.QMessageBox, "critical",
                               lambda *a, **k: None):
            self.win.on_failed(error)

    def test_quarantine_heals_stage_conversation(self):
        poisoned = [
            {"role": "user", "content": "look at this",
             "images": [self._png_b64()]},
            {"role": "assistant", "content": "nice"},
            {"role": "user", "content": "plain follow-up"}]
        cid = self.win.store.save(None, poisoned, model=self.MODEL,
                                  project=str(self.proj_dir))
        self.win.conversation_id = cid
        import copy
        self.win.messages = copy.deepcopy(poisoned)
        mark = len(self.win._log_lines)
        self._fail(self.MULTIMODAL_400)
        # The live list healed, text untouched.
        self.assertFalse(any(m.get("images") for m in self.win.messages))
        self.assertEqual(self.win.messages[0]["content"], "look at this")
        # The stored record healed too — the poison cannot come back.
        stored = self.win.store.load(cid)
        self.assertFalse(any(m.get("images") for m in stored))
        self.assertEqual(stored[0]["content"], "look at this")
        self.assertIn("Removed the stored image(s)", self._log_tail(mark))

    def test_other_failures_quarantine_nothing(self):
        self.win.messages = [
            {"role": "user", "content": "look",
             "images": [self._png_b64()]}]
        self._fail("Ollama returned HTTP 500: something else broke")
        self.assertEqual(self.win.messages[0].get("images"),
                         [self._png_b64()])
        # A non-multimodal image complaint is also not the shape.
        self._fail("Ollama returned HTTP 400: invalid request body")
        self.assertIn("images", self.win.messages[0])

    def test_quarantine_heals_background_conversation(self):
        poisoned = [
            {"role": "user", "content": "look", "images": [self._png_b64()]},
            {"role": "assistant", "content": "seen"}]
        cid = self.win.store.save(None, poisoned, model=self.MODEL,
                                  project=str(self.proj_dir))

        class _StubWorker:
            _cancel = False

        stream = {"id": 999, "worker": _StubWorker(),
                  "conversation_id": cid, "title": "Background chat",
                  "workspace": str(self.proj_dir),
                  "project": self.proj_dir.name, "model": self.MODEL,
                  "mode": "code", "prompt": "look", "started_at": 0.0,
                  "last_activity": 0.0, "last_push": 0.0,
                  "stream_text": "", "status_text": "", "gate": None,
                  "background": True, "planning": False, "side": False,
                  "maintenance": False, "settled": None}
        self.win._settle_background_stream(
            stream, None, None, self.MULTIMODAL_400)
        self.assertEqual(stream["settled"][0], "failed")
        stored = self.win.store.load(cid)
        self.assertFalse(any(m.get("images") for m in stored))
        self.assertEqual(stored[0]["content"], "look")


