    def test_repo_dialog_lists_snapshots(self):
        import shutil
        if shutil.which("git") is None:
            self.skipTest("git not installed")
        from forge import snapshots as snap
        from forge.main import SnapshotsDialog
        proj = Path(self.temp.name)
