# Item #58 — mode system rework (all six modes)
# ---------------------------------------------------------------------------

class ModesModuleTests(unittest.TestCase):
    """forge/modes.py + the rewritten MODE_GUIDANCE: skeletons for
    all six modes, the clarify marker machinery, the homework
    record, and the assumptions safety net — all pure text."""

    def test_skeletons_exist_for_all_six_modes(self):
        from forge import modes
        from forge.permissions import MODES, MODE_GUIDANCE
        self.assertEqual(set(modes.SKELETONS), set(MODES))
        self.assertEqual(set(modes.CLARIFY_QUESTIONS), set(MODES))
        for mode in MODES:
            self.assertIn(mode, MODE_GUIDANCE)
            self.assertTrue(modes.SKELETONS[mode], mode)

    def test_guidance_carries_the_discipline(self):
        from forge.permissions import MODE_GUIDANCE
        plan = MODE_GUIDANCE["plan"]
        self.assertIn("HOMEWORK", plan)
        self.assertIn("READY", plan)
        self.assertIn("QUESTIONS BEFORE DRAFTING:", plan)
        for heading in ("## Goal", "## Context found", "## Contents",
                        "## Steps", "## Risks", "## Assumptions"):
            self.assertIn(heading, plan)
        design = MODE_GUIDANCE["design"]
        for heading in ("## What it is", "## How it plays/works",
                        "## Look & feel", "## Numbers/tuning",
                        "## Assets", "## Hand-off notes"):
            self.assertIn(heading, design)
        architect = MODE_GUIDANCE["architect"]
        for heading in ("## Components", "## Data", "## Interfaces",
                        "## Decisions", "## Open questions"):
            self.assertIn(heading, architect)
        # Review keeps its severity format AND gains the coverage line.
        review = MODE_GUIDANCE["review"]
        self.assertIn("BLOCKER / SHOULD-FIX / NIT", review)
        self.assertIn("COVERAGE — read:", review)
        self.assertIn("NOT read:", review)
        # Ask keeps cite-from-code AND gains the homework pass.
        ask = MODE_GUIDANCE["ask"]
        self.assertIn("cite files", ask)
        self.assertIn("HOMEWORK", ask)
        # Code: read before the first edit, and say what was read.
        code = MODE_GUIDANCE["code"]
        self.assertIn("BEFORE your first edit", code)
        self.assertIn("what you read", code)

    def test_questions_marker_round_trip(self):
        from forge import modes
        text = ("QUESTIONS BEFORE DRAFTING:\n"
                "1. Who is it for?\n"
                "2. What device will it run on?\n"
                "- What does done look like?")
        self.assertTrue(modes.is_questions_response(text))
        self.assertFalse(modes.is_questions_response("Here is the plan:"))
        self.assertFalse(modes.is_questions_response(""))
        self.assertEqual(modes.extract_questions(text),
                         ["Who is it for?", "What device will it run on?",
                          "What does done look like?"])

    def test_asked_questions_reads_the_latest_round_from_history(self):
        from forge import modes
        messages = [
            {"role": "user", "content": "build it"},
            {"role": "assistant", "content":
             "QUESTIONS BEFORE DRAFTING:\n1. Who is it for?"},
            {"role": "user", "content": "my cat"},
            {"role": "assistant", "content":
             "QUESTIONS BEFORE DRAFTING:\n1. Which touchscreen?"},
        ]
        self.assertEqual(modes.asked_questions(messages),
                         ["Which touchscreen?"])
        self.assertEqual(modes.asked_questions(
            [{"role": "user", "content": "hi"}]), [])

    def test_ready_and_proceed_markers(self):
        from forge import modes
        self.assertTrue(modes.is_ready("READY"))
        self.assertTrue(modes.is_ready("READY — read the demo."))
        self.assertFalse(modes.is_ready("Ready or not, here I come"))
        self.assertFalse(modes.is_ready("Here is my answer."))
        self.assertTrue(modes.is_proceed("PROCEED"))
        self.assertFalse(modes.is_proceed("Proceed carefully now"))

    def test_homework_note_empty_and_populated(self):
        from forge import modes
        empty = modes.homework_note("plan", [], [])
        self.assertIn("EMPTY", empty)
        self.assertIn("no files exist yet", empty)
        note = modes.homework_note("review", ["src/demo.py"],
                                   ["src/demo.py", "README.md"])
        self.assertIn("src/demo.py", note)
        self.assertIn("2 file(s)", note)
        self.assertNotIn("EMPTY", note)

    def test_section_instructions_carry_their_rules(self):
        from forge import modes
        steps = modes.section_instruction("plan", "Steps", "", [])
        self.assertIn("Verify:", steps)
        self.assertIn("numbered list", steps)
        context = modes.section_instruction("plan", "Context found", "", [])
        self.assertIn("empty", context)
        assumed = modes.section_instruction(
            "plan", "Assumptions", "", ["What does done look like?"])
        self.assertIn("What does done look like?", assumed)
        self.assertIn("Assumed:", assumed)

    def test_assumptions_fallback_fills_only_an_empty_section(self):
        from forge import modes
        doc = ("# Plan\n\n## Goal\nA game.\n\n## Assumptions\n"
               "(not stated)\n")
        out = modes.assumptions_fallback(
            doc, ["What does done look like?", "Which device?"])
        self.assertIn("Assumed (open question carried forward): "
                      "What does done look like?", out)
        self.assertIn("Which device?", out)
        self.assertIn("## Goal", out)
        # A section with real content is left exactly as drafted.
        real = ("# Plan\n\n## Assumptions\n"
                "Assumed: it runs on the touchscreen.\n")
        self.assertEqual(modes.assumptions_fallback(
            real, ["Which device?"]), real)
        # No questions were ever asked — nothing to carry forward.
        self.assertEqual(modes.assumptions_fallback(doc, []), doc)


class PlanDocumentExtractionTests(unittest.TestCase):
    """Item #58 in forge/planning.py: the checklist is EXTRACTED
    from the plan document (Steps section, detail joined), the
    document rides the sidecar, and pre-#58 shapes still load."""

    DOC = ("# Plan\n\n"
           "## Goal\nBuild the parser.\n\n"
           "## Contents\n"
           "1. a.py — create it\n"
           "2. b.py — edit it\n\n"
           "## Steps\n"
           "1. Create a.py — with the parser in it\n"
           "   Verify: it imports cleanly.\n"
           "2. Edit b.py — wire the parser in\n"
           "   Verify: the suite passes.\n\n"
           "## Risks\nNone worth naming.\n")

    def test_steps_come_from_the_steps_section_with_detail(self):
        from forge import planning
        steps = planning.extract_steps(self.DOC)
        # The Contents section's numbered list is NOT the checklist;
        # each step carries its continuation detail, Verify included.
        self.assertEqual(
            steps,
            ["Create a.py — with the parser in it Verify: it imports cleanly.",
             "Edit b.py — wire the parser in Verify: the suite passes."])

    def test_extract_steps_falls_back_to_a_bare_list(self):
        from forge import planning
        self.assertEqual(planning.extract_steps("1. Alpha\n2. Beta"),
                         ["Alpha", "Beta"])
        self.assertIsNone(planning.extract_steps("just prose"))

    def test_replace_steps_section_keeps_the_rest_of_the_document(self):
        from forge import planning
        out = planning.replace_steps_section(
            self.DOC, ["New first step", "New second step"])
        self.assertIn("## Goal\nBuild the parser.", out)
        self.assertIn("1. New first step\n2. New second step", out)
        self.assertEqual(planning.extract_steps(out),
                         ["New first step", "New second step"])
        # No Steps section — returned unchanged.
        self.assertEqual(planning.replace_steps_section(
            "1. A\n2. B", ["X", "Y"]), "1. A\n2. B")

    def test_work_instruction_carries_the_document(self):
        from forge import planning
        steps = planning.extract_steps(self.DOC)
        text = planning.work_instruction(steps, self.DOC)
        self.assertIn("## Goal\nBuild the parser.", text)
        self.assertIn("The checklist", text)
        self.assertIn("1. Create a.py — with the parser in it", text)
        # Without a document the historical form is byte-identical.
        bare = planning.work_instruction(["Alpha", "Beta"])
        self.assertEqual(
            bare,
            "The owner approved this plan — it is now your working "
            "instruction. Work the steps in order. When you finish a "
            "step, announce it on its own line exactly as: STEP <n> "
            "DONE (for example: STEP 1 DONE). Do not announce a step "
            "you have not finished.\n\n1. Alpha\n2. Beta")

    def test_document_round_trips_and_old_sidecars_still_load(self):
        from forge import planning
        with tempfile.TemporaryDirectory() as td:
            plan = planning.new_plan(["One", "Two"], request="build",
                                     document="# Plan\n\n## Goal\nG.\n")
            planning.save_plan(td, 5, plan)
            loaded = planning.load_plan(td, 5)
            self.assertEqual(loaded["document"], "# Plan\n\n## Goal\nG.\n")
            self.assertEqual([s["text"] for s in loaded["steps"]],
                             ["One", "Two"])
        # A pre-#58 sidecar: no document key at all — loads with "".
        old = {"version": 1, "status": "draft", "request": "build",
               "steps": [{"text": "One", "state": "pending",
                          "resource": ""}],
               "skribe": "", "goldfish": None,
               "created": "", "updated": ""}
        loaded = planning.sanitize_plan(old)
        self.assertIsNotNone(loaded)
        self.assertEqual(loaded["document"], "")
        self.assertEqual(loaded["steps"][0]["text"], "One")
        # The deck projection's shape is untouched by the document.
        shape = planning.deck_plan(loaded)
        self.assertEqual(shape["steps"], [{"text": "One",
                                           "state": "pending"}])
        self.assertNotIn("document", shape)



class HomeworkPhaseWorkerTests(unittest.TestCase):
    """Item #58 at the worker: the Plan turn runs a READ-TOOLS
    homework pass before drafting, the clarify choice can end the
    turn with questions (whose skipped answers become ASSUMPTIONS
    in the document), and sections draft one at a time into the
    plan document the gate then consumes."""

    SECTIONS = [
        {"content": "A tapping game for the owner's cat."},
        {"content": "The project has src/demo.py and nothing else."},
        {"content": "game.py — new file; README.md — update."},
        {"content": "1. Write game.py — the tap targets and scoring\n"
                    "   Verify: it runs and scores a tap.\n"
                    "2. Update README.md — how to play\n"
                    "   Verify: it names the controls."},
        {"content": "The cat may ignore it entirely."},
        {"content": "Assumed: it runs on the touchscreen PC."},
        {"content": "Done means a tap scores on screen and the "
                    "README names the controls."},
        {"content": "Not doing: online leaderboards or accounts."},
    ]
    STEPS = ["Write game.py — the tap targets and scoring "
             "Verify: it runs and scores a tap.",
             "Update README.md — how to play Verify: it names the controls."]

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    def _pump_until(self, pred, timeout=10.0):
        """Wait for a worker predicate while PUMPING the Qt event
        loop — the auto-approval lambda is delivered through it."""
        import time
        deadline = time.time() + timeout
        while time.time() < deadline:
            self.app.processEvents()
            if pred():
                return True
            time.sleep(0.02)
        return pred()

    def _kill_at_gate(self, w, seen):
        w.resolve_plan("kill")
        self.assertTrue(self._pump_until(lambda: bool(seen["finished"])))
        self.assertTrue(w.wait(3000))

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        (self.root / "src").mkdir()
        (self.root / "src" / "demo.py").write_text(
            "def existing_fn():\n    return 1\n", encoding="utf-8")

    def tearDown(self):
        self.temp.cleanup()

    def _worker(self, client, messages, planning=True, **kw):
        from forge.worker import AgentWorker
        seen = {"ready": [], "doc": [], "finished": [], "turn": []}
        w = AgentWorker(
            client, "fake-model", messages, {"num_predict": 512},
            str(self.root),
            permissions={"rules": [], "mode": "plan", "classes": {}},
            planning=planning, **kw)
        w.approval_needed.connect(lambda *a: w.resolve_approval(True))
        w.plan_ready.connect(seen["ready"].append)
        w.plan_document.connect(seen["doc"].append)
        w.finished_text.connect(
            lambda text, msgs: seen["finished"].append(text))
        w.plan_turn_done.connect(seen["turn"].append)
        return w, seen

    def test_homework_reads_before_drafting(self):
        from forge.permissions import tool_class
        client = _PlanClient([
            {"tool": "read_file", "args": {"path": "src/demo.py"}},
            {"content": "READY — the project has src/demo.py."},
            {"content": "PROCEED"},
        ] + self.SECTIONS)
        w, seen = self._worker(
            client, [{"role": "user", "content": "make a cat game"}])
        w.start()
        self.assertTrue(self._wait_ready(w, seen))
        # The FIRST generation offered READ tools only — homework —
        # and the drafting generations offer no tools at all.
        first = [s["function"]["name"] for s in client.schemas_seen[0]]
        self.assertIn("read_file", first)
        self.assertTrue(all(tool_class(n) == "read" for n in first))
        self.assertEqual(client.schemas_seen[3], [])
        # ...and the read really ran through the tool pipeline: the
        # file's content is in the conversation as a tool message,
        # and the homework record names what was read and found.
        tool_text = " ".join(m.get("content", "") for m in w.messages
                             if m.get("role") == "tool")
        self.assertIn("existing_fn", tool_text)
        notes = [m["content"] for m in w.messages
                 if m.get("role") == "system"
                 and m["content"].startswith("[Homework")]
        self.assertEqual(len(notes), 1)
        self.assertIn("src/demo.py", notes[0])
        # The document arrived whole, before the gate, and the gate's
        # checklist was extracted from its Steps section.
        self.assertEqual(len(seen["doc"]), 1)
        doc = seen["doc"][0]
        for heading in ("## Goal", "## Context found", "## Contents",
                        "## Steps", "## Risks", "## Assumptions",
                        "## Success criteria", "## Out of scope"):
            self.assertIn(heading, doc)
        self.assertEqual(seen["ready"], [self.STEPS])
        self._kill_at_gate(w, seen)
        # Killed at the gate: nothing further was generated or run.
        # (Item C7: eleven calls — homework tool + READY + PROCEED
        # + the eight drafted sections.)
        self.assertEqual(client.calls, 11)

    def test_empty_project_document_states_emptiness(self):
        bare = Path(self.temp.name) / "empty"
        bare.mkdir()
        client = _PlanClient([
            {"tool": "list_directory", "args": {"path": "."}},
            {"content": "READY"},
            {"content": "PROCEED"},
            {"content": "A game for the cat."},
            {"content": "The project is empty — no files exist yet, "
                        "so this plan starts from nothing."},
            {"content": "game.py — new."},
            {"content": "1. Write game.py — from scratch\n"
                        "   Verify: it opens.\n"
                        "2. Test it on the touchscreen\n"
                        "   Verify: a tap scores."},
            {"content": "Nothing pre-existing to break."},
            {"content": "Nothing assumed."},
        ])
        from forge.worker import AgentWorker
        seen = {"ready": [], "doc": [], "finished": [], "turn": []}
        w = AgentWorker(
            client, "fake-model",
            [{"role": "user", "content": "make a cat game"}],
            {"num_predict": 512}, str(bare),
            permissions={"rules": [], "mode": "plan", "classes": {}},
            planning=True)
        w.approval_needed.connect(lambda *a: w.resolve_approval(True))
        w.plan_ready.connect(seen["ready"].append)
        w.plan_document.connect(seen["doc"].append)
        w.finished_text.connect(
            lambda text, msgs: seen["finished"].append(text))
        w.start()
        self.assertTrue(self._wait_ready(w, seen))
        notes = [m["content"] for m in w.messages
                 if m.get("role") == "system"
                 and m["content"].startswith("[Homework")]
        self.assertTrue(any("EMPTY" in n for n in notes))
        self.assertEqual(len(seen["doc"]), 1)
        self.assertIn("empty", seen["doc"][0])
        self.assertIn("starts from nothing", seen["doc"][0])
        self._kill_at_gate(w, seen)

    def test_questions_end_the_turn_then_skips_become_assumptions(self):
        questions = ("QUESTIONS BEFORE DRAFTING:\n"
                     "1. Who is it for?\n"
                     "2. What device will it run on?\n"
                     "3. What does done look like?")
        client1 = _PlanClient([{"content": "READY"},
                               {"content": questions}])
        w1, seen1 = self._worker(
            client1, [{"role": "user", "content": "make a cat game"}])
        w1.start()
        self.assertTrue(self._pump_until(lambda: bool(seen1["finished"])))
        self.assertTrue(w1.wait(3000))
        # The turn ended on the questions — no draft, no gate. The
        # questions stand as the turn's last assistant message.
        self.assertEqual(seen1["ready"], [])
        self.assertEqual(seen1["doc"], [])
        last = [m for m in w1.messages if m.get("role") == "assistant"][-1]
        self.assertTrue(last["content"].startswith(
            "QUESTIONS BEFORE DRAFTING:"))
        self.assertIn("What does done look like?",
                      seen1["finished"][-1])
        history = [dict(m) for m in w1.messages]
        history.append({"role": "user", "content":
                        "For my cat, on the touchscreen PC. "
                        "The rest — pick something sensible."})
        sections = [dict(s) for s in self.SECTIONS]
        sections[5] = {"content": "(not stated)"}
        client2 = _PlanClient([{"content": "READY"}] + sections)
        w2, seen2 = self._worker(client2, history)
        w2.start()
        self.assertTrue(self._wait_ready(w2, seen2))
        # No second clarify round: homework (1) + eight sections (8).
        self.assertEqual(client2.calls, 9)
        self.assertEqual(seen2["ready"], [self.STEPS])
        doc = seen2["doc"][0]
        # The question the owner skipped is carried into the document
        # as an explicit assumption — not silently invented away.
        self.assertIn("Assumed (open question carried forward): "
                      "What does done look like?", doc)
        self.assertIn("correct it at the gate", doc)
        self._kill_at_gate(w2, seen2)

    def test_approved_document_becomes_the_work_instruction(self):
        client = _PlanClient(
            [{"content": "READY"}, {"content": "PROCEED"}]
            + self.SECTIONS
            + [{"content": "STEP 1 DONE\nSTEP 2 DONE"}])
        w, seen = self._worker(
            client, [{"role": "user", "content": "make a cat game"}])
        w.start()
        self.assertTrue(self._wait_ready(w, seen))
        w.resolve_plan("approve")
        self.assertTrue(self._pump_until(lambda: bool(seen["turn"])))
        self.assertTrue(w.wait(3000))
        work = [m["content"] for m in w.messages
                if m.get("role") == "user"
                and "approved this plan" in m.get("content", "")]
        self.assertEqual(len(work), 1)
        # The working instruction carries the DOCUMENT, not just the
        # one-line checklist — a builder could build from it alone.
        self.assertIn("## Goal", work[0])
        self.assertIn("A tapping game for the owner's cat.", work[0])
        self.assertIn("The checklist", work[0])
        self.assertTrue(work[0].rstrip().endswith(
            "2. " + self.STEPS[1]))
        self.assertEqual(seen["turn"][0]["steps_done"], 2)

    def _wait_ready(self, w, seen, timeout=10.0):
        return self._pump_until(lambda: bool(seen["ready"]), timeout)

    def test_goldfish_revision_rebuilds_the_document_steps(self):
        sections = [
            {"content": "Summarise src/demo.py for the owner."},
            {"content": "src/demo.py exists with existing_fn."},
            {"content": "summary.md — new."},
            {"content": "1. Write the summary in one pass\n"
                        "   Verify: it covers existing_fn.\n"
                        "2. Hand it over\n"
                        "   Verify: the owner can read it."},
            {"content": "A one-pass summary may miss detail."},
            {"content": "Nothing assumed."},
            {"content": "Done means the summary covers existing_fn."},
            {"content": "Not doing: editing src/demo.py itself."},
        ]
        revision = ("Plan:\n"
                    "1. Write the summary carefully in two passes\n"
                    "2. Verify the summary against the source")
        client = _GoldfishClient(
            driver_script=[{"content": "READY"}, {"content": "PROCEED"}]
            + sections + [{"content": revision}],
            reviewer_script=[
                {"content": "BLOCKER: the summary step never says "
                            "how the summary is verified."},
                {"content": "PARAPHRASE: Write a summary, hand it over."},
                {"content": "NO FINDINGS"},
                {"content": "PARAPHRASE: Write a verified summary in "
                            "two passes."},
            ])
        w, seen = self._worker(
            client, [{"role": "user", "content": "summarise the demo"}],
            goldfish=True)
        w.start()
        self.assertTrue(self._wait_ready(w, seen))
        self.assertEqual(seen["ready"], [[
            "Write the summary carefully in two passes",
            "Verify the summary against the source"]])
        doc = seen["doc"][0]
        # The revision replaced the Steps SECTION of the document —
        # the rest of the document is the drafted original.
        self.assertIn("## Goal\nSummarise src/demo.py for the owner.", doc)
        self.assertIn("Write the summary carefully in two passes", doc)
        self.assertNotIn("in one pass", doc)
        self._kill_at_gate(w, seen)


class InLoopHomeworkWorkerTests(unittest.TestCase):
    """Item #58 in the ordinary mode loop: design / architect /
    review / ask turns open with a read-tools homework pass; the
    first drafting generation restores the mode's full tool set."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    def _run_to_finish(self, w, seen):
        import time
        deadline = time.time() + 10.0
        while time.time() < deadline:
            self.app.processEvents()
            if seen["finished"]:
                break
            time.sleep(0.02)
        self.assertTrue(seen["finished"], "turn never finished")
        self.assertTrue(w.wait(3000))

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        (self.root / "src").mkdir()
        (self.root / "src" / "demo.py").write_text(
            "def existing_fn():\n    return 1\n", encoding="utf-8")

    def tearDown(self):
        self.temp.cleanup()

    def _worker(self, client, mode, text):
        from forge.worker import AgentWorker
        seen = {"finished": []}
        w = AgentWorker(
            client, "fake-model",
            [{"role": "user", "content": text}],
            {"num_predict": 512}, str(self.root),
            permissions={"rules": [], "mode": mode, "classes": {}})
        w.approval_needed.connect(lambda *a: w.resolve_approval(True))
        w.finished_text.connect(
            lambda text, msgs: seen["finished"].append(text))
        return w, seen

    def test_design_turn_reads_before_drafting(self):
        from forge.permissions import tool_class
        client = _PlanClient([
            {"tool": "read_file", "args": {"path": "src/demo.py"}},
            {"content": "READY — read the demo."},
            {"content": "## What it is\nA tiny utility."},
        ])
        w, seen = self._worker(client, "design", "design a utility")
        w.start()
        self._run_to_finish(w, seen)
        first = [s["function"]["name"] for s in client.schemas_seen[0]]
        self.assertIn("read_file", first)
        self.assertNotIn("write_file", first)
        self.assertTrue(all(tool_class(n) == "read" for n in first))
        # After homework the drafting generation sees the FULL mode
        # tool set — design mode may write its spec file.
        third = [s["function"]["name"] for s in client.schemas_seen[2]]
        self.assertIn("write_file", third)
        notes = [m["content"] for m in w.messages
                 if m.get("role") == "system"
                 and m["content"].startswith("[Homework")]
        self.assertEqual(len(notes), 1)
        self.assertIn("src/demo.py", notes[0])
        self.assertIn("## What it is", seen["finished"][-1])

    def test_review_turn_homework_then_report_with_coverage(self):
        client = _PlanClient([
            {"tool": "read_file", "args": {"path": "src/demo.py"}},
            {"content": "READY"},
            {"content": "NIT | clarity | the name is terse\n"
                        "COVERAGE — read: src/demo.py; "
                        "NOT read: the tests (none exist)"},
        ])
        w, seen = self._worker(client, "review", "review the demo")
        w.start()
        self._run_to_finish(w, seen)
        first = [s["function"]["name"] for s in client.schemas_seen[0]]
        self.assertTrue(first)
        self.assertNotIn("run_command", first)
        report = seen["finished"][-1]
        self.assertIn("COVERAGE — read: src/demo.py", report)
        self.assertIn("NOT read:", report)


class PlanDocumentWindowTests(unittest.TestCase):
    """Item #58 at the window: the worker's plan document folds into
    the plan state, the plan .md artifact, and the Plan window's
    document view; a pre-#58 sidecar still loads."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.workspace = str(root)
        self.win.worker = None
        self.win.conversation_id = None
        self.win.plan_state = None
        self.win._pending_plan_document = None
        self.win._pending_goldfish = None
        self.win._plan_render()

    def tearDown(self):
        self.win.worker = None
        self.win.plan_state = None
        self.win._pending_plan_document = None
        self.win._pending_goldfish = None
        self.win._plan_render()
        self.temp.cleanup()

    def test_document_folds_into_state_artifact_and_view(self):
        from forge import artifacts, planning
        doc = "# Plan\n\n## Goal\nA game for the cat.\n"
        self.win.on_plan_document(doc)
        self.win.on_plan_ready(["Write it", "Verify it"])
        self.assertEqual(self.win.plan_state["document"], doc)
        self.assertIn("A game for the cat.",
                      self.win.plan_win.document_view.toPlainText())
        arts = artifacts.list_artifacts(self.win.workspace)
        self.assertEqual(len(arts), 1)
        self.assertEqual(arts[0]["kind"], "plan")
        self.assertEqual(artifacts.read_text(self.win.workspace, arts[0]),
                         doc)

    def test_documentless_draft_keeps_the_historical_artifact(self):
        from forge import artifacts, planning
        self.win.on_plan_ready(["Write it", "Verify it"])
        self.assertEqual(self.win.plan_state["document"], "")
        self.assertEqual(self.win.plan_win.document_view.toPlainText(), "")
        arts = artifacts.list_artifacts(self.win.workspace)
        self.assertEqual(len(arts), 1)
        self.assertEqual(artifacts.read_text(self.win.workspace, arts[0]),
                         "1. Write it\n2. Verify it")

    def test_pre58_sidecar_still_loads_through_the_window(self):
        import json
        from forge import main as main_mod
        cid = self.win.store.save(
            None, [{"role": "user", "content": "old ask"}],
            model=None, project=None)
        app_dir = Path(self.temp.name) / "app"
        (app_dir / "plans").mkdir(parents=True)
        old = {"version": 1, "status": "draft", "request": "old ask",
               "steps": [{"text": "Legacy step", "state": "pending",
                          "resource": ""}],
               "skribe": "", "goldfish": None,
               "created": "", "updated": ""}
        (app_dir / "plans" / f"{cid}.json").write_text(
            json.dumps(old), encoding="utf-8")
        saved = main_mod.APP_DIR
        main_mod.APP_DIR = app_dir
        try:
            self.win.load_conversation(cid)
        finally:
            main_mod.APP_DIR = saved
        self.assertIsNotNone(self.win.plan_state)
        self.assertEqual(self.win.plan_state["document"], "")
        self.assertEqual(self.win.plan_state["steps"][0]["text"],
                         "Legacy step")
        # A draft found on load still parks as interrupted, as before.
        self.assertEqual(self.win.plan_state["status"], "interrupted")


class _BusyWorker:
    """A worker stand-in that reads as mid-turn for guard tests."""

    def isRunning(self):
        return True


class SideChatTests(unittest.TestCase):
    """Item #54: side chats — a temporary fork of the current
    conversation WITH its context, for a quick question that must
    not pollute the main thread. The fork is a deep copy held in
    self.messages while the main list is stashed untouched;
    persist_conversation (the store's only writer) stands down
    while one is open, so the fork never reaches the session store
    — not at send, not at finish, not at app close (closeEvent
    writes no messages at all). Closing discards the fork and
    restores the main list verbatim; conversation switches (load /
    new / persistent fork / maintenance entry) discard it first.
    Scoped by code evidence: Plan mode is refused inside a side
    chat (a plan lives in the window's ONE plan slot and its
    sidecar APP_DIR/plans/<main conversation id>.json — a fork has
    neither), opening is refused while a draft plan waits at the
    gate (every turn end settles a draft), and a finished side turn
    is not filed into the mode rooms or the artifact store (both
    are persistent surfaces). Everything else runs the normal turn
    machinery unchanged."""

    MODEL = "maternion/minicpm5-heretic:2b"

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()
        if cls.win.model_combo.findText(cls.MODEL) < 0:
            cls.win.model_combo.addItem(cls.MODEL)
        cls.win.model_combo.setCurrentText(cls.MODEL)

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        self.win._fold_thread = None
        self.win._side_chat = None
        self.win.side_bar.setVisible(False)
        self.win.side_chat_btn.setEnabled(True)
        self.win.plan_state = None
        self.win.mode_combo.setCurrentText("Code")
        self.main_messages = [
            {"role": "system", "content": "sys"},
            {"role": "user", "content": "main question"},
            {"role": "assistant", "content": "main answer"}]
        self.win.messages = self.main_messages
        self.win.conversation_id = self.win.store.save(
            None, self.main_messages, model=None,
            project=self.win.workspace)
        # new_chat / load paths sync plan state to the deck; satisfy
        # the gate like the other window classes while it is off.
        self._real_server = self.win.deck._server
        self.win.deck._server = object()

    def tearDown(self):
        self.win._side_chat = None
        self.win.side_bar.setVisible(False)
        self.win.side_chat_btn.setEnabled(True)
        self.win.plan_state = None
        self.win.mode_combo.setCurrentText("Code")
        self.win.worker = None
        self.win.deck._server = self._real_server
        self.temp.cleanup()

    def _stored(self):
        return self.win.store.load(self.win.conversation_id)

    # -- the fork itself ------------------------------------------------
    def test_open_forks_a_copy_and_shows_the_banner(self):
        self.win.open_side_chat()
        self.assertIsNotNone(self.win._side_chat)
        self.assertIs(self.win._side_chat["messages"], self.main_messages)
        self.assertIsNot(self.win.messages, self.main_messages)
        self.assertEqual(self.win.messages, self.main_messages)
        self.assertFalse(self.win.side_bar.isHidden())
        self.assertFalse(self.win.side_chat_btn.isEnabled())
        # Mutating the fork (even a nested dict) leaves main alone.
        self.win.messages.append({"role": "user", "content": "fork only"})
        self.win.messages[1]["content"] = "edited in the fork"
        self.assertEqual(len(self.main_messages), 3)
        self.assertEqual(self.main_messages[1]["content"], "main question")

    def test_close_restores_the_main_thread_exactly(self):
        self.win.open_side_chat()
        self.win.messages.append({"role": "user", "content": "side ask"})
        self.win.messages.append({"role": "assistant", "content": "side reply"})
        self.win.close_side_chat()
        self.assertIsNone(self.win._side_chat)
        self.assertIs(self.win.messages, self.main_messages)
        self.assertEqual([m["content"] for m in self.win.messages],
                         ["sys", "main question", "main answer"])
        self.assertTrue(self.win.side_bar.isHidden())
        self.assertTrue(self.win.side_chat_btn.isEnabled())

    def test_a_new_fork_starts_from_the_main_thread_again(self):
        self.win.open_side_chat()
