class _RoutedBlockingClient:
    """Item #64 test client: routes each generation by a tag in
    the conversation's newest user message, so ONE client object
    can drive several window conversations at once. A tag's script
    is a list of per-call step lists; a step is ("block",) — park
    the generation until the tag's release event is set (entered
    fires first) — ("tool", name, args), or ("text", s). Calls
    beyond the script answer a plain end."""

    def __init__(self):
        import threading
        self._threading = threading
        self.entered = {}
        self.release = {}
        self.scripts = {}
        self.calls = []

    def arm(self, tag, calls):
        self.entered[tag] = self._threading.Event()
        self.release[tag] = self._threading.Event()
        self.scripts[tag] = [list(call) for call in calls]

    def release_all(self):
        for event in self.release.values():
            event.set()

    def _tag(self, messages):
        for message in reversed(messages):
            if message.get("role") != "user":
                continue
            content = str(message.get("content") or "")
            for tag in self.scripts:
                if tag in content:
                    return tag
        return None

    def chat_stream(self, model, messages, options, schemas,
                    keep_alive=None):
        tag = self._tag(messages)
        self.calls.append(tag)
        calls = self.scripts.get(tag) or []
        steps = calls.pop(0) if calls else [("text", "end")]
        for step in steps:
            if step[0] == "block":
                self.entered[tag].set()
                self.release[tag].wait(15)
            elif step[0] == "tool":
                yield {"message": {"content": "", "tool_calls": [
                    {"function": {"name": step[1],
                                  "arguments": step[2]}}]}}
            elif step[0] == "text":
                yield {"message": {"content": step[1], "tool_calls": []}}


class ParallelTurnsMissionControlTests(unittest.TestCase):
    """Item #64: parallel agents / mission control. The window's
    architecture is one live stage (one messages list, one plan
    slot, one gate screen), so parallelism is built as DETACH /
    REATTACH: a turn's worker already owns its messages copy,
    options, workspace and (new in #64) plugin-context snapshot,
    so switching conversations with the Parallel turns cap above 1
    parks the stage turn in a stream registry instead of refusing;
    its signals are collected into the record until the owner
    switches back. Proven below with real workers on blocking
    clients: two turns mid-flight at once, a background gate
    labelled and resolved to the right worker while the foreground
    turn runs, the cap refusing a third send, Stop killing only
    its target. The scopings are pinned too: cap 1 keeps the
    classic switch refusal, and a Plan turn never detaches (the
    plan slot/gate/sidecar are the window's single set)."""

    MODEL = "maternion/minicpm5-heretic:2b"

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()
        if cls.win.model_combo.findText(cls.MODEL) < 0:
            cls.win.model_combo.addItem(cls.MODEL)
        cls.win.model_combo.setCurrentText(cls.MODEL)

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.ws_a = root / "proj_a"; self.ws_a.mkdir()
        self.ws_b = root / "proj_b"; self.ws_b.mkdir()
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self._old_client = self.win.client
        self.client = _RoutedBlockingClient()
        self.win.client = self.client
        self._old_workspace = self.win.workspace
        self.win.workspace = str(self.ws_a)
        self.win.plugin_ctx.workspace = str(self.ws_a)
        self._old_settings = {
            key: self.win.settings.get(key, None)
            for key in ("max_parallel_turns", "auto_summarize",
                        "skribe_writes")}
        self.win.settings["max_parallel_turns"] = 2
        self.win.settings["auto_summarize"] = False
        self.win.settings["skribe_writes"] = False
        self.win.council_check.setChecked(False)
        self.win.worker = None
        self.win._fold_thread = None
        self.win._side_chat = None
        self.win.plan_state = None
        self.win._streams = {}
        self.win._stage_stream_id = None
        self.win._gate_queue = []
        self.win._gate_presenting = False
        self.win._gate_owner_worker = None
        self.win.mode_combo.setCurrentText("Code")
        self.cid_a = self.win.store.save(
            None, [{"role": "system", "content": "sys"},
                   {"role": "user", "content": "seed A"}],
            model=None, project=str(self.ws_a))
        self.cid_b = self.win.store.save(
            None, [{"role": "system", "content": "sys"},
                   {"role": "user", "content": "seed B"}],
            model=None, project=str(self.ws_b))
        self.cid_c = self.win.store.save(
            None, [{"role": "system", "content": "sys"},
                   {"role": "user", "content": "seed C"}],
            model=None, project=str(self.ws_a))
        self._real_server = self.win.deck._server
        self.win.deck._server = object()

    def tearDown(self):
        self.client.release_all()
        workers = [s["worker"] for s in self.win._streams.values()]
        if self.win.worker is not None:
            workers.append(self.win.worker)
        for worker in workers:
            cancel = getattr(worker, "cancel", None)
            if worker is not None and worker.isRunning() \
                    and callable(cancel):
                cancel()
        self._pump_until(
            lambda: all(not w.isRunning() for w in workers), timeout=5)
        for worker in workers:
            wait = getattr(worker, "wait", None)
            if callable(wait):
                wait(2000)
        self.win.worker = None
        self.win._streams = {}
        self.win._stage_stream_id = None
        self.win._gate_queue = []
        self.win.client = self._old_client
        self.win.workspace = self._old_workspace
        self.win.plugin_ctx.workspace = self._old_workspace
        for key, value in self._old_settings.items():
            if value is None:
                self.win.settings.pop(key, None)
            else:
                self.win.settings[key] = value
        self.win.mode_combo.setCurrentText("Code")
        self.win.deck._server = self._real_server
        self.temp.cleanup()

    def _pump_until(self, pred, timeout=8.0):
        import time
        deadline = time.time() + timeout
        while time.time() < deadline:
            self.app.processEvents()
            if pred():
                return True
            time.sleep(0.02)
        return pred()

    def _send(self, cid, text):
        if self.win.conversation_id != cid:
            self.win.load_conversation(cid)
        self.win.input.setPlainText(text)
        self.win.send_message()

    def _stub_record(self, sid, worker, title, cid, background=False):
        """A stream record with exactly the keys _register_stream
        builds, for dispatcher-level tests that register by hand."""
        return {"id": sid, "worker": worker, "conversation_id": cid,
                "title": title, "workspace": "", "project": "",
                "model": "stub-model", "mode": "Code", "prompt": "",
                "started_at": 0.0, "last_activity": 0.0, "last_push": 0.0,
                "stream_text": "", "status_text": "", "gate": None,
                "background": background, "planning": False,
                "side": False, "maintenance": False, "settled": None,
                "collector": None, "receipts": None}

    def _stream(self, cid):
        return self.win._stream_for_conversation(cid)

    def _stored_text(self, cid):
        return "\n".join(str(m.get("content") or "")
                         for m in self.win.store.load(cid) or [])

    # -- the concurrency proof -------------------------------------
    def test_two_turns_run_concurrently_and_stay_separate(self):
        self.client.arm("ALPHA", [[("block",), ("text", "ALPHA DONE")]])
        self.client.arm("BETA", [[("block",), ("text", "BETA DONE")]])
        self._send(self.cid_a, "ALPHA task")
        worker_a = self.win.worker
        self.assertTrue(self._pump_until(
            lambda: self.client.entered["ALPHA"].is_set()),
            "turn A never entered its generation")
        # Switch away: A detaches instead of being refused.
        self.win.load_conversation(self.cid_b)
        self.assertIsNone(self.win.worker)
        stream_a = self._stream(self.cid_a)
        self.assertIsNotNone(stream_a)
        self.assertTrue(stream_a["background"])
        self._send(self.cid_b, "BETA task")
        worker_b = self.win.worker
        self.assertTrue(self._pump_until(
            lambda: self.client.entered["BETA"].is_set()),
            "turn B never entered its generation")
        # THE proof: both workers are mid-turn at the same moment.
        self.assertTrue(worker_a.isRunning())
        self.assertTrue(worker_b.isRunning())
        # B finishes on the stage while A is still parked.
        self.client.release["BETA"].set()
        self.assertTrue(self._pump_until(lambda: self.win.worker is None),
                        "turn B never settled on the stage")
        self.assertIn("BETA DONE", self._stored_text(self.cid_b))
        self.assertTrue(worker_a.isRunning(),
                        "A ended just because B finished")
        # A finishes in the background; its own record lands.
        self.client.release["ALPHA"].set()
        self.assertTrue(self._pump_until(
            lambda: self._stream(self.cid_a)["settled"] is not None),
            "turn A never settled in the background")
        self.assertEqual(self._stream(self.cid_a)["settled"][0], "done")
        text_a = self._stored_text(self.cid_a)
        self.assertIn("ALPHA task", text_a)
        self.assertIn("ALPHA DONE", text_a)
        self.assertNotIn("BETA", text_a)
        self.assertNotIn("ALPHA", self._stored_text(self.cid_b))
        # The stage still shows B's conversation, untouched by A.
        self.assertEqual(self.win.conversation_id, self.cid_b)
        self.assertIn("BETA DONE",
                      "\n".join(str(m.get("content") or "")
                                for m in self.win.messages))

    def test_background_gate_is_labelled_and_resolves_to_its_worker(self):
        import forge.main as main_mod
        self.client.arm("ALPHA", [
            [("block",), ("tool", "write_file",
              {"path": "note.txt", "content": "from alpha"})],
            [("text", "ALPHA DONE")]])
        self.client.arm("BETA", [[("block",), ("text", "BETA DONE")]])
        self._send(self.cid_a, "ALPHA task")
        worker_a = self.win.worker
        self.assertTrue(self._pump_until(
            lambda: self.client.entered["ALPHA"].is_set()))
        self.win.load_conversation(self.cid_b)
        self._send(self.cid_b, "BETA task")
        worker_b = self.win.worker
        self.assertTrue(self._pump_until(
            lambda: self.client.entered["BETA"].is_set()))
        title_a = self.win._conversation_title(self.cid_a)
        _RecordingApprovalDialog.instances = []
        _RecordingApprovalDialog.answer = True
        real_dialog = main_mod.ApprovalDialog
        main_mod.ApprovalDialog = _RecordingApprovalDialog
        try:
            # A's generation now lands its tool call; the gate must
            # surface (labelled) while B is still mid-flight.
            self.client.release["ALPHA"].set()
            self.assertTrue(self._pump_until(
                lambda: len(_RecordingApprovalDialog.instances) == 1),
                "the background gate never surfaced")
            dialog = _RecordingApprovalDialog.instances[0]
            self.assertTrue(dialog.description.startswith("[Background · "),
                            dialog.description)
            self.assertIn(title_a, dialog.description)
            self.assertEqual(dialog.model, self.MODEL)
            # Approved: A's worker writes in A's workspace and the
            # turn settles in the background…
            self.assertTrue(self._pump_until(
                lambda: self._stream(self.cid_a)["settled"] is not None),
                "turn A never settled after its gate")
            self.assertEqual((self.ws_a / "note.txt").read_text(),
                             "from alpha")
            self.assertFalse((self.ws_b / "note.txt").exists())
            # …while B never moved.
            self.assertTrue(worker_b.isRunning())
            self.assertIs(self.win.worker, worker_b)
            self.assertNotIn("note.txt", self._stored_text(self.cid_b))
        finally:
            main_mod.ApprovalDialog = real_dialog
            self.client.release["BETA"].set()
        self.assertTrue(self._pump_until(lambda: self.win.worker is None))

    # -- the gate queue ---------------------------------------------
    def test_gate_queue_holds_a_second_gate_until_the_first_resolves(self):
        import threading
        import forge.main as main_mod

        class _StubGateWorker:
            def __init__(self):
                self.model = "stub-model"
                self.answers = []
                self._decision_event = threading.Event()
                self._running = True

            def isRunning(self):
                return self._running

            def resolve_approval(self, ok):
                self.answers.append(ok)

        win = self.win
        stub_a, stub_b = _StubGateWorker(), _StubGateWorker()

        stream_a = self._stub_record(901, stub_a, "Conv A", self.cid_a)
        stream_b = self._stub_record(902, stub_b, "Conv B", self.cid_b)
        win._streams = {901: stream_a, 902: stream_b}
        win._stage_stream_id = 901
        win.worker = stub_a

        events = []

        class _QueueProbeDialog:
            instances = []
            answers = [True, False]

            def __init__(self, parent, model, tool_name, target,
                         description, show_remember=True, diff=None, workspace=None):
                self.tool_name = tool_name
                self.description = description
                self.approved = False
                self.remember = False
                type(self).instances.append(self)

            def isVisible(self):
                return True

            def _approve(self):
                self.approved = True

            def reject(self):
                pass

            def exec(self):
                from PySide6.QtWidgets import QDialog
                events.append(("open", self.tool_name))
                if len(type(self).instances) == 1:
                    # B's ask lands while A's gate is on screen.
                    win._ws_gate(stream_b, "run_command",
                                 {"command": "ls"}, "Run ls?")
                    events.append(("queued", len(win._gate_queue),
                                   len(type(self).instances)))
                if type(self).answers.pop(0):
                    self._approve()
                    return QDialog.Accepted
                return QDialog.Rejected

        _QueueProbeDialog.instances = []
        _QueueProbeDialog.answers = [True, False]
        real_dialog = main_mod.ApprovalDialog
        main_mod.ApprovalDialog = _QueueProbeDialog
        try:
            win._ws_gate(stream_a, "write_file", {"path": "x.txt"},
                         "Write x.txt?")
        finally:
            main_mod.ApprovalDialog = real_dialog
        # B queued while A was presented (no second dialog yet),
        # then B was presented only after A resolved.
        self.assertIn(("queued", 1, 1), events)
        self.assertEqual([e[1] for e in events if e[0] == "open"],
                         ["write_file", "run_command"])
        self.assertEqual(stub_a.answers, [True])
        self.assertEqual(stub_b.answers, [False])
        # A (the stage) is unlabelled; B (background) is labelled.
        first, second = _QueueProbeDialog.instances
        self.assertNotIn("[Background", first.description)
        self.assertTrue(second.description.startswith("[Background · Conv B]"))
        self.assertEqual(win._gate_queue, [])
        self.assertFalse(win._gate_presenting)
        win._streams = {}
        win._stage_stream_id = None
        win.worker = None

    def test_queued_gate_for_a_stopped_turn_is_dropped(self):
        import threading
        import forge.main as main_mod
        from PySide6.QtCore import QTimer
        win = self.win

        class _StubWorker:
            def __init__(self):
                self.model = "stub-model"
                self.answers = []
                self._decision_event = threading.Event()
                self._running = True

            def isRunning(self):
                return self._running

            def resolve_approval(self, ok):
                self.answers.append(ok)

        stub = _StubWorker()
        stub_stream = self._stub_record(777, stub, "Stub conv", -777,
                                        background=True)
        win._streams[777] = stub_stream

        class _HoldingDialog:
            """A gate that stays on screen until released — its
            exec pumps events, which is how the queued ask and the
            stop land while it is up."""
            instances = []
            release = False

            def __init__(self, parent, model, tool_name, target,
                         description, show_remember=True, diff=None, workspace=None):
                self.tool_name = tool_name
                self.approved = False
                self.remember = False
                type(self).instances.append(self)

            def isVisible(self):
                return True

            def _approve(self):
                self.approved = True

            def reject(self):
                pass

            def exec(self):
                import time as _time
                from PySide6.QtWidgets import QApplication, QDialog
                while not type(self).release:
                    QApplication.processEvents()
                    _time.sleep(0.01)
                self._approve()
                return QDialog.Accepted

        _HoldingDialog.instances = []
        _HoldingDialog.release = False

        def _act():
            if len(_HoldingDialog.instances) != 1:
                QTimer.singleShot(100, _act)
                return
            # B's ask arrives while A's gate is on screen: queued.
            win._ws_gate(stub_stream, "run_command",
                         {"command": "ls"}, "Run ls?")
            # The owner stops B's turn from Mission Control. The
            # worker's cancel() releases its parked wait as a
            # denial; the worker then clears its decision state and
            # stops — the exact shape the pump must recognize.
            stub._decision_event = None
            stub._running = False
            _HoldingDialog.release = True

        self.client.arm("ALPHA", [
            [("tool", "write_file", {"path": "a.txt", "content": "a"})],
            [("text", "ALPHA DONE")]])
        real_dialog = main_mod.ApprovalDialog
        main_mod.ApprovalDialog = _HoldingDialog
        try:
            QTimer.singleShot(300, _act)
            self._send(self.cid_a, "ALPHA task")
            self.assertTrue(self._pump_until(
                lambda: self.win.worker is None, timeout=10),
                "the stage turn never settled")
        finally:
            main_mod.ApprovalDialog = real_dialog
        # The dropped gate was NEVER presented: one dialog total.
        self.assertEqual(len(_HoldingDialog.instances), 1)
        self.assertEqual(win._gate_queue, [])
        self.assertIsNone(stub_stream["gate"])
        self.assertEqual(stub.answers, [])
        self.assertTrue(any("dropped" in line for line in win._log_lines))
        del win._streams[777]

