    def test_r23_on_failed_clears_worker_before_the_modal(self):
        from unittest import mock
        import forge.main as main_mod
        win = self.win
        old_worker = win.worker
        sentinel = object()
        seen = {}

        def fake_critical(*args, **kwargs):
            seen["worker_at_modal"] = win.worker
            win.worker = sentinel  # a phone prompt starts a new turn

        try:
            win.worker = object()
            with mock.patch.object(main_mod.QMessageBox, "critical",
                                   fake_critical):
                win.on_failed("boom")
            self.assertIsNone(seen["worker_at_modal"])
            self.assertIs(win.worker, sentinel)
        finally:
            win.worker = old_worker

