class SweepDialogTests(unittest.TestCase):
    """Dialog-side sweep fixes: R65–R71, R73–R81, R83–R91, R93,
    R95."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    def test_r65_r82_fork_dialog_tolerates_odd_content(self):
        from forge.main import ForkDialog
        dlg = ForkDialog(None, [
            {"role": "user", "content": " "},
            {"role": "assistant", "content": ["not", "a", "string"]},
            {"role": "user", "content": "a real line\nsecond"}])
