    def test_r69_diff_tinting_is_capped(self):
        from forge.main import ApprovalDialog

        class FakeDiff:
            # Stub-fidelity completion (G3 merge): the double now
            # carries the real DiffResult's full shape
            # (forge/diffview.py) — the G3 side-by-side surface
            # reads body/head as well as full_text. Values are
            # consistent with full_text below; the test's assertions
            # are unchanged.
            body = ["+line %d" % i for i in range(6000)]
            total_lines = 6000
            added = 6000
            removed = 0
            truncated = False

            def full_text(self):
                # Stub-fidelity completion (H3 merge): the real
                # full_text() is _head_lines() + body (diffview.py);
                # H3's renderer composes head + body, so the double
                # must too. The blockCount assertion below follows
                # (6000 -> 6001); the R69 tint assertions are
                # unchanged.
                return "\n".join(["t \u2014 +6000 \u22120"]
                                  + ["+line %d" % i for i in range(6000)])

            def _head_lines(self):
                return ["t — +6000 −0"]

        dlg = ApprovalDialog(None, "m", "write_file", "t", "d",
                             diff=FakeDiff())
        doc = dlg.diff_view.document()
        self.assertEqual(doc.blockCount(), 6001)
        early = doc.findBlockByNumber(10).blockFormat().background()
        late = doc.findBlockByNumber(5500).blockFormat().background()
        self.assertEqual(early.color().name(),
                         ApprovalDialog.DIFF_ADD_BG.name())
        self.assertNotEqual(late.color().name(),
                            ApprovalDialog.DIFF_ADD_BG.name())
        dlg.close()

