import threading


class _BlockingStreamResponse:
    """urlopen stand-in whose iteration yields ONE line, then blocks
    until close() is called — a stalled model stream in miniature
    (sweep R4). Implements the context-manager + iteration shape the
    clients consume; deliberately has NO socket chain (no .fp), so
    the cancel watch must reach it through the plain close()
    fallback, exactly as it would a test double."""

    def __init__(self, first_line: bytes):
        self._first = first_line
        self._released = threading.Event()
        self.closed = False

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def close(self):
        self.closed = True
        self._released.set()

    def __iter__(self):
        yield self._first
        # The stall: no more bytes ever arrive; only close() ends it.
        # The wait is capped so a broken test cannot hang the suite.
        self._released.wait(30)


class CancelAwareStreamTests(unittest.TestCase):
    """Sweep R4 (+ its client half R144): a stalled model stream can
    now be interrupted. chat_stream takes an OPTIONAL cancel_event;
    a watch force-closes the live response when it fires (socket
    shutdown for a real response — a bare close() deadlocks behind
    the blocked read — close() only where no socket is reachable),
    the read ends as a clean EOF, and the consumer's own cancel
    checks settle the turn. No event -> no watch -> the legacy path,
    byte-for-byte, 1800s timeout and all."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    # -- (a) the local client: cancel breaks a stalled stream ------
    def test_ollama_cancel_breaks_a_stalled_stream(self):
        import time as _time
        from unittest import mock
        from forge.ollama_client import OllamaClient
        response = _BlockingStreamResponse(
            b'{"message": {"content": "one"}, "done": false}\n')
        cancel = threading.Event()
        client = OllamaClient("http://127.0.0.1:11434")
        events, errors = [], []

        def consume():
            try:
                for event in client.chat_stream(
                        "m", [{"role": "user", "content": "hi"}], {}, [],
                        cancel_event=cancel):
                    events.append(event)
            except Exception as exc:  # failure path — asserted empty
                errors.append(exc)

        with mock.patch("urllib.request.urlopen",
                        lambda req, timeout=None: response):
            thread = threading.Thread(target=consume, daemon=True)
            started = _time.monotonic()
            thread.start()
            deadline = started + 5
            while not events and _time.monotonic() < deadline:
                _time.sleep(0.02)
            self.assertEqual(len(events), 1)  # live, then stalled
            cancel.set()
            thread.join(timeout=5)
            elapsed = _time.monotonic() - started
        self.assertFalse(thread.is_alive(),
                         "stalled stream ignored the cancel")
        self.assertLess(elapsed, 5)
        self.assertEqual(errors, [])  # clean end-of-stream, no raise
        self.assertTrue(response.closed)  # the watch reached it

    def test_groq_cancel_breaks_a_stalled_stream(self):
        import time as _time
        from forge.providers import GroqClient
        response = _BlockingStreamResponse(
            b'data: {"choices": [{"delta": {"content": "one"}}]}\n')
        cancel = threading.Event()
        client = GroqClient("test-key",
                            urlopen=lambda req, timeout=None: response)
        events, errors = [], []

        def consume():
            try:
                for event in client.chat_stream(
                        "groq:m", [{"role": "user", "content": "hi"}],
                        {}, [], cancel_event=cancel):
                    events.append(event)
            except Exception as exc:
                errors.append(exc)

        thread = threading.Thread(target=consume, daemon=True)
        started = _time.monotonic()
        thread.start()
        deadline = started + 5
        while not events and _time.monotonic() < deadline:
            _time.sleep(0.02)
        self.assertEqual(len(events), 1)
        cancel.set()
        thread.join(timeout=5)
        elapsed = _time.monotonic() - started
        self.assertFalse(thread.is_alive(),
                         "stalled Groq stream ignored the cancel")
        self.assertLess(elapsed, 5)
        self.assertEqual(errors, [])
        self.assertTrue(response.closed)

    def test_gemini_cancel_breaks_a_stalled_stream(self):
        import time as _time
        from forge.providers import GeminiClient
        response = _BlockingStreamResponse(
            b'data: {"candidates": [{"content": {"parts": '
            b'[{"text": "one"}]}}]}\n')
        cancel = threading.Event()
        client = GeminiClient("test-key",
                              urlopen=lambda req, timeout=None: response)
        events, errors = [], []

        def consume():
            try:
                for event in client.chat_stream(
                        "gemini:m", [{"role": "user", "content": "hi"}],
                        {}, [], cancel_event=cancel):
                    events.append(event)
            except Exception as exc:
                errors.append(exc)

        thread = threading.Thread(target=consume, daemon=True)
        started = _time.monotonic()
        thread.start()
        deadline = started + 5
        while not events and _time.monotonic() < deadline:
            _time.sleep(0.02)
        self.assertEqual(len(events), 1)
        cancel.set()
        thread.join(timeout=5)
        elapsed = _time.monotonic() - started
        self.assertFalse(thread.is_alive(),
                         "stalled Gemini stream ignored the cancel")
        self.assertLess(elapsed, 5)
        self.assertEqual(errors, [])
        self.assertTrue(response.closed)

    # -- (b) the facade threads the event to the routed client -----
    def test_facade_threads_the_cancel_event(self):
        from unittest import mock
        from forge.providers import ProviderClient
        seen = {}

        class _Recording:
            def chat_stream(self, model, messages, options, tools,
                            images=None, keep_alive="30m",
                            cancel_event=None):
                seen["cancel_event"] = cancel_event
                yield {"message": {"content": "ok", "tool_calls": []},
                       "done": True}

        cancel = threading.Event()
        messages = [{"role": "user", "content": "hi"}]
        facade = ProviderClient(config={})
        facade.local = _Recording()
        list(facade.chat_stream("some-model", messages, {}, [],
                                cancel_event=cancel))
        self.assertIs(seen["cancel_event"], cancel)
        cloud = ProviderClient(
            config={"groq_api_key": "k", "groq_enabled": True})
        with mock.patch("forge.providers.create_provider_client",
                        return_value=_Recording()):
            # Allowlist adaptation (2026-11-10): the routed model is
            # an approved one — the facade now refuses unapproved
            # provider models before any client is created, which
            # would test the refusal instead of the cancel threading.
            list(cloud.chat_stream("groq:openai/gpt-oss-20b", messages,
                                   {}, [], cancel_event=cancel))
        self.assertIs(seen["cancel_event"], cancel)
        # No event supplied -> None flows: the legacy default.
        seen.clear()
        list(facade.chat_stream("some-model", messages, {}, []))
        self.assertIsNone(seen["cancel_event"])

    # -- (c) end to end: the worker's Stop reaches the stall -------
    def test_worker_cancel_reaches_a_stalled_stream(self):
        import time as _time
        from unittest import mock
        from forge.ollama_client import OllamaClient
        from forge.worker import AgentWorker
        response = _BlockingStreamResponse(
            b'{"message": {"content": "one"}, "done": false}\n')

        def fake_urlopen(req, timeout=None):
            if req.full_url.endswith("/api/tags"):
                return _FakeHTTPResponse(
                    b'{"models": [{"name": "fake"}]}')
            return response

        client = OllamaClient("http://127.0.0.1:11434")
        log = _FakeEventLog()
        worker = AgentWorker(client, "fake",
                             [{"role": "user", "content": "go"}], {},
                             tempfile.mkdtemp(), eventlog=log,
                             skribe_writes=False)
        with mock.patch("urllib.request.urlopen", fake_urlopen):
            thread = threading.Thread(target=worker.run, daemon=True)
            started = _time.monotonic()
            thread.start()
            _time.sleep(0.6)  # the generation is live and stalled
            worker.cancel()
            thread.join(timeout=8)
            elapsed = _time.monotonic() - started
        self.assertFalse(thread.is_alive(),
                         "Stop never reached the stalled stream")
        self.assertLess(elapsed, 8)
        # The turn settled as a cancel does: the partial generation
        # is in the transcript and the settle was logged — not a
        # failure (a failure logs "error" and never logs the settle).
        self.assertIn("turn_complete", log.kinds())
        self.assertNotIn("error", log.kinds())
        assistants = [m.get("content", "") for m in worker.messages
                      if m.get("role") == "assistant"]
        self.assertIn("one", assistants)
        self.assertTrue(response.closed)

    # -- (d) legacy: no event, no watch, no behavior change --------
    def test_stream_without_a_cancel_event_stays_blocked(self):
        import time as _time
        from unittest import mock
        from forge.ollama_client import OllamaClient
        response = _BlockingStreamResponse(
            b'{"message": {"content": "one"}, "done": false}\n')
        client = OllamaClient("http://127.0.0.1:11434")
        events = []

        def consume():
            for event in client.chat_stream(
                    "m", [{"role": "user", "content": "hi"}], {}, []):
                events.append(event)

        with mock.patch("urllib.request.urlopen",
                        lambda req, timeout=None: response):
            thread = threading.Thread(target=consume, daemon=True)
            thread.start()
            _time.sleep(0.6)
            # Nothing was promised a cancel, so nothing interrupts:
            # the consumer is still parked in the stall, exactly as
            # before R4. Release it by hand to let the suite move on.
            self.assertTrue(thread.is_alive())
            self.assertEqual(len(events), 1)
            response.close()
            thread.join(timeout=5)
        self.assertFalse(thread.is_alive())

    def test_cancel_event_defaults_to_none_everywhere(self):
        import inspect as _inspect
        from forge.ollama_client import OllamaClient
        from forge.providers import (GeminiClient, GroqClient,
                                     ProviderClient)
        for cls in (OllamaClient, GroqClient, GeminiClient,
                    ProviderClient):
            param = _inspect.signature(
                cls.chat_stream).parameters["cancel_event"]
            self.assertIsNone(param.default, cls.__name__)

    def test_client_accepts_cancel_classification(self):
        from forge.ollama_client import (OllamaClient,
                                         client_accepts_cancel)
        from forge.providers import ProviderClient

        class _FixedSignature:
            def chat_stream(self, model, messages, options, schemas,
                            keep_alive=None):
                yield {}

        class _KwargsSignature:
            def chat_stream(self, model, messages, options, schemas,
                            **kwargs):
                yield {}

        self.assertTrue(client_accepts_cancel(OllamaClient()))
        self.assertTrue(client_accepts_cancel(ProviderClient(config={})))
        self.assertFalse(client_accepts_cancel(_FixedSignature()))
        self.assertTrue(client_accepts_cancel(_KwargsSignature()))
        self.assertFalse(client_accepts_cancel(object()))

    def test_stream_kwargs_helper_gates_on_capability(self):
        from forge.ollama_client import OllamaClient
        from forge.worker import AgentWorker
        capable = AgentWorker(OllamaClient(), "fake",
                              [{"role": "user", "content": "go"}], {},
                              tempfile.mkdtemp(), eventlog=_FakeEventLog(),
                              skribe_writes=False)
        kwargs = capable._stream_cancel_kwargs("5m")
        self.assertEqual(kwargs["keep_alive"], "5m")
        self.assertIs(kwargs["cancel_event"], capable._cancel_event)
        legacy = AgentWorker(_ScriptedClient([{"content": "done"}]),
                             "fake", [{"role": "user", "content": "go"}],
                             {}, tempfile.mkdtemp(),
                             eventlog=_FakeEventLog(), skribe_writes=False)
        self.assertEqual(legacy._stream_cancel_kwargs("30m"),
                         {"keep_alive": "30m"})

    def test_summarize_thread_threads_its_cancel_event(self):
        from forge.main import SummarizeThread
        seen = {}

        class _Recording:
            def chat_stream(self, model, messages, options, tools,
                            images=None, keep_alive="30m",
                            cancel_event=None):
                seen["cancel_event"] = cancel_event
                yield {"message": {"content": "sum", "tool_calls": []}}

        thread = SummarizeThread(_Recording(), "fake",
                                 [{"role": "user", "content": "hi"}], {})
        done = []
        thread.done.connect(done.append)
        thread.run()
        self.assertIs(seen["cancel_event"], thread._cancel)
        self.assertEqual(done, ["sum"])

    def test_summarize_thread_legacy_client_keeps_the_old_call(self):
        from forge.main import SummarizeThread

        class _FixedSignature:
            def chat_stream(self, model, messages, options, schemas):
                yield {"message": {"content": "sum", "tool_calls": []}}

        thread = SummarizeThread(_FixedSignature(), "fake",
                                 [{"role": "user", "content": "hi"}], {})
        done = []
        thread.done.connect(done.append)
        thread.run()  # must not raise TypeError on the missing kwarg
        self.assertEqual(done, ["sum"])


