class ChunkCApprovalWaitTests(unittest.TestCase):
    """Chunk C / G1: cancel() while the worker is PARKED in the
    approval event.wait() (F8's no-timeout wait). Chunk A's R3 pinned
    cancel during approval PREPARATION; this pins the wait itself:
    Stop must release the parked batch as a denial, promptly, with
    nothing executed."""

    def test_cancel_releases_a_parked_approval_as_a_denial(self):
        import threading as threading_mod
        import time as time_mod
        from forge.worker import AgentWorker
        root = Path(tempfile.mkdtemp())
        log = _FakeEventLog()
        worker = AgentWorker(_ScriptedClient([]), "fake",
                             [{"role": "user", "content": "go"}], {},
                             str(root), eventlog=log, skribe_writes=False)
        asked = []
        # The human never answers: no resolve_approval call, ever.
        # (The recorder also documents the harness truth that a
        # cross-thread emission queues to the main thread's loop —
        # the PARK is what this test pins, proven below by the live
        # thread + the set-but-unanswered decision event.)
        worker.approval_needed.connect(lambda *a: asked.append(a))
        calls = [{"function": {"name": "write_file",
                                "arguments": {"path": "g1.txt",
                                              "content": "hello"}}}]
        errors = []

        def drive():
            try:
                worker._execute_call_batch(calls, {}, {})
            except Exception as exc:  # recorded, asserted empty below
                errors.append(exc)

        thread = threading_mod.Thread(target=drive, daemon=True)
        thread.start()
        deadline = time_mod.time() + 10
        while time_mod.time() < deadline and worker._decision_event is None:
            time_mod.sleep(0.01)
        self.assertIsNotNone(worker._decision_event,
                             "the batch never parked in the approval wait")
        # Parked means: thread alive, decision event armed, and
        # nobody has answered it (it is not set).
        self.assertTrue(thread.is_alive())
        self.assertFalse(worker._decision_event.is_set())
        worker.cancel()
        thread.join(timeout=10)
        self.assertFalse(thread.is_alive(),
                         "the parked approval wait never released")
        self.assertEqual(errors, [])
        self.assertFalse((root / "g1.txt").exists())
        results = [m.get("content", "") for m in worker.messages
                   if m.get("role") == "tool"]
        self.assertEqual(results, ["Tool execution denied by user."])
        approvals = [f for k, f in log.events if k == "approval"]
        self.assertEqual(len(approvals), 1)
        self.assertIs(approvals[0]["approved"], False)


class ChunkCCommandWriteQueueTests(unittest.TestCase):
    """Chunk C / G2: _queue_command_writes pinned DIRECTLY (the
    end-to-end grading path is covered by
    test_run_command_writes_are_graded; the snapshot seam by R8's
    counting test). Created/changed plausible text queues; unchanged,
    deleted, binary, oversized and skip-dir files do not."""

    def test_queue_command_writes_diffs_the_workspace_directly(self):
        from forge.worker import AgentWorker
        root = Path(tempfile.mkdtemp())
        (root / "keep.txt").write_text("v1\n")
        (root / "gone.txt").write_text("bye\n")
        (root / ".git").mkdir()
        (root / ".git" / "ignored.txt").write_text("git internal\n")
        worker = AgentWorker(_ScriptedClient([]), "fake",
                             [{"role": "user", "content": "go"}], {},
                             str(root), eventlog=_FakeEventLog(),
                             skribe_writes=False)
        before = worker._workspace_snapshot()
        self.assertNotIn(".git/ignored.txt", before)
        (root / "keep.txt").write_text("v1 — with more text now\n")
        (root / "new.txt").write_text("fresh\n")
        (root / "gone.txt").unlink()
        (root / "bin.dat").write_bytes(bytes(range(256)) * 4)
        (root / "big.txt").write_text("a" * (1024 * 1024 + 1))
        queued = worker._queue_command_writes(before)
        self.assertEqual(sorted(queued), ["keep.txt", "new.txt"])
        self.assertEqual(sorted(worker._skribe_queue.paths()),
                         ["keep.txt", "new.txt"])


class ChunkCReviewStreamCancelTests(unittest.TestCase):
    """Chunk C / G5 (second half): cancel in the middle of the
    council review stream. Chunk A's R16 pinned a tags() failure;
    this pins a stream that yields once and then stalls — with R4's
    cancel threading the stall ends when the owner presses Stop and
    the partial critique settles the review instead of hanging."""

    def test_cancel_mid_review_stream_returns_promptly(self):
        import threading as threading_mod
        import time as time_mod
        from forge.worker import AgentWorker

        class _StalledReviewClient:
            def tags(self):
                return [{"name": "rev-model"}]

            def chat_stream(self, model, messages, options, tools,
                            keep_alive=None, cancel_event=None):
                yield {"message": {"content": "partial critique"}}
                # Stalled: no further events. The R4 cancel watch
                # closes a real stream here; the fake models that by
                # waiting on the very event the worker threads in.
                # Without the event it sleeps the full safety window,
                # so a missing thread-through fails the join below
                # instead of passing silently.
                if cancel_event is not None:
                    cancel_event.wait(timeout=30)
                else:
                    time_mod.sleep(30)

        log = _FakeEventLog()
        worker = AgentWorker(_StalledReviewClient(), "fake",
                             [{"role": "user", "content": "go"}], {},
                             tempfile.mkdtemp(), eventlog=log,
                             skribe_writes=False)
        worker._turn_request = "build the thing"
        worker._turn_receipts = []
        outcome = {}
        thread = threading_mod.Thread(
            target=lambda: outcome.__setitem__(
                "result", worker._run_review("rev-model", "the answer")),
            daemon=True)
        thread.start()
        time_mod.sleep(0.5)  # parked inside the stalled stream
        worker.cancel()
        thread.join(timeout=10)
        self.assertFalse(thread.is_alive(),
                         "the review stream ignored the cancel")
        self.assertEqual(outcome.get("result"), "partial critique")
        self.assertNotIn("council_failed", log.kinds())


class ChunkCDispatchContractTests(unittest.TestCase):
    """Chunk C / G7: the REAL _dispatch paths for extra (plugin)
    tools. Chunk A's R20 test monkeypatched _dispatch itself; these
    drive the unpatched seam: a handler that raises, and a handler
    that returns a non-string."""

    def _worker(self, extra):
        from forge.worker import AgentWorker
        return AgentWorker(_ScriptedClient([]), "fake",
                           [{"role": "user", "content": "go"}], {},
                           tempfile.mkdtemp(), extra_tools=extra,
                           eventlog=_FakeEventLog(), skribe_writes=False)

    def test_raising_extra_handler_becomes_a_tool_error(self):
        def boom(args):
            raise RuntimeError("handler exploded")

        worker = self._worker(
            {"boom_tool": (_ping_schema(), boom, False, "test")})
        self.assertEqual(worker._execute("boom_tool", {}),
                         "Tool error: handler exploded")
        errors = [f for k, f in worker.eventlog.events
                  if k == "tool_execute_error"]
        self.assertEqual(len(errors), 1)
        self.assertIn("handler exploded", errors[0]["error"])

    def test_nonstring_extra_result_is_coerced_to_text(self):
        worker = self._worker(
            {"num_tool": (_ping_schema(), lambda args: 42, False, "test")})
        result = worker._execute("num_tool", {})
        self.assertIsInstance(result, str)
        self.assertEqual(result, "42")
        # And through the batch: the tool MESSAGE content is text,
        # so the next generation's payload stays well-formed.
        worker._execute_call_batch(
            [{"function": {"name": "num_tool",
                            "arguments": {"word": "a"}}}], {}, {})
        tools = [m for m in worker.messages if m.get("role") == "tool"]
        self.assertEqual(tools[-1]["content"], "42")


class ChunkCWindowGapTests(unittest.TestCase):
    """Chunk C window-side gaps: G8 (stop_generation), G13
    (_apply_models selection), G14 (transcription refusal +
    closeEvent), G15 (non-serialisable settings save), G16
    (history at scale)."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    # -- G8: stop_generation -------------------------------------------
    def test_stop_generation_cancels_a_running_fold_first(self):
        import types
        win = self.win
        old_fold, old_worker = win._fold_thread, win.worker
        calls = []
        fold = types.SimpleNamespace(
            isRunning=lambda: True, cancel=lambda: calls.append("fold"))
        worker = types.SimpleNamespace(
            isRunning=lambda: True, cancel=lambda: calls.append("worker"))
        try:
            win._fold_thread, win.worker = fold, worker
            win.stop_generation()
            self.assertEqual(calls, ["fold"])
            self.assertFalse(win.stop_btn.isEnabled())
        finally:
            win._fold_thread, win.worker = old_fold, old_worker
            win.stop_btn.setEnabled(True)

    def test_stop_generation_cancels_the_worker(self):
        import types
        win = self.win
        old_fold, old_worker = win._fold_thread, win.worker
        calls = []
        worker = types.SimpleNamespace(
            isRunning=lambda: True, cancel=lambda: calls.append("worker"))
        try:
            win._fold_thread, win.worker = None, worker
            before = len(win._log_lines)
            win.stop_generation()
            self.assertEqual(calls, ["worker"])
            self.assertFalse(win.stop_btn.isEnabled())
            self.assertTrue(any("Stop requested." in line
                                for line in win._log_lines[before:]))
        finally:
            win._fold_thread, win.worker = old_fold, old_worker
            win.stop_btn.setEnabled(True)

    # -- G13: _apply_models keeps the owner's selection -----------------
    def test_apply_models_preserves_a_non_driver_selection(self):
        # The R32/#69 rule, pinned at the distinguishing case: the
        # preserved selection is NOT the hard-coded driver, so a
        # refresh that reset to the driver would fail here.
        win = self.win
        models = [{"name": "local-a:2b"}, {"name": "cloud-b"}]
        win._apply_models(models)
        win.model_combo.setCurrentText("cloud-b")
        win._apply_models(models)
        self.assertEqual(win.model_combo.currentText(), "cloud-b")
        # A selection that vanished falls back to a listed model,
        # never to the stale name.
        win._apply_models([{"name": "local-a:2b"}])
        self.assertEqual(win.model_combo.currentText(), "local-a:2b")

    # -- G14: one-at-a-time transcription + closeEvent ------------------
    def test_second_transcription_is_refused_while_one_runs(self):
        import types
        win = self.win
        old = win._transcriber
        busy = types.SimpleNamespace(isRunning=lambda: True)
        try:
            win._transcriber = busy
            before = len(win._log_lines)
            win._start_transcription("clip.wav", "clip.txt",
                                     lambda msg: None)
            self.assertIs(win._transcriber, busy)
            self.assertTrue(any("still running" in line
                                for line in win._log_lines[before:]))
        finally:
            win._transcriber = old

    def test_close_event_stops_timers_deck_and_threads_in_order(self):
        import types
        from PySide6.QtGui import QCloseEvent
        from forge.main import ForgeWindow
        win = ForgeWindow()
        order = []

        class _Busy:
            def __init__(self, name):
                self.name = name

            def isRunning(self):
                return True

            def stop(self):
                order.append((self.name, "stop"))

            def wait(self, ms):
                order.append((self.name, "wait"))
                return True

            def cancel(self):
                order.append((self.name, "cancel"))

        old = (win._maintenance_thread, win._transcriber, win.deck)
        timers = (win._render_timer, win._gauge_timer,
                  win._sched_timer, win._watch_timer)
        try:
            win._maintenance_thread = _Busy("maintenance")
            win._transcriber = _Busy("transcriber")
            win.deck = types.SimpleNamespace(
                stop=lambda: order.append(("deck", "stop")))
            for timer in timers:
                timer.start()
            win.closeEvent(QCloseEvent())
            self.assertTrue(all(not t.isActive() for t in timers))
            self.assertIn(("deck", "stop"), order)
            # R91: the maintenance child is stopped BEFORE the wait.
            self.assertLess(order.index(("maintenance", "stop")),
                            order.index(("maintenance", "wait")))
            self.assertIn(("transcriber", "wait"), order)
        finally:
            (win._maintenance_thread, win._transcriber, win.deck) = old
            win.close()

    # -- G15: a non-serialisable settings value --------------------------
    def test_save_settings_with_a_nonserialisable_value_is_swallowed(self):
        from unittest import mock
        import forge.main as main_mod
        win = self.win
        with tempfile.TemporaryDirectory() as td:
            db = Path(td) / "settings.json"
            with mock.patch.object(main_mod, "DB_FILE", db):
                win.save_settings()
                good = db.read_text(encoding="utf-8")
                self.assertNotIn("chunkc_bad", good)
                win.settings["chunkc_bad"] = object()
                try:
                    before = len(win._log_lines)
                    win.save_settings()  # must not raise
                finally:
                    del win.settings["chunkc_bad"]
                self.assertTrue(any("could not be saved" in line
                                    for line in win._log_lines[before:]))
                # The last good file is untouched, byte for byte.
                self.assertEqual(db.read_text(encoding="utf-8"), good)

    # -- G16: the history list at its full 200-conversation scale -------
    def test_history_list_scales_to_two_hundred_conversations(self):
        from forge.storage import ConversationStore
        win = self.win
        old_store = win.store
        temp = tempfile.TemporaryDirectory()
        try:
            win.store = ConversationStore(Path(temp.name) / "c.db")
            for i in range(200):
                win.store.save(None, [{"role": "user",
                                       "content": f"scale chat {i:03d}"}])
            win._history_signature = None
            win.refresh_history()
            buttons = [win.history_list.itemAt(i).widget()
                       for i in range(win.history_list.count())]
            buttons = [b for b in buttons if b is not None]
            self.assertEqual(len(buttons), 200)
            self.assertIn("scale chat 199", buttons[0].text())
            self.assertIn("scale chat 000", buttons[-1].text())
            # The cap holds past 200: the oldest falls off, the
            # newest leads, nothing is lost in between.
            win.store.save(None, [{"role": "user",
                                   "content": "scale chat 200"}])
            win.refresh_history()
            buttons = [win.history_list.itemAt(i).widget()
                       for i in range(win.history_list.count())]
            buttons = [b for b in buttons if b is not None]
            self.assertEqual(len(buttons), 200)
            self.assertIn("scale chat 200", buttons[0].text())
            self.assertIn("scale chat 001", buttons[-1].text())
            # Search-keystroke rebuilds at the same scale: a query
            # narrows the list to the matches, clearing restores it.
            win.history_search.setText("scale chat 19")
            win.refresh_history()
            buttons = [win.history_list.itemAt(i).widget()
                       for i in range(win.history_list.count())]
            buttons = [b for b in buttons if b is not None]
            self.assertEqual(len(buttons), 10)
            self.assertIn("scale chat 199", buttons[0].text())
            self.assertIn("scale chat 190", buttons[-1].text())
            win.history_search.setText("")
            win.refresh_history()
            buttons = [win.history_list.itemAt(i).widget()
                       for i in range(win.history_list.count())]
            buttons = [b for b in buttons if b is not None]
            self.assertEqual(len(buttons), 200)
        finally:
            win.history_search.setText("")
            win.store = old_store
            win._history_signature = None
            win.refresh_history()
            temp.cleanup()


class ChunkCStreamingAnchorTests(unittest.TestCase):
    """Chunk C / G9: the B14 streaming anchor at the shapes chunk
    A's R27 verdict rested on — multi-paragraph streamed content
    and a stream that follows a REVIEWER tail — plus R54's scroll
    discipline DURING streaming (the parked-gate tests pin the
    idle/render paths). The fixture mirrors StreamingRenderTests."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()
        cls.win.resize(900, 700)
        cls.win.show()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        win = self.win
        self._saved_messages = win.messages
        self._saved_worker = win.worker
        self._saved_stream = win._stream_text
        self._had_own_render = "render" in win.__dict__
        win._render_timer.stop()
        win._stream_text = ""
        win._stream_bubble = None
        win._stream_prefix_len = 0
        win._stream_anchor = None
        self.render_calls = 0
        real_render = win.render

        def spy(messages=None):
            self.render_calls += 1
            return real_render(messages)

        win.render = spy

        class _FakeWorker:
            def isRunning(self):
                return True

        win.worker = _FakeWorker()

    def tearDown(self):
        win = self.win
        win._render_timer.stop()
        if not self._had_own_render:
            win.__dict__.pop("render", None)
        win.worker = self._saved_worker
        win.messages = self._saved_messages
        win._stream_text = self._saved_stream
        win._stream_bubble = None
        win._stream_prefix_len = 0
        win._stream_anchor = None

    def test_multi_paragraph_stream_stays_incremental(self):
        win = self.win
        win.messages = [{"role": "user", "content": "three paragraphs"}]
        for tok in ["First paragraph stands.\n\n",
                    "Second paragraph ", "grows here.\n\n",
                    "Third paragraph lands."]:
            win.on_token(tok)
            win._on_render_tick()
        self.assertLessEqual(self.render_calls, 1)
        self.assertIsNotNone(win._stream_anchor)
        text = win.chat.document().toPlainText()
        self.assertIn("First paragraph stands.", text)
        self.assertIn("Second paragraph grows here.", text)
        self.assertIn("Third paragraph lands.", text)

    def test_stream_anchors_after_a_reviewer_tail(self):
        # The history the fixture models is the real one: a turn
        # that ended on a council critique, then the owner's next
        # message (every send path appends it before tokens can
        # arrive), then the new turn's stream. The anchor must
        # engage with the reviewer bubble sitting mid-history.
        win = self.win
        win.messages = [
            {"role": "user", "content": "do the thing"},
            {"role": "assistant", "reviewer": "rev-model",
             "content": "the critique of the last answer"},
            {"role": "user", "content": "now fix it"}]
        for tok in ["Fresh answer ", "part one.\n\n", "Part two lands."]:
            win.on_token(tok)
            win._on_render_tick()
        self.assertLessEqual(self.render_calls, 1)
        self.assertIsNotNone(win._stream_anchor)
        text = win.chat.document().toPlainText()
        self.assertIn("the critique of the last answer", text)
        self.assertIn("Fresh answer part one.", text)
        self.assertIn("Part two lands.", text)

    def test_streaming_never_yanks_an_unpinned_reader(self):
        win = self.win
        win.messages = [{"role": "system", "content": "sys"}] + [
            {"role": "user" if i % 2 == 0 else "assistant",
             "content": f"message {i}\n" + ("some body text\n" * 12)}
            for i in range(14)]
        win.render()
        self.app.processEvents()
        bar = win.chat.verticalScrollBar()
        self.assertGreater(bar.maximum(), 0)
        bar.setValue(bar.maximum() // 3)
        self.app.processEvents()
        place = bar.value()
        for tok in ["streamed ", "words ", "arrive ", "below."]:
            win.on_token(tok)
            win._on_render_tick()
            self.app.processEvents()
            self.assertEqual(bar.value(), place)


class ChunkCGitPanelGapTests(unittest.TestCase):
    """Chunk C / G20 residuals: R73 (a stage FAILURE's output must
    survive the async rescan that follows the op) and R74 (a stale
    diff answer must never paint) — pinned at the RunWindow seam
    with the unbound-stub pattern test_r120 established."""

    def _stub(self):
        import types
        labels, diffs, clears = [], [], []

        class _Diff:
            def setPlainText(self, text):
                diffs.append(text)

            def clear(self):
                clears.append(True)

        stub = types.SimpleNamespace(
            _git_thread=types.SimpleNamespace(action="stage"),
            _git_label_override=None,
            _git_scan_thread=None,
            _git_state="", _git_changes=[],
            _git_rescan_pending=False,
            _owner=types.SimpleNamespace(workspace="/ws"),
            git_status_label=types.SimpleNamespace(setText=labels.append),
            git_diff_view=_Diff(),
            git_changes_list=types.SimpleNamespace(
                clear=lambda: None, addItem=lambda item: None,
                setCurrentRow=lambda row: None),
            git_init_btn=types.SimpleNamespace(setVisible=lambda v: None),
            git_commit_message=types.SimpleNamespace(clear=lambda: None),
            refresh_git=lambda: None,
            _sync_git_controls=lambda: None,
        )
        return stub, labels, diffs, clears

    def test_stage_failure_output_survives_the_rescan(self):
        from forge.main import RunWindow
        stub, labels, diffs, clears = self._stub()
        RunWindow._on_git_op_done(
            stub, False, "fatal: pathspec 'x' did not match")
        self.assertEqual(stub._git_label_override,
                         "fatal: pathspec 'x' did not match")
        self.assertEqual(diffs, ["fatal: pathspec 'x' did not match"])
        # The rescan the op triggers lands with an empty tree: the
        # label is repainted FROM the override and the failure text
        # in the diff view is not wiped.
        RunWindow._on_git_scanned(stub, "/ws", "ok", [])
        self.assertEqual(labels[-1], "fatal: pathspec 'x' did not match")
        self.assertEqual(clears, [])
        self.assertEqual(diffs, ["fatal: pathspec 'x' did not match"])

    def test_stale_diff_answer_never_paints(self):
        import types
        from forge.main import RunWindow
        diffs = []
        sentinel = object()
        stub = types.SimpleNamespace(
            _git_diff_seq=3, _git_diff_thread=sentinel,
            selected_change=lambda: {"path": "a.py"},
            git_diff_view=types.SimpleNamespace(
                setPlainText=diffs.append))
        RunWindow._on_git_diff(stub, "a.py", "STALE", seq=2)
        self.assertEqual(diffs, [])
        self.assertIs(stub._git_diff_thread, sentinel)
        RunWindow._on_git_diff(stub, "a.py", "FRESH", seq=3)
        self.assertEqual(diffs, ["FRESH"])
        self.assertIsNone(stub._git_diff_thread)


class ChunkCDeckLifecycleTests(unittest.TestCase):
    """Chunk C / G23 residual: stop() releases the listening port
    (the R107 server_close half), pinned explicitly — start, stop,
    and a raw bind must succeed on the same port."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    def test_stop_releases_the_port(self):
        import socket
        from forge.deck import DeckServer
        server = DeckServer()
        server.start()
        try:
            self.assertTrue(server.port)
            self.assertTrue(server.token)
        finally:
            server.stop()
        # The invariant: no LISTENER survives stop(). The probe
        # sets SO_REUSEADDR (the same flag http.server sets on the
        # deck's own server) so it measures exactly that — a plain
        # bind would also fail on the TIME_WAIT corpses of EARLIER
        # deck tests' accepted connections, which say nothing
        # about this stop(). (First full-suite run proved the
        # distinction the hard way: solo pass, suite error 98.)
        sock = socket.socket()
        try:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            sock.bind(("127.0.0.1", server.port))  # raises if still held
        finally:
            sock.close()
        # And the product-level proof: a fresh server starts on
        # the same port straight after the stop.
        second = DeckServer()
        second.start()
        try:
            self.assertEqual(second.port, server.port)
        finally:
            second.stop()


class ChunkCArtifactGapTests(unittest.TestCase):
    """Chunk C / G24 (artifacts half): record()'s kind coercion and
    MAX_TEXT cap, and a corrupt index's read path — the escape,
    atomicity and naming halves are pinned by R115/R116/R118."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.ws = Path(self.temp.name)

    def tearDown(self):
        self.temp.cleanup()

    def test_unknown_kind_lands_as_a_note(self):
        from forge import artifacts
        entry = artifacts.record(self.ws, "brainwave", "Idea", "body text")
        self.assertEqual(entry["kind"], "note")
        listed = artifacts.list_artifacts(self.ws)
        self.assertEqual([e["kind"] for e in listed], ["note"])

    def test_oversized_text_is_capped_with_the_honest_line(self):
        from forge import artifacts
        entry = artifacts.record(self.ws, "note", "Big",
                                 "x" * (artifacts.MAX_TEXT + 5000))
        body = (artifacts._folder(self.ws) / entry["file"]).read_text(
            encoding="utf-8")
        self.assertTrue(body.startswith("x" * 100))
        self.assertLess(len(body), artifacts.MAX_TEXT + 200)
        self.assertIn("[artifact truncated — the full text lives in "
                      "the conversation]", body)

    def test_corrupt_index_reads_as_empty_and_recovers(self):
        from forge import artifacts
        artifacts.record(self.ws, "note", "One", "first")
        artifacts._index_path(self.ws).write_text(
            "{torn json", encoding="utf-8")
        self.assertEqual(artifacts.list_artifacts(self.ws), [])
        artifacts.record(self.ws, "note", "Two", "second")
        listed = artifacts.list_artifacts(self.ws)
        self.assertEqual([e["title"] for e in listed], ["Two"])


class ChunkCQrDecodeTests(unittest.TestCase):
    """Chunk C / G24 (QR half) + the checked-clean encoder claim:
    DeckQrTests pin the matrix's shape; this DEcodes matrices with
    an independent decoder (OpenCV) and demands the payload back
    byte-exact — plain, multibyte UTF-8, and near the size cap."""

    def test_qr_matrix_decodes_back_byte_exact(self):
        try:
            import cv2
            import numpy as np
        except ImportError:
            self.skipTest("opencv not available in this environment")
        from forge import qr as qr_mod
        detector = cv2.QRCodeDetector()

        def decode(text):
            matrix = qr_mod.qr_matrix(text)
            self.assertIsNotNone(matrix)
            img = np.array([[0 if cell else 255 for cell in row]
                            for row in matrix], dtype=np.uint8)
            img = cv2.resize(img, (len(matrix) * 10, len(matrix) * 10),
                             interpolation=cv2.INTER_NEAREST)
            value, _points, _straight = detector.detectAndDecode(img)
            return value

        for payload in ("http://192.168.1.5:8765/?k=abc123XYZ",
                        "héllo wörld — café ✓",
                        "x" * 200):
            self.assertEqual(decode(payload), payload)


