class ChunkCUpdaterGapTests(unittest.TestCase):
    """Chunk C / G25 (updater half): a symlink ENTRY inside an
    update zip, and a manifest whose extra_pip is non-empty — the
    escape/skip halves are pinned by UpdateTests."""

    def _updater(self):
        root = Path(__file__).resolve().parent.parent
        if str(root) not in sys.path:
            sys.path.insert(0, str(root))
        import forge_updater
        return forge_updater

    def test_safe_extract_lands_a_symlink_entry_as_a_plain_file(self):
        import stat as stat_mod
        import zipfile as zf
        forge_updater = self._updater()
        with tempfile.TemporaryDirectory() as td:
            base = Path(td)
            zip_path = base / "update.zip"
            with zf.ZipFile(zip_path, "w") as z:
                info = zf.ZipInfo("Linux Forge Agent/forge/link.py")
                info.external_attr = (stat_mod.S_IFLNK | 0o777) << 16
                z.writestr(info, "/etc/passwd")
                z.writestr("Linux Forge Agent/forge/real.py", "x = 1\n")
            staging = base / "staging"
            staging.mkdir()
            steps = []
            landed = forge_updater.safe_extract(
                zip_path, staging, steps, "Linux Forge Agent")
            self.assertEqual(landed, 2)
            link = staging / "forge" / "link.py"
            self.assertTrue(link.is_file())
            self.assertFalse(link.is_symlink())
            # The link target lands as inert TEXT content — no
            # symlink is ever created for a later entry to write
            # through, and nothing outside staging was touched.
            self.assertEqual(link.read_bytes(), b"/etc/passwd")

    def test_install_deps_runs_a_nonempty_extra_pip(self):
        from unittest import mock
        forge_updater = self._updater()
        with tempfile.TemporaryDirectory() as td:
            app_dir = Path(td) / "app"
            python = app_dir / ".venv" / "bin" / "python"
            python.parent.mkdir(parents=True)
            python.write_text("")
            calls = []

            class _Done:
                returncode = 0
                stdout = "installed"
                stderr = ""

            def fake_run(cmd, **kw):
                calls.append(cmd)
                return _Done()

            steps = []
            with mock.patch.object(forge_updater.subprocess, "run",
                                   fake_run):
                forge_updater.install_deps(
                    app_dir, ["pkg-a==1.0", "pkg-b"], steps)
            self.assertEqual(calls, [[str(python), "-m", "pip", "install",
                                      "pkg-a==1.0", "pkg-b"]])
            self.assertTrue(any(s.startswith("pip (install")
                                for s in steps))

            class _Failed:
                returncode = 1
                stdout = ""
                stderr = "nope"

            with mock.patch.object(forge_updater.subprocess, "run",
                                   lambda cmd, **kw: _Failed()):
                with self.assertRaises(RuntimeError):
                    forge_updater.install_deps(app_dir, ["pkg-a==1.0"], [])


class ChunkCOllamaStreamShapeTests(unittest.TestCase):
    """Chunk C / G25 (client half): chat_stream's failure shapes —
    a malformed NDJSON line mid-stream and a transport error. The
    tags/ps shapes are pinned by R143 and ResidencyPolicyTests."""

    def test_malformed_ndjson_line_fails_the_stream_after_good_events(self):
        from unittest import mock
        from forge.ollama_client import OllamaClient, OllamaError
        body = (b'{"message": {"content": "one"}}\n'
                b'this is not json\n'
                b'{"message": {"content": "two"}}\n')
        client = OllamaClient("http://127.0.0.1:11434")
        with mock.patch("urllib.request.urlopen",
                        lambda req, timeout=None: _FakeHTTPResponse(body)):
            stream = client.chat_stream(
                "m", [{"role": "user", "content": "hi"}], {}, [])
            first = next(stream)
            self.assertEqual(first["message"]["content"], "one")
            with self.assertRaises(OllamaError):
                next(stream)

    def test_transport_error_raises_ollama_error(self):
        import urllib.error
        from unittest import mock
        from forge.ollama_client import OllamaClient, OllamaError

        def refusing(req, timeout=None):
            raise urllib.error.URLError("connection refused")

        client = OllamaClient("http://127.0.0.1:11434")
        with mock.patch("urllib.request.urlopen", refusing):
            with self.assertRaises(OllamaError) as ctx:
                list(client.chat_stream(
                    "m", [{"role": "user", "content": "hi"}], {}, []))
        self.assertIn("Ollama request failed", str(ctx.exception))


class WindowHeaderStandardTests(unittest.TestCase):
    """G4 (GUIFX Research Brief #1, 2026-11-09): the window header
    standard. Every closable QWidget window carries a WindowHeader:
    title (prominent) · status slot · primary controls slot ·
    overflow (⋯) menu for SECONDARY actions · Details toggle only
    where a details region already exists. Primaries never move;
    secondaries moved into overflow stay bound to the same callable
    — the no-action-lost sets below are the audit's reachable-action
    sets per window, encoded."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    # ---------- the helper ----------

    def test_helper_overflow_lists_actions_and_trigger_calls(self):
        import forge.main as main_mod
        from PySide6.QtWidgets import QWidget
        parent = QWidget()
        calls = []
        header = main_mod.build_window_header(
            parent, "Room",
            overflow_actions=[("Alpha", lambda: calls.append("a")),
                              ("Beta", lambda: calls.append("b"), False)])
        try:
            self.assertEqual(header.title_label.text(), "Room")
            self.assertIsNotNone(header.overflow_btn)
            self.assertEqual(header.overflow_btn.text(), "⋯")
            self.assertTrue(header.overflow_btn.toolTip())
            actions = header.overflow_menu.actions()
            self.assertEqual([a.text() for a in actions],
                             ["Alpha", "Beta"])
            self.assertTrue(actions[0].isEnabled())
            self.assertFalse(actions[1].isEnabled())
            actions[0].trigger()
            self.assertEqual(calls, ["a"])
        finally:
            parent.close()

    def test_helper_details_toggle_only_with_callback(self):
        import forge.main as main_mod
        from PySide6.QtWidgets import QWidget
        parent = QWidget()
        states = []

        def record(state):
            states.append(state)

        try:
            plain = main_mod.build_window_header(parent, "Plain")
            self.assertIsNone(plain.details_btn)
            self.assertIsNone(plain.overflow_btn)
            self.assertIsNone(plain.overflow_menu)
            self.assertIsNone(plain.status_label)
            header = main_mod.build_window_header(
                parent, "Detailed", status_text="ready",
                details_callback=record)
            self.assertEqual(header.status_label.text(), "ready")
            self.assertIsNotNone(header.details_btn)
            self.assertTrue(header.details_btn.isChecked())
            header.details_btn.click()
            header.details_btn.click()
            self.assertEqual(states, [False, True])
        finally:
            parent.close()

    # ---------- per-window conformance ----------

    def test_run_window_header(self):
        from PySide6.QtWidgets import QPushButton
        rw = self.win.run_win
        self.assertIs(rw.header.title_label, rw.run_title)
        self.assertIs(rw.header.status_label, rw.run_status)
        self.assertTrue(rw.run_title.text().startswith("RUN"))
        self.assertIsNone(rw.header.overflow_btn)
        texts = {b.text() for b in rw.findChildren(QPushButton)}
        # No action lost: primaries + Rescan + the git panel's verbs.
        self.assertTrue({"▶ Run selected", "■ Stop", "↻ Rescan",
                         "Stage", "Commit staged", "Push"}
                        <= texts)
        self.assertFalse(rw.run_start_btn.isHidden())
        self.assertFalse(rw.run_stop_btn.isHidden())

    def test_mode_window_header(self):
        mw = self.win.mode_windows["design"]
        self.assertIs(mw.header.title_label, mw.mode_title)
        self.assertTrue(mw.mode_title.text().startswith("DESIGN"))
        self.assertIsNone(mw.header.overflow_btn)
        self.assertIsNone(mw.header.details_btn)

    def test_plan_window_gate_stays_visible_in_header(self):
        from PySide6.QtWidgets import QPushButton
        pw = self.win.plan_win
        self.assertEqual(pw.header.title_label.text(), pw.windowTitle())
        in_header = {b.text() for b in
                     pw.header.findChildren(QPushButton)}
        self.assertTrue({"✓ Approve", "✎ Edit", "✕ Kill"} <= in_header)
        self.assertIsNone(pw.header.overflow_btn)
        pw.set_project(self.win.workspace)
        self.assertEqual(pw.header.title_label.text(), pw.windowTitle())

    def test_artifacts_window_refresh_moved_to_overflow(self):
        from PySide6.QtWidgets import QComboBox
        aw = self.win.artifacts_win
        self.assertFalse(hasattr(aw, "artifacts_refresh_btn"))
        actions = aw.header.overflow_menu.actions()
        self.assertEqual([a.text() for a in actions], ["Refresh"])
        self.assertIn(aw.kind_filter,
                      aw.header.findChildren(QComboBox))
        aw.setWindowTitle("stale")
        actions[0].trigger()
        self.assertEqual(aw.windowTitle(),
                         f"Artifacts — {Path(self.win.workspace).name}")
        self.assertEqual(aw.header.title_label.text(), aw.windowTitle())

    def test_maintenance_window_providers_moved_to_overflow(self):
        import forge.main as main_mod
        from PySide6.QtWidgets import QPushButton
        mw = main_mod.MaintenanceWindow(self.win)
        try:
            self.assertFalse(hasattr(mw, "test_providers_btn"))
            actions = mw.header.overflow_menu.actions()
            self.assertEqual([a.text() for a in actions],
                             ["Test providers"])
            self.assertIs(mw.test_providers_action, actions[0])
            self.assertEqual(mw.header.title_label.text(),
                             mw.windowTitle())
            texts = {b.text() for b in mw.findChildren(QPushButton)}
            # Primaries stay in their tabs, untouched.
            self.assertTrue({"Send", "Stop", "Refresh",
                             "Run full verification",
                             "Build candidate update",
                             "Install candidate…"} <= texts)
        finally:
            mw.close()

    def test_skill_editor_header(self):
        import forge.main as main_mod
        with tempfile.TemporaryDirectory() as td:
            skills_dir = Path(td) / "skills"; skills_dir.mkdir()
            win = main_mod.SkillEditorWindow(None, skills_dir)
            try:
                self.assertIs(win.header.title_label, win.win_title)
                self.assertEqual(win.win_title.text(), "NEW SKILL")
                self.assertEqual(win.save_btn.text(), "Save skill")
                self.assertEqual(win.save_btn.objectName(), "primary")
                win.name_edit.setText("demo-skill")
                win.desc_edit.setText("Does demo things.")
                win.body_edit.setPlainText("Step one.")
                ok, msg = win.save()
                self.assertTrue(ok, msg)
                # _retitle updates the header's title label itself.
                self.assertEqual(win.win_title.text(), "EDIT SKILL")
            finally:
                win.close()

    def test_plugin_editor_header(self):
        import forge.main as main_mod
        with tempfile.TemporaryDirectory() as td:
            plugins_dir = Path(td) / "plugins"; plugins_dir.mkdir()
            win = main_mod.PluginEditorWindow(None, plugins_dir)
            try:
                self.assertIs(win.header.title_label, win.win_title)
                self.assertEqual(win.win_title.text(), "NEW PLUGIN")
                self.assertEqual(win.save_btn.text(), "Save plugin")
                self.assertEqual(win.save_btn.objectName(), "primary")
                self.assertIsNone(win.header.overflow_btn)
            finally:
                win.close()


class _SessionsFakeWorker:
    """A live-worker stand-in for G2 state tests: isRunning()
    true, nothing else — _session_rows only ever asks that."""

    def isRunning(self):
        return True


class SessionsWindowTests(unittest.TestCase):
    """G2 (GUIFX Research Brief #1, 2026-11-09): the sessions
    window. One row per OPEN tab, in tab order — title · state ·
    model · project · last activity — read from the data the bench
    already keeps. The state set is the honest one the app's
    signals support: the single worker and the single plan gate
    both belong to the ACTIVE conversation, so only it can be
    Running or Parked at gate; there is no per-session Done flag
    and none is invented."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        self.win.plan_state = None
        self.win._turn_started = 0.0
        self.win.conversation_id = None
        self.win._chat_tab_ids = []
        self.win._sync_chat_tabs()
        self.win.sessions_win.hide()

    def tearDown(self):
        self.win.worker = None
        self.win.plan_state = None
        self.win._turn_started = 0.0
        self.win.sessions_win.hide()
        self.temp.cleanup()

    # ---------- helpers ----------

    def _save(self, text, model="model-a", project=None):
        return self.win.store.save(
            None, [{"role": "user", "content": text},
                   {"role": "assistant", "content": "ok"}],
            model=model, project=project or self.win.workspace)

    def _open_pair(self):
        cid_a = self._save("alpha chat", model="model-a")
        cid_b = self._save("beta chat", model="model-b")
        self.win.load_conversation(cid_a)
        self.win.load_conversation(cid_b)
        self.app.processEvents()
        return cid_a, cid_b

    # ---------- rows ----------

    def test_rows_match_open_tab_order_and_store_data(self):
        cid_a, cid_b = self._open_pair()
        rows = self.win._session_rows()
        self.assertEqual([r["id"] for r in rows], [cid_a, cid_b])
        self.assertEqual([r["id"] for r in rows],
                         list(self.win._chat_tab_ids))
        by_id = {row["id"]: row for row in self.win.store.recent(10)}
        for row in rows:
            saved = by_id[row["id"]]
            self.assertEqual(row["title"],
                             self.win._conversation_title(row["id"]))
            self.assertEqual(row["model"], saved["model"])
            self.assertEqual(row["project"],
                             Path(saved["project"]).name)
            self.assertEqual(row["activity"], saved["updated_at"])
            self.assertEqual(row["state"], "Idle")
        self.assertTrue(rows[-1]["active"])   # beta is the live one
        self.assertFalse(rows[0]["active"])

    def test_unsaved_session_row_shows_what_it_will_save_under(self):
        import time as time_mod
        self.win.new_chat()
        self.app.processEvents()
        rows = self.win._session_rows()
        self.assertEqual([r["id"] for r in rows], [None])
        row = rows[0]
        self.assertTrue(row["active"])
        self.assertEqual(row["title"], "New chat")
        combo_text = self.win.model_combo.currentText().strip()
        self.assertEqual(row["model"], combo_text or "—")
        self.assertEqual(row["project"],
                         Path(self.win.workspace).name)
        # No turn yet -> no activity; a turn start becomes it, in
        # the store's own timestamp shape (SQLite CURRENT_TIMESTAMP).
        self.assertEqual(row["activity"], "—")
        self.win._turn_started = 1762000000.0
        row = self.win._session_rows()[0]
        self.assertEqual(row["activity"],
                         time_mod.strftime("%Y-%m-%d %H:%M:%S",
                                           time_mod.gmtime(1762000000.0)))

    # ---------- state derivation ----------

    def test_state_pure_helper(self):
        import forge.main as main_mod
        state = main_mod._session_state
        self.assertEqual(state(True, True, True), "Parked at gate")
        self.assertEqual(state(True, False, True), "Parked at gate")
        self.assertEqual(state(True, True, False), "Running")
        self.assertEqual(state(True, False, False), "Idle")
        self.assertEqual(state(False, True, True), "Idle")
        self.assertEqual(state(False, False, False), "Idle")

    def test_state_running_for_active_only(self):
        cid_a, cid_b = self._open_pair()
        self.win.worker = _SessionsFakeWorker()
        try:
            rows = {r["id"]: r for r in self.win._session_rows()}
        finally:
            self.win.worker = None
        self.assertEqual(rows[cid_b]["state"], "Running")
        self.assertEqual(rows[cid_a]["state"], "Idle")

    def test_state_parked_at_gate_wins_over_running(self):
        cid_a, cid_b = self._open_pair()
        self.win.worker = _SessionsFakeWorker()
        self.win.plan_state = {"status": "draft", "steps": []}
        try:
            rows = {r["id"]: r for r in self.win._session_rows()}
            self.assertEqual(rows[cid_b]["state"], "Parked at gate")
            self.assertEqual(rows[cid_a]["state"], "Idle")
            # An approved (running) plan is not a parked gate.
            self.win.plan_state = {"status": "running", "steps": []}
            rows = {r["id"]: r for r in self.win._session_rows()}
            self.assertEqual(rows[cid_b]["state"], "Running")
        finally:
            self.win.worker = None
            self.win.plan_state = None

    # ---------- the window ----------

    def test_row_click_switches_through_the_tab_bar(self):
        cid_a, cid_b = self._open_pair()
        win = self.win
        win.open_sessions_window()
        self.app.processEvents()
        sw = win.sessions_win
        self.assertTrue(sw.isVisible())
        self.assertEqual(sw.sessions_list.count(), 2)
        item = sw.sessions_list.item(0)
        sw.sessions_list.itemClicked.emit(item)
        self.app.processEvents()
        self.assertEqual(win.conversation_id, cid_a)
        self.assertEqual(win.chat_tabs.currentIndex(),
                         win._chat_tab_ids.index(cid_a))
        # Clicking the already-active row is a no-op.
        sw.refresh()
        item = sw.sessions_list.item(
            [r["id"] for r in sw._rows].index(cid_a))
        sw.sessions_list.itemClicked.emit(item)
        self.app.processEvents()
        self.assertEqual(win.conversation_id, cid_a)
        sw.hide()

    def test_sync_chat_tabs_refreshes_a_visible_sessions_window(self):
        cid_a, cid_b = self._open_pair()
        win = self.win
        win.open_sessions_window()
        self.app.processEvents()
        sw = win.sessions_win
        self.assertEqual(sw.sessions_list.count(), 2)
        cid_c = self._save("gamma chat")
        win.load_conversation(cid_c)   # syncs tabs -> refreshes rows
        self.app.processEvents()
        self.assertEqual(sw.sessions_list.count(), 3)
        self.assertEqual(sw._rows[-1]["id"], cid_c)
        sw.hide()

    def test_view_menu_entry_and_open(self):
        win = self.win
        self.assertTrue(hasattr(win, "view_act_sessions"))
        self.assertIn("Sessions window", win.view_act_sessions.text())
        win.open_sessions_window()
        self.app.processEvents()
        self.assertTrue(win.sessions_win.isVisible())
        win.sessions_win.hide()

    def test_header_is_g4_standard_with_refresh_in_overflow(self):
        import forge.main as main_mod
        sw = self.win.sessions_win
        self.assertIsInstance(sw.header, main_mod.WindowHeader)
        self.assertEqual(sw.header.title_label.text(),
                         sw.windowTitle())
        actions = sw.header.overflow_menu.actions()
        self.assertEqual([a.text() for a in actions], ["Refresh"])
        # Triggering overflow Refresh re-runs refresh: a session
        # opened while the window was hidden (so the _sync hook
        # skipped it) is stale until the trigger lands.
        sw.refresh()
        self.assertEqual([r["id"] for r in sw._rows], [None])
        cid = self._save("delta chat")
        self.win.load_conversation(cid)
        self.assertEqual([r["id"] for r in sw._rows], [None])
        actions[0].trigger()
        self.assertEqual([r["id"] for r in sw._rows], [cid])
        self.assertEqual(sw.sessions_list.count(), 1)


class AdaptiveDiffTests(unittest.TestCase):
    """G3: adaptive diff in ApprovalDialog — the pure pairing of the
    unified body into old | new rows, the Auto width rule and the
    manual override, and the dialog showing the same DiffResult in
    its two forms. Rendering only: the classic inline form is
    byte-identical to before."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    def _sample_diff(self):
        from forge import diffview
        return diffview.build_diff("a.py", "one\ntwo\nthree\n",
                                   "one\nTWO\nthree\n")

    def _dialog(self, diff):
        from forge.main import ApprovalDialog
        return ApprovalDialog(None, "model-x", "write_file", "a.py",
                              "Write a.py inside /ws?", diff=diff)

    # -- pairing (pure) ---------------------------------------------

    def test_pairing_context_appears_on_both_sides(self):
        from forge.main import paired_diff_rows
        rows = paired_diff_rows([" alpha", " beta"])
        self.assertEqual(rows, [("alpha", "alpha", "context", "context"),
                                ("beta", "beta", "context", "context")])

    def test_pairing_replace_block_pairs_positionally(self):
        from forge.main import paired_diff_rows
        rows = paired_diff_rows(["-one", "-two", "+ONE", "+TWO"])
        self.assertEqual(rows, [("one", "ONE", "pair_del", "pair_add"),
                                ("two", "TWO", "pair_del", "pair_add")])

    def test_pairing_uneven_runs_pad_with_fillers(self):
        from forge.main import paired_diff_rows
        rows = paired_diff_rows(["-a", "-b", "+A"])
        self.assertEqual(rows, [("a", "A", "pair_del", "pair_add"),
                                ("b", None, "del", "filler")])
        rows = paired_diff_rows(["-a", "+A", "+B"])
        self.assertEqual(rows, [("a", "A", "pair_del", "pair_add"),
                                (None, "B", "filler", "add")])

    def test_pairing_pure_add_and_pure_delete_blocks(self):
        from forge.main import paired_diff_rows
        self.assertEqual(paired_diff_rows(["+x", "+y"]),
                         [(None, "x", "filler", "add"),
                          (None, "y", "filler", "add")])
        self.assertEqual(paired_diff_rows(["-x", "-y"]),
                         [("x", None, "del", "filler"),
                          ("y", None, "del", "filler")])

    def test_pairing_hunk_separator_and_block_boundaries(self):
        from forge.main import paired_diff_rows
        rows = paired_diff_rows(
            ["@@ -1,3 +1,3 @@", " keep", "-old", "+new",
             "@@ -9,2 +9,2 @@", "-gone"])
        self.assertEqual(rows[0], ("@@ -1,3 +1,3 @@", "@@ -1,3 +1,3 @@",
                                   "hunk", "hunk"))
        self.assertEqual(rows[1], ("keep", "keep", "context", "context"))
        self.assertEqual(rows[2], ("old", "new", "pair_del", "pair_add"))
        self.assertEqual(rows[3][2:], ("hunk", "hunk"))
        self.assertEqual(rows[4], ("gone", None, "del", "filler"))

    def test_pairing_marker_and_notes_pass_through(self):
        from forge.main import paired_diff_rows
        marker = "… diff truncated — showing 400 of 900 lines (+5 −5 total)"
        rows = paired_diff_rows(["+x", "\\ No newline at end of file", marker])
        self.assertEqual(rows[0], (None, "x", "filler", "add"))
        self.assertEqual(rows[1], ("\\ No newline at end of file",
                                   "\\ No newline at end of file",
                                   "note", "note"))
        self.assertEqual(rows[2], (marker, marker, "note", "note"))

    def test_pairing_strips_prefixes_but_keeps_hunk_text(self):
        from forge.main import paired_diff_rows
        rows = paired_diff_rows([" ctx", "-del", "+add", "@@ -1 +1 @@"])
        self.assertEqual(rows[0][0], "ctx")
        self.assertEqual(rows[1][0], "del")
        self.assertEqual(rows[1][1], "add")
        self.assertEqual(rows[2][0], "@@ -1 +1 @@")

    # -- mode resolution (pure) --------------------------------------

    def test_mode_resolution_auto_follows_width(self):
        from forge.main import DIFF_SIDE_MIN_WIDTH, resolve_diff_mode
        self.assertEqual(DIFF_SIDE_MIN_WIDTH, 880)
        self.assertEqual(resolve_diff_mode("auto", 879), "inline")
        self.assertEqual(resolve_diff_mode("auto", 880), "side")
        self.assertEqual(resolve_diff_mode("auto", 1400), "side")
        self.assertEqual(resolve_diff_mode("auto", 320), "inline")

    def test_mode_resolution_forced_modes_ignore_width(self):
        from forge.main import resolve_diff_mode
        self.assertEqual(resolve_diff_mode("side", 320), "side")
        self.assertEqual(resolve_diff_mode("inline", 2400), "inline")

    # -- dialog integration ------------------------------------------

    def test_wide_dialog_shows_side_panes_with_old_and_new(self):
        dlg = self._dialog(self._sample_diff())
        try:
            dlg.show()
            dlg.resize(1280, 760)
            self.app.processEvents()
            self.assertEqual(dlg._diff_resolved, "side")
            self.assertTrue(dlg.diff_side.isVisible())
            self.assertFalse(dlg.diff_view.isVisible())
            self.assertTrue(dlg.diff_head.isVisible())
            self.assertEqual(dlg.diff_head.text(), "a.py — +1 −1")
            left = dlg.diff_left.toPlainText().splitlines()
            right = dlg.diff_right.toPlainText().splitlines()
            self.assertEqual(left, ["@@ -1,3 +1,3 @@", "one", "two", "three"])
            self.assertEqual(right, ["@@ -1,3 +1,3 @@", "one", "TWO", "three"])
        finally:
            dlg.close()

    def test_side_panes_tint_changed_blocks_only(self):
        from forge.main import ApprovalDialog
        dlg = self._dialog(self._sample_diff())
        try:
            dlg.show()
            dlg.resize(1280, 760)
            self.app.processEvents()

            def bg_of(view, text):
                block = view.document().firstBlock()
                while block.isValid():
                    if block.text() == text:
                        return block.blockFormat().background().color()
                    block = block.next()
                return None

            self.assertEqual(bg_of(dlg.diff_left, "two"),
                             ApprovalDialog.DIFF_DEL_BG)
            self.assertEqual(bg_of(dlg.diff_right, "TWO"),
                             ApprovalDialog.DIFF_ADD_BG)
            self.assertEqual(bg_of(dlg.diff_left, "@@ -1,3 +1,3 @@"),
                             ApprovalDialog.DIFF_HUNK_BG)
            for view, text in ((dlg.diff_left, "one"), (dlg.diff_right, "one"),
                               (dlg.diff_left, "three")):
                self.assertNotIn(bg_of(view, text),
                                 (ApprovalDialog.DIFF_ADD_BG,
                                  ApprovalDialog.DIFF_DEL_BG,
                                  ApprovalDialog.DIFF_HUNK_BG))
        finally:
            dlg.close()

    def test_narrow_dialog_shows_classic_inline_byte_identical(self):
        d = self._sample_diff()
        dlg = self._dialog(d)
        try:
            dlg.show()
            dlg.resize(620, 760)
            self.app.processEvents()
            self.assertEqual(dlg._diff_resolved, "inline")
            self.assertTrue(dlg.diff_view.isVisible())
            self.assertFalse(dlg.diff_side.isVisible())
            self.assertFalse(dlg.diff_head.isVisible())
            self.assertEqual(dlg.diff_view.toPlainText(), d.full_text())
        finally:
            dlg.close()

    def test_mode_buttons_flip_the_rendering_both_ways(self):
        dlg = self._dialog(self._sample_diff())
        try:
            dlg.show()
            dlg.resize(700, 760)   # narrow: Auto resolves inline
            self.app.processEvents()
            self.assertEqual(dlg._diff_resolved, "inline")
            dlg._diff_mode_btns["side"].click()
            self.app.processEvents()
            self.assertEqual(dlg._diff_resolved, "side")
            self.assertTrue(dlg.diff_side.isVisible())
            dlg._diff_mode_btns["inline"].click()
            self.app.processEvents()
            self.assertEqual(dlg._diff_resolved, "inline")
            self.assertTrue(dlg.diff_view.isVisible())
            dlg.resize(1280, 760)  # forced inline still wins when wide
            self.app.processEvents()
            self.assertEqual(dlg._diff_resolved, "inline")
            dlg._diff_mode_btns["auto"].click()
            self.app.processEvents()
            self.assertEqual(dlg._diff_resolved, "side")
        finally:
            dlg.close()

    def test_auto_follows_a_live_resize(self):
        dlg = self._dialog(self._sample_diff())
        try:
            dlg.show()
            dlg.resize(1280, 760)
            self.app.processEvents()
            self.assertEqual(dlg._diff_resolved, "side")
            dlg.resize(600, 760)
            self.app.processEvents()
            self.assertEqual(dlg._diff_resolved, "inline")
            self.assertTrue(dlg.diff_view.isVisible())
        finally:
            dlg.close()

    def test_diff_dialog_opens_at_the_clamped_wide_width(self):
        # Offscreen the screen reports 800 px available, so the
        # clamp(1080, 560, screen) rule lands on 800 — above the 560
        # classic minimum a no-diff dialog keeps.
        dlg = self._dialog(self._sample_diff())
        try:
            screen = dlg.screen()
            avail = screen.availableGeometry().width() if screen else 0
            expected = max(560, min(1080, avail)) if avail else 1080
            self.assertEqual(dlg.width(), expected)
            self.assertGreaterEqual(dlg.width(), 560)
        finally:
            dlg.close()

    def test_no_diff_dialog_has_no_mode_row_and_is_classic(self):
        from PySide6.QtWidgets import QPlainTextEdit, QPushButton
        from forge.main import ApprovalDialog
        desc = "Run this command in /ws:\n\nls -la"
        dlg = ApprovalDialog(None, "model-x", "run_command", "ls -la", desc)
        try:
            self.assertIsNone(dlg.diff_view)
            self.assertIsNone(dlg.diff_area)
            self.assertIsNone(dlg.diff_side)
            self.assertEqual(dlg._diff_mode_btns, {})
            labels = {b.text() for b in dlg.findChildren(QPushButton)}
            self.assertNotIn("Auto", labels)
            self.assertNotIn("Side by side", labels)
            bodies = dlg.findChildren(QPlainTextEdit)
            self.assertEqual(len(bodies), 1)
            self.assertEqual(bodies[0].toPlainText(), desc)
        finally:
            dlg.close()


