# G5 — Density toggle (Comfortable / Compact)
# ------------------------------------------------------------------

class DensityTests(unittest.TestCase):
    """G5 (GUIFX Research Brief #1, 2026-11-09): the Compact density
    is a pure token swap — build_style("compact") substitutes
    TOKENS_COMPACT over TOKENS in the same _STYLE_TEMPLATE, so the
    compact sheet may differ from STYLE only in spacing
    declarations. Comfortable (the default, and the fallback for
    any unknown value) must stay byte-identical to STYLE and to
    the pinned snapshot TokensTests holds. The setting lives in
    settings["density"], is edited in Settings → Behavior, and is
    applied by ForgeWindow.apply_density at startup and on save."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        import forge.main as main_mod
        cls.main = main_mod

    def tearDown(self):
        # Density lives in the single app stylesheet — always hand
        # it back as the comfortable default other tests expect.
        self.app.setStyleSheet(self.main.STYLE)

    def test_comfortable_build_is_style_and_pinned_snapshot(self):
        self.assertEqual(self.main.build_style(), self.main.STYLE)
        self.assertEqual(self.main.build_style("comfortable"),
                         self.main.STYLE)
        self.assertEqual(self.main.build_style(),
                         TokensTests.EXPECTED_STYLE)

    def test_unknown_density_falls_back_to_comfortable(self):
        for junk in ("cozy", "", None, "COMPACT"):
            self.assertEqual(self.main.build_style(junk), self.main.STYLE)

    def test_every_padding_token_has_a_compact_override(self):
        import re
        padding_tokens = {k for k in self.main.TOKENS
                          if k.startswith("padding_")}
        self.assertEqual(set(self.main.TOKENS_COMPACT), padding_tokens)
        referenced = {r for r in re.findall(
            r"\$([a-z_]+)", self.main._STYLE_TEMPLATE.template)
            if r.startswith("padding_")}
        self.assertEqual(referenced, padding_tokens)

    def test_compact_never_exceeds_comfortable_and_keeps_floors(self):
        def parts(value):
            return [int(x[:-2]) for x in value.split()]

        def expand(v):
            if len(v) == 1:
                return v * 4
            if len(v) == 2:
                return [v[0], v[1], v[0], v[1]]
            if len(v) == 3:
                return [v[0], v[1], v[2], v[1]]
            return v

        for name, compact_value in self.main.TOKENS_COMPACT.items():
            comfy = expand(parts(self.main.TOKENS[name]))
            compact = expand(parts(compact_value))
            for comfy_px, compact_px in zip(comfy, compact):
                self.assertLessEqual(compact_px, comfy_px, name)
                self.assertGreaterEqual(compact_px, 1, name)
        # Horizontal floor: buttons / inputs stay tappable (>= 8px).
        for name in ("padding_button", "padding_input"):
            horiz = parts(self.main.TOKENS_COMPACT[name])
            right = horiz[1] if len(horiz) > 1 else horiz[0]
            self.assertGreaterEqual(right, 8, name)

    def test_compact_differs_only_in_spacing_declarations(self):
        import re
        strip = lambda s: re.sub(r"(padding|margin):[^;}]*;?", "", s)
        compact = self.main.build_style("compact")
        self.assertNotEqual(compact, self.main.STYLE)
        self.assertEqual(strip(compact), strip(self.main.STYLE))
        self.assertIn("padding:5px 8px", compact)     # button
        self.assertIn("padding:6px 8px", compact)     # nav / input
        self.assertIn("padding:5px 14px 5px 8px", compact)  # menu item
        self.assertNotIn("padding:8px 12px", compact)
        self.assertNotIn("padding:9px 10px", compact)
        self.assertNotIn("padding:9px;", compact)

    def test_window_starts_compact_from_saved_setting(self):
        import json, tempfile
        from pathlib import Path
        from unittest import mock
        with tempfile.TemporaryDirectory() as td:
            db = Path(td) / "settings.json"
            db.write_text(json.dumps({"density": "compact"}))
            with mock.patch.object(self.main, "DB_FILE", db):
                win = self.main.ForgeWindow()
                try:
                    sheet = self.app.styleSheet()
                    self.assertIn("padding:5px 8px", sheet)
                    self.assertNotIn("padding:8px 12px", sheet)
                finally:
                    win.close()

    def test_window_defaults_to_style_itself(self):
        import tempfile
        from pathlib import Path
        from unittest import mock
        with tempfile.TemporaryDirectory() as td:
            db = Path(td) / "settings.json"  # never written: no settings
            with mock.patch.object(self.main, "DB_FILE", db):
                win = self.main.ForgeWindow()
                try:
                    self.assertEqual(self.app.styleSheet(),
                                     self.main.STYLE)
                finally:
                    win.close()

    def test_settings_dialog_density_control_roundtrip(self):
        dlg = self.main.SettingsDialog(None, {})
        try:
            self.assertEqual(dlg.density.currentData(), "comfortable")
            self.assertEqual(dlg.values()["density"], "comfortable")
            dlg.density.setCurrentIndex(
                dlg.density.findData("compact"))
            self.assertEqual(dlg.values()["density"], "compact")
        finally:
            dlg.close()
        dlg2 = self.main.SettingsDialog(None, {"density": "compact"})
        try:
            self.assertEqual(dlg2.density.currentData(), "compact")
            self.assertEqual(dlg2.values()["density"], "compact")
        finally:
            dlg2.close()

    def test_apply_density_live_and_save_persists(self):
        import json, tempfile
        from pathlib import Path
        from unittest import mock
        with tempfile.TemporaryDirectory() as td:
            db = Path(td) / "settings.json"
            db.write_text(json.dumps({}))
            with mock.patch.object(self.main, "DB_FILE", db):
                win = self.main.ForgeWindow()
                try:
                    self.assertEqual(self.app.styleSheet(),
                                     self.main.STYLE)
                    # The open_settings save path: update + save +
                    # apply_density — exercised at the same seams.
                    win.settings.update({"density": "compact"})
                    win.save_settings()
                    win.apply_density()
                    self.assertIn("padding:5px 8px",
                                  self.app.styleSheet())
                    self.assertNotIn("padding:8px 12px",
                                     self.app.styleSheet())
                    saved = json.loads(db.read_text())
                    self.assertEqual(saved.get("density"), "compact")
                    win.settings.update({"density": "comfortable"})
                    win.apply_density()
                    self.assertEqual(self.app.styleSheet(),
                                     self.main.STYLE)
                finally:
                    win.close()


