class PrivacyWindowTests(unittest.TestCase):
    """H1 (GUIFX Research Brief #2, 2026-11-09): the privacy
    window + the per-conversation LOCAL/CLOUD badge. The window's
    dynamic claims are computed from the live facts — the
    connector config on disk (a provider is "set up" only with a
    key present AND enabled) and the store on the window — and
    the deletes run against a temp APP_DIR only, patched in the
    suite's established way (APP_DIR + DB_FILE + a swapped store).
    A sentinel project file outside APP_DIR proves the wipe is
    enumerative: it removes Forge's data files, nothing else."""

    @classmethod
    def setUpClass(cls):
        import time
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()
        # The window's startup model refresh runs on a thread whose
        # apply rewrites the combo (here it lands in the
        # disconnected fallback). Drain it before any test
        # populates the combo, or its late apply would stomp the
        # badge tests' model picks (the PaletteModelWindowTests
        # pattern).
        deadline = time.time() + 30
        while (cls.win._models_thread is not None
               and cls.win._models_thread.isRunning()
               and time.time() < deadline):
            cls.app.processEvents()
            time.sleep(0.05)
        cls.app.processEvents()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        import forge.main as main_mod
        self.main_mod = main_mod
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.app_dir = root / "app"
        self.app_dir.mkdir()
        self.project_dir = root / "project"
        self.project_dir.mkdir()
        (self.project_dir / "keep.txt").write_text("sentinel")
        self._real_app_dir = main_mod.APP_DIR
        self._real_db_file = main_mod.DB_FILE
        main_mod.APP_DIR = self.app_dir
        main_mod.DB_FILE = self.app_dir / "settings.json"
        # S2 merge adaptation (fixture only, assertions unchanged):
        # provider_api_key() now consults the encrypted vault before
        # the config dict, and the vault's default location is the
        # suite-shared app dir — keys vaulted by other classes'
        # Customize saves would otherwise read as "configured" here.
        # The vault default joins this class's APP_DIR sandbox, the
        # same redirect the S2 classes apply.
        from forge import vault as vault_mod
        self._vault_mod = vault_mod
        self._real_vault_default = vault_mod.default_app_dir
        vault_mod.default_app_dir = lambda: self.app_dir
        self.win.store = ConversationStore(
            self.app_dir / "conversations.sqlite3")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        self.win.plan_state = None
        self.win.conversation_id = None
        self.win._chat_tab_ids = []
        self.win._sync_chat_tabs()
        self.win.privacy_win.hide()

    def tearDown(self):
        self.win.worker = None
        self.win.plan_state = None
        self.win.privacy_win.hide()
        self.main_mod.APP_DIR = self._real_app_dir
        self.main_mod.DB_FILE = self._real_db_file
        self._vault_mod.default_app_dir = self._real_vault_default
        self.temp.cleanup()

    # ---------- helpers ----------

    def _save(self, text, model="model-a"):
        return self.win.store.save(
            None, [{"role": "user", "content": text},
                   {"role": "assistant", "content": "ok"}],
            model=model, project=self.win.workspace)

    def _write_connectors(self, config):
        (self.app_dir / "connectors.json").write_text(
            json.dumps(config), encoding="utf-8")

    def _cloud_texts(self):
        return [label.text()
                for label in self.win.privacy_win._cloud_labels]

    # ---------- the window ----------

    def test_window_builds_on_the_g4_header(self):
        import forge.main as main_mod
        pw = self.win.privacy_win
        self.assertIsInstance(pw.header, main_mod.WindowHeader)
