    # ---------- delete all data ----------

    def _seed_data_files(self):
        cid = self._save("alpha chat")
        (self.app_dir / "settings.json").write_text(
            json.dumps({"palette_recents": ["x"]}))
        self._write_connectors({"groq_api_key": "test-key"})
        (self.app_dir / "seats.json").write_text("{}")
        (self.app_dir / "unlisted-note.txt").write_text("keep me")
        for folder, name in (("plans", f"{cid}.json"),
                             ("recipes", "r.json"),
                             ("checkpoints", "blob"),
                             ("logs", "today.log")):
            folder_path = self.app_dir / folder
            folder_path.mkdir(exist_ok=True)
            (folder_path / name).write_text("data")
        return cid

    def test_delete_all_dialog_requires_the_typed_word(self):
        from PySide6.QtWidgets import QDialog
        self._seed_data_files()
        pw = self.win.privacy_win
        dialog = pw._build_delete_all_dialog()
        self.assertFalse(dialog.confirm_btn.isEnabled())
        dialog.confirm_input.setText("DELET")
        self.assertFalse(dialog.confirm_btn.isEnabled())
        dialog.confirm_input.setText("DELETE")
        self.assertTrue(dialog.confirm_btn.isEnabled())
        # The copy states what is NOT touched, in plain words.
        body_texts = [w.text() for w in dialog.findChildren(
            self.main_mod.QLabel) if w.text()]
        joined = "\n".join(body_texts)
        self.assertIn("Your project files are never touched",
                      joined)
        self.assertIn("Ollama's own storage", joined)
        dialog.confirm_btn.click()
        self.app.processEvents()
        self.assertEqual(dialog.result(), QDialog.Accepted)

    def test_delete_all_removes_data_and_keeps_projects(self):
        self._seed_data_files()
        removed = self.win.delete_all_forge_data()
        self.assertIsNotNone(removed)
        for name in ("settings.json", "connectors.json",
                     "seats.json"):
            self.assertFalse((self.app_dir / name).exists(), name)
            self.assertIn(name, removed)
        for folder in ("plans", "recipes", "checkpoints"):
            self.assertFalse((self.app_dir / folder).exists(),
                             folder)
        # The logs folder itself is recreated empty by the reload
        # path (the fresh EventLog) — what matters is the old log
        # content is gone.
        self.assertFalse(
            (self.app_dir / "logs" / "today.log").exists())
        # The store is rebuilt fresh and empty; Forge keeps
        # running on it.
        self.assertTrue(
            (self.app_dir / "conversations.sqlite3").exists())
        self.assertEqual(self.win.store.recent(10), [])
        self.assertIsNone(self.win.conversation_id)
        # The settings really are fresh defaults now.
        self.assertEqual(
            self.win.settings.get("palette_recents"), None)
        # Nothing outside the enumerated data set was touched:
        # the project sentinel and an unlisted data-dir file both
        # survive.
        self.assertEqual(
            (self.project_dir / "keep.txt").read_text(),
            "sentinel")
        self.assertTrue(
            (self.app_dir / "unlisted-note.txt").exists())
        # And the privacy window now reports an empty house.
        pw = self.win.privacy_win
        pw.refresh()
        self.assertTrue(
            pw.data_counts_label.text().startswith(
                "0 conversations · "),
            pw.data_counts_label.text())
        texts = self._cloud_texts()
        self.assertIn("No cloud providers are set up", texts[0])

    # ---------- the badge ----------

