class S6CandidateHashTests(unittest.TestCase):
    """S6 (audit S1-22): the candidate sidecar's sha256 is VERIFIED
    at install — a matching hash verifies, a tampered zip and a
    hash-less candidate are refused, all before anything is
    extracted or spawned."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        base = Path(self.temp.name)
        self.root = base / "Linux Forge Agent"
        self.app_dir = base / "appdata"
        (self.root / "forge").mkdir(parents=True)
        (self.root / "forge" / "main.py").write_text("print('live')\n")

    def tearDown(self):
        self.temp.cleanup()

    def _build(self):
        from forge import self_maintenance as sm
        work = sm.prepare_work_copy(self.root, self.app_dir)
        (work / "forge" / "main.py").write_text("print('candidate')\n")
        return sm.build_candidate_package(
            self.root, work, self.app_dir, {"tests_passed": True})

    def test_matching_hash_verifies(self):
        from forge import self_maintenance as sm
        zip_path, manifest = self._build()
        verified = sm.verify_candidate_package(zip_path)
        self.assertEqual(verified["sha256"], manifest["sha256"])
        self.assertEqual(len(verified["sha256"]), 64)

    def test_tampered_zip_refused(self):
        from forge import self_maintenance as sm
        zip_path, _manifest = self._build()
        with open(zip_path, "ab") as fh:
            fh.write(b"tampered")
        with self.assertRaises(sm.MaintenanceError) as ctx:
            sm.verify_candidate_package(zip_path)
        self.assertIn("does not match its recorded checksum",
                      str(ctx.exception))
        self.assertIn("refusing to install", str(ctx.exception))

    def test_missing_hash_refused(self):
        from forge import self_maintenance as sm
        zip_path, manifest = self._build()
        sidecar = zip_path.with_suffix(".json")
        data = json.loads(sidecar.read_text(encoding="utf-8"))
        del data["sha256"]
        sidecar.write_text(json.dumps(data), encoding="utf-8")
        with self.assertRaises(sm.MaintenanceError) as ctx:
            sm.verify_candidate_package(zip_path)
        self.assertIn("no recorded checksum", str(ctx.exception))

    def test_missing_sidecar_refused(self):
        from forge import self_maintenance as sm
        zip_path, _manifest = self._build()
        zip_path.with_suffix(".json").unlink()
        with self.assertRaises(sm.MaintenanceError):
            sm.verify_candidate_package(zip_path)


class _StubTimer:
    """QTimer stand-in for the apply_update tests: the 400 ms quit
    shot is recorded, never fired."""

    shots = []

    @staticmethod
    def singleShot(*args, **kwargs):
        _StubTimer.shots.append(args)


class S6CandidateInstallWindowTests(unittest.TestCase):
    """S6 (audit S1-22), window half: apply_update verifies a
    candidate BEFORE the updater spawns — the spawn recorder is the
    pre-spawn point. Matching hash → spawn + the short hash logged;
    tampered / hash-less → warning, no spawn."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    def _fresh_window(self):
        import time
        from unittest import mock
        import forge.main as main_mod
        temp = tempfile.TemporaryDirectory()
        root = Path(temp.name)
        (root / "settings.json").write_text("{}", encoding="utf-8")
        patchers = [mock.patch.object(main_mod, "APP_DIR", root),
                    mock.patch.object(main_mod, "DB_FILE",
                                      root / "settings.json")]
        for patcher in patchers:
            patcher.start()
        try:
            win = main_mod.ForgeWindow()
        except Exception:
            for patcher in patchers:
                patcher.stop()
            raise
        win.store = ConversationStore(root / "c.db")
        win.eventlog = EventLog(root / "log")
        deadline = time.time() + 30
        while (win._models_thread is not None
               and win._models_thread.isRunning()
               and time.time() < deadline):
            self.app.processEvents()
            time.sleep(0.05)
        self.app.processEvents()
        win.worker = None
        return win, temp, patchers

    @staticmethod
    def _stop_patchers(patchers):
        for patcher in patchers:
            patcher.stop()

    def _candidate(self, base):
        from forge import self_maintenance as sm
        root = base / "Linux Forge Agent"
        app_dir = base / "appdata"
        (root / "forge").mkdir(parents=True)
        (root / "forge" / "main.py").write_text("print('live')\n")
        work = sm.prepare_work_copy(root, app_dir)
        (work / "forge" / "main.py").write_text("print('candidate')\n")
        return sm.build_candidate_package(
            root, work, app_dir, {"tests_passed": True})

    def _apply(self, win, zip_path):
        from unittest import mock
        import forge.main as main_mod
        import forge.update as upd_mod
        spawns = []
        _StubMessageBox.warnings = []
        _StubTimer.shots = []
        with mock.patch.object(upd_mod, "spawn_updater",
                               lambda *a, **k: spawns.append(a)), \
                mock.patch.object(main_mod, "QMessageBox",
                                  _StubMessageBox), \
                mock.patch.object(main_mod, "QTimer", _StubTimer):
            win.apply_update(str(zip_path))
        return spawns

    def test_matching_candidate_reaches_spawn_with_short_hash_logged(self):
        win, temp, patchers = self._fresh_window()
        try:
            zip_path, manifest = self._candidate(Path(temp.name))
            spawns = self._apply(win, zip_path)
            self.assertEqual(len(spawns), 1)
            self.assertTrue(any(
                "Candidate checksum verified" in line
                and manifest["sha256"][:12] in line
                for line in win._log_lines), win._log_lines[-3:])
            self.assertEqual(_StubMessageBox.warnings, [])
        finally:
            win.close()
            self._stop_patchers(patchers)
            temp.cleanup()

    def test_tampered_candidate_refused_before_spawn(self):
        win, temp, patchers = self._fresh_window()
        try:
            zip_path, _manifest = self._candidate(Path(temp.name))
            with open(zip_path, "ab") as fh:
                fh.write(b"tampered")
            spawns = self._apply(win, zip_path)
            self.assertEqual(spawns, [])
            self.assertTrue(any(
                "does not match its recorded checksum" in text
                for _title, text in _StubMessageBox.warnings),
                _StubMessageBox.warnings)
        finally:
            win.close()
            self._stop_patchers(patchers)
            temp.cleanup()

    def test_hashless_candidate_refused_before_spawn(self):
        win, temp, patchers = self._fresh_window()
        try:
            zip_path, _manifest = self._candidate(Path(temp.name))
            sidecar = zip_path.with_suffix(".json")
            data = json.loads(sidecar.read_text(encoding="utf-8"))
            del data["sha256"]
            sidecar.write_text(json.dumps(data), encoding="utf-8")
            spawns = self._apply(win, zip_path)
            self.assertEqual(spawns, [])
            self.assertTrue(any(
                "no recorded checksum" in text
                for _title, text in _StubMessageBox.warnings),
                _StubMessageBox.warnings)
        finally:
            win.close()
            self._stop_patchers(patchers)
            temp.cleanup()


class S6ExtensionTrustTests(unittest.TestCase):
    """S6 (audit S1-25): extension trust symmetry — the bundled
    seed on first run, update-of-enabled → disabled, and skills
    starting disabled exactly like plugins."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    def _fresh_window(self):
        import time
        from unittest import mock
        import forge.main as main_mod
        temp = tempfile.TemporaryDirectory()
        root = Path(temp.name)
        (root / "settings.json").write_text("{}", encoding="utf-8")
        patchers = [mock.patch.object(main_mod, "APP_DIR", root),
                    mock.patch.object(main_mod, "DB_FILE",
                                      root / "settings.json")]
        for patcher in patchers:
            patcher.start()
        try:
            win = main_mod.ForgeWindow()
        except Exception:
            for patcher in patchers:
                patcher.stop()
            raise
        win.store = ConversationStore(root / "c.db")
        win.eventlog = EventLog(root / "log")
        deadline = time.time() + 30
        while (win._models_thread is not None
               and win._models_thread.isRunning()
               and time.time() < deadline):
            self.app.processEvents()
            time.sleep(0.05)
        self.app.processEvents()
        win.worker = None
        return win, temp, patchers

    @staticmethod
    def _stop_patchers(patchers):
        for patcher in patchers:
            patcher.stop()

    @staticmethod
    def _plant_plugin(plugins_dir, folder_name, pid, name, tool, code):
        folder = Path(plugins_dir) / folder_name
        folder.mkdir(parents=True)
        (folder / "plugin.json").write_text(json.dumps({
            "id": pid, "name": name, "kind": "plugin",
            "description": "planted",
            "tools": [{"name": tool, "description": "planted",
                       "parameters": {"type": "object", "properties": {}},
                       "requires_approval": True}]}))
        (folder / "plugin.py").write_text(code)
        return folder

    # -- (a) the seed ---------------------------------------------
    def test_seed_matches_the_shipped_plugin_folders(self):
        from forge.plugins import BUNDLED_PLUGIN_IDS
        root = Path(__file__).resolve().parent.parent
        shipped = set()
        for folder in sorted((root / "plugins").iterdir()):
            meta = folder / "plugin.json"
            if folder.is_dir() and meta.is_file():
                shipped.add(json.loads(
                    meta.read_text(encoding="utf-8"))["id"])
        self.assertEqual(set(BUNDLED_PLUGIN_IDS), shipped)

    def test_unseeded_plugin_never_executes_on_first_run(self):
        with tempfile.TemporaryDirectory() as tmp:
            pdir = Path(tmp) / "plugins"
            sentinel = Path(tmp) / "ran.txt"
            code = ("from pathlib import Path\n"
                    f"Path({str(sentinel)!r}).write_text('ran')\n"
                    "def _go(args, ctx):\n    return 'went'\n"
                    "HANDLERS = {'rogue_probe': _go}\n")
            self._plant_plugin(pdir, "rogue-one", "rogue-one",
                               "Rogue One", "rogue_probe", code)
            self._plant_plugin(
                pdir, "tester-clone", "tester", "Tester Clone",
                "seeded_probe",
                "def _go(args, ctx):\n    return 'went'\n"
                "HANDLERS = {'seeded_probe': _go}\n")
            from forge.plugins import BUNDLED_PLUGIN_IDS
            ctx = PluginContext(workspace=tmp, log=lambda m: None)
            _plugins, registry = load_plugins(
                pdir, ctx, known=sorted(BUNDLED_PLUGIN_IDS))
            self.assertFalse(sentinel.exists())
            self.assertNotIn("rogue_probe", registry)
            self.assertIn("seeded_probe", registry)

    def test_first_run_window_disables_unseeded_keeps_seeded(self):
        win, temp, patchers = self._fresh_window()
        base = Path(temp.name)
        pdir = base / "plugins"
        sentinel = base / "ran.txt"
        old_dir = win.app_plugins_dir
        saved = {k: win.settings.get(k) for k in
                 ("known_plugins", "disabled_plugins")}
        try:
            self._plant_plugin(
                pdir, "rogue-one", "rogue-one", "Rogue One", "rogue_probe",
                "from pathlib import Path\n"
                f"Path({str(sentinel)!r}).write_text('ran')\n"
                "def _go(args, ctx):\n    return 'went'\n"
                "HANDLERS = {'rogue_probe': _go}\n")
            self._plant_plugin(
                pdir, "tester-clone", "tester", "Tester Clone",
                "seeded_probe",
                "def _go(args, ctx):\n    return 'went'\n"
                "HANDLERS = {'seeded_probe': _go}\n")
            win.app_plugins_dir = pdir
            win.settings.pop("known_plugins", None)
            win.settings["disabled_plugins"] = []
            win.rescan_extensions()
            # unseeded: code never ran, tools absent, starts disabled
            self.assertFalse(sentinel.exists())
            self.assertNotIn("rogue_probe", win.plugin_registry)
            self.assertIn("rogue-one",
                          win.settings.get("disabled_plugins", []))
            self.assertIn("rogue-one",
                          win.settings.get("known_plugins", []))
            # seeded: today's first-run behaviour — loaded and live
            self.assertIn("seeded_probe", win.plugin_registry)
            self.assertNotIn("tester",
                             win.settings.get("disabled_plugins", []))
        finally:
            win.app_plugins_dir = old_dir
            for key, value in saved.items():
                if value is None:
                    win.settings.pop(key, None)
                else:
                    win.settings[key] = value
            win.rescan_extensions()
            win.close()
            self._stop_patchers(patchers)
            temp.cleanup()

    # -- (b) update of an enabled plugin ---------------------------
    def test_update_of_enabled_plugin_switches_it_off(self):
        win, temp, patchers = self._fresh_window()
        base = Path(temp.name)
        old_skills, old_plugins = win.app_skills_dir, win.app_plugins_dir
        try:
            win.app_skills_dir = base / "skills"
            win.app_plugins_dir = base / "plugins"
            win.app_skills_dir.mkdir()
            win.app_plugins_dir.mkdir()
            msg = win._create_plugin_tool(
                {"name": "flip-plug", "description": "v1",
                 "code": UpdateExtTests.GOOD_CODE})
            self.assertIn("Created", msg)
            self.assertIn("flip-plug",
                          win.settings.get("disabled_plugins", []))
            # the owner enables it in Customize (the settings act)
            win.settings["disabled_plugins"] = [
                p for p in win.settings.get("disabled_plugins", [])
                if p != "flip-plug"]
            win.save_settings()
            win.rescan_extensions()
            self.assertIn("go_now", win.plugin_registry)
            # an agent update now lands it back in DISABLED
            msg = win._update_plugin_tool(
                {"name": "flip-plug", "description": "v2",
                 "code": UpdateExtTests.GOOD_CODE_V2})
            self.assertIn("Updated", msg)
            self.assertIn("switched it OFF", msg)
            self.assertIn("flip-plug",
                          win.settings.get("disabled_plugins", []))
            self.assertNotIn("go_now", win.plugin_registry)
            # and the owner can re-enable it — the new code serves
            win.settings["disabled_plugins"] = [
                p for p in win.settings.get("disabled_plugins", [])
                if p != "flip-plug"]
            win.save_settings()
            win.rescan_extensions()
            self.assertIn("go_now", win.plugin_registry)
        finally:
            win.app_skills_dir, win.app_plugins_dir = old_skills, old_plugins
            win.rescan_extensions()
            win.close()
            self._stop_patchers(patchers)
            temp.cleanup()

    def test_update_of_disabled_plugin_stays_disabled(self):
        win, temp, patchers = self._fresh_window()
        base = Path(temp.name)
        old_skills, old_plugins = win.app_skills_dir, win.app_plugins_dir
        try:
            win.app_skills_dir = base / "skills"
            win.app_plugins_dir = base / "plugins"
            win.app_skills_dir.mkdir()
            win.app_plugins_dir.mkdir()
            msg = win._create_plugin_tool(
                {"name": "still-off", "description": "v1",
                 "code": UpdateExtTests.GOOD_CODE})
            self.assertIn("Created", msg)
            msg = win._update_plugin_tool(
                {"name": "still-off", "description": "v2",
                 "code": UpdateExtTests.GOOD_CODE_V2})
            self.assertIn("Updated", msg)
            self.assertNotIn("switched it OFF", msg)
            self.assertIn("still-off",
                          win.settings.get("disabled_plugins", []))
        finally:
            win.app_skills_dir, win.app_plugins_dir = old_skills, old_plugins
            win.rescan_extensions()
            win.close()
            self._stop_patchers(patchers)
            temp.cleanup()

    # -- (c) skills start disabled ---------------------------------
    def test_created_skill_starts_disabled_and_load_refuses(self):
        win, temp, patchers = self._fresh_window()
        base = Path(temp.name)
        old_skills, old_plugins = win.app_skills_dir, win.app_plugins_dir
        try:
            win.app_skills_dir = base / "skills"
            win.app_plugins_dir = base / "plugins"
            win.app_skills_dir.mkdir()
            win.app_plugins_dir.mkdir()
            msg = win._create_skill_tool(
                {"name": "fresh-skill", "description": "does fresh things",
                 "body": "Fresh body."})
            self.assertIn("Created", msg)
            self.assertIn("DISABLED", msg)
            # on disk and listed, but NOT active
            self.assertIn("fresh-skill",
                          [s.name for s in win.all_skills])
            self.assertNotIn("fresh-skill",
                             [s.name for s in win.skills])
            self.assertIn("fresh-skill",
                          win.settings.get("disabled_skills", []))
            handler = win._extra_tools()["load_skill"][1]
            refusal = handler({"name": "fresh-skill"})
            self.assertIn("disabled", refusal)
            self.assertIn("Customize", refusal)
            # the owner enables it — now it loads
            win.settings["disabled_skills"] = [
                n for n in win.settings.get("disabled_skills", [])
                if n != "fresh-skill"]
            win.save_settings()
            win.reload_extensions()
            self.assertIn("fresh-skill", [s.name for s in win.skills])
            handler = win._extra_tools()["load_skill"][1]
            self.assertIn("Fresh body.", handler({"name": "fresh-skill"}))
        finally:
            win.app_skills_dir, win.app_plugins_dir = old_skills, old_plugins
            win.rescan_extensions()
            win.close()
            self._stop_patchers(patchers)
            temp.cleanup()

    def test_preexisting_skill_keeps_its_state(self):
        # A skill that exists BEFORE any known_skills history is an
        # existing install's skill: grandfathered active, never
        # retroactively disabled.
        win, temp, patchers = self._fresh_window()
        base = Path(temp.name)
        old_skills, old_plugins = win.app_skills_dir, win.app_plugins_dir
        saved = {k: win.settings.get(k) for k in
                 ("known_skills", "disabled_skills")}
        try:
            win.app_skills_dir = base / "skills"
            win.app_plugins_dir = base / "plugins"
            win.app_plugins_dir.mkdir()
            folder = win.app_skills_dir / "old-skill"
            folder.mkdir(parents=True)
            (folder / "SKILL.md").write_text(
                "name: old-skill\ndescription: been here\n\nOld body.\n",
                encoding="utf-8")
            win.settings.pop("known_skills", None)
            win.settings["disabled_skills"] = []
            win.rescan_extensions()
            self.assertIn("old-skill", [s.name for s in win.skills])
            self.assertNotIn("old-skill",
                             win.settings.get("disabled_skills", []))
            self.assertIn("old-skill",
                          win.settings.get("known_skills", []))
        finally:
            win.app_skills_dir, win.app_plugins_dir = old_skills, old_plugins
            for key, value in saved.items():
                if value is None:
                    win.settings.pop(key, None)
                else:
                    win.settings[key] = value
            win.rescan_extensions()
            win.close()
            self._stop_patchers(patchers)
            temp.cleanup()

    def test_load_skill_handler_disabled_refusal_unit(self):
        with tempfile.TemporaryDirectory() as tmp:
            folder = Path(tmp) / "off-skill"
            folder.mkdir()
            (folder / "SKILL.md").write_text(
                "name: off-skill\ndescription: off\n\nBody.\n",
                encoding="utf-8")
            skills = scan_skills(Path(tmp))
            handler = make_load_skill_handler([], disabled={"off-skill"})
            out = handler({"name": "off-skill"})
            self.assertIn("disabled", out)
            self.assertIn("Customize", out)
            # a merely absent name keeps the classic answer
            self.assertIn("Unknown skill",
                          handler({"name": "never-existed"}))
            # no disabled set at all: unchanged behaviour
            plain = make_load_skill_handler(skills)
            self.assertIn("Body.", plain({"name": "off-skill"}))


class _CappedFakeResponse:
    """urlopen stand-in whose read(size) honours the size argument
    and records every requested size — the S1-29 cap tests prove the
    reader never asks for (or buffers) more than cap + 1."""

    def __init__(self, body: bytes):
        self._body = body
        self.requested = []

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return False

    def read(self, size=-1):
        self.requested.append(size)
        if size is None or size < 0:
            return self._body
        return self._body[:size]


class S6CappedReadsTests(unittest.TestCase):
    """S6 (audit S1-29/30/34): capped JSON reads in providers + the
    GitHub/HF plugins, the GitHub repo shape check, and the
    faster-whisper pin."""

    def _plugin_module(self, folder, modname):
        import importlib.util
        root = Path(__file__).resolve().parent.parent
        path = root / "plugins" / folder / "plugin.py"
        spec = importlib.util.spec_from_file_location(modname, path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    # -- providers._json -------------------------------------------
    def test_provider_json_oversize_refused_at_cap(self):
        from forge import providers as p
        from forge.ollama_client import OllamaError
        cap = p._ProviderHTTP.MAX_JSON_BYTES
        fake = _CappedFakeResponse(b'{"data": "' + b"x" * cap + b'"}')
        client = p.GroqClient("test-key",
                              urlopen=lambda req, timeout=None: fake)
        with self.assertRaises(OllamaError) as ctx:
            client.models()
        self.assertIn("too large", str(ctx.exception))
        # the wire was never asked for more than cap + 1
        self.assertTrue(fake.requested)
        self.assertTrue(all(size <= cap + 1 for size in fake.requested))

    def test_provider_json_normal_body_parses(self):
        from forge import providers as p
        # Allowlist adaptation (2026-11-10): the stand-in catalog ID
        # is an approved model — an unapproved ID is now filtered
        # out of the catalog, which would test the filter instead of
        # the JSON parse this test pins.
        fake = _CappedFakeResponse(
            b'{"data": [{"id": "openai/gpt-oss-20b"}]}')
        client = p.GroqClient("test-key",
                              urlopen=lambda req, timeout=None: fake)
        self.assertEqual([m["name"] for m in client.models()],
                         ["groq:openai/gpt-oss-20b"])

    # -- GitHub / HF _get caps --------------------------------------
    def test_github_get_oversize_refused(self):
        from unittest import mock
        gh = self._plugin_module("github", "gh_plugin_s6")
        cap = gh.MAX_BYTES
        fake = _CappedFakeResponse(b'{"items": "' + b"x" * cap + b'"}')
        ctx = PluginContext(workspace="/tmp")
        with mock.patch("urllib.request.urlopen", lambda req, timeout=None: fake):
            out = gh.github_search_repos({"query": "forge"}, ctx)
        self.assertIn("too large", out)
        self.assertTrue(all(size <= cap + 1 for size in fake.requested))

    def test_hf_get_oversize_refused(self):
        from unittest import mock
        hf = self._plugin_module("huggingface", "hf_plugin_s6")
        cap = hf.MAX_BYTES
        fake = _CappedFakeResponse(b'[{"id": "' + b"x" * cap + b'"}]')
        ctx = PluginContext(workspace="/tmp")
        with mock.patch("urllib.request.urlopen", lambda req, timeout=None: fake):
            out = hf.hf_search_models({"query": "forge"}, ctx)
        self.assertIn("too large", out)
        self.assertTrue(all(size <= cap + 1 for size in fake.requested))

    def test_plugin_get_normal_body_parses(self):
        from unittest import mock
        gh = self._plugin_module("github", "gh_plugin_s6b")
        body = json.dumps({"full_name": "owner/name",
                           "stargazers_count": 3, "language": "Python",
                           "license": {"spdx_id": "MIT"},
                           "pushed_at": "2026-01-01", "description": "d",
                           "html_url": "https://example.invalid"}).encode()
        fake = _CappedFakeResponse(body)
        ctx = PluginContext(workspace="/tmp")
        with mock.patch("urllib.request.urlopen", lambda req, timeout=None: fake):
            out = gh.github_repo_info({"repo": "owner/name"}, ctx)
        self.assertIn("owner/name", out)

    # -- GitHub repo shape (S1-30) ----------------------------------
    def test_github_repo_shape_refused_before_http(self):
        from unittest import mock
        gh = self._plugin_module("github", "gh_plugin_s6c")
        calls = []

        def recording(req, timeout=None):
            calls.append(req)
            return _CappedFakeResponse(b"{}")

        ctx = PluginContext(workspace="/tmp")
        for bad in ("../x", "a/b/c", "a/", "/b", "a/..", "noslash",
                    "a//b", "./x", "..", ""):
            with mock.patch("urllib.request.urlopen", recording):
                out = gh.github_repo_info({"repo": bad}, ctx)
            self.assertIn("owner/name", out, bad)
        self.assertEqual(calls, [])

    # -- requirements pin (S1-34) ------------------------------------
    def test_requirements_pins_faster_whisper_bounded(self):
        root = Path(__file__).resolve().parent.parent
        lines = [line.strip() for line in
                 (root / "requirements.txt").read_text(
                     encoding="utf-8").splitlines() if line.strip()]
        self.assertIn("faster-whisper>=1.1,<2", lines)
        self.assertIn("PySide6>=6.7,<7", lines)


