class S6CyclePromptTests(unittest.TestCase):
    """S6 (audit S1-33): the soft long-turn prompt — asked ONCE when
    a turn crosses 40 tool cycles, through the approval bridge;
    deny ends the turn gracefully; approve runs it on; short turns
    are never asked. NOT a cap."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    def _worker(self, script, answer):
        from forge.worker import AgentWorker
        hits = {"n": 0}

        def handler(args):
            hits["n"] += 1
            return "pong"

        extra = {"ping_tool": (_ping_schema(), handler, False, "test")}
        worker = AgentWorker(
            _ScriptedClient(script), "fake",
            [{"role": "user", "content": "go"}], {"num_ctx": 100000},
            tempfile.mkdtemp(), extra_tools=extra)
        asked = []
        finished = []

        def on_approval(name, args, description, diff):
            asked.append((name, description))
            worker.resolve_approval(answer)

        worker.approval_needed.connect(on_approval)
        worker.finished_text.connect(lambda *a: finished.append(a))
        return worker, hits, asked, finished

    @staticmethod
    def _script(calls, tail="done"):
        return ([{"tool": "ping_tool", "args": {"word": f"w{i}"}}
                 for i in range(calls)] + [{"content": tail}])

    def test_crossing_40_asks_once_and_approval_runs_on(self):
        from forge.worker import LONG_TURN_TOOL
        worker, hits, asked, finished = self._worker(
            self._script(45), answer=True)
        worker.run()
        self.assertEqual(len(asked), 1)
        self.assertEqual(asked[0][0], LONG_TURN_TOOL)
        self.assertIn("40 tool cycles", asked[0][1])
        self.assertIn("Still working — continue?", asked[0][1])
        self.assertEqual(hits["n"], 45)
        self.assertTrue(finished)
        self.assertTrue(any(
            m.get("content") == "done" for m in worker.messages
            if m.get("role") == "assistant"))

    def test_denial_ends_turn_gracefully_with_partial_work(self):
        worker, hits, asked, finished = self._worker(
            self._script(45), answer=False)
        worker.run()
        self.assertEqual(len(asked), 1)
        # exactly the 40 approved cycles ran; nothing after the ask
        self.assertEqual(hits["n"], 40)
        self.assertTrue(finished)  # settled, no exception escaped
        self.assertFalse(any(
            m.get("content") == "done" for m in worker.messages
            if m.get("role") == "assistant"))

    def test_short_turn_never_asks(self):
        worker, hits, asked, finished = self._worker(
            self._script(3), answer=True)
        worker.run()
        self.assertEqual(asked, [])
        self.assertEqual(hits["n"], 3)
        self.assertTrue(finished)

# Ported from the S7 held copy (S7UpdateGateDiffTests, S6->S7 delta),
# with two disclosed adaptations for the DEV tree: the worker
# fixture uses the tree's plugins_dir kwarg (S7: ext_plugins_dir),
# assertions unchanged; and S7's missing-target method is NOT
# ported -- the DEV tree pins the opposite behaviour (missing
# update target earns no diff, UpdateDiffApprovalTests), so that
# S7 behaviour is a reported divergence, not ported code.



class S7UpdateGateDiffTests(unittest.TestCase):
    """S7 (audit S1-25b): update_skill / update_plugin approvals carry
    a diff too — the gate used to show only the target NAME for an
    update while a create showed every line. The preview is a true
    old-vs-new diff: the current file is read from the app-global
    root handed over by the window (never a guessed root), the
    proposed side is composed by the same helpers the updates write
    with, and a changed plugin description is named in the note
    line. Display only — diffview has no write path, so no tool's
    execution or S6's trust semantics can change here."""

    OLD_PLUGIN_CODE = ("def _go(args, ctx):\n"
                       "    return 'old-answer'\n\n"
                       "HANDLERS = {'go_now': _go}\n")
    NEW_PLUGIN_CODE = ("def _go(args, ctx):\n"
                       "    return 'new-answer'\n\n"
                       "HANDLERS = {'go_now': _go}\n")

    def _roots(self):
        base = Path(tempfile.mkdtemp())
        skills, plugins = base / "skills", base / "plugins"
        skills.mkdir()
        plugins.mkdir()
        return base, skills, plugins

    def _make_plugin(self, plugins, description="Fetches things."):
        from forge import create_ext
        ok, message = create_ext.create_plugin(
            plugins, "go-fer", description, self.OLD_PLUGIN_CODE)
        self.assertTrue(ok, message)

    def _make_skill(self, skills):
        from forge import create_ext
        ok, message = create_ext.create_skill(
            skills, "pdf-tables", "Extract tables.",
            "# Steps\n1. Read the PDF.\n2. Pull the tables.")
        self.assertTrue(ok, message)

    def test_update_plugin_diff_shows_old_against_new(self):
        from forge import diffview
        _, _, plugins = self._roots()
        self._make_plugin(plugins)
        args = {"name": "go-fer", "description": "Fetches things.",
                "code": self.NEW_PLUGIN_CODE}
        d = diffview.diff_for_approval("update_plugin", args, "/anywhere",
                                       plugins_dir=plugins)
        self.assertIsNotNone(d)
        self.assertFalse(d.is_new)
        self.assertEqual(d.path, "plugins/go-fer/plugin.py")
        self.assertIn("-    return 'old-answer'", d.body)
        self.assertIn("+    return 'new-answer'", d.body)
        self.assertEqual(d.removed, 1)
        self.assertEqual(d.added, 1)
        # The description did not change, so none is claimed.
        self.assertNotIn("Description changes", d.full_text())

    def test_update_plugin_description_change_named_with_code_change(self):
        from forge import diffview
        _, _, plugins = self._roots()
        self._make_plugin(plugins)
        args = {"name": "go-fer", "description": "Fetches things quickly.",
                "code": self.NEW_PLUGIN_CODE}
        d = diffview.diff_for_approval("update_plugin", args, "/anywhere",
                                       plugins_dir=plugins)
        self.assertIsNotNone(d)
        text = d.full_text()
        self.assertIn("-    return 'old-answer'", d.body)
        self.assertIn("+    return 'new-answer'", d.body)
        self.assertIn("Description changes too", text)
        self.assertIn("Fetches things.", text)
        self.assertIn("Fetches things quickly.", text)

    def test_update_plugin_description_only_update(self):
        from forge import diffview
        _, _, plugins = self._roots()
        self._make_plugin(plugins)
        args = {"name": "go-fer", "description": "Fetches things quickly.",
                "code": self.OLD_PLUGIN_CODE}
        d = diffview.diff_for_approval("update_plugin", args, "/anywhere",
                                       plugins_dir=plugins)
        self.assertIsNotNone(d)
        # Not "no changes": the description change is the update, and
        # the preview says so on both renderings (dialog + deck card).
        self.assertFalse(d.no_change)
        self.assertEqual(d.body, [])
        self.assertEqual(d.added, 0)
        self.assertEqual(d.removed, 0)
        self.assertIn("Description changes too", d.full_text())
        self.assertIn("The plugin code itself is unchanged.", d.full_text())
        self.assertIn("Description changes too", d.compact_text())

    def test_update_skill_diff_shows_old_against_new(self):
        from forge import diffview
        _, skills, _ = self._roots()
        self._make_skill(skills)
        args = {"name": "pdf-tables", "description": "Extract tables.",
                "body": "# Steps\n1. Read the PDF.\n"
                        "2. Pull the tables into CSV.\n3. Save the file."}
        d = diffview.diff_for_approval("update_skill", args, "/anywhere",
                                       skills_dir=skills)
        self.assertIsNotNone(d)
        self.assertFalse(d.is_new)
        self.assertEqual(d.path, "skills/pdf-tables/SKILL.md")
        self.assertIn("-2. Pull the tables.", d.body)
        self.assertIn("+2. Pull the tables into CSV.", d.body)
        self.assertIn("+3. Save the file.", d.body)

    def test_update_never_reads_outside_the_roots(self):
        import os
        from forge import diffview
        base, skills, plugins = self._roots()
        # A sentinel file OUTSIDE both roots, where a naive path join
        # of a traversal name would land.
        outside = base / "evil"
        outside.mkdir()
        (outside / "SKILL.md").write_text("SENTINEL-OUTSIDE\n",
                                          encoding="utf-8")
        (outside / "plugin.py").write_text("SENTINEL-OUTSIDE\n",
                                           encoding="utf-8")
        for bad in ("../evil", "..", "a/b", "..\\evil"):
            self.assertIsNone(diffview.diff_for_approval(
                "update_skill",
                {"name": bad, "description": "d", "body": "b"},
                "/anywhere", skills_dir=skills), bad)
            self.assertIsNone(diffview.diff_for_approval(
                "update_plugin",
                {"name": bad, "description": "d", "code": "c"},
                "/anywhere", plugins_dir=plugins), bad)
        # A VALID slug whose folder is a symlink out of the root: the
        # inside check resolves the link, the current content counts
        # as unavailable, and the sentinel never reaches the preview.
        os.symlink(outside, plugins / "linked")
        d = diffview.diff_for_approval(
            "update_plugin",
            {"name": "linked", "description": "d",
             "code": self.NEW_PLUGIN_CODE},
            "/anywhere", plugins_dir=plugins)
        self.assertIsNotNone(d)
        self.assertEqual(d.note, diffview.UNAVAILABLE_NOTE)
        self.assertNotIn("SENTINEL-OUTSIDE", d.full_text())

    def test_update_refusal_shapes_and_missing_root_get_no_diff(self):
        from forge import diffview
        _, skills, plugins = self._roots()
        plugin = {"name": "ok-name", "description": "d",
                  "code": "X = 1\n"}
        for bad in ({**plugin, "name": "Bad Name"},
                    {**plugin, "name": "../escape"},
                    {**plugin, "name": "  "},
                    {**plugin, "description": "  "},
                    {**plugin, "description": None},
                    {**plugin, "code": ""},
                    {**plugin, "code": "  \n "},
                    {"name": "ok-name", "description": "d"},
                    {"code": "X = 1\n"}):
            self.assertIsNone(
                diffview.diff_for_approval("update_plugin", bad,
                                           "/anywhere",
                                           plugins_dir=plugins),
                bad)
        skill = {"name": "ok-name", "description": "d", "body": "b"}
        for bad in ({**skill, "name": "Bad Name"},
                    {**skill, "description": ""},
                    {**skill, "body": "   "},
                    {"name": "ok-name", "description": "d"}):
            self.assertIsNone(
                diffview.diff_for_approval("update_skill", bad,
                                           "/anywhere",
                                           skills_dir=skills),
                bad)
        # No root handed over -> no diff, never a guessed root: the
        # pre-S7 call shape (three positional args) stays classic.
        self.assertIsNone(diffview.diff_for_approval(
            "update_plugin", plugin, "/anywhere"))
        self.assertIsNone(diffview.diff_for_approval(
            "update_skill", skill, "/anywhere"))
        self.assertIsNone(diffview.diff_for_approval(
            "update_plugin", plugin, "/anywhere", plugins_dir=None))
        self.assertIsNone(diffview.diff_for_approval(
            "update_skill", skill, "/anywhere", skills_dir=None))

    def test_worker_carries_the_update_plugin_diff(self):
        from forge.worker import AgentWorker
        from forge import create_ext, diffview
        _, _, plugins = self._roots()
        self._make_plugin(plugins)
        ws = Path(tempfile.mkdtemp())
        args = {"name": "go-fer", "description": "Fetches things.",
                "code": self.NEW_PLUGIN_CODE}
        expected = diffview.diff_for_approval(
            "update_plugin", args, str(ws), plugins_dir=plugins)
        self.assertIsNotNone(expected)
        tools = {"update_plugin": (create_ext.UPDATE_PLUGIN_SCHEMA,
                                   lambda a: "Updated GLOBAL plugin "
                                             "'go-fer'",
                                   True, "Forge shell")}
        worker = AgentWorker(_ScriptedClient([
            {"tool": "update_plugin", "args": args},
            {"content": "done"}]), "fake",
            [{"role": "user", "content": "go"}], {}, str(ws),
            extra_tools=tools, skribe_writes=False,
            plugins_dir=plugins)
        seen = []

        def on_approval(name, a, desc, diff):
            seen.append(diff)
            worker.resolve_approval(True)

        worker.approval_needed.connect(on_approval)
        worker.run()
        self.assertEqual(len(seen), 1)
        self.assertIsNotNone(seen[0])
        self.assertEqual(seen[0].path, "plugins/go-fer/plugin.py")
        self.assertEqual(seen[0].full_text(), expected.full_text())
        self.assertIn("-    return 'old-answer'", seen[0].body)

    def test_create_plugin_diff_byte_identical_after_s7(self):
        from forge import diffview
        # Pinned against the pre-S7 (S6) implementation's output for
        # the same inputs, byte for byte — the S7 branches must not
        # drift the create previews by a single character.
        code = ("def _go(args, ctx):\n    return 'went'\n\n"
                "HANDLERS = {'go_now': _go}")
        d = diffview.diff_for_approval(
            "create_plugin",
            {"name": "go-fer", "description": "Fetches things.",
             "code": code}, "/anywhere")
        self.assertIsNotNone(d)
        self.assertEqual(
            d.full_text(),
            "plugins/go-fer/plugin.py — new file, +4 −0\n"
            "@@ -0,0 +1,4 @@\n"
            "+def _go(args, ctx):\n"
            "+    return 'went'\n"
            "+\n"
            "+HANDLERS = {'go_now': _go}")

class _FakeProviderChatClient:
    """Provider-chat fake for the facade seam: records every
    chat_stream call and streams a scripted two-chunk reply.
    tags() serves a canned cloud catalog so the picker's catalog
    merge path runs offline."""

    def __init__(self, chunks=("Hello ", "from the cloud."), fail=None):
        self.chunks = chunks
        self.fail = fail
        self.calls = []

    def chat_stream(self, model, messages, options, tools,
                    images=None, keep_alive="30m"):
        self.calls.append({"model": model,
                           "messages": [dict(m) for m in messages],
                           "options": options, "tools": tools})
        if self.fail:
            raise RuntimeError(self.fail)
        for chunk in self.chunks:
            yield {"message": {"content": chunk, "tool_calls": []},
                   "done": False}
        yield {"message": {"content": "", "tool_calls": []},
               "done": True}

    def tags(self, scope="project"):
        return [{"name": "groq:catalog-only-model",
                 "model": "catalog-only-model", "provider": "groq"}]


class _StubRunningWorker:
    """The least a stream record's worker must be for the registry
    reads: still running."""

    def isRunning(self):
        return True


class ProviderChatWindowTests(unittest.TestCase):
    """Provider chat (owner ask, 2026-11-09): a hosted-model
    conversation that runs alongside the bench. Pins: the pickers
    come from the #69 registry (cloud models only, configured
    providers only), a send streams through the facade seam with
    NO tools, the window's history is its own, the main window's
    messages object and the conversation store are untouched by
    an exchange, the bench line is sourced from mission_rows(),
    and the no-key state speaks plainly instead of showing an
    empty picker."""

    # Allowlist adaptation (2026-11-10): the registry stand-in is an
    # approved provider model — llama-3.3-70b-versatile is not on
    # Code Forge's provider allowlist, so the picker (which gates
    # registry rows through model_allowed) would no longer list it.
    MODEL = "groq:openai/gpt-oss-120b"

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        # PC-merge fixture adaptation (disclosed): on the current
        # tree provider_api_key is vault-first (S2), and an earlier
        # class (CustomizeProvidersTests) leaves both provider keys
        # in the default vault — the copy's fixture semantics ("Gemini
        # has a registry entry but NO key") need a hermetic vault.
        # Same isolation VaultTests use: point the vault's default
        # location at a fresh temp app dir for the test's duration.
        self._vault_temp = tempfile.TemporaryDirectory()
        self._vault_app_dir = Path(self._vault_temp.name) / "appdata"
        self._vault_app_dir.mkdir(parents=True)
        from forge import vault as vault_mod
        self._vault_mod = vault_mod
        self._real_vault_default = vault_mod.default_app_dir
        vault_mod.default_app_dir = lambda: self._vault_app_dir
        self._old_client = self.win.client
        self._old_config = self.win._connector_config
        self.client = _FakeProviderChatClient()
        self.win.client = self.client
        # Groq is keyed; Gemini has a registry entry but NO key,
        # so it must not appear — the picker lists only providers
        # the owner can actually talk to.
        self.win._connector_config = {
            "groq_api_key": "test-key",
            "groq_enabled": True,
            "model_registry": [
                {"id": self.MODEL, "enabled": True, "scope": "both",
                 "roles": ["driver"]},
                {"id": "gemini:gemini-3.8-flash", "enabled": True,
                 "scope": "both", "roles": ["driver"]}]}
        self.win._streams = {}
        self.win._stage_stream_id = None
        self.win.messages = []
        from forge.main import ProviderChatWindow
        self.chat = ProviderChatWindow(self.win)

    def tearDown(self):
        if self.chat._thread is not None:
            self.chat._thread.wait(5000)
        self.chat.close()
        self.win.client = self._old_client
        self.win._connector_config = self._old_config
        self.win._streams = {}
        self.win._stage_stream_id = None
        self.win.messages = []
        self._vault_mod.default_app_dir = self._real_vault_default
        self._vault_temp.cleanup()

    def _pump_until(self, pred, timeout=8.0):
        import time
        deadline = time.time() + timeout
        while time.time() < deadline:
            self.app.processEvents()
            if pred():
                return True
            time.sleep(0.02)
        return pred()

    def _exchange(self, text="How is the bench doing?"):
        self.chat.input.setPlainText(text)
        self.chat.send()
        self.assertTrue(
            self._pump_until(lambda: len(self.chat.messages) >= 2),
            "provider chat exchange never completed")

    def test_pickers_come_from_the_registry_cloud_only(self):
        providers = [self.chat.provider_combo.itemData(i)
                     for i in range(self.chat.provider_combo.count())]
        self.assertEqual(providers, ["groq"])
        models = [self.chat.model_combo.itemText(i)
                  for i in range(self.chat.model_combo.count())]
        self.assertIn(self.MODEL, models)
        # The facade catalog merges in; the unkeyed provider's
        # registry entry does not.
        self.assertIn("groq:catalog-only-model", models)
        self.assertFalse(any(m.startswith("gemini:") for m in models))
        # The window is never shown in this test, so "shown" state
        # is read via isHidden() — setVisible(False) is what hides.
        self.assertTrue(self.chat.setup_label.isHidden())
        self.assertTrue(self.chat.send_btn.isEnabled())

    def test_send_streams_through_the_facade_with_no_tools(self):
        self._exchange()
        self.assertEqual(len(self.client.calls), 1)
        call = self.client.calls[0]
        self.assertEqual(call["tools"], [])
        self.assertEqual(call["model"], self.MODEL)
        self.assertEqual(call["messages"][0]["role"], "system")
        self.assertIn("conversation only",
                      call["messages"][0]["content"])
        self.assertEqual(call["messages"][-1],
                         {"role": "user",
                          "content": "How is the bench doing?"})
        self.assertEqual(
            self.chat.messages,
            [{"role": "user", "content": "How is the bench doing?"},
             {"role": "assistant", "content": "Hello from the cloud."}])
        self.assertIn("Hello from the cloud.",
                      self.chat.transcript.toPlainText())

    def test_main_window_and_store_are_untouched(self):
        import copy
        sentinel = [{"role": "system", "content": "sys"},
                    {"role": "user", "content": "main work"}]
        self.win.messages = sentinel
        snapshot = copy.deepcopy(sentinel)
        cid_before = self.win.conversation_id
        stored_before = len(self.win.store.recent(200))
        self._exchange()
        # Identity AND content: the bench's list was never read,
        # swapped, appended to, or persisted from this window.
        self.assertIs(self.win.messages, sentinel)
        self.assertEqual(self.win.messages, snapshot)
        self.assertEqual(self.win.conversation_id, cid_before)
        self.assertEqual(len(self.win.store.recent(200)), stored_before)

    def test_bench_status_line_follows_the_registry(self):
        self.assertEqual(self.chat.refresh_status(), "Bench: idle")
        record = {"id": 777, "worker": _StubRunningWorker(),
                  "conversation_id": 42, "title": "Big refactor",
                  "workspace": "", "project": "proj_x",
                  "model": "stub-model", "mode": "Code", "prompt": "",
                  "started_at": 0.0, "last_activity": 0.0,
                  "last_push": 0.0, "stream_text": "",
                  "status_text": "", "gate": None, "background": False,
                  "planning": False, "side": False,
                  "maintenance": False, "settled": None,
                  "collector": None, "receipts": None}
        self.win._streams = {777: record}
        self.win._stage_stream_id = 777
        text = self.chat.refresh_status()
        self.assertTrue(text.startswith("Bench: "))
        self.assertIn("Big refactor", text)
        self.assertIn("proj_x", text)
        self.assertIn("Running", text)
        record["settled"] = ("done", None)
        self.assertEqual(self.chat.refresh_status(), "Bench: idle")

    def test_no_key_state_speaks_plainly(self):
        self.win._connector_config = {}
        from forge.main import ProviderChatWindow
        chat = ProviderChatWindow(self.win)
        try:
            # Not hidden = the setup text is what the owner sees
            # when the window opens (isVisible() needs a shown
            # parent; isHidden() is the setVisible record).
            self.assertFalse(chat.setup_label.isHidden())
            self.assertIn("Customize → Providers",
                          chat.setup_label.text())
            self.assertEqual(chat.provider_combo.count(), 0)
            self.assertEqual(chat.model_combo.count(), 0)
            self.assertFalse(chat.send_btn.isEnabled())
            chat.input.setPlainText("anyone there?")
            chat.send()
            self.assertEqual(chat.messages, [])
            self.assertEqual(self.client.calls, [])
        finally:
            chat.close()

    def test_failed_stream_surfaces_a_plain_notice(self):
        self.client.fail = "boom from the provider"
        self.chat.input.setPlainText("hello?")
        self.chat.send()
        self.assertTrue(
            self._pump_until(lambda: bool(self.chat._notice)),
            "provider failure never surfaced")
        self.assertIn("boom from the provider", self.chat._notice)
        # The failure is a notice in the view, never a fake
        # assistant message in the window's own history.
        self.assertEqual(self.chat.messages,
                         [{"role": "user", "content": "hello?"}])
        self.assertTrue(self.chat.send_btn.isEnabled())

    def test_palette_and_menu_open_the_window(self):
        from forge import palette as palette_mod
        ids = [entry["id"] for entry in palette_mod.base_catalog()]
        self.assertIn("provider_chat", ids)
        _entries, bindings = self.win.palette_actions()
        self.assertIn("provider_chat", bindings)
        self.win.open_provider_chat()
        try:
            self.assertIsNotNone(self.win.provider_chat_win)
            self.assertTrue(self.win.provider_chat_win.isVisible())
        finally:
            self.win.provider_chat_win.hide()


class UiBuilderStyleTests(unittest.TestCase):
    """UI Builder completion (owner's order, 2026-11-09): the
    per-widget properties system — the model holds them, invalid
    edits are refused whole, old designs load with defaults, and
    the JSON round-trip carries them."""

    def test_style_round_trip_through_the_model(self):
        from forge import uibuilder as uib
        d = uib.new_design()
        a = uib.add_widget(d, "button", 10, 10)
        self.assertEqual(a["style"], uib.default_style())
        out = uib.set_widget_style(
            d, "button", fg="#FF0000", bg="#00ff00",
            font_family="Courier New", font_size=14, bold=True,
            italic=True, border_width=2, border_style="dashed",
            border_color="#0000FF", padding=6)
        self.assertIs(out, a)
        style = uib.widget_style(a)
        # colors normalize to lowercase hex on the way in
        self.assertEqual(style["fg"], "#ff0000")
        self.assertEqual(style["bg"], "#00ff00")
        self.assertEqual(style["border_color"], "#0000ff")
        self.assertEqual(style["font_family"], "Courier New")
        self.assertEqual(style["font_size"], 14)
        self.assertTrue(style["bold"])
        self.assertTrue(style["italic"])
        self.assertEqual(style["border_width"], 2)
        self.assertEqual(style["border_style"], "dashed")
        self.assertEqual(style["padding"], 6)
        # partial edits merge with what is already there
        uib.set_widget_style(d, "button", fg="")
        style = uib.widget_style(a)
        self.assertEqual(style["fg"], "")
        self.assertEqual(style["bg"], "#00ff00")
        # and the whole style survives the JSON round-trip
        self.assertEqual(uib.design_from_json(uib.design_to_json(d)), d)

    def test_invalid_style_edits_are_refused_whole(self):
        from forge import uibuilder as uib
        d = uib.new_design()
        a = uib.add_widget(d, "label", 0, 0)
        for bad in ({"fg": "red"}, {"fg": "#12345"}, {"bg": 12},
                    {"font_size": -1}, {"font_size": 500},
                    {"font_size": True}, {"border_width": 99},
                    {"padding": -2}, {"border_style": "wavy"},
                    {"bold": "yes"}, {"nonsense": 1}):
            self.assertIsNone(uib.set_widget_style(d, "label", **bad),
                              bad)
        self.assertEqual(a["style"], uib.default_style())
        self.assertIsNone(uib.set_widget_style(d, "ghost", fg="#ffffff"))

    def test_old_format_design_loads_with_default_styles(self):
        from forge import uibuilder as uib
        old = {"title": "Old", "width": 300, "height": 200, "widgets": [
            {"type": "button", "name": "go", "text": "Go",
             "x": 5, "y": 5, "w": 90, "h": 30},
            {"type": "label", "name": "lab", "text": "Hi",
             "x": 5, "y": 45, "w": 90, "h": 20}]}
        d = uib.sanitize_design(old)
        self.assertEqual([w["name"] for w in d["widgets"]], ["go", "lab"])
        for entry in d["widgets"]:
            self.assertEqual(entry["style"], uib.default_style())
            self.assertEqual(uib.widget_stylesheet(entry), "")
            self.assertIsNone(uib.widget_font(entry))
        # garbage style data is cleaned, never carried through
        old["widgets"][0]["style"] = {"fg": "red", "font_size": "big",
                                      "border_width": 999, "bold": 1}
        d = uib.sanitize_design(old)
        style = uib.widget_style(d["widgets"][0])
        self.assertEqual(style["fg"], "")
        self.assertEqual(style["font_size"], 0)
        self.assertEqual(style["border_width"], uib.MAX_BORDER_WIDTH)
        self.assertTrue(style["bold"])

    def test_stylesheet_and_font_spec_builders(self):
        from forge import uibuilder as uib
        entry = {"style": uib.default_style()}
        self.assertEqual(uib.widget_stylesheet(entry), "")
        self.assertIsNone(uib.widget_font(entry))
        entry["style"].update(fg="#ff0000", bg="#00ff00", padding=4)
        self.assertEqual(
            uib.widget_stylesheet(entry),
            "color: #ff0000; background-color: #00ff00; padding: 4px;")
        # a width without a color falls back to the shared tone
        entry["style"].update(border_width=3, border_style="dotted")
        self.assertIn("border: 3px dotted #000000;",
                      uib.widget_stylesheet(entry))
        entry["style"]["border_style"] = "none"
        self.assertNotIn("border:", uib.widget_stylesheet(entry))
        entry["style"].update(font_family="Georgia", font_size=18,
                              italic=True)
        self.assertEqual(uib.widget_font(entry),
                         {"family": "Georgia", "size": 18,
                          "bold": False, "italic": True})


class UiBuilderCatalogTests(unittest.TestCase):
    """The widened catalog: the six original types stay, the new
    standard set is placeable, and every type instantiates through
    the preview builder as its real Qt class."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    # Assembly (lead fix, 2026-11-10): Forge's own app stylesheet
    # (G5/G7 — QWidget font-family 'Inter') cascades over setFont in
    # any process where a ForgeWindow has existed, which would judge
    # G5's cascade instead of the builder's font seam. The class
    # sandboxes the app stylesheet like other classes sandbox the
    # vault; assertions unchanged.
    def setUp(self):
        from PySide6.QtWidgets import QApplication
        app = QApplication.instance()
        self._saved_sheet = app.styleSheet() if app else None
        if app:
            app.setStyleSheet("")

    def tearDown(self):
        from PySide6.QtWidgets import QApplication
        app = QApplication.instance()
        if app and self._saved_sheet is not None:
            app.setStyleSheet(self._saved_sheet)

    def test_catalog_keeps_the_original_six_and_adds_the_standard_set(self):
        from forge import uibuilder as uib
        for kept in ("label", "button", "line_edit", "text_edit",
                     "checkbox", "svg"):
            self.assertIn(kept, uib.WIDGET_TYPES)
        for added in ("combo_box", "spin_box", "slider", "progress_bar",
                      "radio_button", "group_box", "h_line", "v_line"):
            self.assertIn(added, uib.WIDGET_TYPES)
        d = uib.new_design()
        for wtype in uib.WIDGET_TYPES:
            entry = uib.add_widget(d, wtype, 0, 0)
            self.assertIsNotNone(entry, wtype)
            self.assertEqual(entry["style"], uib.default_style())
        self.assertEqual(len(d["widgets"]), len(uib.WIDGET_TYPES))

    def test_every_type_instantiates_in_the_preview(self):
        from PySide6.QtWidgets import (QCheckBox, QComboBox, QFrame,
                                       QGroupBox, QLabel, QLineEdit,
                                       QProgressBar, QPushButton,
                                       QRadioButton, QSlider, QSpinBox,
                                       QTextEdit)
        from forge import uibuilder as uib
        from forge.main import build_ui_preview
        d = uib.new_design("All", 800, 600)
        for wtype in uib.WIDGET_TYPES:
            if wtype != "svg":   # svg needs a payload; covered elsewhere
                uib.add_widget(d, wtype, 0, 0)
        win = build_ui_preview(d)
        try:
            expected = {"label": QLabel, "button": QPushButton,
                        "line_edit": QLineEdit, "text_edit": QTextEdit,
                        "checkbox": QCheckBox,
                        "radio_button": QRadioButton,
                        "combo_box": QComboBox, "spin_box": QSpinBox,
                        "slider": QSlider,
                        "progress_bar": QProgressBar,
                        "group_box": QGroupBox, "h_line": QFrame,
                        "v_line": QFrame}
            for name, cls in expected.items():
                self.assertIsInstance(getattr(win, name), cls, name)
            # the per-type text semantics match the exporter's
            self.assertEqual(win.group_box.title(), "Group")
            self.assertEqual(
                [win.combo_box.itemText(i)
                 for i in range(win.combo_box.count())],
                ["One", "Two", "Three"])
            self.assertEqual(win.progress_bar.value(), 50)
            self.assertEqual(win.h_line.frameShape(), QFrame.Shape.HLine)
            self.assertEqual(win.v_line.frameShape(), QFrame.Shape.VLine)
            self.assertEqual(win.radio_button.text(), "Option")
        finally:
            win.close()

    def test_preview_applies_the_styling(self):
        from PySide6.QtGui import QColor
        from forge import uibuilder as uib
        from forge.main import build_ui_preview
        d = uib.new_design()
        a = uib.add_widget(d, "button", 10, 10)
        uib.set_widget_style(d, "button", fg="#ff0000", bg="#00ff00",
                             font_size=16, bold=True, padding=5)
        win = build_ui_preview(d)
        try:
            btn = win.button
            self.assertIn("color: #ff0000", btn.styleSheet())
            self.assertIn("background-color: #00ff00", btn.styleSheet())
            self.assertIn("padding: 5px", btn.styleSheet())
            self.assertEqual(btn.font().pointSize(), 16)
            self.assertTrue(btn.font().bold())
            self.assertEqual(a["name"], "button")  # model untouched
        finally:
            win.close()


class UiBuilderResizeHandleTests(unittest.TestCase):
    """The 8-handle model: hit-testing, and drags that change the
    rect in the dragged direction only (pure model level)."""

    ENTRY = {"x": 100, "y": 80, "w": 120, "h": 60}

    def test_handle_at_finds_corners_and_edges(self):
        from forge import uibuilder as uib
        e = dict(self.ENTRY)
        self.assertEqual(uib.handle_at(e, 102, 82), "nw")
        self.assertEqual(uib.handle_at(e, 215, 82), "ne")
        self.assertEqual(uib.handle_at(e, 102, 135), "sw")
        self.assertEqual(uib.handle_at(e, 215, 135), "se")
        self.assertEqual(uib.handle_at(e, 157, 82), "n")
        self.assertEqual(uib.handle_at(e, 157, 135), "s")
        self.assertEqual(uib.handle_at(e, 102, 107), "w")
        self.assertEqual(uib.handle_at(e, 215, 107), "e")
        self.assertIsNone(uib.handle_at(e, 150, 110))   # the body
        self.assertIsNone(uib.handle_at(e, 10, 10))     # outside

    def test_edge_drags_change_one_axis_only(self):
        from forge import uibuilder as uib
        x, y, w, h = self.ENTRY["x"], self.ENTRY["y"], \
            self.ENTRY["w"], self.ENTRY["h"]
        self.assertEqual(uib.drag_rect(x, y, w, h, "e", 30, 999),
                         (100, 80, 150, 60))
        self.assertEqual(uib.drag_rect(x, y, w, h, "s", 999, 20),
                         (100, 80, 120, 80))
        self.assertEqual(uib.drag_rect(x, y, w, h, "w", 25, 999),
                         (125, 80, 95, 60))
        self.assertEqual(uib.drag_rect(x, y, w, h, "n", 999, 15),
                         (100, 95, 120, 45))

    def test_corner_drags_change_two_axes_and_pin_the_opposite_edge(self):
        from forge import uibuilder as uib
        x, y, w, h = self.ENTRY["x"], self.ENTRY["y"], \
            self.ENTRY["w"], self.ENTRY["h"]
        self.assertEqual(uib.drag_rect(x, y, w, h, "se", 10, 10),
                         (100, 80, 130, 70))
        self.assertEqual(uib.drag_rect(x, y, w, h, "nw", -10, -5),
                         (90, 75, 130, 65))
        # dragged past the minimum: size floors at MIN_WIDGET and
        # the fixed (south-east) corner does not move
        nx, ny, nw, nh = uib.drag_rect(x, y, w, h, "nw", 500, 500)
        self.assertEqual((nw, nh), (uib.MIN_WIDGET, uib.MIN_WIDGET))
        self.assertEqual((nx + nw, ny + nh), (x + w, y + h))

    def test_canvas_drag_via_edge_and_corner_handles(self):
        from PySide6.QtCore import QEvent, QPointF, Qt
        from PySide6.QtGui import QMouseEvent
        from PySide6.QtWidgets import QApplication
        QApplication.instance() or QApplication([])
        from forge import uibuilder as uib
        from forge.main import BuilderCanvas
        canvas = BuilderCanvas()
        try:
            design = uib.new_design()
            entry = uib.add_widget(design, "button", 40, 40)  # 110x32
            canvas.set_design(design)
            canvas.selected = entry["name"]

            def drag(x0, y0, x1, y1):
                press = QMouseEvent(QEvent.MouseButtonPress,
                                    QPointF(x0, y0), Qt.LeftButton,
                                    Qt.LeftButton, Qt.NoModifier)
                canvas.mousePressEvent(press)
                move = QMouseEvent(QEvent.MouseMove,
                                   QPointF(x1, y1), Qt.LeftButton,
                                   Qt.LeftButton, Qt.NoModifier)
                canvas.mouseMoveEvent(move)
                release = QMouseEvent(QEvent.MouseButtonRelease,
                                      QPointF(x1, y1), Qt.LeftButton,
                                      Qt.LeftButton, Qt.NoModifier)
                canvas.mouseReleaseEvent(release)

            # east edge handle: centre of the right edge (150, 56)
            drag(147, 53, 187, 90)
            self.assertEqual((entry["x"], entry["y"]), (40, 40))
            self.assertEqual((entry["w"], entry["h"]), (150, 32))
            # north-west corner handle (40, 40): both axes move
            drag(42, 42, 22, 27)
            self.assertEqual((entry["x"], entry["y"]), (20, 25))
            self.assertEqual((entry["w"], entry["h"]), (170, 47))
        finally:
            canvas.close()


class UiBuilderStyledCodegenTests(unittest.TestCase):
    """The exporter carries the styling: generated code contains
    the stylesheet/font calls with the design's values, an unstyled
    design exports exactly as before, and the generated file runs
    with the styling actually on the widgets."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    # Assembly (lead fix, 2026-11-10): the generated file is built
    # to run standalone; executed in THIS process it would inherit
    # Forge's app stylesheet (G5/G7), whose QWidget font rule
    # cascades over the generated widgets' setFont. The class
    # sandboxes the app stylesheet like other classes sandbox the
    # vault; assertions unchanged.
    def setUp(self):
        from PySide6.QtWidgets import QApplication
        app = QApplication.instance()
        self._saved_sheet = app.styleSheet() if app else None
        if app:
            app.setStyleSheet("")

    def tearDown(self):
        from PySide6.QtWidgets import QApplication
        app = QApplication.instance()
        if app and self._saved_sheet is not None:
            app.setStyleSheet(self._saved_sheet)

    def _styled_design(self):
        from forge import uibuilder as uib
        d = uib.new_design("Styled", 400, 300)
        uib.add_widget(d, "button", 20, 20)
        uib.set_widget_style(
            d, "button", fg="#ff0000", bg="#00ff00",
            font_family="Courier New", font_size=14, bold=True,
            border_width=2, border_style="dashed",
            border_color="#0000ff", padding=6)
        uib.add_widget(d, "combo_box", 20, 70)
        uib.add_widget(d, "group_box", 20, 120)
        uib.add_widget(d, "h_line", 20, 280)
        return d

    def test_generated_code_contains_the_styling(self):
        from forge import uibuilder as uib
        code = uib.generate_code(self._styled_design())
        self.assertIn("from PySide6.QtGui import QFont", code)
        self.assertIn(
            "self.button.setStyleSheet('color: #ff0000; "
            "background-color: #00ff00; border: 2px dashed #0000ff; "
            "padding: 6px;')", code)
        self.assertIn("_font.setFamily('Courier New')", code)
        self.assertIn("_font.setPointSize(14)", code)
        self.assertIn("_font.setBold(True)", code)
        self.assertIn("self.button.setFont(_font)", code)
        # the new types' own lines ride along
        self.assertIn("self.combo_box.addItems(['One', 'Two', 'Three'])",
                      code)
        self.assertIn("self.group_box.setTitle('Group')", code)
        self.assertIn(
            "self.h_line.setFrameShape(QFrame.Shape.HLine)", code)
        self.assertIn("QFrame", code)
        compile(code, "styled_ui.py", "exec")

    def test_unstyled_design_exports_without_styling_lines(self):
        from forge import uibuilder as uib
        code = uib.generate_code(_sample_design())
        self.assertNotIn("setStyleSheet", code)
        self.assertNotIn("QFont", code)

    def test_generated_styled_file_runs_with_the_styling_on(self):
        import importlib.util
        from forge import uibuilder as uib
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "styled_ui.py"
            path.write_text(uib.generate_code(self._styled_design()),
                            encoding="utf-8")
            spec = importlib.util.spec_from_file_location(
                "styled_ui_sample", path)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            win = module.BuiltWindow()
            try:
                btn = win.button
                self.assertIn("color: #ff0000", btn.styleSheet())
                self.assertIn("border: 2px dashed #0000ff",
                              btn.styleSheet())
                self.assertEqual(btn.font().family(), "Courier New")
                self.assertEqual(btn.font().pointSize(), 14)
                self.assertTrue(btn.font().bold())
                self.assertEqual(
                    [win.combo_box.itemText(i)
                     for i in range(win.combo_box.count())],
                    ["One", "Two", "Three"])
                self.assertEqual(win.group_box.title(), "Group")
            finally:
                win.close()


class UiBuilderInspectorTests(unittest.TestCase):
    """The dialog's properties inspector: driving its controls
    writes the style into the model, selection refreshes it, and
    the palette offers the whole catalog."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        from forge.main import UiBuilderDialog
        self.temp = tempfile.TemporaryDirectory()
        self.dlg = UiBuilderDialog(self.win, self.temp.name)

    def tearDown(self):
        if self.dlg._preview is not None:
            self.dlg._preview.close()
        self.dlg.close()
        self.temp.cleanup()

    def _place(self, wtype, x, y):
        from PySide6.QtCore import QEvent, QPointF, Qt
        from PySide6.QtGui import QMouseEvent
        self.dlg._palette_btns[wtype].click()
        ev = QMouseEvent(QEvent.MouseButtonPress, QPointF(x, y),
                         Qt.LeftButton, Qt.LeftButton, Qt.NoModifier)
        self.dlg.canvas.mousePressEvent(ev)
        return self.dlg.design["widgets"][-1]

    def test_palette_offers_the_full_catalog(self):
        for wtype in ("label", "button", "line_edit", "text_edit",
                      "checkbox", "radio_button", "combo_box",
                      "spin_box", "slider", "progress_bar", "group_box",
                      "h_line", "v_line"):
            self.assertIn(wtype, self.dlg._palette_btns)
        entry = self._place("slider", 30, 30)
        self.assertEqual(entry["type"], "slider")
        entry = self._place("group_box", 30, 80)
        self.assertEqual(entry["type"], "group_box")

    def test_inspector_controls_write_the_style(self):
        from forge import uibuilder as uib
        dlg = self.dlg
        entry = self._place("button", 30, 30)
        self.assertTrue(dlg.style_fg_btn.isEnabled())
        dlg._apply_style(fg="#123456", bg="#654321")
        style = uib.widget_style(entry)
        self.assertEqual(style["fg"], "#123456")
        self.assertEqual(dlg.style_fg_btn.text(), "#123456")
        # driving the real controls flows into the model too
        dlg.style_size.setValue(20)
        self.assertEqual(uib.widget_style(entry)["font_size"], 20)
        dlg.style_bold.setChecked(True)
        self.assertTrue(uib.widget_style(entry)["bold"])
        dlg.style_border_width.setValue(3)
        dlg.style_border_style.setCurrentText("dotted")
        dlg.style_padding.setValue(7)
        style = uib.widget_style(entry)
        self.assertEqual(style["border_width"], 3)
        self.assertEqual(style["border_style"], "dotted")
        self.assertEqual(style["padding"], 7)
        # deselecting disables the inspector and resets its face
        from PySide6.QtCore import QEvent, QPointF, Qt
        from PySide6.QtGui import QMouseEvent
        ev = QMouseEvent(QEvent.MouseButtonPress, QPointF(450, 330),
                         Qt.LeftButton, Qt.LeftButton, Qt.NoModifier)
        dlg.canvas.mousePressEvent(ev)
        self.assertIsNone(dlg.canvas.selected)
        self.assertFalse(dlg.style_fg_btn.isEnabled())
        self.assertEqual(dlg.style_fg_btn.text(), "default")

    def test_canvas_paints_the_styling(self):
        from PySide6.QtGui import QColor, QPixmap
        entry = self._place("button", 30, 30)
        self.dlg._apply_style(bg="#00ff00")
        canvas = self.dlg.canvas
        pixmap = QPixmap(canvas.width(), canvas.height())
        canvas.render(pixmap)
        # an interior pixel clear of the painted texts and handles
        # carries the background color
        self.assertEqual(pixmap.toImage().pixelColor(120, 45),
                         QColor("#00ff00"))

# ---------- Debug capability (forge/debugger + Debug window + tools) ----------

DEBUG_FIXTURE = (
    "def compute(n):\n"          # 1
    "    total = n * 2\n"        # 2
    "    return total\n"         # 3
    "\n"                         # 4
    "def main():\n"              # 5
    "    x = 21\n"               # 6
    "    y = compute(x)\n"       # 7
    "    print(\"result is\", y)\n"  # 8
    "\n"                         # 9
    "main()\n"                   # 10
)


class DebugEngineTests(unittest.TestCase):
    """forge/debugger: a Python target under stdlib pdb in a
    subprocess — breakpoints land where they should, steps advance,
    inspect reads the live frame, finishing/stopping leaves no
    process behind. The engine is Qt-free; these tests drive it
    directly against a fixture script in a temp workspace."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        (self.root / "app.py").write_text(DEBUG_FIXTURE)
        self.session = None

    def tearDown(self):
        if self.session is not None:
            self.session.stop()
        self.temp.cleanup()

    def _start(self, breakpoints=((("app.py"), 7),)):
        from forge.debugger import DebugSession
        self.session = DebugSession(self.root, timeout=15)
        return self.session.start("app.py", breakpoints=list(breakpoints))

    def test_start_stops_at_entry_and_registers_the_breakpoint(self):
        state = self._start()
        self.assertEqual(state["status"], "stopped")
        self.assertEqual(state["line"], 1)
        self.assertTrue(state["file"].endswith("app.py"))
        self.assertIn("Breakpoint 1 at", state["output"])
        self.assertTrue(self.session.alive)

    def test_breakpoint_hit_lands_on_the_right_line(self):
        self._start()
        state = self.session.continue_()
        self.assertEqual(state["status"], "stopped")
        self.assertEqual(state["line"], 7)
        self.assertEqual(state["function"], "main")

    def test_step_over_advances_and_inspect_reads_the_frame(self):
        self._start()
        self.session.continue_()
        self.assertEqual(self.session.inspect("x"), "21")
        state = self.session.step_over()
        self.assertEqual(state["status"], "stopped")
        self.assertEqual(state["line"], 8)
        self.assertEqual(self.session.inspect("y"), "42")

    def test_step_into_enters_the_call(self):
        self._start()
        self.session.continue_()
        state = self.session.step_into()
        self.assertEqual(state["status"], "stopped")
        self.assertEqual(state["function"], "compute")
        self.assertEqual(self.session.inspect("n"), "21")

    def test_continue_to_end_finishes_and_the_process_is_gone(self):
        import os
        self._start()
        pid = self.session.proc.pid
        state = self.session.continue_()
        self.assertEqual(state["status"], "stopped")  # the breakpoint first
        self.assertEqual(state["line"], 7)
        state = self.session.continue_()
        self.assertEqual(state["status"], "finished")
        self.assertIn("result is 42", state["output"])
        self.assertFalse(self.session.alive)
        self.assertIsNone(self.session.proc)
        with self.assertRaises(ProcessLookupError):
            os.kill(pid, 0)
        # A finished session refuses further driving, in words.
        state = self.session.step_over()
        self.assertEqual(state["status"], "error")
        self.assertIn("no debug session is live", state["output"])

    def test_stop_kills_the_process(self):
        import os
        self._start()
        pid = self.session.proc.pid
        self.session.stop()
        self.assertFalse(self.session.alive)
        self.assertIsNone(self.session.proc)
        with self.assertRaises(ProcessLookupError):
            os.kill(pid, 0)

    def test_target_outside_the_workspace_is_refused(self):
        from forge.debugger import DebugSession
        session = DebugSession(self.root, timeout=15)
        outside = self.root.parent / "outside.py"
        outside.write_text("print('outside')\n")
        with self.assertRaises(ValueError):
            session.start(str(outside))
        with self.assertRaises(ValueError):
            session.start("missing.py")
        (self.root / "notes.txt").write_text("not python\n")
        with self.assertRaises(ValueError):
            session.start("notes.txt")
        self.assertFalse(session.alive)

    def test_inspect_refuses_smuggled_commands(self):
        self._start()
        self.session.continue_()
        self.assertTrue(self.session.inspect("x\nq").startswith("Refused"))
        self.assertTrue(self.session.inspect("!x = 1").startswith("Refused"))
        # The session is untouched: still stopped, still readable.
        self.assertEqual(self.session.inspect("x"), "21")

    def test_calls_with_no_session_refuse_in_plain_words(self):
        from forge.debugger import DebugSession
        session = DebugSession(self.root, timeout=15)
        state = session.step_over()
        self.assertEqual(state["status"], "error")
        self.assertIn("no debug session is live", session.inspect("x"))

    def test_parse_breakpoints_shapes(self):
        from forge.debugger import parse_breakpoints
        self.assertEqual(parse_breakpoints("7, util.py:9\n12", "app.py"),
                         [("app.py", 7), ("util.py", 9), ("app.py", 12)])
        self.assertEqual(parse_breakpoints("", "app.py"), [])
        with self.assertRaises(ValueError):
            parse_breakpoints("soon", "app.py")
        with self.assertRaises(ValueError):
            parse_breakpoints("0", "app.py")


class DebugWindowTests(unittest.TestCase):
    """The Debug room + the agent's debug_* tools: ONE session on
    the ForgeWindow, driven from both surfaces. The window lists
    the project's Python files and starts the session the tools
    then stand in; starting refuses while a Run is live."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        if cls.win.debug_session_live():
            cls.win.debug_stop_session()
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        (self.root / "app.py").write_text(DEBUG_FIXTURE)
        if self.win.debug_session_live():
            self.win.debug_stop_session()
        self.win._run_thread = None
        self.win.workspace = str(self.root)
        self.win.debug_win.refresh()
        self.win.debug_win.debug_output.clear()
        self.win.debug_win.debug_bp_edit.clear()

    def tearDown(self):
        if self.win.debug_session_live():
            self.win.debug_stop_session()
        self.win.debug_win.close()
        self.temp.cleanup()

    def _pump_until(self, predicate, timeout_s=15):
        """Wait for the debug window's control thread, pumping the
        event loop so its queued done signal lands."""
        import time
        deadline = time.monotonic() + timeout_s
        while time.monotonic() < deadline:
            self.app.processEvents()
            if predicate():
                return True
            time.sleep(0.02)
        return predicate()

    def test_window_lists_python_files(self):
        win = self.win.debug_win
        labels = [win.debug_file_list.item(i).text()
                  for i in range(win.debug_file_list.count())]
        self.assertIn("app.py", labels)

    def test_window_starts_steps_and_inspects_the_session(self):
        win = self.win.debug_win
        win.debug_bp_edit.setPlainText("7")
        win._start_debug()
        self.assertTrue(self._pump_until(
            lambda: win.debug_status.text() == "stopped"))
        self.assertTrue(self.win.debug_session_live())
        self.assertIn("app.py:1", win.debug_location.text())
        win._drive("continue")
        self.assertTrue(self._pump_until(
            lambda: "app.py:7" in win.debug_location.text()))
        win.debug_inspect_edit.setText("x")
        win._inspect()
        self.assertTrue(self._pump_until(
            lambda: ">>> x" in win.debug_output.toPlainText()))
        self.assertIn("21", win.debug_output.toPlainText())
        win.close()
        self.assertFalse(self.win.debug_session_live())

    def test_tools_registered_with_the_right_gates(self):
        extra = self.win._extra_tools()
        for name in ("debug_start", "debug_step", "debug_continue",
                     "debug_inspect", "debug_stop"):
            self.assertIn(name, extra)
            self.assertEqual(extra[name][3], "debugger")
        # Starting/stepping/continuing execute code: gated.
        for name in ("debug_start", "debug_step", "debug_continue"):
            self.assertTrue(extra[name][2], name)
        # Inspecting and stopping change nothing: read-class.
        for name in ("debug_inspect", "debug_stop"):
            self.assertFalse(extra[name][2], name)

    def test_agent_tools_drive_the_same_session(self):
        text = self.win._debug_tool_start(
            {"path": "app.py", "breakpoints": "7"}, str(self.root))
        self.assertIn("Stopped at", text)
        self.assertIn("app.py:7", text)
        self.assertIn("main()", text)
        self.assertTrue(self.win.debug_session_live())
        self.assertEqual(
            self.win._debug_tool_inspect({"expression": "x"}), "21")
        self.assertIn("'x': '21'", self.win._debug_tool_inspect({}))
        text = self.win._debug_tool_step({})
        self.assertIn("app.py:8", text)
        text = self.win._debug_tool_stop({})
        self.assertIn("stopped", text)
        self.assertFalse(self.win.debug_session_live())
        self.assertIn("No debug session",
                      self.win._debug_tool_inspect({"expression": "x"}))

    def test_debug_start_refuses_while_a_run_is_live(self):
        class _FakeRunThread:
            def isRunning(self):
                return True

        self.win._run_thread = _FakeRunThread()
        try:
            text = self.win._debug_tool_start(
                {"path": "app.py", "breakpoints": "7"}, str(self.root))
        finally:
            self.win._run_thread = None
        self.assertIn("run is live", text)
        self.assertFalse(self.win.debug_session_live())


class MonitorClassifierTests(unittest.TestCase):
    """C1: the Watch seat's line classifier (forge/monitor.py) —
    pure detection, no Qt, no run needed. Kinds: crash (traceback
    or a hard error line), http (an HTTP 4xx/5xx status). Clean
    output earns no alert."""

    def test_traceback_line_is_a_crash_alert_with_evidence(self):
        from forge import monitor
        hit = monitor.classify_line("Traceback (most recent call last):")
        self.assertIsNotNone(hit)
        self.assertEqual(hit[0], "crash")

    def test_error_class_line_is_a_crash(self):
        from forge import monitor
        self.assertEqual(monitor.classify_line(
            "ValueError: bad literal for int()")[0], "crash")
        self.assertEqual(monitor.classify_line(
            "  File \"app.py\", line 3\nRuntimeError: boom")[0], "crash")

    def test_http_500_line_is_an_http_alert(self):
        from forge import monitor
        hit = monitor.classify_line(
            '127.0.0.1 - - [09/Nov/2026 10:00:00] "GET /api HTTP/1.1" 500 -')
        self.assertEqual(hit, ("http", "HTTP 500"))

    def test_http_404_and_status_forms(self):
        from forge import monitor
        self.assertEqual(monitor.classify_line(
            '"POST /submit HTTP/1.1" 404')[0], "http")
        self.assertEqual(monitor.classify_line(
            "request failed status=503")[1], "HTTP 503")

    def test_clean_output_raises_nothing(self):
        from forge import monitor
        for line in ("Server listening on port 8080",
                     "GET /index HTTP/1.1 200 OK",
                     "compiled 42 modules in 300 ms",
                     "user 404 logged in",  # a bare number is not a status
                     "", "   "):
            self.assertIsNone(monitor.classify_line(line), line)


class MonitorRunSessionTests(unittest.TestCase):
    """C1: RunMonitor's stateful detection — repeated identical
    errors cross a threshold once and then count in place; a silent
    live run stalls; an unexplained non-zero exit is a crash; a
    clean or stopped run is not."""

    def _monitor(self):
        from forge import monitor
        clock = {"t": 1000.0}
        mon = monitor.RunMonitor(now=lambda: clock["t"])
        return mon, clock

    def test_repeated_error_threshold(self):
        from forge import monitor
        mon, _clock = self._monitor()
        mon.begin("python app.py")
        self.assertIsNone(mon.observe_line("connection failed for peer 12"))
        self.assertIsNone(mon.observe_line("connection failed for peer 99"))
        alert = mon.observe_line("connection failed for peer 7")
        self.assertIsNotNone(alert)
        self.assertEqual(alert["kind"], "repeat")
        self.assertEqual(alert["count"], monitor.REPEAT_THRESHOLD)
        # The evidence is the RAW line that crossed the line.
        self.assertEqual(alert["evidence"], "connection failed for peer 7")
        # A fourth identical failure bumps the same alert, no stack.
        again = mon.observe_line("connection failed for peer 3")
        self.assertIs(again, alert)
        self.assertEqual(alert["count"], 4)
        self.assertEqual(len(mon.alerts), 1)

    def test_distinct_errors_do_not_pool(self):
        mon, _clock = self._monitor()
        mon.begin("python app.py")
        for line in ("timeout error on socket a", "disk failure on volume b",
                     "auth error for user c"):
            self.assertIsNone(mon.observe_line(line))
        self.assertEqual(mon.alerts, [])

    def test_stall_alert_once_per_silent_stretch(self):
        from forge import monitor
        mon, clock = self._monitor()
        mon.begin("python server.py")
        mon.observe_line("booted")
        clock["t"] += monitor.STALL_SECONDS + 5
        alert = mon.check_stall()
        self.assertIsNotNone(alert)
        self.assertEqual(alert["kind"], "stall")
        self.assertIsNone(mon.check_stall())  # not twice for one stretch
        mon.observe_line("a request arrived")  # fresh output re-arms
        clock["t"] += monitor.STALL_SECONDS + 5
        self.assertIsNotNone(mon.check_stall())

    def test_no_stall_after_the_run_ends(self):
        from forge import monitor
        mon, clock = self._monitor()
        mon.begin("python app.py")
        mon.observe_finish(0, False)
        clock["t"] += monitor.STALL_SECONDS * 3
        self.assertIsNone(mon.check_stall())

    def test_unexplained_nonzero_exit_is_a_crash_alert(self):
        mon, _clock = self._monitor()
        mon.begin("python app.py")
        mon.observe_line("starting up")
        alert = mon.observe_finish(2, False)
        self.assertIsNotNone(alert)
        self.assertEqual(alert["kind"], "crash")
        self.assertIn("exited 2", alert["detail"])

    def test_explained_exit_and_clean_and_stopped_raise_nothing(self):
        mon, _clock = self._monitor()
        mon.begin("python app.py")
        mon.observe_line("Traceback (most recent call last):")
        self.assertIsNone(mon.observe_finish(1, False))  # already told
        mon2, _ = self._monitor()
        mon2.begin("python app.py")
        self.assertIsNone(mon2.observe_finish(0, False))
        mon3, _ = self._monitor()
        mon3.begin("python app.py")
        self.assertIsNone(mon3.observe_finish(1, True))  # owner's Stop


class MonitorSeatResolutionTests(unittest.TestCase):
    """C1: the Watch seat resolves through forge/seats.py's own
    guard — seats.py is NOT extended; the seat name, the plain
    `watch_model` setting and the raw-file reader live in
    forge/monitor.py (the council.py parity discipline)."""

    def test_seats_module_is_not_extended(self):
        from forge import seats
        self.assertEqual(seats.SEATS, ("driver", "tester", "reviewer"))

    def test_blank_setting_gets_the_roster_default(self):
        from forge import monitor
        model, refused = monitor.resolve_watch_model("", None)
        self.assertEqual(model, monitor.DEFAULT_WATCH_MODEL)
        self.assertIsNone(refused)

    def test_roster_model_may_hold_the_seat(self):
        from forge import monitor
        model, refused = monitor.resolve_watch_model(
            "eriktonon/bonsai-2-uncensored:2b", None)
        self.assertEqual(model, "eriktonon/bonsai-2-uncensored:2b")
        self.assertIsNone(refused)

    def test_stock_model_is_refused_to_the_default(self):
        from forge import monitor
        model, refused = monitor.resolve_watch_model("bonsai-2:4b", None)
        self.assertEqual(model, monitor.DEFAULT_WATCH_MODEL)
        self.assertEqual(refused, "bonsai-2:4b")

    def test_file_entry_wins_and_is_guarded_identically(self):
        from forge import monitor
        raw = {"seats": {"watch": {"model": "maternion/minicpm5-heretic:2b"}}}
        model, refused = monitor.resolve_watch_model(
            "eriktonon/bonsai-2-uncensored:2b", raw)
        self.assertEqual(model, "maternion/minicpm5-heretic:2b")
        self.assertIsNone(refused)
        bad = {"seats": {"watch": {"model": "llama3.2:latest"}}}
        model, refused = monitor.resolve_watch_model("", bad)
        self.assertEqual(model, monitor.DEFAULT_WATCH_MODEL)
        self.assertEqual(refused, "llama3.2:latest")

    def test_malformed_file_shapes_earn_no_entry(self):
        from forge import monitor
        for raw in (None, {}, {"seats": []}, {"seats": {"watch": "x"}},
                    {"seats": {"watch": {"model": "  "}}}):
            self.assertEqual(monitor.monitor_seat_config(raw), {}, raw)


class _MonitorFixClient:
    """One scripted generation for the Watch seat: a well-formed
    FIX-FILE reply (or whatever the test hands it)."""

    def __init__(self, reply):
        self.reply = reply
        self.calls = 0

    def chat_stream(self, model, messages, options, schemas, keep_alive=None):
        self.calls += 1
        yield {"message": {"content": self.reply, "tool_calls": []}}


class MonitorProposalTests(unittest.TestCase):
    """C1: a fix proposal is owner-triggered, parsed strictly,
    diffed, and presented through the EXISTING approval gate
    (request_approval with a write_file diff, the recording-dialog
    fixture standing at the gate). Denial writes nothing; approval
    applies through the same execute_tool the worker uses."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        import forge.main as main_mod
        self._main = main_mod
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        self.win.store = ConversationStore(self.root / "c.db")
        self.win.eventlog = EventLog(self.root / "log")
        self._old_workspace = self.win.workspace
        self.win.workspace = str(self.root)
        self.win.worker = None
        self.win._monitor_thread = None
        self.win._run_monitor.begin("python app.py")
        (self.root / "app.py").write_text("x = 1\nraise ValueError('boom')\n")
        _RecordingApprovalDialog.instances = []
        _RecordingApprovalDialog.answer = False
        self._real_dialog = main_mod.ApprovalDialog
        main_mod.ApprovalDialog = _RecordingApprovalDialog

    def tearDown(self):
        self._main.ApprovalDialog = self._real_dialog
        if self.win._monitor_thread is not None:
            self.win._monitor_thread.wait(3000)
            self.win._monitor_thread = None
        self.win.workspace = self._old_workspace
        self.win.worker = None
        self.temp.cleanup()

    def _alert(self):
        return self.win._run_monitor.observe_line(
            "Traceback (most recent call last):")

    def _reply(self):
        return ("FIX-FILE: app.py\n```\nx = 1\n"
                "print('fixed instead of raising')\n```\n")

    def test_parse_fix_reply_is_strict(self):
        from forge import monitor
        listing = ["app.py", "util.py"]
        self.assertEqual(
            monitor.parse_fix_reply(self._reply(), listing),
            ("app.py", "x = 1\nprint('fixed instead of raising')\n"))
        self.assertIsNone(monitor.parse_fix_reply("NONE", listing))
        self.assertIsNone(monitor.parse_fix_reply(
            "FIX-FILE: other.py\n```\nx = 2\n```\n", listing))
        self.assertIsNone(monitor.parse_fix_reply(
            "I think you should change x to 2.", listing))
        self.assertIsNone(monitor.parse_fix_reply("", listing))

    def test_denied_proposal_writes_nothing(self):
        before = (self.root / "app.py").read_bytes()
        alert = self._alert()
        _RecordingApprovalDialog.answer = False
        self.win._on_monitor_fix_ready(self._reply(), alert,
                                       ["app.py"])
        # The proposal DID reach the gate, wearing a real diff…
        self.assertEqual(len(_RecordingApprovalDialog.instances), 1)
        fake = _RecordingApprovalDialog.instances[0]
        self.assertEqual(fake.tool_name, "write_file")
        self.assertIsNotNone(fake.diff)
        self.assertEqual(fake.diff.path, "app.py")
        self.assertEqual(fake.model, self.win._watch_seat_model())
        self.assertEqual(fake.seen_pending["tool"], "write_file")
        # …and the denial left the file byte-identical.
        self.assertEqual((self.root / "app.py").read_bytes(), before)
        self.assertIsNone(self.win.worker)  # stage worker restored

    def test_approved_proposal_applies_through_execute_tool(self):
        before = (self.root / "app.py").read_bytes()
        alert = self._alert()
        _RecordingApprovalDialog.answer = True
        self.win._on_monitor_fix_ready(self._reply(), alert, ["app.py"])
        after = (self.root / "app.py").read_bytes()
        self.assertNotEqual(after, before)
        self.assertEqual(after.decode(),
                         "x = 1\nprint('fixed instead of raising')\n")
        self.assertIsNone(self.win.worker)

    def test_unparseable_reply_never_reaches_the_gate(self):
        before = (self.root / "app.py").read_bytes()
        alert = self._alert()
        _RecordingApprovalDialog.answer = True
        self.win._on_monitor_fix_ready(
            "the bug is probably on line 2, good luck", alert, ["app.py"])
        self.assertEqual(_RecordingApprovalDialog.instances, [])
        self.assertEqual((self.root / "app.py").read_bytes(), before)

    def test_button_path_generates_then_gates(self):
        import time
        alert = self._alert()
        self.win.client = _MonitorFixClient(self._reply())
        self.win.run_win.refresh_watch()
        self.win.run_win.watch_alerts_list.setCurrentRow(0)
        _RecordingApprovalDialog.answer = True
        self.win.run_win._propose_selected()
        deadline = time.monotonic() + 8
        while time.monotonic() < deadline:
            self.app.processEvents()
            if _RecordingApprovalDialog.instances:
                break
            time.sleep(0.02)
        self.app.processEvents()
        self.assertEqual(len(_RecordingApprovalDialog.instances), 1)
        self.assertEqual((self.root / "app.py").read_text(),
                         "x = 1\nprint('fixed instead of raising')\n")


class MonitorDeckAndRunSurfaceTests(unittest.TestCase):
    """C1: alerts raised from real run output land in the deck
    state and on the Run window's WATCH list — the integration
    seams, exercised through the actual Run machinery."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        if cls.win.run_is_running():
            cls.win.stop_run()
            cls.win._run_thread.wait(3000)
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        if self.win.run_is_running():
            self.win.stop_run()
            self.win._run_thread.wait(3000)
        # The window's event log is a temp-dir log for this class,
        # so the monitor_alert records are assertable (and the
        # run's records never touch the real APP_DIR log).
        self.win.eventlog = EventLog(self.root / "log")
        self.win.run_win.clear_blocks()
        (self.root / "marker.py").write_text("print('marker')\n")
        self.win.workspace = str(self.root)
        self.win.run_win.refresh()
        self.win.run_status.setText("idle")
        self.win._set_run_controls(False)
        self.win._run_monitor.begin("")
        self.win.deck.set_state(monitor={"alerts": [], "watching": False})

    def tearDown(self):
        if self.win.run_is_running():
            self.win.stop_run()
            self.win._run_thread.wait(3000)
        self.win.run_win.close()
        self.temp.cleanup()

    def _pump_until(self, predicate, timeout=8.0):
        import time
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            self.app.processEvents()
            if predicate():
                return True
            time.sleep(0.02)
        self.app.processEvents()
        return predicate()

    def test_crashing_run_alert_reaches_deck_and_run_window(self):
        script = ("import sys; print('booting'); "
                  "print('Traceback (most recent call last):', file=sys.stderr); "
                  "print('ValueError: boom', file=sys.stderr); sys.exit(3)")
        self.win.start_run(f'python3 -c "{script}"', str(self.root))
        landed = self._pump_until(
            lambda: bool(self.win.deck.snapshot()
                         .get("monitor", {}).get("alerts")))
        self.assertTrue(landed, "no monitor alert reached the deck state")
        state = self.win.deck.snapshot()["monitor"]
        kinds = [a["kind"] for a in state["alerts"]]
        self.assertIn("crash", kinds)
        crash = next(a for a in state["alerts"] if a["kind"] == "crash")
        self.assertIn("Traceback", crash["evidence"])
        self.assertFalse(state["watching"])  # the run has ended
        self.assertGreaterEqual(self.win.run_win.watch_alerts_list.count(), 1)
        labels = [self.win.run_win.watch_alerts_list.item(i).text()
                  for i in range(self.win.run_win.watch_alerts_list.count())]
        self.assertTrue(any("crash" in label for label in labels), labels)
        event_kinds = [kind for kind, _fields in
                       _read_eventlog(self.win.eventlog)]
        self.assertIn("monitor_alert", event_kinds)

    def test_clean_run_raises_no_alerts(self):
        self.win.start_run("python3 -c \"print('all good')\"",
                           str(self.root))
        done = self._pump_until(lambda: not self.win.run_is_running())
        self.assertTrue(done)
        self.app.processEvents()
        state = self.win.deck.snapshot()["monitor"]
        self.assertEqual(state["alerts"], [])
        self.assertEqual(self.win.run_win.watch_alerts_list.count(), 0)


def _read_eventlog(eventlog):
    """The (kind, fields) pairs an EventLog has recorded — read
    from its JSONL file, the same surface session_summary reads."""
    import json as _json
    out = []
    try:
        for line in eventlog.path.read_text(encoding="utf-8").splitlines():
            if line.strip():
                record = _json.loads(line)
                out.append((record.get("kind", ""), record))
    except OSError:
        pass
    return out
class ProductionMarkingLoadTests(unittest.TestCase):
    """Item C2, the loading half: .forge/production.json parses
    into normalized markings. A missing file is the unmarked
    project; a broken file is an ERROR state, never an empty one —
    a fence that failed open on a typo would silently unprotect
    the data it exists to protect."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        (self.root / ".forge").mkdir()

    def tearDown(self):
        self.temp.cleanup()

    def _mark(self, text):
        (self.root / ".forge" / "production.json").write_text(text)
        from forge import production as prod_mod
        return prod_mod.load_markings(str(self.root))

    def test_missing_file_is_the_unmarked_project(self):
        from forge import production as prod_mod
        markings = prod_mod.load_markings(str(self.root))
        self.assertFalse(markings.present)
        self.assertFalse(markings.active)
        self.assertIsNone(markings.error)

    def test_valid_file_normalizes_entries(self):
        markings = self._mark(json.dumps({
            "paths": ["./data/prod/", "data\\backups", "a/../keep"],
            "files": ["db/live.sqlite3"]}))
        self.assertTrue(markings.present)
        self.assertIsNone(markings.error)
        self.assertEqual(markings.paths,
                         ("data/prod", "data/backups", "keep"))
        self.assertEqual(markings.files, ("db/live.sqlite3",))

    def test_malformed_json_is_broken_not_empty(self):
        markings = self._mark("{not json")
        self.assertTrue(markings.present)
        self.assertIsNotNone(markings.error)
        self.assertFalse(markings.active)

    def test_non_object_is_broken(self):
        markings = self._mark('["data/prod"]')
        self.assertIsNotNone(markings.error)

    def test_non_list_key_is_broken(self):
        markings = self._mark('{"paths": "data/prod"}')
        self.assertIsNotNone(markings.error)

    def test_escaping_entries_are_broken(self):
        for text in ('{"paths": ["../outside"]}',
                     '{"paths": ["/etc"]}',
                     '{"files": ["../secret.txt"]}'):
            markings = self._mark(text)
            self.assertIsNotNone(markings.error, msg=text)

    def test_dot_marks_the_whole_project(self):
        from forge import production as prod_mod
        markings = self._mark('{"paths": ["."]}')
        self.assertEqual(markings.paths, ("",))
        self.assertEqual(
            prod_mod.covering_entry(markings, str(self.root),
                                    "anything/at/all.txt"), ".")

    def test_covering_rules_prefix_vs_exact(self):
        from forge import production as prod_mod
        markings = self._mark(json.dumps({
            "paths": ["data/prod"], "files": ["db/live.sqlite3"]}))
        root = str(self.root)
        self.assertEqual(prod_mod.covering_entry(
            markings, root, "data/prod"), "data/prod")
        self.assertEqual(prod_mod.covering_entry(
            markings, root, "data/prod/deep/x.db"), "data/prod")
        # A prefix is a path boundary, not a string prefix.
        self.assertIsNone(prod_mod.covering_entry(
            markings, root, "data/prod2/x.db"))
        self.assertEqual(prod_mod.covering_entry(
            markings, root, "db/live.sqlite3"), "db/live.sqlite3")
        self.assertIsNone(prod_mod.covering_entry(
            markings, root, "db/live.sqlite3.bak"))


class ProductionPathFenceTests(unittest.TestCase):
    """Item C2 at execute_tool: marked writes are refused
    OUTRIGHT (ToolError before anything touches disk), reads are
    untouched, and without the production argument the tool layer
    behaves byte-for-byte as before."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        (self.root / "data" / "prod").mkdir(parents=True)
        (self.root / "data" / "prod" / "db.txt").write_text("live")
        (self.root / "db").mkdir()
        (self.root / ".forge").mkdir()
        (self.root / ".forge" / "production.json").write_text(json.dumps(
            {"paths": ["data/prod"], "files": ["db/live.sqlite3"]}))
        from forge import production as prod_mod
        self.prod_mod = prod_mod
        self.markings = prod_mod.load_markings(str(self.root))

    def tearDown(self):
        self.temp.cleanup()

    def _exec(self, name, args, **kw):
        return execute_tool(name, args, str(self.root), **kw)

    def test_write_to_marked_path_refused_file_untouched(self):
        with self.assertRaises(ToolError) as ctx:
            self._exec("write_file",
                       {"path": "data/prod/db.txt", "content": "wiped"},
                       production=self.markings)
        text = str(ctx.exception)
        self.assertIn("data/prod/db.txt", text)
        self.assertIn(".forge/production.json", text)
        self.assertIn("production", text)
        self.assertEqual(
            (self.root / "data" / "prod" / "db.txt").read_text(), "live")

    def test_new_file_under_marked_prefix_refused(self):
        with self.assertRaises(ToolError):
            self._exec("write_file",
                       {"path": "data/prod/new.txt", "content": "x"},
                       production=self.markings)
        self.assertFalse((self.root / "data" / "prod" / "new.txt").exists())

    def test_append_to_marked_refused(self):
        with self.assertRaises(ToolError):
            self._exec("append_file",
                       {"path": "data/prod/db.txt", "content": "more"},
                       production=self.markings)
        self.assertEqual(
            (self.root / "data" / "prod" / "db.txt").read_text(), "live")

    def test_named_file_refused_sibling_allowed(self):
        with self.assertRaises(ToolError):
            self._exec("write_file",
                       {"path": "db/live.sqlite3", "content": "x"},
                       production=self.markings)
        result = self._exec("write_file",
                            {"path": "db/dev.sqlite3", "content": "x"},
                            production=self.markings)
        self.assertIn("Wrote db/dev.sqlite3", result)

    def test_dotdot_into_marked_refused(self):
        (self.root / "src").mkdir()
        with self.assertRaises(ToolError):
            self._exec("write_file",
                       {"path": "src/../data/prod/db.txt",
                        "content": "wiped"},
                       production=self.markings)
        self.assertEqual(
            (self.root / "data" / "prod" / "db.txt").read_text(), "live")

    def test_reads_of_marked_data_allowed(self):
        self.assertEqual(
            self._exec("read_file", {"path": "data/prod/db.txt"},
                       production=self.markings), "live")
        listing = self._exec("list_directory", {"path": "data/prod"},
                             production=self.markings)
        self.assertIn("db.txt", listing)

    def test_unmarked_paths_write_normally(self):
        result = self._exec("write_file",
                            {"path": "src/x.txt", "content": "fine"},
                            production=self.markings)
        self.assertIn("Wrote src/x.txt", result)

    def test_no_production_argument_is_the_old_behavior(self):
        # The control: without the markings argument (every
        # unmarked project, every pre-C2 caller) the same write to
        # the same path succeeds — the fence exists only when the
        # worker passes markings in.
        result = self._exec("write_file",
                            {"path": "data/prod/db.txt",
                             "content": "changed"})
        self.assertIn("Wrote data/prod/db.txt", result)

    def test_absent_markings_object_is_inert(self):
        empty_root = Path(self.temp.name) / "elsewhere"
        empty_root.mkdir()
        markings = self.prod_mod.load_markings(str(empty_root))
        self.assertFalse(markings.present)
        self.assertIsNone(self.prod_mod.path_refusal(
            markings, str(self.root), "data/prod/db.txt"))
        self.assertIsNone(self.prod_mod.command_refusal(
            markings, str(self.root), "rm data/prod/db.txt"))

    def test_broken_marking_refuses_all_writes_but_not_reads(self):
        (self.root / ".forge" / "production.json").write_text("{broken")
        markings = self.prod_mod.load_markings(str(self.root))
        self.assertIsNotNone(markings.error)
        with self.assertRaises(ToolError) as ctx:
            self._exec("write_file",
                       {"path": "src/anywhere.txt", "content": "x"},
                       production=markings)
        self.assertIn(".forge/production.json", str(ctx.exception))
        self.assertIn("broken", str(ctx.exception))
        self.assertEqual(
            self._exec("read_file", {"path": "data/prod/db.txt"},
                       production=markings), "live")


class ProductionCommandFenceTests(unittest.TestCase):
    """Item C2, run_command: the posture scan over command TEXT.
    Writing postures to a marked path refuse; read-only references
    pass; and the documented limit — a path built indirectly is
    outside the fence — is pinned as a test, not just prose."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        (self.root / "data" / "prod").mkdir(parents=True)
        (self.root / "data" / "prod" / "db.txt").write_text("live")
        (self.root / "db").mkdir()
        (self.root / ".forge").mkdir()
        (self.root / ".forge" / "production.json").write_text(json.dumps(
            {"paths": ["data/prod"], "files": ["db/live.sqlite3"]}))
        from forge import production as prod_mod
        self.prod_mod = prod_mod
        self.markings = prod_mod.load_markings(str(self.root))

    def tearDown(self):
        self.temp.cleanup()

    def _refusal(self, command):
        return self.prod_mod.command_refusal(
            self.markings, str(self.root), command)

    def test_writing_postures_refused(self):
        refused = [
            "echo x > data/prod/db.txt",
            "echo x >> data/prod/log.txt",
            "echo x >data/prod/db.txt",
            "echo x 2> data/prod/err.txt",
            "rm data/prod/db.txt",
            "rm -rf data",
            "mv data/prod/db.txt data/prod/db2.txt",
            "mv tmp.txt data/prod/db.txt",
            "cp tmp.txt data/prod/db.txt",
            "cat tmp.txt | tee data/prod/db.txt",
            "sed -i 's/a/b/' data/prod/db.txt",
            "sed --in-place 's/a/b/' db/live.sqlite3",
            "dd if=/dev/zero of=data/prod/db.txt bs=1 count=1",
            "touch data/prod/new.txt",
            "mkdir data/prod/newdir",
            "find data -delete",
            "find data/prod -delete",
            "python3 -c \"open('data/prod/db.txt','w').write('x')\"",
            "python3 -c \"open('db/live.sqlite3', 'a')\"",
            "python3 -c \"import os; os.remove('data/prod/db.txt')\"",
            "python3 -c \"from pathlib import Path; "
            "Path('db/live.sqlite3').write_text('x')\"",
            "python3 -c \"import shutil; "
            "shutil.copy('tmp.txt', 'data/prod/db.txt')\"",
            "grep x data/prod/db.txt > data/prod/out.txt",
            "cat data/prod/db.txt > db/live.sqlite3",
        ]
        for command in refused:
            refusal = self._refusal(command)
            self.assertIsNotNone(refusal, msg=command)
            self.assertIn(".forge/production.json", refusal, msg=command)
            self.assertIn("production", refusal, msg=command)

    def test_read_postures_allowed(self):
        allowed = [
            "cat data/prod/db.txt",
            "ls -la data/prod",
            "cp data/prod/db.txt tmp/copy.txt",
            "grep prod data/prod/db.txt",
            "sed 's/a/b/' data/prod/db.txt",
            "echo data/prod/db.txt",
            "stat db/live.sqlite3",
            "echo x > tmp/out.txt",
            "rm tmp/scratch.txt",
            "python3 -c \"print(open('data/prod/db.txt').read())\"",
            "python3 -c \"print(open('data/prod/db.txt', 'r').read())\"",
            "python3 -c \"import shutil; "
            "shutil.copy('data/prod/db.txt', 'tmp/copy.txt')\"",
        ]
        for command in allowed:
            self.assertIsNone(self._refusal(command), msg=command)

    def test_indirect_path_is_outside_the_fence_by_design(self):
        # The honest limit, pinned: the fence reads the command
        # TEXT. A path assembled through a variable is not an
        # identifiable reference in that text, so the fence does
        # not fire — the approval gate is the backstop there, and
        # the module docstring + README say exactly this.
        self.assertIsNone(self._refusal("P=data/prod; rm $P/db.txt"))
        self.assertIsNone(self._refusal("rm $(cat target.txt)"))

    def test_execute_tool_refuses_redirect_end_to_end(self):
        with self.assertRaises(ToolError) as ctx:
            execute_tool("run_command",
                         {"command": "echo wiped > data/prod/db.txt"},
                         str(self.root), production=self.markings)
        self.assertIn("production", str(ctx.exception))
        self.assertEqual(
            (self.root / "data" / "prod" / "db.txt").read_text(), "live")

    def test_execute_tool_runs_read_command(self):
        result = execute_tool("run_command",
                              {"command": "cat data/prod/db.txt"},
                              str(self.root), production=self.markings)
        self.assertIn("Exit code: 0", result)
        self.assertIn("live", result)


class ProductionDispatchTests(unittest.TestCase):
    """Item C2 at the worker seam: _dispatch threads the markings
    into execute_tool only when the project has a marking file —
    unmarked projects take the dispatch path byte-for-byte as
    before — and approval-gated plugin tools get the fence on
    their path arguments while read-class plugin tools do not."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        (self.root / "data" / "prod").mkdir(parents=True)
        (self.root / "data" / "prod" / "db.txt").write_text("live")
        (self.root / ".forge").mkdir()

    def tearDown(self):
        self.temp.cleanup()

    def _worker(self, extra_tools=None):
        from forge.worker import AgentWorker
        return AgentWorker(object(), "fake",
                           [{"role": "user", "content": "go"}], {},
                           str(self.root), extra_tools=extra_tools or {})

    def _mark(self):
        (self.root / ".forge" / "production.json").write_text(json.dumps(
            {"paths": ["data/prod"]}))

    def test_dispatch_refuses_marked_write(self):
        self._mark()
        worker = self._worker()
        with self.assertRaises(ToolError) as ctx:
            worker._dispatch("write_file",
                             {"path": "data/prod/db.txt",
                              "content": "wiped"})
        self.assertIn("production", str(ctx.exception))
        self.assertEqual(
            (self.root / "data" / "prod" / "db.txt").read_text(), "live")

    def test_dispatch_unmarked_project_writes_as_before(self):
        worker = self._worker()
        result = worker._dispatch("write_file",
                                  {"path": "data/prod/db.txt",
                                   "content": "changed"})
        self.assertIn("Wrote data/prod/db.txt", result)

    def test_dispatch_read_of_marked_data_flows(self):
        self._mark()
        worker = self._worker()
        self.assertEqual(
            worker._dispatch("read_file", {"path": "data/prod/db.txt"}),
            "live")

    def test_gated_plugin_tool_refused_on_marked_path(self):
        self._mark()
        calls = []

        def handler(args):
            calls.append(args)
            return "handler ran"

        schema = {"type": "function",
                  "function": {"name": "fake_write", "parameters": {}}}
        worker = self._worker(extra_tools={
            "fake_write": (schema, handler, True, "test")})
        result = worker._dispatch("fake_write",
                                  {"path": "data/prod/db.txt"})
        self.assertIn("production", result)
        self.assertIn(".forge/production.json", result)
        self.assertEqual(calls, [])

    def test_read_class_plugin_tool_not_fenced(self):
        self._mark()

        def handler(args):
            return "read the thing"

        schema = {"type": "function",
                  "function": {"name": "fake_read", "parameters": {}}}
        worker = self._worker(extra_tools={
            "fake_read": (schema, handler, False, "test")})
        self.assertEqual(
            worker._dispatch("fake_read", {"path": "data/prod/db.txt"}),
            "read the thing")


class ProductionSurfacingTests(unittest.TestCase):
    """Item C2, the agent-facing half: context_text names the
    boundary, and build_system_prompt carries it into the turn —
    the model knows the data is production before it reaches
    for it (the HintsPromptTests pattern: one shared window,
    the workspace swapped per test)."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        proj.ensure_project(self.root)
        self._old_workspace = self.win.workspace
        self.win.workspace = str(self.root)

    def tearDown(self):
        self.win.workspace = self._old_workspace
        self.temp.cleanup()

    def _mark(self, text):
        (self.root / ".forge" / "production.json").write_text(text)

    def test_context_text_names_boundary_and_file(self):
        from forge import production as prod_mod
        self._mark(json.dumps({"paths": ["data/prod"],
                               "files": ["db/live.sqlite3"]}))
        text = prod_mod.context_text(prod_mod.load_markings(str(self.root)))
        self.assertIn("READ-ONLY", text)
        self.assertIn("data/prod", text)
        self.assertIn("db/live.sqlite3", text)
        self.assertIn(".forge/production.json", text)

    def test_prompt_carries_the_boundary_when_marked(self):
        self._mark(json.dumps({"paths": ["data/prod"]}))
        prompt = self.win.build_system_prompt()
        self.assertIn("Production data — READ-ONLY", prompt)
        self.assertIn("data/prod", prompt)

    def test_prompt_has_no_production_block_when_unmarked(self):
        prompt = self.win.build_system_prompt()
        self.assertNotIn("Production data", prompt)

    def test_prompt_warns_when_marking_file_broken(self):
        self._mark("{broken")
        prompt = self.win.build_system_prompt()
        self.assertIn("Production data", prompt)
        self.assertIn("BROKEN", prompt)


class ProductionWriteResearchKitTests(unittest.TestCase):
    """Item C2 at the assembly merge (NOT part of the C2 build's
    own suite): the C2 copy predates the Write/Research merge, so
    its execute_tool fence named only write_file / append_file /
    run_command. The tree's kit also carries edit_file,
    delete_file, copy_file and move_file through the same
    execute_tool choke point, and the merge judges them by the
    same rules the command fence uses for cp vs mv: a copy reads
    its source and writes only its destination; a move deletes
    its source and writes its destination, so both ends refuse."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        (self.root / "data" / "prod").mkdir(parents=True)
        (self.root / "data" / "prod" / "db.txt").write_text("live")
        (self.root / "src").mkdir()
        (self.root / "src" / "tmp.txt").write_text("scratch")
        (self.root / ".forge").mkdir()
        (self.root / ".forge" / "production.json").write_text(json.dumps(
            {"paths": ["data/prod"]}))
        from forge import production as prod_mod
        self.markings = prod_mod.load_markings(str(self.root))

    def tearDown(self):
        self.temp.cleanup()

    def _exec(self, name, args):
        return execute_tool(name, args, str(self.root),
                            production=self.markings)

    def test_edit_of_marked_file_refused(self):
        with self.assertRaises(ToolError):
            self._exec("edit_file",
                       {"path": "data/prod/db.txt",
                        "find": "live", "replace": "wiped"})
        self.assertEqual(
            (self.root / "data" / "prod" / "db.txt").read_text(), "live")

    def test_delete_of_marked_file_refused(self):
        with self.assertRaises(ToolError):
            self._exec("delete_file", {"path": "data/prod/db.txt"})
        self.assertTrue((self.root / "data" / "prod" / "db.txt").exists())

    def test_copy_from_marked_reads_fine_onto_marked_refused(self):
        result = self._exec("copy_file",
                            {"source": "data/prod/db.txt",
                             "destination": "src/copy.txt"})
        self.assertIn("src/copy.txt", result)
        with self.assertRaises(ToolError):
            self._exec("copy_file",
                       {"source": "src/tmp.txt",
                        "destination": "data/prod/db.txt"})

    def test_move_either_end_marked_refused(self):
        with self.assertRaises(ToolError):
            self._exec("move_file",
                       {"source": "src/tmp.txt",
                        "destination": "data/prod/db.txt"})
        with self.assertRaises(ToolError):
            self._exec("move_file",
                       {"source": "data/prod/db.txt",
                        "destination": "src/stolen.txt"})
        self.assertTrue((self.root / "data" / "prod" / "db.txt").exists())
        self.assertTrue((self.root / "src" / "tmp.txt").exists())

    def test_unmarked_kit_calls_unaffected(self):
        result = self._exec("move_file",
                            {"source": "src/tmp.txt",
                             "destination": "src/moved.txt"})
        self.assertIn("src/moved.txt", result)
