class TestCadenceModuleTests(unittest.TestCase):
    """C3, the pure half: forge/testcadence.py's accumulator and
    rule. The tester seat runs when the changes SINCE IT LAST RAN
    reach the thresholds (or the smaller boundary floors); a pass
    clears the whole tab, a fail leaves it standing."""

    def test_constants_are_the_documented_defaults(self):
        from forge import testcadence as cadence_mod
        self.assertEqual(cadence_mod.FILES_THRESHOLD, 5)
        self.assertEqual(cadence_mod.LINES_THRESHOLD, 300)
        self.assertEqual(cadence_mod.BOUNDARY_FILES_THRESHOLD, 2)
        self.assertEqual(cadence_mod.BOUNDARY_LINES_THRESHOLD, 60)

    def test_accumulator_counts_and_latest_tally_stands(self):
        from forge.testcadence import ChangeAccumulator
        acc = ChangeAccumulator()
        acc.record({"a.py": 10, "b.py": 5})
        acc.record({"c.py": 1})
        self.assertEqual(acc.debt_counts(), (3, 16))
        self.assertEqual(acc.since_run_counts(), (3, 16))
        # A rewritten file's untested content is its NEW content —
        # the latest tally replaces, never sums.
        acc.record({"a.py": 4})
        self.assertEqual(acc.debt_counts(), (3, 10))
        self.assertTrue(acc.has_debt())
        self.assertEqual(acc.since_run_paths(), ["a.py", "b.py", "c.py"])

    def test_due_judges_the_since_run_delta(self):
        from forge.testcadence import ChangeAccumulator
        acc = ChangeAccumulator()
        acc.record({"a.py": 3, "b.py": 3, "c.py": 3, "d.py": 3})
        self.assertFalse(acc.due(5, 300))          # 4 files < 5
        acc.record({"e.py": 1})
        self.assertTrue(acc.due(5, 300))           # 5 files fires
        acc.note_run()
        self.assertFalse(acc.due(5, 300))          # delta reset…
        self.assertEqual(acc.debt_counts(), (5, 13))  # …debt NOT
        acc.record({"f.py": 400})
        self.assertTrue(acc.due(5, 300))           # lines alone fire

    def test_boundary_floors_are_smaller(self):
        from forge.testcadence import ChangeAccumulator
        acc = ChangeAccumulator()
        acc.record({"a.py": 10})
        self.assertFalse(acc.due(5, 300))
        self.assertFalse(acc.due(5, 300, boundary=True))
        acc.record({"b.py": 5})
        self.assertTrue(acc.due(5, 300, boundary=True))   # 2 files
        acc2 = ChangeAccumulator()
        acc2.record({"big.py": 60})
        self.assertFalse(acc2.due(5, 300))
        self.assertTrue(acc2.due(5, 300, boundary=True))  # 60 lines

    def test_note_pass_clears_everything(self):
        from forge.testcadence import ChangeAccumulator
        acc = ChangeAccumulator()
        acc.record({"a.py": 10})
        acc.note_run()
        acc.note_pass()
        self.assertEqual(acc.debt_counts(), (0, 0))
        self.assertEqual(acc.since_run_counts(), (0, 0))
        self.assertFalse(acc.has_debt())

    def test_verdict_of_reads_the_tester_contract(self):
        from forge.testcadence import verdict_of
        self.assertEqual(
            verdict_of("TESTER REPORT (model: x)\nVERDICT: PASS\nok"),
            "pass")
        self.assertEqual(
            verdict_of("TESTER REPORT (model: x)\nVERDICT: FAIL\nboom"),
            "fail")
        self.assertEqual(verdict_of("Tester error: model missing"), "none")
        self.assertEqual(
            verdict_of("TESTER REPORT — INCOMPLETE (model: x): …"), "none")
        self.assertEqual(verdict_of(""), "none")
        self.assertEqual(verdict_of(None), "none")

    def test_palette_carries_test_now(self):
        from forge import palette as palette_mod
        ids = [e["id"] for e in palette_mod.base_catalog()]
        self.assertIn("test_now", ids)


class _CadenceScriptClient:
    """Worker-feed script: plays a fixed list of (tool, args)
    calls one per generation, answers a SKRIBE grading generation
    with a finalize verdict for every file the gate's instruction
    lists, and settles in text otherwise."""

    def __init__(self, script):
        self.script = list(script)
        self.calls = 0

    def chat_stream(self, model, messages, options, schemas,
                    keep_alive=None):
        self.calls += 1
        last_user = next(
            (str(m.get("content", "")) for m in reversed(messages)
             if m.get("role") == "user"), "")
        if "[SHELL — SKRIBE GATE]" in last_user:
            import re
            paths = re.findall(r"^- (.+?) \(", last_user, re.M)
            verdicts = "\n".join(
                f"SKRIBE-VERDICT file={p} fzi=90 decision=finalize"
                for p in paths)
            yield {"message": {"content": verdicts, "tool_calls": []}}
        elif self.script:
            name, args = self.script.pop(0)
            yield {"message": {"content": "", "tool_calls": [
                {"function": {"name": name, "arguments": args}}]}}
        else:
            yield {"message": {"content": "done", "tool_calls": []}}


class TestCadenceWorkerFeedTests(unittest.TestCase):
    """C3, the worker half: executed calls feed the turn's change
    tally beside the SKRIBE queue — writes/appends by their own
    text, command-made files by the A10 snapshot diff — and the
    tally rides turn_changes out at settle."""

    def _worker(self, client, td, log, skribe_writes=False):
        from forge.worker import AgentWorker
        worker = AgentWorker(client, "fake",
                             [{"role": "user", "content": "go"}],
                             {"num_ctx": 100000}, td,
                             eventlog=log, skribe_writes=skribe_writes)
        worker.approval_needed.connect(
            lambda *a: worker.resolve_approval(True))
        return worker

    def _run(self, script, td, skribe_writes=False):
        log = _FakeEventLog()
        client = _CadenceScriptClient(script)
        worker = self._worker(client, td, log,
                              skribe_writes=skribe_writes)
        tallies, finished = [], []
        worker.turn_changes.connect(lambda c: tallies.append(c))
        worker.finished_text.connect(
            lambda text, msgs: finished.append(text))
        worker.run()
        self.assertTrue(finished)
        self.assertEqual(len(tallies), 1)
        return tallies[0]

    def test_writes_and_appends_tally_by_their_text(self):
        with tempfile.TemporaryDirectory() as td:
            tally = self._run([
                ("write_file", {"path": "a.txt",
                                "content": "one\ntwo\nthree\n"}),
                ("append_file", {"path": "a.txt",
                                 "content": "four\nfive\n"}),
                ("write_file", {"path": "b.txt", "content": "only\n"}),
            ], td)
            # a.txt: the write's 3 lines, then the append ADDS 2.
            self.assertEqual(tally, {"a.txt": 5, "b.txt": 1})

    def test_rewrite_replaces_the_paths_tally(self):
        with tempfile.TemporaryDirectory() as td:
            tally = self._run([
                ("write_file", {"path": "a.txt",
                                "content": "1\n2\n3\n4\n5\n6\n"}),
                ("write_file", {"path": "a.txt", "content": "x\n"}),
            ], td)
            self.assertEqual(tally, {"a.txt": 1})

    def test_denied_calls_tally_nothing(self):
        with tempfile.TemporaryDirectory() as td:
            log = _FakeEventLog()
            client = _CadenceScriptClient([
                ("write_file", {"path": "a.txt", "content": "x\n"})])
            worker = self._worker(client, td, log)
            worker.approval_needed.disconnect()
            worker.approval_needed.connect(
                lambda *a: worker.resolve_approval(False))
            tallies = []
            worker.turn_changes.connect(lambda c: tallies.append(c))
            worker.run()
            self.assertEqual(tallies, [{}])

    def test_command_made_files_join_from_the_snapshot_diff(self):
        with tempfile.TemporaryDirectory() as td:
            tally = self._run([
                ("run_command",
                 {"command": "printf 'x\\ny\\n' > made.txt"}),
            ], td, skribe_writes=True)
            self.assertEqual(tally, {"made.txt": 2})

    def test_two_turns_accumulate_in_the_tab(self):
        from forge.testcadence import ChangeAccumulator
        with tempfile.TemporaryDirectory() as td:
            acc = ChangeAccumulator()
            acc.record(self._run([
                ("write_file", {"path": "a.txt",
                                "content": "1\n2\n3\n"}),
                ("write_file", {"path": "b.txt", "content": "1\n"}),
            ], td))
            acc.record(self._run([
                ("write_file", {"path": "a.txt",
                                "content": "1\n2\n3\n4\n"}),
                ("write_file", {"path": "c.txt",
                                "content": "1\n2\n"}),
            ], td))
            # a.txt rewritten (4 stands), b.txt 1, c.txt 2.
            self.assertEqual(acc.debt_counts(), (3, 7))


class TestCadenceWindowTests(unittest.TestCase):
    """C3, the window half: settles feed the workspace's tab via
    _ws_changes; _cadence_evaluate fires the EXISTING run_tester
    handler (faked here at the registry seam, completed through
    the real _cadence_run_done) exactly once at the threshold; a
    FAIL leaves the debt standing; 'Test now' fires on ask."""

    PASS_REPORT = "TESTER REPORT (model: fake)\nVERDICT: PASS\nall good"
    FAIL_REPORT = "TESTER REPORT (model: fake)\nVERDICT: FAIL\nit broke"

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.ws = str(Path(self.temp.name) / "proj")
        Path(self.ws).mkdir(parents=True)
        self.win.eventlog = _FakeEventLog()
        self.win.settings.pop("test_cadence_files", None)
        self.win.settings.pop("test_cadence_lines", None)
        self.win._test_debt = {}
        self.win._cadence_boundary = set()
        self.win._cadence_thread = None
        self.win._cadence_running_for = None
        self.win.workspace = self.ws
        self.tester_calls = []
        self.report = self.PASS_REPORT

        def fake_tester(args):
            self.tester_calls.append(args.get("task", ""))
            return self.report

        self.win._extra_tools = lambda: {
            "run_tester": (None, fake_tester, True, "Tester Seat")}
        # Complete runs synchronously through the REAL completion
        # path — only the thread is bypassed.
        self.win._launch_cadence_run = (
            lambda ws, handler, task:
                self.win._cadence_run_done(ws, handler({"task": task})))

    def tearDown(self):
        del self.win._extra_tools
        del self.win._launch_cadence_run
        self.temp.cleanup()

    def _feed(self, changes):
        self.win._ws_changes({"workspace": self.ws}, changes)

    def _kinds(self):
        return self.win.eventlog.kinds()

    def test_thresholds_default_to_the_module_constants(self):
        self.assertEqual(self.win._cadence_thresholds(), (5, 300))
        self.win.settings["test_cadence_files"] = 3
        self.win.settings["test_cadence_lines"] = 120
        self.assertEqual(self.win._cadence_thresholds(), (3, 120))
        self.win.settings.pop("test_cadence_files")
        self.win.settings.pop("test_cadence_lines")

    def test_below_threshold_settle_is_quiet(self):
        self._feed({"a.py": 10, "b.py": 5})
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(self.tester_calls, [])
        self.assertNotIn("test_cadence_fired", self._kinds())
        acc = self.win._test_debt[self.ws]
        self.assertEqual(acc.debt_counts(), (2, 15))

    def test_crossing_threshold_across_turns_fires_once_and_resets(self):
        self._feed({"a.py": 3, "b.py": 3, "c.py": 3})
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(self.tester_calls, [])
        self._feed({"d.py": 3, "e.py": 3})
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(len(self.tester_calls), 1)
        self.assertIn("a.py", self.tester_calls[0])
        self.assertEqual(self._kinds().count("test_cadence_fired"), 1)
        self.assertIn("test_cadence_passed", self._kinds())
        acc = self.win._test_debt[self.ws]
        self.assertEqual(acc.debt_counts(), (0, 0))
        # A further settle with nothing new fires nothing.
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(len(self.tester_calls), 1)

    def test_failed_run_keeps_the_debt_and_does_not_refire_trivially(self):
        self.report = self.FAIL_REPORT
        self._feed({f"f{i}.py": 10 for i in range(5)})
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(len(self.tester_calls), 1)
        self.assertIn("test_cadence_owed", self._kinds())
        acc = self.win._test_debt[self.ws]
        self.assertEqual(acc.debt_counts(), (5, 50))   # still owed
        # One more small change: the tab is judged on the delta
        # since the failed run — below threshold, no refire.
        self._feed({"small.py": 1})
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(len(self.tester_calls), 1)
        # Another threshold of NEW change refires; a pass then
        # clears the whole tab, old debt included.
        self.report = self.PASS_REPORT
        self._feed({f"g{i}.py": 10 for i in range(5)})
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(len(self.tester_calls), 2)
        self.assertEqual(acc.debt_counts(), (0, 0))

    def test_lines_alone_can_fire(self):
        self._feed({"big.py": 300})
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(len(self.tester_calls), 1)

    def test_manual_test_now_fires_below_threshold_and_resets(self):
        self._feed({"a.py": 2})
        self.win.test_now()
        self.assertEqual(len(self.tester_calls), 1)
        fired = [f for k, f in self.win.eventlog.events
                 if k == "test_cadence_fired"]
        self.assertTrue(fired[0]["manual"])
        acc = self.win._test_debt[self.ws]
        self.assertEqual(acc.debt_counts(), (0, 0))

    def test_boundary_floor_fires_smaller_debt(self):
        self._feed({"a.py": 10, "b.py": 5})     # 2 files, 15 lines
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(self.tester_calls, [])  # main floor: no
        self.win._cadence_boundary.add(self.ws)
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(len(self.tester_calls), 1)  # boundary: yes
        fired = [f for k, f in self.win.eventlog.events
                 if k == "test_cadence_fired"]
        self.assertTrue(fired[0]["boundary"])

    def test_boundary_below_floor_records_the_skip(self):
        self._feed({"a.py": 10})                # 1 file, 10 lines
        self.win._cadence_boundary.add(self.ws)
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(self.tester_calls, [])
        self.assertIn("test_cadence_skipped", self._kinds())
        # The boundary is consumed by the settle that judged it.
        self.assertNotIn(self.ws, self.win._cadence_boundary)

    def test_plan_step_done_marks_the_boundary(self):
        real_render = self.win._plan_render
        real_persist = self.win._plan_persist
        real_state = self.win.plan_state
        self.win._plan_render = lambda: None
        self.win._plan_persist = lambda: None
        self.win.plan_state = {"status": "running",
                               # C3-merge stub fidelity: the step
                               # carries "text" — the tree's real
                               # plan-step shape (H5's notes append
                               # in on_plan_step_done reads it; the
                               # C3 copy's base predated that hunk).
                               "steps": [{"state": "active",
                                          "text": "step"}]}
        try:
            self.win.on_plan_step_done(0)
        finally:
            self.win._plan_render = real_render
            self.win._plan_persist = real_persist
            self.win.plan_state = real_state
        self.assertIn(self.ws, self.win._cadence_boundary)

    def test_missing_tester_seat_skips_without_losing_the_tab(self):
        self.win._extra_tools = lambda: {}
        self._feed({f"f{i}.py": 10 for i in range(5)})
        self.win._cadence_evaluate(self.ws)
        self.assertEqual(self.tester_calls, [])
        self.assertIn("test_cadence_skipped", self._kinds())
        acc = self.win._test_debt[self.ws]
        self.assertEqual(acc.debt_counts(), (5, 50))


class TemplatesShelfTests(unittest.TestCase):
    """Item C4: the templates shelf registry (forge/templates.py).
    Packaged templates are folders under templates/ with a
    template.json manifest (plugin.json's idiom); discovery is a
    scan that skips malformed folders with a log line, never a
    crash; instantiation copies content files byte-identical into
    a fresh project folder and runs the ordinary ensure_project
    setup, leaving template sources untouched. EMBER BREAK is a
    registered slot (templates_mod.EMBER_BREAK_ID), not content
    authored here: while its folder is absent the shelf shows what
    exists, and a folder dropped in at runtime appears with no
    code change — proven below by creating it mid-test."""

    def _make_template(self, base, folder, manifest, files):
        tdir = Path(base) / folder
        tdir.mkdir(parents=True)
        if manifest is not None:
            (tdir / "template.json").write_text(
                manifest if isinstance(manifest, str)
                else json.dumps(manifest), encoding="utf-8")
        for rel, data in files.items():
            p = tdir / rel
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_bytes(data if isinstance(data, bytes)
                          else data.encode("utf-8"))
        return tdir

    def test_builtin_blank_page_is_on_the_shelf(self):
        from forge import templates as templates_mod
        entries = templates_mod.discover_templates()
        by_id = {e["id"]: e for e in entries}
        self.assertIn("blank-page", by_id)
        entry = by_id["blank-page"]
        self.assertEqual(entry["name"], "Blank page")
        self.assertTrue(entry["description"])
        files = templates_mod.content_files(entry)
        self.assertEqual([f.name for f in files], ["index.html"])

    def test_ember_break_slot_absent_then_present_at_runtime(self):
        from forge import templates as templates_mod
        with tempfile.TemporaryDirectory() as tmp:
            shelf = Path(tmp) / "templates"
            shelf.mkdir()
            # Absent: handled gracefully — an empty shelf, no error.
            self.assertEqual(templates_mod.discover_templates(shelf), [])
            # The owner's build lands the folder later; no code change.
            self._make_template(
                shelf, templates_mod.EMBER_BREAK_ID,
                {"id": "ember-break", "name": "EMBER BREAK",
                 "description": "Breakout.", "kind": "game",
                 "tags": ["game"]},
                {"ember-break.html": "<html>game</html>"})
            entries = templates_mod.discover_templates(shelf)
            self.assertEqual([e["id"] for e in entries],
                             [templates_mod.EMBER_BREAK_ID])
            self.assertEqual(entries[0]["name"], "EMBER BREAK")

    def test_malformed_templates_skipped_never_crash(self):
        from forge import templates as templates_mod
        with tempfile.TemporaryDirectory() as tmp:
            shelf = Path(tmp)
            self._make_template(shelf, "good-one",
                                {"id": "good-one", "name": "Good"},
                                {"a.txt": "a"})
            self._make_template(shelf, "bad-json", "{not json", {})
            self._make_template(shelf, "no-manifest", None,
                                {"a.txt": "a"})
            self._make_template(shelf, "not-an-object", "[1, 2]", {})
            skipped = []
            entries = templates_mod.discover_templates(
                shelf, on_skip=skipped.append)
            self.assertEqual([e["id"] for e in entries], ["good-one"])
            self.assertEqual(len(skipped), 3)
            self.assertTrue(any("bad-json" in s for s in skipped))

    def test_missing_templates_folder_is_an_empty_shelf(self):
        from forge import templates as templates_mod
        with tempfile.TemporaryDirectory() as tmp:
            self.assertEqual(
                templates_mod.discover_templates(Path(tmp) / "nope"), [])

    def test_instantiation_copies_bytes_and_runs_project_setup(self):
        from forge import templates as templates_mod
        with tempfile.TemporaryDirectory() as tmp:
            shelf = Path(tmp) / "templates"
            payload = bytes(range(256))
            tdir = self._make_template(
                shelf, "demo",
                {"id": "demo", "name": "Demo"},
                {"index.html": "<html>demo</html>",
                 "assets/blob.bin": payload,
                 "docs/readme.md": "# Demo\n"})
            before = {p.relative_to(tdir): p.read_bytes()
                      for p in tdir.rglob("*") if p.is_file()}
            entry = templates_mod.discover_templates(shelf)[0]
            dest = Path(tmp) / "projects" / "my-demo"
            made = templates_mod.instantiate_template(entry, dest)
            self.assertEqual(made, dest)
            # Content copied byte-identical, manifest not copied.
            self.assertEqual((dest / "index.html").read_bytes(),
                             b"<html>demo</html>")
            self.assertEqual((dest / "assets" / "blob.bin").read_bytes(),
                             payload)
            self.assertEqual((dest / "docs" / "readme.md").read_bytes(),
                             b"# Demo\n")
            self.assertFalse((dest / "template.json").exists())
            # The ordinary project setup ran, as ensure_project makes it.
            self.assertTrue((dest / ".forge" / "instructions.md").is_file())
            self.assertTrue((dest / ".forge" / "scratchpad.md").is_file())
            self.assertTrue((dest / ".forge" / "sources").is_dir())
            self.assertTrue((dest / ".forge" / "uploads").is_dir())
            # Template sources untouched by the instantiation.
            after = {p.relative_to(tdir): p.read_bytes()
                     for p in tdir.rglob("*") if p.is_file()}
            self.assertEqual(before, after)

    def test_instantiation_refuses_an_existing_destination(self):
        from forge import templates as templates_mod
        with tempfile.TemporaryDirectory() as tmp:
            shelf = Path(tmp) / "templates"
            self._make_template(shelf, "demo",
                                {"id": "demo", "name": "Demo"},
                                {"a.txt": "a"})
            entry = templates_mod.discover_templates(shelf)[0]
            dest = Path(tmp) / "taken"
            dest.mkdir()
            (dest / "keep.txt").write_text("mine", encoding="utf-8")
            with self.assertRaises(FileExistsError):
                templates_mod.instantiate_template(entry, dest)
            # Nothing written into the refused destination.
            self.assertEqual((dest / "keep.txt").read_text(
                encoding="utf-8"), "mine")
            self.assertFalse((dest / "a.txt").exists())
            self.assertFalse((dest / ".forge").exists())


class TemplatesWindowTests(unittest.TestCase):
    """Item C4: the shelf surface + creation flow on the real
    window. The window lists a fresh discovery scan; creating from
    a template adopts the new folder through the same bookkeeping
    add_project uses; an existing destination is refused in words;
    and plain (no-template) project opening is unchanged."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.shelf = root / "templates"
        tdir = self.shelf / "ember-break"
        tdir.mkdir(parents=True)
        (tdir / "template.json").write_text(json.dumps(
            {"id": "ember-break", "name": "EMBER BREAK",
             "description": "Breakout.", "kind": "game"}),
            encoding="utf-8")
        (tdir / "ember-break.html").write_text(
            "<html>game</html>", encoding="utf-8")
        self.parent = root / "projects"
        self.parent.mkdir()
        self._old_templates_dir = self.win.app_templates_dir
        self.win.app_templates_dir = self.shelf
        self._old_workspace = self.win.workspace
        self._old_projects = list(self.win.projects)
        self.win.worker = None

    def tearDown(self):
        self.win.app_templates_dir = self._old_templates_dir
        self.win.projects = self._old_projects
        self.win.workspace = self._old_workspace
        self.temp.cleanup()

    def test_shelf_window_lists_the_runtime_ember_break(self):
        win = self.win.templates_win
        win.refresh()
        self.assertEqual(len(win._entries), 1)
        self.assertEqual(win._entries[0]["id"], "ember-break")
        self.assertEqual(win.rows_list.count(), 1)
        self.assertIn("EMBER BREAK", win.rows_list.item(0).text())
        self.assertTrue(win.use_btn.isEnabled())

    def test_create_project_from_template_opens_it(self):
        entry = self.win.template_entries()[0]
        created = self.win.create_project_from_template(
            entry, str(self.parent), "my-breakout")
        dest = self.parent / "my-breakout"
        self.assertEqual(created, str(dest))
        self.assertEqual((dest / "ember-break.html").read_bytes(),
                         b"<html>game</html>")
        self.assertTrue((dest / ".forge" / "instructions.md").is_file())
        self.assertEqual(self.win.workspace, str(dest))
        self.assertIn(str(dest),
                      [e.get("path") for e in self.win.projects])

    def test_create_refuses_an_existing_folder(self):
        from unittest import mock
        from forge import main as main_mod
        entry = self.win.template_entries()[0]
        (self.parent / "taken").mkdir()
        with mock.patch.object(main_mod.QMessageBox, "information",
                               lambda *a, **k: None):
            created = self.win.create_project_from_template(
                entry, str(self.parent), "taken")
        self.assertIsNone(created)
        self.assertEqual(self.win.workspace, self._old_workspace)
        self.assertFalse((self.parent / "taken" / ".forge").exists())

    def test_plain_project_opening_unchanged(self):
        plain = self.parent / "plain"
        plain.mkdir()
        self.win.set_project(str(plain))
        self.assertEqual(self.win.workspace, str(plain))
        self.assertTrue((plain / ".forge" / "instructions.md").is_file())
        # No template content rides along on the plain path.
        self.assertFalse((plain / "ember-break.html").exists())


class ProjectSecurityScanTests(unittest.TestCase):
    """Item C6: the project-security-scan skill's bundled scanner,
    run as a real subprocess against a seeded fixture project.
    The planted secrets below are fake shapes (the AWS one is
    digit-substituted); the redaction assertions require that
    NONE of them appears whole anywhere in the scanner output."""

    AWS = "AKIATESTTESTTEST1234"
    GITHUB = "ghp_ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    SLACK = "xoxb-123456789012-abcdefghijkl"
    APIKEY = "sk-abcdefghijklmnopqrstuvwx"
    PASSWORD = "hunter2hunter2"
    ENV_SECRET = "shhh-do-not-print-this"
    GIT_TOKEN = "TOKENXYZ123"

    @classmethod
    def setUpClass(cls):
        cls.skills_dir = Path(__file__).resolve().parent.parent / "skills"
        cls.scanner = cls.skills_dir / "project-security-scan" / "scan.py"

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        r = self.root
        (r / "app.py").write_text(
            f'aws_key = "{self.AWS}"\n'                    # line 1
            f'github_token = "{self.GITHUB}"\n'            # line 2
            f'db_password = "{self.PASSWORD}"\n'           # line 3
            'password = "changeme"\n'                      # placeholder
            f'slack = "{self.SLACK}"\n'                    # line 5
            f'api_key = "{self.APIKEY}"\n'                 # line 6
            "-----BEGIN RSA PRIVATE KEY-----\n"            # line 7
            "import subprocess, pickle\n"
            "subprocess.run(cmd, shell=True)\n"            # line 9
            "data = pickle.loads(blob)\n"                  # line 10
            "result = eval(user_input)\n"                  # line 11
            'ok = eval("1+1")\n'                           # literal: clean
            'cursor.execute(f"SELECT * FROM t WHERE id={uid}")\n'  # 13
            'app.run(host="0.0.0.0", port=5000)\n',        # line 14
            encoding="utf-8")
        (r / ".env").write_text(f"TOPSECRET={self.ENV_SECRET}\n",
                                encoding="utf-8")
        (r / "credentials.json").write_text("{}\n", encoding="utf-8")
        git = r / ".git"
        git.mkdir()
        (git / "config").write_text(
            '[remote "origin"]\n'
            f"\turl = https://user:{self.GIT_TOKEN}@github.com/org/repo.git\n",
            encoding="utf-8")
        nm = r / "node_modules"
        nm.mkdir()
        (nm / "evil.py").write_text(f'x = "{self.AWS}"\n', encoding="utf-8")
        venv = r / "venv"
        venv.mkdir()
        (venv / "lib.py").write_text(f'x = "{self.AWS}"\n', encoding="utf-8")
        (r / "big.py").write_bytes(b"# pad\n" * 200_000
                                   + f'x = "{self.AWS}"\n'.encode())
        (r / "blob.py").write_bytes(b"\x00\x01\x02" + self.AWS.encode())
        (r / "clean.py").write_text(
            "def add(a, b):\n    return a + b\n", encoding="utf-8")

    def tearDown(self):
        self.temp.cleanup()

    def _run(self, *extra):
        import subprocess
        proc = subprocess.run(
            [sys.executable, str(self.scanner), str(self.root), *extra],
            capture_output=True, text=True, timeout=120)
        return proc

    def _report(self):
        proc = self._run()
        self.assertEqual(proc.returncode, 0, proc.stderr)
        return proc, json.loads(proc.stdout)

    def _by(self, report, path, line=None):
        return [f for f in report["findings"]
                if f["path"] == path and (line is None or f["line"] == line)]

    def test_planted_findings_reported_with_file_and_line(self):
        _, report = self._report()
        self.assertEqual(len(self._by(report, "app.py", 1)), 1)   # AWS
        self.assertEqual(len(self._by(report, "app.py", 2)), 1)   # GitHub
        self.assertEqual(len(self._by(report, "app.py", 3)), 1)   # password
        self.assertEqual(len(self._by(report, "app.py", 5)), 1)   # Slack
        self.assertEqual(len(self._by(report, "app.py", 6)), 1)   # sk-
        key = self._by(report, "app.py", 7)
        self.assertEqual(len(key), 1)
        self.assertIn("private key", key[0]["message"])
        for line in (9, 10, 11, 13, 14):
            found = self._by(report, "app.py", line)
            self.assertEqual(len(found), 1, f"line {line}: {found}")
            self.assertEqual(found[0]["category"], "code-pattern")
        # The literal eval and the placeholder password stay clean.
        self.assertEqual(self._by(report, "app.py", 4), [])
        self.assertEqual(self._by(report, "app.py", 12), [])
        self.assertEqual(self._by(report, "clean.py"), [])

    def test_redaction_holds_everywhere(self):
        proc, report = self._report()
        for planted in (self.AWS, self.GITHUB, self.SLACK, self.APIKEY,
                        self.PASSWORD, self.ENV_SECRET, self.GIT_TOKEN):
            self.assertNotIn(planted, proc.stdout)
        aws = self._by(report, "app.py", 1)[0]
        self.assertEqual(aws["evidence"], "AKIA...(20 chars)")

    def test_env_named_but_never_read(self):
        _, report = self._report()
        env = self._by(report, ".env")
        self.assertEqual(len(env), 1)
        self.assertIsNone(env[0]["line"])
        self.assertEqual(env[0]["evidence"], "")

    def test_config_findings(self):
        _, report = self._report()
        creds = self._by(report, "credentials.json")
        self.assertEqual(len(creds), 1)
        self.assertEqual(creds[0]["severity"], "MEDIUM")
        remote = self._by(report, ".git/config")
        self.assertEqual(len(remote), 1)
        self.assertIn("github.com/org/repo.git", remote[0]["message"])
        self.assertNotIn(self.GIT_TOKEN, remote[0]["message"])

    def test_skip_rules_hold(self):
        _, report = self._report()
        for skipped in ("node_modules/evil.py", "venv/lib.py",
                        "big.py", "blob.py"):
            self.assertEqual(self._by(report, skipped), [], skipped)

    def test_sorted_by_severity_and_summary_counts(self):
        _, report = self._report()
        order = {"HIGH": 0, "MEDIUM": 1, "LOW": 2}
        ranks = [order[f["severity"]] for f in report["findings"]]
        self.assertEqual(ranks, sorted(ranks))
        self.assertEqual(report["findings"][0]["severity"], "HIGH")
        s = report["summary"]
        self.assertEqual(s["total"], len(report["findings"]))
        self.assertEqual(s["HIGH"] + s["MEDIUM"] + s["LOW"], s["total"])
        self.assertGreaterEqual(s["HIGH"], 6)

    def test_text_mode_and_error_exit(self):
        proc = self._run("--text")
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertIn("[HIGH] app.py:1", proc.stdout)
        self.assertNotIn(self.AWS, proc.stdout)
        import subprocess
        bad = subprocess.run(
            [sys.executable, str(self.scanner),
             str(self.root / "does-not-exist")],
            capture_output=True, text=True, timeout=60)
        self.assertNotEqual(bad.returncode, 0)

    def test_clean_project_reports_clean(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            (root / "main.py").write_text("print('hello')\n",
                                          encoding="utf-8")
            import subprocess
            proc = subprocess.run(
                [sys.executable, str(self.scanner), str(root)],
                capture_output=True, text=True, timeout=60)
            self.assertEqual(proc.returncode, 0, proc.stderr)
            report = json.loads(proc.stdout)
            self.assertEqual(report["findings"], [])
            self.assertEqual(report["summary"]["total"], 0)


class ProjectSecurityScanSkillTests(unittest.TestCase):
    """Item C6 registration parity: the skill loads through
    forge/skills.py exactly like the other packaged skills —
    scanned by folder, header parsed, body loadable, and active
    under the tree's own enable rule (a skill is on unless the
    owner disabled it by name in settings; nothing about this
    skill is special-cased)."""

    def test_skill_scans_loads_and_is_active_by_default(self):
        skills_dir = Path(__file__).resolve().parent.parent / "skills"
        skills = scan_skills(skills_dir)
        by_name = {s.name: s for s in skills}
        self.assertIn("project-security-scan", by_name)
        skill = by_name["project-security-scan"]
        self.assertEqual(skill.folder.name, "project-security-scan")
        self.assertIn("security", skill.description.lower())
        handler = make_load_skill_handler(skills)
        body = handler({"name": "project-security-scan"})
        self.assertIn("scan.py", body)
        self.assertIn("Never auto-fix", body)
        self.assertLessEqual(len(body), 9000)
        # The tree's enable rule (forge/main.py reload_extensions):
        # active unless named in settings["disabled_skills"],
        # which defaults to empty — this skill included.
        disabled = set()
        active = [s.name for s in skills if s.name not in disabled]
        self.assertIn("project-security-scan", active)
        # The bundled scanner ships inside the skill folder.
        self.assertTrue((skill.folder / "scan.py").is_file())


class PlanCardFieldsTests(unittest.TestCase):
    """Item C7: a plan document carries Success criteria and Out
    of scope sections — drafted with the rest of the skeleton,
    extracted from the document the sidecar already stores, and
    surfaced where plans are judged (the desktop document view is
    the document text itself; the deck card and the Goldfish
    review consume them as below). A pre-C7 document has neither
    section: the fields read as absent and nothing changes."""

    DOC = ("# Plan\n\n"
           "## Goal\nBuild the parser.\n\n"
           "## Contents\n"
           "1. a.py — create it\n"
           "2. b.py — edit it\n\n"
           "## Steps\n"
           "1. Create a.py — with the parser in it\n"
           "   Verify: it imports cleanly.\n"
           "2. Edit b.py — wire the parser in\n"
           "   Verify: the suite passes.\n\n"
           "## Risks\nNone worth naming.\n\n"
           "## Assumptions\nAssumed: Python 3 only.\n\n"
           "## Success criteria\n"
           "Done means the parser imports cleanly.\n"
           "Done means the suite passes end to end.\n\n"
           "## Out of scope\n"
           "Not doing: a GUI for the parser.\n"
           "Not doing: packaging or publishing.\n")

    OLD_DOC = ("# Plan\n\n"
               "## Goal\nBuild the parser.\n\n"
               "## Steps\n"
               "1. Create a.py — with the parser in it\n"
               "   Verify: it imports cleanly.\n"
               "2. Edit b.py — wire the parser in\n"
               "   Verify: the suite passes.\n")

    CRITERIA = ("Done means the parser imports cleanly.\n"
                "Done means the suite passes end to end.")
    SCOPE = ("Not doing: a GUI for the parser.\n"
             "Not doing: packaging or publishing.")

    def test_sections_round_trip_through_the_sidecar(self):
        from forge import planning
        with tempfile.TemporaryDirectory() as td:
            steps = planning.extract_steps(self.DOC)
            plan = planning.new_plan(steps, request="build the parser",
                                     document=self.DOC)
            planning.save_plan(td, 7, plan)
            loaded = planning.load_plan(td, 7)
            self.assertEqual(loaded["document"], self.DOC)
            self.assertEqual(planning.success_criteria(loaded["document"]),
                             self.CRITERIA)
            self.assertEqual(planning.out_of_scope(loaded["document"]),
                             self.SCOPE)
            # The checklist still comes from the Steps section only —
            # the numbered Contents list is not steps, and neither
            # new section leaks into it.
            self.assertEqual(
                steps,
                ["Create a.py — with the parser in it "
                 "Verify: it imports cleanly.",
                 "Edit b.py — wire the parser in "
                 "Verify: the suite passes."])

    def test_pre_c7_document_loads_with_the_fields_absent(self):
        from forge import planning
        self.assertEqual(planning.success_criteria(self.OLD_DOC), "")
        self.assertEqual(planning.out_of_scope(self.OLD_DOC), "")
        self.assertIsNone(planning.document_section(self.OLD_DOC,
                                                    "Success criteria"))
        # Steps extraction is identical to the pre-C7 behaviour.
        self.assertEqual(planning.extract_steps(self.OLD_DOC),
                         planning.extract_steps(self.DOC))
        # ...and through the sidecar, with the document intact.
        with tempfile.TemporaryDirectory() as td:
            steps = planning.extract_steps(self.OLD_DOC)
            plan = planning.new_plan(steps, request="build",
                                     document=self.OLD_DOC)
            planning.save_plan(td, 8, plan)
            loaded = planning.load_plan(td, 8)
            self.assertEqual(loaded["document"], self.OLD_DOC)
            self.assertEqual([s["text"] for s in loaded["steps"]], steps)

    def test_skeleton_and_drafting_instructions_carry_the_fields(self):
        from forge import modes
        from forge import reference_build as rdb
        skeleton = modes.SKELETONS["plan"]
        self.assertIn("Success criteria", skeleton)
        self.assertIn("Out of scope", skeleton)
        # Both reference-driven variants carry them too.
        self.assertEqual(rdb.plan_sections(False), skeleton)
        for name in ("Success criteria", "Out of scope"):
            self.assertIn(name, rdb.plan_sections(True))
        criteria = modes.section_instruction(
            "plan", "Success criteria", "## Goal\nBuild it.", [])
        self.assertIn("checkable", criteria)
        self.assertIn("Done means", criteria)
        scope = modes.section_instruction("plan", "Out of scope", "", [])
        self.assertIn("Not doing:", scope)
        # The Plan guidance skeleton string rides the same list.
        from forge.permissions import MODE_GUIDANCE
        self.assertIn("## Success criteria", MODE_GUIDANCE["plan"])
        self.assertIn("## Out of scope", MODE_GUIDANCE["plan"])

    def test_deck_payload_carries_the_fields_when_present(self):
        from forge import planning
        steps = planning.extract_steps(self.DOC)
        plan = planning.new_plan(steps, request="build the parser",
                                 document=self.DOC)
        shape = planning.deck_plan(plan)
        self.assertEqual(shape["success_criteria"], self.CRITERIA)
        self.assertEqual(shape["out_of_scope"], self.SCOPE)

    def test_deck_payload_is_empty_fields_when_absent(self):
        from forge import planning
        steps = planning.extract_steps(self.OLD_DOC)
        plan = planning.new_plan(steps, request="build",
                                 document=self.OLD_DOC)
        shape = planning.deck_plan(plan)
        self.assertEqual(shape["success_criteria"], "")
        self.assertEqual(shape["out_of_scope"], "")
        # Everything else about the projection is the pre-C7 shape.
        self.assertEqual(shape["status"], "draft")
        self.assertEqual(shape["steps"][0]["text"], steps[0])
        self.assertNotIn("document", shape)
        # A bare-list plan (no document at all) reads the same way.
        bare = planning.deck_plan(planning.new_plan(["A", "B"]))
        self.assertEqual(bare["success_criteria"], "")
        self.assertEqual(bare["out_of_scope"], "")

    def test_deck_card_renders_the_fields(self):
        # The deck page's plan card reads the two payload keys the
        # same way it reads the Goldfish summary (Item #56 pattern).
        from forge.deck import PAGE
        self.assertIn("p.success_criteria", PAGE)
        self.assertIn("p.out_of_scope", PAGE)
        self.assertIn("Success criteria:", PAGE)
        self.assertIn("Out of scope:", PAGE)

    def test_goldfish_stage_input_contains_the_criteria(self):
        # build_stage_messages embeds the plan text whole — the
        # document IS the input, so the new sections ride along
        # with no Goldfish change. Both model stages are checked.
        from forge import goldfish
        for stage in ("zoom", "comprehension"):
            messages = goldfish.build_stage_messages(stage, self.DOC)
            user = messages[-1]["content"]
            self.assertIn("THE PLAN UNDER REVIEW:", user)
            self.assertIn("## Success criteria", user)
            self.assertIn(self.CRITERIA, user)
            self.assertIn("## Out of scope", user)
            self.assertIn(self.SCOPE, user)
        # A pre-C7 document reaches the reviewer exactly as before.
        messages = goldfish.build_stage_messages("zoom", self.OLD_DOC)
        user = messages[-1]["content"]
        self.assertIn("## Goal", user)
        self.assertNotIn("Success criteria", user)

    def test_assumptions_fallback_keeps_the_new_sections(self):
        from forge import modes
        doc = self.DOC.replace(
            "Assumed: Python 3 only.", "(not stated)")
        out = modes.assumptions_fallback(doc, ["Which Python?"])
        self.assertIn("Assumed (open question carried forward): "
                      "Which Python?", out)
        self.assertIn("## Success criteria\n" + self.CRITERIA, out)
        self.assertIn("## Out of scope\n" + self.SCOPE, out)

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])

    def test_worker_drafts_both_sections_into_the_document(self):
        # The end-to-end drafting path: homework + PROCEED + eight
        # section generations, and the document that reaches the
        # gate carries both C7 sections in the skeleton's order.
        import time
        temp = tempfile.TemporaryDirectory()
        self.addCleanup(temp.cleanup)
        root = Path(temp.name)
        (root / "src").mkdir()
        (root / "src" / "demo.py").write_text(
            "def existing_fn():\n    return 1\n", encoding="utf-8")
        client = _PlanClient([
            {"content": "READY"},
            {"content": "PROCEED"},
            {"content": "A tapping game for the owner's cat."},
            {"content": "The project has src/demo.py and nothing else."},
            {"content": "game.py — new file."},
            {"content": "1. Write game.py — the tap targets\n"
                        "   Verify: a tap scores.\n"
                        "2. Test it on the touchscreen\n"
                        "   Verify: it opens and plays."},
            {"content": "The cat may ignore it entirely."},
            {"content": "Assumed: it runs on the touchscreen PC."},
            {"content": "Done means a tap scores on screen."},
            {"content": "Not doing: online leaderboards."},
        ])
        from forge.worker import AgentWorker
        seen = {"ready": [], "doc": []}
        w = AgentWorker(
            client, "fake-model",
            [{"role": "user", "content": "make a cat game"}],
            {"num_predict": 512}, str(root),
            permissions={"rules": [], "mode": "plan", "classes": {}},
            planning=True)
        w.approval_needed.connect(lambda *a: w.resolve_approval(True))
        w.plan_ready.connect(seen["ready"].append)
        w.plan_document.connect(seen["doc"].append)
        w.start()
        deadline = time.time() + 10.0
        while time.time() < deadline and not seen["ready"]:
            self.app.processEvents()
            time.sleep(0.02)
        self.assertTrue(seen["ready"], "plan never reached the gate")
        # Ten generations: READY + PROCEED + eight sections.
        self.assertEqual(client.calls, 10)
        doc = seen["doc"][0]
        self.assertIn("## Success criteria\n"
                      "Done means a tap scores on screen.", doc)
        self.assertIn("## Out of scope\n"
                      "Not doing: online leaderboards.", doc)
        self.assertLess(doc.index("## Assumptions"),
                        doc.index("## Success criteria"))
        self.assertLess(doc.index("## Success criteria"),
                        doc.index("## Out of scope"))
        w.resolve_plan("kill")
        deadline = time.time() + 10.0
        while time.time() < deadline and w.isRunning():
            self.app.processEvents()
            time.sleep(0.02)
        self.assertTrue(w.wait(3000))


class TestViewParserTests(unittest.TestCase):
    """Item C8, the tally (forge/testview.py): counts ONLY what a
    runner's output states in a recognized form. A summary line
    replaces the running tally — the runner's own final numbers
    outrank a count accumulated mid-stream — and output no runner
    would produce grows no tally at all."""

    def _feed(self, lines):
        from forge import testview as tv
        tally = tv.TestTally()
        for line in lines:
            tally.feed(line)
        return tally

    def test_unittest_verbose_tallies_then_summary_locks(self):
        tally = self._feed([
            "test_add (test_calc.CalcTests) ... ok",
            "test_div (test_calc.CalcTests) ... FAIL",
            "test_err (test_calc.CalcTests) ... ERROR",
            "test_skip (test_calc.CalcTests) ... skipped 'later'",
        ])
        self.assertTrue(tally.recognized)
        self.assertEqual(
            (tally.run, tally.failures, tally.errors, tally.skipped),
            (4, 1, 1, 1))
        tally.feed("Ran 4 tests in 0.012s")
        tally.feed("FAILED (failures=1, errors=1, skipped=1)")
        self.assertEqual(tally.summary_line,
                         "FAILED (failures=1, errors=1, skipped=1)")
        self.assertEqual(tally.tally_text(),
                         "4 run · 1 failed · 1 error · 1 skipped")
        # Locked: a stray late line cannot move a stated summary.
        tally.feed("test_late (test_calc.CalcTests) ... ok")
        self.assertEqual(tally.run, 4)

    def test_unittest_passing_run_ok_verdict(self):
        tally = self._feed([
            "test_a (t.T) ... ok",
            "test_b (t.T) ... ok",
            "Ran 2 tests in 0.001s",
            "OK",
        ])
        self.assertEqual(tally.summary_line, "OK")
        self.assertEqual(tally.tally_text(), "2 run")

    def test_pytest_progress_and_failing_summary(self):
        tally = self._feed([
            "tests/test_a.py ....F. [ 60%]",
            "tests/test_b.py ..E [100%]",
        ])
        self.assertEqual(
            (tally.run, tally.failures, tally.errors), (9, 1, 1))
        tally.feed("===== 1 failed, 7 passed, 1 error in 0.42s =====")
        self.assertEqual(
            (tally.run, tally.failures, tally.errors), (9, 1, 1))
        self.assertEqual(tally.summary_line,
                         "===== 1 failed, 7 passed, 1 error in 0.42s =====")
        self.assertEqual(tally.tally_text(), "9 run · 1 failed · 1 error")

    def test_pytest_verbose_lines(self):
        tally = self._feed([
            "tests/test_x.py::test_a PASSED [ 50%]",
            "tests/test_x.py::test_b FAILED [100%]",
            "===== 1 failed, 1 passed in 0.10s =====",
        ])
        self.assertEqual((tally.run, tally.failures), (2, 1))

    def test_unknown_output_never_tallies(self):
        tally = self._feed([
            "building widgets...",
            "done ok",
            "Ran the numbers in 3s flat",
            "progress ........ [ 50%]",
            "FAILED to connect to the printer",
        ])
        self.assertFalse(tally.recognized)
        self.assertEqual(tally.tally_text(), "")
        self.assertEqual(tally.run, 0)

    def test_run_log_records_and_verdicts(self):
        from forge import testview as tv
        log = tv.TestRunLog()
        log.note_started("python3 -m pytest -q", "/proj")
        log.note_line("===== 1 failed, 1 passed in 0.10s =====")
        self.assertEqual(log.live_tally_text(), "2 run · 1 failed")
        record = log.note_finished(1, False)
        self.assertIsNotNone(record)
        self.assertEqual(record["exit_code"], 1)
        self.assertIsInstance(record["duration_s"], float)
        self.assertGreaterEqual(record["duration_s"], 0)
        # The runner's own summary outranks the bare exit code.
        self.assertEqual(tv.run_verdict(record),
                         "===== 1 failed, 1 passed in 0.10s =====")
        line = tv.history_line(record)
        self.assertIn("python3 -m pytest -q", line)
        self.assertIn("2 run · 1 failed", line)
        self.assertEqual(len(log.history), 1)
        self.assertIsNone(log.current)

    def test_verdict_words_for_stop_failure_and_plain_exit(self):
        from forge import testview as tv
        log = tv.TestRunLog()
        log.note_started("sleep 30", "/proj")
        stopped = log.note_finished(0, True)
        self.assertEqual(tv.run_verdict(stopped), "stopped")
        log.note_started("nope-cmd", "/proj")
        failed = log.note_failed("No such file or directory")
        self.assertEqual(tv.run_verdict(failed),
                         "could not start: No such file or directory")
        self.assertIsNone(failed["exit_code"])
        log.note_started("make build", "/proj")
        plain = log.note_finished(3, False)
        self.assertEqual(tv.run_verdict(plain), "exit 3")
        # Settling with nothing live is a no-op, not a phantom run.
        self.assertIsNone(log.note_finished(0, False))
        self.assertEqual(len(log.history), 3)


class TestCommandResolutionTests(unittest.TestCase):
    """Item C8: the Testing view's default command comes from the
    SAME configuration the worker verifies with — the project's
    .forge/verify.json first, else settings verify_commands. No
    second store is invented."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)

    def tearDown(self):
        self.temp.cleanup()

    def _verify_json(self, data):
        area = self.root / ".forge"
        area.mkdir(exist_ok=True)
        (area / "verify.json").write_text(json.dumps(data),
                                          encoding="utf-8")

    def test_unconfigured_everywhere(self):
        from forge import testview as tv
        self.assertEqual(tv.resolve_test_command(str(self.root), {}),
                         ("", None))
        self.assertEqual(
            tv.resolve_test_command(str(self.root),
                                    {"verify_commands": []}),
            ("", None))

    def test_settings_list_is_the_default(self):
        from forge import testview as tv
        cmd, source = tv.resolve_test_command(
            str(self.root),
            {"verify_commands": ["make lint", "make test"]})
        self.assertEqual(source, "settings")
        self.assertEqual(cmd, "make lint && make test")

    def test_project_test_key_wins_outright(self):
        from forge import testview as tv
        self._verify_json({"test": "python3 -m pytest tests/",
                           "lint": "ruff ."})
        cmd, source = tv.resolve_test_command(
            str(self.root), {"verify_commands": ["make test"]})
        self.assertEqual((cmd, source),
                         ("python3 -m pytest tests/", "project"))

    def test_project_checks_run_in_order(self):
        from forge import testview as tv
        self._verify_json({"lint": "ruff .", "commands": ["pytest -q"]})
        cmd, source = tv.resolve_test_command(str(self.root), {})
        self.assertEqual((cmd, source),
                         ("ruff . && pytest -q", "project"))

    def test_broken_verify_json_falls_back_to_settings(self):
        from forge import testview as tv
        area = self.root / ".forge"
        area.mkdir()
        (area / "verify.json").write_text("{not json", encoding="utf-8")
        cmd, source = tv.resolve_test_command(
            str(self.root), {"verify_commands": ["make test"]})
        self.assertEqual((cmd, source), ("make test", "settings"))


class TestingWindowTests(unittest.TestCase):
    """Item C8, the room itself: it exists hidden from startup,
    opens as a single instance from the menus / palette, shows the
    unconfigured state in plain words, runs the project's test
    command through ForgeWindow.start_run (the Run machinery —
    same thread, same Stop), streams the lines into its own pane
    with the tally the output states, and files each finished run
    in the session history. Runs started from the Run window are
    observed through the same tap."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        if cls.win.run_is_running():
            cls.win.stop_run()
            cls.win._run_thread.wait(3000)
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        if self.win.run_is_running():
            self.win.stop_run()
            self.win._run_thread.wait(3000)
        self._saved_verify = self.win.settings.get("verify_commands")
        self.win.settings["verify_commands"] = []
        self.win.workspace = str(self.root)
        view = self.win.testing_win
        view.run_log.history.clear()
        view.run_log.current = None
        view.test_output.clear()
        view.test_history_list.clear()
        view.test_status_label.setText("idle")
        view.test_tally_label.setText("")
        view.refresh_command()

    def tearDown(self):
        if self.win.run_is_running():
            self.win.stop_run()
            self.win._run_thread.wait(3000)
        self.win.testing_win.close()
        if self._saved_verify is None:
            self.win.settings.pop("verify_commands", None)
        else:
            self.win.settings["verify_commands"] = self._saved_verify
        self.temp.cleanup()

    def _pump_until(self, predicate, timeout=6.0):
        import time
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            self.app.processEvents()
            if predicate():
                return True
            time.sleep(0.02)
        self.app.processEvents()
        return predicate()

    def _settled(self):
        return (not self.win.run_is_running()
                and self.win.testing_win.run_log.current is None)

    def test_window_exists_hidden_and_opens_single_instance(self):
        view = self.win.testing_win
        self.assertFalse(view.isVisible())
        self.win.open_testing_window()
        self.app.processEvents()
        self.assertTrue(view.isVisible())
        self.win.open_testing_window()
        self.app.processEvents()
        self.assertIs(self.win.testing_win, view)
        self.assertTrue(view.isVisible())
        # Both menus and the palette carry the same door.
        self.assertIsNotNone(self.win.act_testing_window)
        self.assertIsNotNone(self.win.view_act_testing)
        _entries, bindings = self.win.palette_actions()
        self.assertIn("testing_window", bindings)

    def test_unconfigured_state_is_plain_words(self):
        view = self.win.testing_win
        self.assertIsNone(view.command_source)
        self.assertIn("No test command is configured",
                      view.test_source_label.text())
        self.assertEqual(view.test_command_edit.text(), "")
        self.assertFalse(view.test_run_btn.isEnabled())
        view.test_command_edit.setText("python3 -m pytest -q")
        view.test_command_edit.textEdited.emit("python3 -m pytest -q")
        self.assertTrue(view.test_run_btn.isEnabled())

    def test_project_verify_json_prefills_the_command(self):
        area = self.root / ".forge"
        area.mkdir()
        (area / "verify.json").write_text(
            json.dumps({"test": "python3 -m pytest tests/"}),
            encoding="utf-8")
        view = self.win.testing_win
        view.refresh_command()
        self.assertEqual(view.command_source, "project")
        self.assertEqual(view.test_command_edit.text(),
                         "python3 -m pytest tests/")
        self.assertIn("verify.json", view.test_source_label.text())

    def test_run_tests_persists_first_command_and_streams(self):
        view = self.win.testing_win
        command = ("python3 -c 'print(\"test_a (t.T) ... ok\"); "
                   "print(\"Ran 1 test in 0.001s\"); print(\"OK\")'")
        view.test_command_edit.setText(command)
        view.test_command_edit.textEdited.emit(command)
        view.test_run_btn.click()
        # First configuration persisted through the settings store
        # the worker's verify loop reads — immediately, not on exit.
        self.assertEqual(self.win.settings.get("verify_commands"),
                         [command])
        self.assertTrue(self._pump_until(self._settled))
        out = view.test_output.toPlainText()
        self.assertIn("test_a (t.T) ... ok", out)
        self.assertIn("OK", out)
        self.assertEqual(view.test_tally_label.text(), "1 run")
        self.assertEqual(view.test_history_list.count(), 1)
        record = view.run_log.history[-1]
        self.assertEqual(record["command"], command)
        self.assertEqual(record["exit_code"], 0)
        self.assertIsInstance(record["duration_s"], float)
        self.assertIn("OK", view.test_history_list.item(0).text())

    def test_view_observes_a_run_window_run_and_its_failure(self):
        # A run started through start_run directly (the Run
        # window's door) streams into the testing room too, and a
        # failing pytest-shaped run files its own summary as the
        # verdict with the honest exit code on the record.
        command = ("python3 -c 'import sys; "
                   "print(\"===== 1 failed, 1 passed in 0.10s =====\"); "
                   "sys.exit(1)'")
        self.win.start_run(command, str(self.root))
        self.assertTrue(self._pump_until(self._settled))
        view = self.win.testing_win
        record = view.run_log.history[-1]
        self.assertEqual(record["exit_code"], 1)
        from forge import testview as tv
        self.assertEqual(tv.run_verdict(record),
                         "===== 1 failed, 1 passed in 0.10s =====")
        self.assertEqual(view.test_tally_label.text(), "2 run · 1 failed")
        # The Run window's own pane got the same stream, untouched.
        # G6 adaptation: the transcript is blocks_text() now.
        # Invariant kept: the Run window's surface holds the same
        # streamed line the testing room tallied.
        self.assertIn("1 failed, 1 passed",
                      self.win.run_win.blocks_text())

    def test_stop_files_the_run_as_stopped(self):
        self.win.start_run("sleep 30", str(self.root))
        view = self.win.testing_win
        self.assertTrue(self._pump_until(
            lambda: view.run_log.current is not None))
        self.assertEqual(view.test_status_label.text(), "running…")
        self.assertTrue(view.test_stop_btn.isEnabled())
        self.win.stop_run()
        self.assertTrue(self._pump_until(self._settled))
        record = view.run_log.history[-1]
        self.assertTrue(record["stopped"])
        self.assertEqual(view.test_status_label.text(), "stopped")


class TurnTimelineDataTests(unittest.TestCase):
    """Item C9 (data half): the timeline is a pairing of the event
    log's own turn records — request opens a turn, turn_complete
    closes it with the worker's numbers, error closes it without
    them. Seeded records in, entries out: the numbers must be the
    records' numbers, and anything unrecorded must be ABSENT,
    never zero-filled."""

    MODEL = "maternion/minicpm5-heretic:2b"

    def _rec(self, kind, **fields):
        record = {"ts": "2026-11-09T14:02:11", "kind": kind}
        record.update(fields)
        return record

    def test_entries_match_the_records(self):
        from forge import timeline as timeline_mod
        records = [
            self._rec("request", model=self.MODEL, prompt="build it"),
            self._rec("tool_call", tool="write_file"),
            self._rec("turn_complete", model=self.MODEL, seconds=83.5,
                      generations=3, prompt_tokens=1240, eval_tokens=312),
            self._rec("request", model=self.MODEL, prompt="fix it"),
            self._rec("error", model=self.MODEL, error="boom"),
        ]
        entries = timeline_mod.turn_entries(records)
        self.assertEqual(len(entries), 2)
        first, second = entries
        self.assertEqual(first["outcome"], "finished")
        self.assertEqual(first["seconds"], 83.5)
        self.assertEqual(first["generations"], 3)
        self.assertEqual(first["prompt_tokens"], 1240)
        self.assertEqual(first["eval_tokens"], 312)
        self.assertEqual(first["model"], self.MODEL)
        self.assertEqual(first["prompt"], "build it")
        self.assertEqual(first["started"], "2026-11-09T14:02:11")
        self.assertEqual(second["outcome"], "failed")
        self.assertIsNone(second["prompt_tokens"])
        self.assertIsNone(second["eval_tokens"])
        self.assertIsNone(second["seconds"])

    def test_unclosed_request_is_dropped_not_fabricated(self):
        from forge import timeline as timeline_mod
        records = [
            self._rec("request", model=self.MODEL, prompt="lost turn"),
            self._rec("request", model=self.MODEL, prompt="real turn"),
            self._rec("turn_complete", model=self.MODEL, seconds=1.0,
                      generations=1, prompt_tokens=10, eval_tokens=5),
        ]
        entries = timeline_mod.turn_entries(records)
        self.assertEqual(len(entries), 1)
        self.assertEqual(entries[0]["prompt"], "real turn")

    def test_orphan_turn_complete_still_counts(self):
        from forge import timeline as timeline_mod
        entries = timeline_mod.turn_entries([
            self._rec("turn_complete", model=self.MODEL, seconds=2.0,
                      generations=1, prompt_tokens=7, eval_tokens=3)])
        self.assertEqual(len(entries), 1)
        self.assertEqual(entries[0]["prompt_tokens"], 7)
        self.assertIsNone(entries[0]["started"])

    def test_rollups_sum_present_fields_only(self):
        from forge import timeline as timeline_mod
        records = [
            self._rec("request", model=self.MODEL, prompt="a"),
            self._rec("turn_complete", model=self.MODEL, seconds=10.0,
                      generations=2, prompt_tokens=100, eval_tokens=40),
            self._rec("request", model=self.MODEL, prompt="b"),
            self._rec("error", model=self.MODEL, error="x"),
            self._rec("request", model=self.MODEL, prompt="c"),
            self._rec("turn_complete", model=self.MODEL, seconds=5.0,
                      generations=1, prompt_tokens=50),
        ]
        totals = timeline_mod.rollups(timeline_mod.turn_entries(records))
        self.assertEqual(totals["turns"], 3)
        self.assertEqual(totals["prompt_tokens"], 150)
        self.assertEqual(totals["eval_tokens"], 40)
        self.assertEqual(totals["total_tokens"], 190)
        self.assertEqual(totals["seconds"], 15.0)
        self.assertEqual(totals["generations"], 3)

    def test_conversation_entries_select_in_order_and_merge_marks(self):
        from forge import timeline as timeline_mod
        records = [
            self._rec("request", model=self.MODEL, prompt="alpha"),
            self._rec("turn_complete", model=self.MODEL, seconds=1.0,
                      generations=1, prompt_tokens=10, eval_tokens=5),
            self._rec("request", model=self.MODEL, prompt="beta"),
            self._rec("turn_complete", model=self.MODEL, seconds=2.0,
                      generations=1, prompt_tokens=20, eval_tokens=6),
            self._rec("request", model=self.MODEL, prompt="alpha"),
            self._rec("turn_complete", model=self.MODEL, seconds=3.0,
                      generations=2, prompt_tokens=30, eval_tokens=7),
        ]
        marks = [
            {"prompt": "alpha", "model": self.MODEL, "mode": "code",
             "outcome": "finished"},
            {"prompt": "alpha", "model": self.MODEL, "mode": "plan",
             "outcome": "stopped"},
        ]
        picked = timeline_mod.conversation_entries(records, marks)
        self.assertEqual(len(picked), 2)
        self.assertEqual(picked[0]["prompt_tokens"], 10)
        self.assertEqual(picked[0]["mode"], "code")
        self.assertEqual(picked[0]["outcome"], "finished")
        # The second mark takes the SECOND alpha (in order), and
        # the settle signal's "stopped" overrides the log's plain
        # turn_complete — the log alone cannot tell them apart.
        self.assertEqual(picked[1]["prompt_tokens"], 30)
        self.assertEqual(picked[1]["mode"], "plan")
        self.assertEqual(picked[1]["outcome"], "stopped")

    def test_unmatched_marks_are_absent_not_zero_filled(self):
        from forge import timeline as timeline_mod
        marks = [{"prompt": "never ran", "model": self.MODEL,
                  "mode": "code", "outcome": "finished"}]
        picked = timeline_mod.conversation_entries([], marks)
        self.assertEqual(picked, [])
        totals = timeline_mod.rollups(picked)
        self.assertEqual(totals["turns"], 0)
        self.assertEqual(totals["total_tokens"], 0)

    def test_read_records_streams_day_files_and_skips_garbage(self):
        from forge import timeline as timeline_mod
        with tempfile.TemporaryDirectory() as td:
            log_dir = Path(td)
            (log_dir / "forge-20260101.jsonl").write_text(
                json.dumps({"kind": "request", "n": 1}) + "\n"
                + "not json at all\n"
                + json.dumps(["a", "list"]) + "\n",
                encoding="utf-8")
            (log_dir / "forge-20260102.jsonl").write_text(
                json.dumps({"kind": "turn_complete", "n": 2}) + "\n",
                encoding="utf-8")
            (log_dir / "unrelated.txt").write_text("ignore me",
                                                   encoding="utf-8")
            records = timeline_mod.read_records(log_dir)
            self.assertEqual([r["n"] for r in records], [1, 2])

    def test_default_soft_budget_is_the_named_constant(self):
        from forge import timeline as timeline_mod
        self.assertEqual(timeline_mod.DEFAULT_SOFT_TOKEN_BUDGET, 200_000)


class TurnTimelineWindowTests(unittest.TestCase):
    """Item C9 (window half): settle marks land through the same
    hook the two settle dispatchers call; the timeline pairs them
    with the log records the production EventLog wrote; the soft
    budget announces exactly once per crossing, re-arms when the
    owner raises it, and never blocks a send."""

    MODEL = "maternion/minicpm5-heretic:2b"

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()
        if cls.win.model_combo.findText(cls.MODEL) < 0:
            cls.win.model_combo.addItem(cls.MODEL)
        cls.win.model_combo.setCurrentIndex(
            cls.win.model_combo.findText(cls.MODEL))

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self._real_client = self.win.client
        self._saved_budget = self.win.settings.get("soft_token_budget")
        self.win.settings.pop("soft_token_budget", None)
        self.win.worker = None
        self.win._fold_thread = None
        self.win.messages = []
        self.win._turn_marks = {}
        self.win._soft_budget_announced = {}
        self.win._log_lines = []
        self.cid = self.win.store.save(
            None, [{"role": "user", "content": "seed"}],
            model=None, project=None)
        self.win.conversation_id = self.cid
        _GateWorker.instances = []

    def tearDown(self):
        self.win.client = self._real_client
        if self._saved_budget is None:
            self.win.settings.pop("soft_token_budget", None)
        else:
            self.win.settings["soft_token_budget"] = self._saved_budget
        self.win.worker = None
        if self.win.timeline_win is not None:
            self.win.timeline_win.hide()
        self.temp.cleanup()

    # --- seeding: records through the production writer, marks
    # through the production settle hook ---
    def _seed_turn(self, prompt, prompt_tokens, eval_tokens,
                   seconds=10.0, generations=1):
        self.win.eventlog.record("request", model=self.MODEL,
                                 prompt=prompt)
        self.win.eventlog.record(
            "turn_complete", model=self.MODEL, seconds=seconds,
            generations=generations, prompt_tokens=prompt_tokens,
            eval_tokens=eval_tokens)

    def _settle(self, prompt, outcome="finished", mode="code",
                side=False):
        stream = {"conversation_id": self.cid, "prompt": prompt,
                  "model": self.MODEL, "mode": mode,
                  "worker": None, "side": side}
        self.win._note_turn_settled(stream, outcome)

    def _budget_lines(self):
        return [l for l in self.win._log_lines if "soft budget" in l]

    def test_timeline_data_pairs_marks_with_records(self):
        self._seed_turn("first ask", 600, 300)
        self._settle("first ask")
        self._seed_turn("second ask", 400, 200, seconds=5.0)
        self._settle("second ask", outcome="stopped", mode="plan")
        data = self.win.timeline_data(self.cid)
        self.assertEqual(len(data["entries"]), 2)
        first, second = data["entries"]
        self.assertEqual(first["prompt_tokens"], 600)
        self.assertEqual(first["eval_tokens"], 300)
        self.assertEqual(first["outcome"], "finished")
        self.assertEqual(first["mode"], "code")
        self.assertEqual(second["outcome"], "stopped")
        self.assertEqual(second["mode"], "plan")
        totals = data["rollups"]
        self.assertEqual(totals["turns"], 2)
        self.assertEqual(totals["total_tokens"], 1500)
        self.assertEqual(totals["seconds"], 15.0)
        self.assertFalse(data["over"])

    def test_budget_alert_fires_once_and_rearms_on_raise(self):
        self.win.settings["soft_token_budget"] = 1000
        self._seed_turn("one", 500, 200)
        self._settle("one")
        self.assertEqual(self._budget_lines(), [])
        self._seed_turn("two", 400, 100)
        self._settle("two")
        lines = self._budget_lines()
        self.assertEqual(len(lines), 1)
        self.assertIn("≈1,200 tokens (soft budget 1,000)", lines[0])
        # Still over, same budget: no second announcement.
        self._seed_turn("three", 10, 0)
        self._settle("three")
        self.assertEqual(len(self._budget_lines()), 1)
        # The owner raises the budget: re-armed. Crossing the NEW
        # value announces again, naming the new numbers.
        self.win.settings["soft_token_budget"] = 2000
        self._seed_turn("four", 800, 100)
        self._settle("four")
        lines = self._budget_lines()
        self.assertEqual(len(lines), 2)
        self.assertIn("≈2,110 tokens (soft budget 2,000)", lines[1])

    def test_new_conversation_starts_unannounced(self):
        self.win.settings["soft_token_budget"] = 1000
        self._seed_turn("one", 900, 200)
        self._settle("one")
        self.assertEqual(len(self._budget_lines()), 1)
        other = self.win.store.save(
            None, [{"role": "user", "content": "fresh"}],
            model=None, project=None)
        self.win.conversation_id = other
        self.cid = other
        self._seed_turn("fresh ask", 50, 10)
        self._settle("fresh ask")
        self.assertEqual(len(self._budget_lines()), 1)

    def test_side_chat_turns_leave_no_mark(self):
        self._seed_turn("fork question", 10, 5)
        self._settle("fork question", side=True)
        self.assertEqual(self.win._turn_marks.get(self.cid), None)
        data = self.win.timeline_data(self.cid)
        self.assertEqual(data["entries"], [])

    def test_alert_never_blocks_a_send(self):
        from unittest import mock
        import forge.main as main_mod
        self.win.settings["soft_token_budget"] = 1000
        self._seed_turn("big ask", 900, 200)
        self._settle("big ask")
        self.assertEqual(
            self.win._soft_budget_announced.get(self.cid), 1000)
        self.win.client = _FoldClient()
        self.win.messages = [{"role": "user", "content": "earlier"}]
        self.win.input.setPlainText("keep going")
        with mock.patch.object(main_mod, "AgentWorker", _GateWorker):
            self.win.send_message()
        self.assertEqual(len(_GateWorker.instances), 1)
        self.assertFalse(getattr(self.win, "_send_refusal", None))

    def test_timeline_window_empty_then_populated(self):
        self.win.open_timeline()
        win = self.win.timeline_win
        try:
            self.assertIn("no turns recorded", win.head.text())
            self.assertEqual(win.rows_list.count(), 1)
            self._seed_turn("ask", 120, 30)
            self._settle("ask")
            win.refresh()
            self.assertEqual(win.rows_list.count(), 1)
            self.assertIn("≈150 estimated tokens", win.head.text())
            self.assertIn("Soft budget: 200,000", win.head.text())
            row = win.rows_list.item(0).text()
            self.assertIn("finished", row)
            self.assertIn("≈120 in / ≈30 out (estimated)", row)
        finally:
            win.hide()

    def test_settings_dialog_carries_the_soft_budget(self):
        from forge.main import SettingsDialog
        dlg = SettingsDialog(None, {"soft_token_budget": 123456})
        try:
            # A stored value rides through the dialog into values().
            self.assertEqual(dlg.soft_token_budget.value(), 123456)
            dlg.soft_token_budget.setValue(222000)
            self.assertEqual(dlg.values()["soft_token_budget"], 222000)
        finally:
            dlg.close()
        dlg2 = SettingsDialog(None, {})
        try:
            self.assertEqual(dlg2.values()["soft_token_budget"], 200_000)
        finally:
            dlg2.close()



class ResizablePanelsTests(unittest.TestCase):
    """Resizable panels (owner's order, 2026-11-10): the main
    window's sidebar and inspector used to be setFixedWidth — the
    owner could not widen a panel to read what was in it. The three
    columns now ride a QSplitter whose widths persist through
    forge/layout.py alongside the rest of the Note 24 layout state.
    Defaults are the old fixed widths, so an untouched bench opens
    pixel-identical."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()
        cls.win.show()
        cls.app.processEvents()

    @classmethod
    def tearDownClass(cls):
        # Leave the shared settings file at the default widths —
        # later classes construct their own windows from it.
        try:
            cls.win.main_splitter.setSizes([244, 800, 268])
            cls.win._save_layout()
        except Exception:
            pass
        cls.win.close()
        cls.app.processEvents()

    def setUp(self):
        # Hermetic geometry: whatever state earlier classes left in
        # the shared settings file (a collapsed sidebar, saved panel
        # widths), every test here starts from a visible sidebar at
        # the default widths, fully laid out.
        if not self.win.sidebar.isVisible():
            self.win.set_sidebar_collapsed(False)
        self.win.settings.pop("layout_panel_sizes", None)
        self.win._apply_panel_sizes([244, 268])
        self._settle()

    def _pump(self):
        for _ in range(5):
            self.app.processEvents()

    def _settle(self, win=None):
        # Pump until the splitter reaches the window's full width —
        # under suite load a fixed number of event pumps can return
        # before the first layout pass lands, and geometry
        # assertions would read the pre-show sizes.
        win = win or self.win
        splitter = win.main_splitter
        for _ in range(100):
            self.app.processEvents()
            if splitter.width() >= win.width() - 20:
                break

    # ---------- layout.py rules ----------

    def test_panel_sizes_default_to_the_old_fixed_widths(self):
        from forge import layout as layout_mod
        self.assertEqual(layout_mod.read_layout({})["panel_sizes"], [244, 268])
        self.assertEqual(layout_mod.read_layout(None)["panel_sizes"], [244, 268])

    def test_panel_sizes_sanitize_junk_and_clamp(self):
        from forge import layout as layout_mod
        read = layout_mod.read_layout
        self.assertEqual(read({"layout_panel_sizes": "junk"})["panel_sizes"],
                         [244, 268])
        self.assertEqual(read({"layout_panel_sizes": [300]})["panel_sizes"],
                         [244, 268])
        self.assertEqual(read({"layout_panel_sizes": [True, "x"]})["panel_sizes"],
                         [244, 268])
        # Below the floors and past the ceilings: clamped, never trusted.
        self.assertEqual(read({"layout_panel_sizes": [5, 99999]})["panel_sizes"],
                         [180, 900])
        self.assertEqual(read({"layout_panel_sizes": [300.9, 320]})["panel_sizes"],
                         [300, 320])

    def test_write_layout_without_sizes_keeps_the_stored_pair(self):
        from forge import layout as layout_mod
        settings = {"layout_panel_sizes": [350, 360]}
        layout_mod.write_layout(settings, {"sidebar_collapsed": False,
                                           "accordions": {}, "docks": []})
        self.assertEqual(settings["layout_panel_sizes"], [350, 360])

    # ---------- the splitter itself ----------

    def test_columns_live_in_a_splitter(self):
        from PySide6.QtWidgets import QSplitter
        splitter = self.win.main_splitter
        self.assertIsInstance(splitter, QSplitter)
        self.assertEqual(splitter.count(), 3)
        self.assertIs(splitter.widget(0), self.win.sidebar)
        self.assertIs(splitter.widget(2), self.win.inspector)
        # Neither panel is fixed any more; both carry their floors.
        self.assertEqual(self.win.sidebar.minimumWidth(), 180)
        self.assertEqual(self.win.inspector.minimumWidth(), 200)
        self.assertGreater(self.win.sidebar.maximumWidth(), 10000)
        self.assertGreater(self.win.inspector.maximumWidth(), 10000)

    def test_default_sizes_equal_the_old_fixed_widths(self):
        from forge import layout as layout_mod
        self.win.settings.pop("layout_panel_sizes", None)
        defaults = layout_mod.read_layout(self.win.settings)["panel_sizes"]
        self.win._apply_panel_sizes(defaults)
        self._settle()
        sizes = self.win.main_splitter.sizes()
        self.assertEqual(sizes[0], 244)
        self.assertEqual(sizes[2], 268)

    def test_set_sizes_actually_changes_panel_widths(self):
        splitter = self.win.main_splitter
        splitter.setSizes([420, splitter.width() - 420 - 380 - 12, 380])
        self._settle()
        self.assertEqual(self.win.sidebar.width(), 420)
        self.assertEqual(self.win.inspector.width(), 380)
        self.assertEqual(splitter.sizes()[0], 420)
        self.assertEqual(splitter.sizes()[2], 380)

    def test_minimum_widths_hold_under_set_sizes(self):
        splitter = self.win.main_splitter
        splitter.setSizes([40, splitter.width(), 40])
        self._settle()
        self.assertGreaterEqual(self.win.sidebar.width(), 180)
        self.assertGreaterEqual(self.win.inspector.width(), 200)

    def test_persistence_round_trip_through_the_real_settings_path(self):
        from forge.main import ForgeWindow
        splitter = self.win.main_splitter
        splitter.setSizes([420, splitter.width() - 420 - 380 - 12, 380])
        self._settle()
        self.win._save_layout()
        self.assertEqual(self.win.settings.get("layout_panel_sizes"), [420, 380])
        win2 = ForgeWindow()
        try:
            win2.show()
            self._settle(win2)
            sizes = win2.main_splitter.sizes()
            self.assertEqual(sizes[0], 420)
            self.assertEqual(sizes[2], 380)
        finally:
            win2.close()
            self._pump()

    def test_corrupt_saved_state_falls_back_to_defaults(self):
        from forge import layout as layout_mod
        for junk in ("junk", [5, 99999, 3], [None, None], 42):
            state = layout_mod.read_layout({"layout_panel_sizes": junk})
            side, insp = state["panel_sizes"]
            self.assertGreaterEqual(side, 180)
            self.assertLessEqual(side, 900)
            self.assertGreaterEqual(insp, 200)
            self.assertLessEqual(insp, 900)
        self.win._apply_panel_sizes(
            layout_mod.read_layout({"layout_panel_sizes": "junk"})["panel_sizes"])
        self._settle()
        sizes = self.win.main_splitter.sizes()
        self.assertEqual(sizes[0], 244)
        self.assertEqual(sizes[2], 268)

    def test_collapsing_the_sidebar_does_not_eat_its_width(self):
        splitter = self.win.main_splitter
        splitter.setSizes([420, splitter.width() - 420 - 380 - 12, 380])
        self._settle()
        self.win.set_sidebar_collapsed(True)
        self._pump()
        self.assertEqual(self.win._panel_sizes_state()[0], 420)
        self.win.set_sidebar_collapsed(False)
        self._pump()
        self.assertEqual(self.win.sidebar.width(), 420)

    # ---------- the size-lock audit ----------

    def test_content_windows_are_not_size_locked(self):
        from forge.main import PaletteDialog, UiBuilderDialog
        attached = ["plan_win", "artifacts_win", "sessions_win",
                    "privacy_win", "notes_win", "sees_win", "models_win",
                    "mission_win", "templates_win", "provider_chat_win",
                    "run_win", "debug_win"]
        wins = [getattr(self.win, name) for name in attached]
        wins.append(UiBuilderDialog(self.win, self.win.workspace))
        wins.append(PaletteDialog(self.win, [], lambda _id: None))
        for win in wins:
            self.assertGreater(win.maximumWidth(), win.minimumWidth(),
                               f"{win.__class__.__name__} width is locked")
            self.assertGreater(win.maximumHeight(), win.minimumHeight(),
                               f"{win.__class__.__name__} height is locked")
        # The UI Builder's canvas keeps its designed size — that IS
        # its function (a WYSIWYG mirror) — while its dialog resizes
        # and the canvas scrolls inside it.
        builder = wins[-2]
        self.assertEqual(builder.canvas.width(), builder.design["width"])
        self.assertEqual(builder.canvas.height(), builder.design["height"])


class DesignCanvasModelTests(unittest.TestCase):
    """Item C5, the board model (forge/design_canvas.py): pure
    data — sanitization of whatever lands in canvas.json (the
    agent can write that file through the ordinary tools, so it
    is never trusted), the frame operations incl. variant
    lineage, persistence, the generated summary, excerpts, and
    the bench-prompt composition. No Qt in this layer."""

    def setUp(self):
        from forge import design_canvas as dc
        self.dc = dc
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)

    def tearDown(self):
        self.temp.cleanup()

    def test_sanitize_drops_junk_and_clamps_geometry(self):
        dc = self.dc
        raw = {"version": 1, "seq": 3, "frames": [
            "not a frame",
            {"kind": "artifact", "title": "no id"},
            {"id": "a", "kind": "artifact", "title": "One",
             "x": -50, "y": 99999, "w": 10, "h": 99999, "z": 5},
            {"id": "a", "kind": "note", "title": "duplicate id"},
            {"id": "b", "kind": "portal", "title": "bad kind",
             "x": 20, "y": 20, "w": 300, "h": 200, "z": 1},
        ]}
        board = dc.sanitize_board(raw)
        ids = [f["id"] for f in board["frames"]]
        self.assertEqual(ids, ["b", "a"])  # z order, junk dropped
        a = dc.get_frame(board, "a")
        self.assertEqual(a["x"], 0)                       # clamped in
        self.assertEqual(a["y"], dc.BOARD_H - dc.MIN_H)   # clamped in
        self.assertEqual(a["w"], dc.MIN_W)                # clamped up
        self.assertEqual(a["h"], dc.MAX_H)                # clamped down
        b = dc.get_frame(board, "b")
        self.assertEqual(b["kind"], "note")  # unknown kind -> note
        self.assertEqual([f["z"] for f in board["frames"]], [0, 1])

    def test_sanitize_drops_dangling_links_and_lineage(self):
        dc = self.dc
        raw = {"frames": [
            {"id": "a", "kind": "note",
             "links": ["ghost", "a", "b", "b"]},
            {"id": "b", "kind": "variant", "derived_from": "ghost"},
            {"id": "c", "kind": "variant", "derived_from": "c"},
            {"id": "d", "kind": "variant", "derived_from": "a"},
        ]}
        board = dc.sanitize_board(raw)
        self.assertEqual(dc.get_frame(board, "a")["links"], ["b"])
        self.assertEqual(dc.get_frame(board, "b")["derived_from"], "")
        self.assertEqual(dc.get_frame(board, "c")["derived_from"], "")
        self.assertEqual(dc.get_frame(board, "d")["derived_from"], "a")

    def test_sanitize_drops_escaping_file_refs(self):
        dc = self.dc
        for bad in ("/etc/passwd", "../secret.txt", "a/../../b.txt",
                    "C:/windows/x.txt", "\\\\server\\share\\f.txt", ""):
            board = dc.sanitize_board({"frames": [
                {"id": "a", "kind": "artifact", "file": bad}]})
            self.assertEqual(
                dc.get_frame(board, "a")["file"], "", bad)
        board = dc.sanitize_board({"frames": [
            {"id": "a", "kind": "artifact",
             "file": "pages\\landing.html"}]})
        self.assertEqual(dc.get_frame(board, "a")["file"],
                         "pages/landing.html")

    def test_sanitize_labels_are_closed_vocabulary(self):
        dc = self.dc
        board = dc.sanitize_board({"frames": [
            {"id": "a", "kind": "variant", "viewport": "watch",
             "state": "weird"},
            {"id": "b", "kind": "variant", "viewport": "phone",
             "state": "hover"}]})
        a, b = dc.get_frame(board, "a"), dc.get_frame(board, "b")
        self.assertEqual((a["viewport"], a["state"]), ("", ""))
        self.assertEqual((b["viewport"], b["state"]), ("phone", "hover"))

    def test_persistence_round_trip_identical(self):
        dc = self.dc
        board = dc.empty_board()
        a = dc.add_frame(board, "artifact", title="Landing",
                         file="pages/landing.html")
        n = dc.add_frame(board, "note", title="Idea", note="Try ember")
        v = dc.duplicate_as_variant(board, a["id"])
        dc.set_links(board, a["id"], [n["id"]])
        saved = dc.save_board(str(self.root), board)
        self.assertTrue(dc.canvas_path(str(self.root)).is_file())
        loaded = dc.load_board(str(self.root))
        self.assertEqual(loaded, saved)
        self.assertEqual(dc.get_frame(loaded, v["id"])["derived_from"],
                         a["id"])

    def test_load_absent_and_corrupt_are_empty_boards(self):
        dc = self.dc
        self.assertEqual(dc.load_board(str(self.root))["frames"], [])
        path = dc.canvas_path(str(self.root))
        path.parent.mkdir(parents=True)
        path.write_text("{not json", encoding="utf-8")
        self.assertEqual(dc.load_board(str(self.root))["frames"], [])
        path.write_text('["a", "list"]', encoding="utf-8")
        self.assertEqual(dc.load_board(str(self.root))["frames"], [])

    def test_frame_operations(self):
        dc = self.dc
        board = dc.empty_board()
        f = dc.add_frame(board, "artifact", title="A", file="a.html")
        dc.move_frame(board, f["id"], 5000, -10)
        self.assertEqual((f["x"], f["y"]),
                         (dc.BOARD_W - dc.MIN_W, 0))
        dc.resize_frame(board, f["id"], 10, 5000)
        self.assertEqual((f["w"], f["h"]), (dc.MIN_W, dc.MAX_H))
        dc.rename_frame(board, f["id"], "Renamed")
        self.assertEqual(f["title"], "Renamed")
        dc.set_note(board, f["id"], "hello")
        self.assertEqual(f["note"], "hello")
        dc.set_file(board, f["id"], "../evil.txt")
        self.assertEqual(f["file"], "")  # escaping ref refused by op too
        dc.set_labels(board, f["id"], viewport="tablet", state="focus")
        self.assertEqual((f["viewport"], f["state"]), ("tablet", "focus"))
        dc.set_labels(board, f["id"], viewport="junk")
        self.assertEqual(f["viewport"], "")
        self.assertIsNone(dc.move_frame(board, "ghost", 0, 0))

    def test_duplicate_as_variant_lineage(self):
        dc = self.dc
        board = dc.empty_board()
        src = dc.add_frame(board, "artifact", title="Home",
                           file="home.html", x=100, y=100)
        var = dc.duplicate_as_variant(board, src["id"])
        self.assertEqual(var["kind"], "variant")
        self.assertEqual(var["derived_from"], src["id"])
        self.assertEqual(var["file"], "home.html")
        self.assertEqual(var["viewport"], "desktop")
        self.assertEqual(var["state"], "default")
        self.assertEqual((var["x"], var["y"]), (132, 132))
        self.assertIn("variant", var["title"])
        self.assertEqual(src["kind"], "artifact")  # source untouched
        var2 = dc.duplicate_as_variant(board, var["id"])
        self.assertEqual(var2["derived_from"], var["id"])  # chain link
        self.assertIsNone(dc.duplicate_as_variant(board, "ghost"))

    def test_delete_clears_references(self):
        dc = self.dc
        board = dc.empty_board()
        a = dc.add_frame(board, "artifact", title="A", file="a.html")
        b = dc.add_frame(board, "artifact", title="B", file="b.html")
        c = dc.duplicate_as_variant(board, b["id"])
        dc.set_links(board, a["id"], [b["id"]])
        self.assertTrue(dc.delete_frame(board, b["id"]))
        self.assertEqual(a["links"], [])
        self.assertEqual(c["derived_from"], "")
        self.assertIsNone(dc.get_frame(board, b["id"]))
        self.assertFalse(dc.delete_frame(board, b["id"]))

    def test_z_order_front_and_back(self):
        dc = self.dc
        board = dc.empty_board()
        a = dc.add_frame(board, "note", title="A")
        b = dc.add_frame(board, "note", title="B")
        c = dc.add_frame(board, "note", title="C")
        dc.bring_to_front(board, a["id"])
        order = [f["id"] for f in sorted(
            board["frames"], key=lambda f: f["z"])]
        self.assertEqual(order, [b["id"], c["id"], a["id"]])
        dc.send_to_back(board, a["id"])
        order = [f["id"] for f in sorted(
            board["frames"], key=lambda f: f["z"])]
        self.assertEqual(order, [a["id"], b["id"], c["id"]])
        self.assertEqual([f["z"] for f in sorted(
            board["frames"], key=lambda f: f["z"])], [0, 1, 2])

    def test_summary_text_covers_frames_and_lineage(self):
        dc = self.dc
        board = dc.empty_board()
        a = dc.add_frame(board, "artifact", title="Landing",
                         file="pages/landing.html")
        dc.add_frame(board, "note", title="Idea", note="Ember trail")
        dc.duplicate_as_variant(board, a["id"])
        text = dc.summary_text(board, "demo")
        self.assertIn("# Design canvas — demo", text)
        self.assertIn("1 artifact, 1 note, 1 variant", text)
        self.assertIn("pages/landing.html", text)
        self.assertIn("variant of: Landing", text)
        self.assertIn("Ember trail", text)
        empty = dc.summary_text(dc.empty_board(), "demo")
        self.assertIn("The board is empty.", empty)

    def test_save_summary_writes_markdown(self):
        dc = self.dc
        board = dc.empty_board()
        dc.add_frame(board, "note", title="Only")
        path = dc.save_summary(str(self.root), board, "demo")
        self.assertTrue(path.is_file())
        self.assertEqual(path.name, "canvas-summary.md")
        self.assertIn("Design canvas — demo",
                      path.read_text(encoding="utf-8"))

    def test_compose_bench_prompt(self):
        dc = self.dc
        board = dc.empty_board()
        a = dc.add_frame(board, "artifact", title="Landing",
                         file="pages/landing.html")
        v = dc.duplicate_as_variant(board, a["id"])
        prompt = dc.compose_bench_prompt(board, v, "<html>head</html>")
        self.assertIn("[DESIGN CANVAS]", prompt)
        self.assertIn("pages/landing.html", prompt)
        self.assertIn('variant of "Landing"', prompt)
        self.assertIn("viewport: desktop", prompt)
        self.assertIn("<html>head</html>", prompt)
        self.assertIn(".forge/design/canvas.json", prompt)

    def test_frame_excerpt_reads_head_and_missing_is_empty(self):
        dc = self.dc
        (self.root / "page.html").write_text(
            "x" * 5000, encoding="utf-8")
        frame = {"id": "a", "kind": "artifact", "file": "page.html",
                 "note": ""}
        excerpt = dc.frame_excerpt(str(self.root), frame)
        self.assertEqual(len(excerpt), dc.EXCERPT_CAP)
        gone = {"id": "b", "kind": "artifact", "file": "nope.html",
                "note": ""}
        self.assertEqual(dc.frame_excerpt(str(self.root), gone), "")
        note = {"id": "c", "kind": "note", "file": "",
                "note": "remember the ember"}
        self.assertEqual(dc.frame_excerpt(str(self.root), note),
                         "remember the ember")


class DesignCanvasAgentFileTests(unittest.TestCase):
    """Item C5, agent integration: the board is a project file.
    The agent reads and revises .forge/design/canvas.json
    through the ORDINARY file tools — proven here through
    forge.tools.execute_tool itself, the engine under the
    worker's gate. There is no canvas tool and no other path."""

    def setUp(self):
        from forge import design_canvas as dc
        self.dc = dc
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)

    def tearDown(self):
        self.temp.cleanup()

    def test_agent_round_trip_through_file_tools(self):
        dc = self.dc
        board = dc.empty_board()
        dc.add_frame(board, "artifact", title="Landing",
                     file="pages/landing.html")
        payload = json.dumps(dc.sanitize_board(board))
        result = execute_tool(
            "write_file",
            {"path": ".forge/design/canvas.json", "content": payload},
            str(self.root))
        self.assertIn("Wrote", result)
        loaded = dc.load_board(str(self.root))
        self.assertEqual(len(loaded["frames"]), 1)
        # The agent revises with edit_file; the window's load
        # path sees the revision.
        execute_tool(
            "edit_file",
            {"path": ".forge/design/canvas.json",
             "old_text": '"Landing"', "new_text": '"Homepage"'},
            str(self.root))
        text = execute_tool(
            "read_file", {"path": ".forge/design/canvas.json"},
            str(self.root))
        self.assertIn("Homepage", text)
        self.assertEqual(
            dc.load_board(str(self.root))["frames"][0]["title"],
            "Homepage")

    def test_agent_written_junk_is_sanitized_on_load(self):
        dc = self.dc
        junk = {"frames": [
            {"id": "x", "kind": "artifact", "file": "../../etc/passwd",
             "x": -5, "links": ["nobody"]},
            {"no": "id"}]}
        execute_tool(
            "write_file",
            {"path": ".forge/design/canvas.json",
             "content": json.dumps(junk)},
            str(self.root))
        loaded = dc.load_board(str(self.root))
        self.assertEqual(len(loaded["frames"]), 1)
        frame = loaded["frames"][0]
        self.assertEqual(frame["file"], "")
        self.assertEqual(frame["links"], [])
        self.assertEqual(frame["x"], 0)


class DesignCanvasWindowTests(unittest.TestCase):
    """Item C5, the room itself: it exists hidden from startup,
    opens as a single instance from the menus / palette, a
    project with no board opens empty without error, operations
    persist to .forge/design/canvas.json, the summary files as
    a design artifact through the ordinary path, and "send
    frame to bench" composes a normal turn (composition proven
    with send_message stubbed — the turn machinery itself is
    the worker tests' ground)."""

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        from forge import design_canvas as dc
        self.dc = dc
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        self.win.workspace = str(self.root)
        self.view = self.win.design_canvas_win
        self.view.selected_id = None
        self.view._loaded_workspace = None
        self.view.refresh()

    def tearDown(self):
        self.view.close()
        self.temp.cleanup()

    def _add(self, kind="artifact", **kw):
        frame = self.dc.add_frame(self.view.board, kind, **kw)
        self.view.selected_id = frame["id"]
        self.view._changed()
        return frame

    def test_window_exists_hidden_and_opens_single_instance(self):
        view = self.win.design_canvas_win
        self.assertIsNotNone(view)
        self.assertFalse(view.isVisible())
        self.win.open_design_canvas()
        self.app.processEvents()
        self.assertTrue(view.isVisible())
        self.win.open_design_canvas()
        self.app.processEvents()
        self.assertIs(self.win.design_canvas_win, view)
        self.assertIsNotNone(self.win.act_design_canvas)
        self.assertIsNotNone(self.win.view_act_design_canvas)
        _entries, bindings = self.win.palette_actions()
        self.assertIn("design_canvas", bindings)

    def test_header_is_the_g4_standard(self):
        view = self.win.design_canvas_win
        self.assertEqual(view.header.title_label.text(),
                         "Design Canvas — Code Forge")
        labels = [a.text() for a in view.header.overflow_menu.actions()]
        self.assertIn("Refresh", labels)
        self.assertIn("File summary as design artifact", labels)
        self.assertIn("Send frame to bench", labels)

    def test_board_absent_opens_empty_without_error(self):
        view = self.win.design_canvas_win
        self.assertEqual(view.board["frames"], [])
        self.assertEqual(view.frames_list.count(), 0)
        self.assertIn("0 frame(s)", view.status_label.text())
        view.show()
        self.app.processEvents()
        self.assertTrue(view.isVisible())

    def test_operations_persist_to_canvas_json(self):
        frame = self._add("artifact", title="Landing",
                          file="pages/landing.html")
        on_disk = self.dc.load_board(str(self.root))
        self.assertEqual(
            self.dc.get_frame(on_disk, frame["id"])["title"], "Landing")
        self.assertTrue(
            (self.root / ".forge" / "design"
             / "canvas-summary.md").is_file())
        self.view.add_variant()
        variant = self.view._selected()
        self.assertEqual(variant["kind"], "variant")
        self.assertEqual(variant["derived_from"], frame["id"])
        on_disk = self.dc.load_board(str(self.root))
        self.assertIsNotNone(self.dc.get_frame(on_disk, variant["id"]))
        self.view.front_selected()
        self.view.back_selected()
        self.view.delete_selected()
        on_disk = self.dc.load_board(str(self.root))
        self.assertIsNone(self.dc.get_frame(on_disk, variant["id"]))
        self.assertIsNotNone(self.dc.get_frame(on_disk, frame["id"]))

    def test_project_switch_reloads_board(self):
        self._add("note", title="In A", note="aaa")
        other = Path(self.temp.name) / "b"
        other.mkdir()
        self.win.workspace = str(other)
        self.view.refresh()
        self.assertEqual(self.view.board["frames"], [])
        self.win.workspace = str(self.root)
        self.view.refresh()
        self.assertEqual(len(self.view.board["frames"]), 1)
        self.assertEqual(self.view.board["frames"][0]["title"], "In A")

    def test_variant_label_combos_write_through(self):
        self._add("artifact", title="Home", file="home.html")
        self.view.add_variant()
        variant = self.view._selected()
        self.assertTrue(self.view.viewport_combo.isEnabled())
        idx = self.view.viewport_combo.findText("phone")
        self.view.viewport_combo.setCurrentIndex(idx)
        self.app.processEvents()
        self.assertEqual(variant["viewport"], "phone")
        on_disk = self.dc.load_board(str(self.root))
        self.assertEqual(
            self.dc.get_frame(on_disk, variant["id"])["viewport"],
            "phone")

    def test_send_frame_to_bench_composes_a_normal_turn(self):
        (self.root / "home.html").write_text(
            "<html>landing</html>", encoding="utf-8")
        frame = self._add("artifact", title="Home", file="home.html")
        win = self.win
        # No model on the bench: a plain-words refusal, no turn.
        saved_items = [win.model_combo.itemText(i)
                       for i in range(win.model_combo.count())]
        win.model_combo.clear()
        try:
            ok, message = win.send_canvas_frame_to_bench(
                self.view.board, frame)
            self.assertFalse(ok)
            self.assertIn("No model selected", message)
        finally:
            win.model_combo.addItems(saved_items)
        # With a model and the send path stubbed, the composed
        # prompt is what a normal turn would carry.
        if win.model_combo.count() == 0:
            win.model_combo.addItem("fake-model")
        win.model_combo.setCurrentIndex(0)
        captured = {}
        original_send = win.send_message
        original_worker = win.worker

        def fake_send():
            captured["text"] = win.input.toPlainText()
            win._send_refusal = None
            win.worker = object()  # a NEW worker: the turn started

        win.send_message = fake_send
        try:
            ok, message = win.send_canvas_frame_to_bench(
                self.view.board, frame)
        finally:
            win.send_message = original_send
            win.worker = original_worker
        self.assertTrue(ok, message)
        self.assertIn("[DESIGN CANVAS]", captured["text"])
        self.assertIn("Home", captured["text"])
        self.assertIn("home.html", captured["text"])
        self.assertIn("<html>landing</html>", captured["text"])

    def test_file_summary_as_design_artifact(self):
        from forge import artifacts as artifacts_mod
        self._add("artifact", title="Landing",
                  file="pages/landing.html")
        self.view.file_summary_as_artifact()
        entries = artifacts_mod.list_artifacts(str(self.root))
        self.assertTrue(entries)
        self.assertEqual(entries[0]["kind"], "design")
        self.assertIn("Design canvas", entries[0]["title"])
        body = artifacts_mod.read_text(str(self.root), entries[0])
        self.assertIn("pages/landing.html", body)
        self.assertIn("filed as a design artifact",
                      self.view.status_label.text())
class _RegistryContinuityClient(_ContinuityClient):
    """The continuity script plus a provider config riding the
    client, the way the ProviderClient facade carries one — the
    worker's budget resolution reads it from there."""

    def __init__(self, config, **kwargs):
        super().__init__(**kwargs)
        self.config = config


class DynamicContextWindowTests(unittest.TestCase):
    """Dynamic context windows (2026-11-10): budgeting resolves
    per model — provider catalogs keep their stated windows, the
    registry preserves them through sanitize, locals resolve
    through /api/show with the min(trained max, setting) rule, and
    the worker folds against the DRIVER's resolved window instead
    of the one global num_ctx setting. Unknown always falls back
    to the setting; nothing ever guesses a bigger window."""

    # ---------- catalogs keep stated windows ----------

    def test_groq_catalog_keeps_context_window(self):
        from forge import providers as p

        # Context-window merge adaptation (2026-11-10): the fake
        # catalog names approved models — the provider allowlist
        # (merged before this class landed) filters unapproved
        # catalog IDs out of models() entirely, so the stand-ins
        # moved to approved IDs; what this test pins — a stated
        # window kept, a junk window dropped, an unstated window
        # absent — is unchanged.
        def fake_urlopen(req, timeout=None):
            return _ProviderFakeResponse(json.dumps({"data": [
                {"id": "openai/gpt-oss-120b", "context_window": 131072},
                {"id": "openai/gpt-oss-20b", "context_window": "lots"},
                {"id": "qwen/qwen3.8-27b"}]}))

        client = p.GroqClient("test-key", urlopen=fake_urlopen)
        models = {m["name"]: m for m in client.models()}
        self.assertEqual(
            models["groq:openai/gpt-oss-120b"]["context_window"], 131072)
        self.assertNotIn("context_window",
                         models["groq:openai/gpt-oss-20b"])
        self.assertNotIn("context_window", models["groq:qwen/qwen3.8-27b"])

    def test_gemini_catalog_keeps_input_token_limit(self):
        from forge import providers as p

        # Context-window merge adaptation (2026-11-10): the fake
        # catalog names approved models — the provider allowlist
        # filters unapproved catalog IDs out of models() entirely;
        # the pinned behavior (inputTokenLimit kept as the window,
        # absent when unstated) is unchanged.
        def fake_urlopen(req, timeout=None):
            return _ProviderFakeResponse(json.dumps({"models": [
                {"name": "models/gemini-3.8-flash",
                 "supportedGenerationMethods": ["generateContent"],
                 "inputTokenLimit": 1048576},
                {"name": "models/gemini-3.6-flash",
                 "supportedGenerationMethods": ["generateContent"]}]}))

        client = p.GeminiClient("test-key", urlopen=fake_urlopen)
        models = {m["name"]: m for m in client.models()}
        self.assertEqual(models["gemini:gemini-3.8-flash"]["context_window"],
                         1048576)
        self.assertNotIn("context_window", models["gemini:gemini-3.6-flash"])

    # ---------- registry sanitize ----------

    def test_registry_sanitize_preserves_window_drops_junk(self):
        from forge import providers as p
        raw = [
            {"id": "groq:int", "context_window": 131072},
            {"id": "groq:str", "context_window": "131072"},
            {"id": "groq:float", "context_window": 131072.0},
            {"id": "groq:word", "context_window": "lots"},
            {"id": "groq:neg", "context_window": -5},
            {"id": "groq:zero", "context_window": 0},
            {"id": "groq:bool", "context_window": True},
            {"id": "groq:none", "context_window": None},
            {"id": "groq:dict", "context_window": {"x": 1}},
        ]
        entries = {e["id"]: e
                   for e in p.sanitize_model_registry(raw)}
        self.assertEqual(entries["groq:int"]["context_window"], 131072)
        self.assertEqual(entries["groq:str"]["context_window"], 131072)
        self.assertEqual(entries["groq:float"]["context_window"], 131072)
        for bad in ("groq:word", "groq:neg", "groq:zero", "groq:bool",
                    "groq:none", "groq:dict"):
            self.assertNotIn("context_window", entries[bad])

    # ---------- the resolver ----------

    def test_resolve_local_min_rule(self):
        from forge import providers as p

        class _Local:
            def __init__(self, value):
                self._value = value

            def context_length(self, model):
                return self._value

        self.assertEqual(
            p.resolve_context_budget("local-x", client=_Local(4096),
                                     fallback=8192), 4096)
        # The setting is the owner's RAM cap: a bigger trained max
        # never raises the budget above it.
        self.assertEqual(
            p.resolve_context_budget("local-x", client=_Local(32768),
                                     fallback=8192), 8192)
        self.assertEqual(
            p.resolve_context_budget("local-x", client=_Local(None),
                                     fallback=8192), 8192)

    def test_resolve_provider_registry_stated_window_wins(self):
        from forge import providers as p
        config = {"model_registry": [
            {"id": "groq:big", "context_window": 131072},
            {"id": "groq:small", "context_window": 4096}]}
        self.assertEqual(
            p.resolve_context_budget("groq:big", config=config,
                                     fallback=8192), 131072)
        # Stated wins in the small direction too — that is the
        # direction that prevents a provider refusal.
        self.assertEqual(
            p.resolve_context_budget("groq:small", config=config,
                                     fallback=32768), 4096)

    def test_resolve_provider_catalog_cache_and_registry_order(self):
        from forge import providers as p

        # Context-window merge adaptation (2026-11-10): the fake
        # catalog and registry name an approved model — the
        # allowlist filters unapproved catalog IDs and model_allowed
        # refuses unapproved registry rows, so the pre-filter
        # stand-in ("groq:big") never reached the facade's tags();
        # the pinned ordering (registry statement outranks the
        # catalog cache) is unchanged.
        def fake_urlopen(req, timeout=None):
            return _ProviderFakeResponse(json.dumps({"data": [
                {"id": "openai/gpt-oss-120b", "context_window": 131072}]}))

        config = {"groq_api_key": "k", "model_registry": []}
        facade = p.ProviderClient("http://127.0.0.1:11434", config,
                                  urlopen=fake_urlopen)
        facade.local.tags = lambda: []
        entries = {e["name"]: e for e in facade.tags("project")}
        # The stated window rides the tags entry (Models window)
        # and is remembered for budgeting.
        self.assertEqual(
            entries["groq:openai/gpt-oss-120b"]["context_window"], 131072)
        self.assertEqual(
            facade.catalog_context_window("groq:openai/gpt-oss-120b"),
            131072)
        self.assertEqual(
            p.resolve_context_budget("groq:openai/gpt-oss-120b",
                                     config=config, client=facade,
                                     fallback=8192),
            131072)
        # A registry-stated window outranks the catalog cache: it
        # is the owner's persisted statement about the model.
        config2 = {"groq_api_key": "k", "model_registry": [
            {"id": "groq:openai/gpt-oss-120b", "context_window": 64000}]}
        self.assertEqual(
            p.resolve_context_budget("groq:openai/gpt-oss-120b",
                                     config=config2, client=facade,
                                     fallback=8192),
            64000)
        # The facade's one context_length seam routes locals to
        # the local client's own resolution.
        facade.local.context_length = lambda model: 4096
        self.assertEqual(facade.context_length("local-x"), 4096)
        self.assertEqual(
            p.resolve_context_budget("local-x", client=facade,
                                     fallback=8192), 4096)

    def test_resolve_unknown_falls_back_to_setting(self):
        from forge import providers as p
        self.assertEqual(
            p.resolve_context_budget("groq:unknown", config={},
                                     fallback=8192), 8192)
        self.assertEqual(
            p.resolve_context_budget("local-x", fallback=16384), 16384)
        self.assertEqual(
            p.resolve_context_budget("local-x", fallback="abc"), 8192)
        self.assertEqual(
            p.resolve_context_budget("local-x", fallback=0), 8192)

    # ---------- the local /api/show seam ----------

    def test_ollama_context_length_parse_and_cache(self):
        from forge.ollama_client import OllamaClient
        client = OllamaClient("http://127.0.0.1:9")
        calls = {"n": 0}

        def fake_show(model):
            calls["n"] += 1
            return {"model_info": {
                "general.architecture": "llama",
                "llama.context_length": 131072}}

        client.show = fake_show
        self.assertEqual(client.context_length("m1"), 131072)
        self.assertEqual(client.context_length("m1"), 131072)
        self.assertEqual(calls["n"], 1)  # cached per model name

        def dead_show(model):
            raise RuntimeError("server down")

        client.show = dead_show
        self.assertIsNone(client.context_length("m2"))  # never raises

    # ---------- worker budgeting ----------

    def _worker(self, client, td, log, model, messages, num_ctx=8000):
        from forge.worker import AgentWorker
        schema = {"type": "function",
                  "function": {"name": "big_tool", "description": "test",
                               "parameters": {"type": "object",
                                              "properties": {
                                                  "n": {"type": "integer"}}}}}
        hits = {"n": 0}

        def handler(args):
            hits["n"] += 1
            return "R" * 20000

        extra = {"big_tool": (schema, handler, False, "test")}
        worker = AgentWorker(client, model, messages,
                             {"num_ctx": num_ctx}, td,
                             extra_tools=extra, eventlog=log)
        return worker, hits

    def _fat_history(self):
        msgs = []
        for i in range(3):
            msgs.append({"role": "user",
                         "content": f"earlier request {i}"})
            msgs.append({"role": "assistant", "content": "A" * 16000})
        for i in range(3, 6):
            msgs.append({"role": "user",
                         "content": f"recent request {i}"})
            msgs.append({"role": "assistant", "content": "done"})
        msgs.append({"role": "user", "content": "go"})
        return msgs

    def test_worker_large_provider_window_does_not_fold_at_8k(self):
        with tempfile.TemporaryDirectory() as td:
            log = _FakeEventLog()
            config = {"model_registry": [
                {"id": "groq:big-window", "context_window": 131072}]}
            client = _RegistryContinuityClient(config)
            worker, hits = self._worker(
                client, td, log, "groq:big-window",
                messages=self._fat_history())
            finished = []
            worker.finished_text.connect(
                lambda text, msgs: finished.append(text))
            worker.run()
            # ~14k estimated tokens against a 131k stated window:
            # no fold, no budget stop — under the old law the 8k
            # setting folded this history twice.
            self.assertNotIn("context_fold_mid_turn", log.kinds())
            self.assertNotIn("context_budget_stop", log.kinds())
            self.assertEqual(hits["n"], 1)
            self.assertTrue(finished)

    def test_worker_small_provider_window_folds_earlier(self):
        with tempfile.TemporaryDirectory() as td:
            log = _FakeEventLog()
            config = {"model_registry": [
                {"id": "groq:small-window", "context_window": 3000}]}
            client = _RegistryContinuityClient(config)
            # One fat exchange plus four small ones: ~4.7k
            # estimated tokens — under the 8k setting's stop line
            # (7,200) but over the stated 3k window's (2,700). Only
            # the resolved window folds. (Five exchanges because
            # split_fold keeps the last KEEP_EXCHANGES=4 verbatim —
            # the fat one is the only span candidate.)
            messages = [
                {"role": "user", "content": "earlier request"},
                {"role": "assistant", "content": "A" * 16000},
                {"role": "user", "content": "middle request"},
                {"role": "assistant", "content": "done"},
                {"role": "user", "content": "recent request"},
                {"role": "assistant", "content": "done"},
                {"role": "user", "content": "latest request"},
                {"role": "assistant", "content": "done"},
                {"role": "user", "content": "newest request"},
                {"role": "assistant", "content": "done"},
                {"role": "user", "content": "go"}]
            worker, hits = self._worker(
                client, td, log, "groq:small-window", messages=messages)
            finished = []
            worker.finished_text.connect(
                lambda text, msgs: finished.append(text))
            worker.run()
            folds = [f for k, f in log.events
                     if k == "context_fold_mid_turn"]
            self.assertGreaterEqual(len(folds), 1)
            for fold in folds:
                self.assertEqual(fold["num_ctx"], 3000)
            self.assertNotIn("context_budget_stop", log.kinds())
            self.assertTrue(finished)


class ResendReplyTests(unittest.TestCase):
    """Resend + Reply (owner request, 2026-11-10): per-message
    anchors in the rendered bubbles (forge-resend:N on the
    owner's bubbles, forge-reply:N on his and the agent's) load
    the composer — Resend EDIT-FIRST (one of his own sent messages
    back into the box exactly as written; never an automatic
    re-send, never over an existing draft), Reply as a capped
    markdown quote block at the head of the draft with the draft
    preserved below it. Neither action sends, starts a turn,
    rewrites history, or persists — pinned here by a persist spy,
    a worker that stays None, and history compared verbatim. In a
    side chat the actions work on the fork's messages (the list
    the render is showing) and the main thread restores untouched
    on close, like every other side-chat turn machinery."""

    MODEL = "maternion/minicpm5-heretic:2b"

    @classmethod
    def setUpClass(cls):
        from PySide6.QtWidgets import QApplication
        cls.app = QApplication.instance() or QApplication([])
        from forge.main import ForgeWindow
        cls.win = ForgeWindow()
        if cls.win.model_combo.findText(cls.MODEL) < 0:
            cls.win.model_combo.addItem(cls.MODEL)
        cls.win.model_combo.setCurrentText(cls.MODEL)

    @classmethod
    def tearDownClass(cls):
        cls.win.close()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.win.store = ConversationStore(root / "c.db")
        self.win.eventlog = EventLog(root / "log")
        self.win.worker = None
        self.win._fold_thread = None
        self.win._side_chat = None
        self.win.side_bar.setVisible(False)
        self.win.side_chat_btn.setEnabled(True)
        self.win.messages = [
            {"role": "user", "content": "first line\nsecond line"},
            {"role": "assistant", "content": "the agent's answer"},
            {"role": "user", "content": "a later ask"},
        ]
        self.win.input.clear()
        self.persist_calls = []
        self._real_persist = self.win.persist_conversation

        def spy(*args, **kwargs):
            self.persist_calls.append(1)

        self.win.persist_conversation = spy

    def tearDown(self):
        self.win.persist_conversation = self._real_persist
        self.win._side_chat = None
        self.win.messages = []
        self.win.input.clear()
        self.temp.cleanup()

    # ---------- Resend ----------

    def test_resend_loads_exact_text_and_sends_nothing(self):
        before = [dict(m) for m in self.win.messages]
        ok, _note = self.win.resend_message(0)
        self.assertTrue(ok)
        self.assertEqual(self.win.input.toPlainText(),
                         "first line\nsecond line")
        # The box now holds that text, so a second resend would
        # meet the draft guard — clear it, as the owner would by
        # sending, before the next load.
        self.win.input.clear()
        ok, _note = self.win.resend_message(2)
        self.assertTrue(ok)
        self.assertEqual(self.win.input.toPlainText(), "a later ask")
        # Nothing sent, nothing started, nothing rewritten.
        self.assertIsNone(self.win.worker)
        self.assertEqual(self.win.messages, before)
        self.assertEqual(self.persist_calls, [])

    def test_resend_refused_for_the_agents_message(self):
        ok, note = self.win.resend_message(1)
        self.assertFalse(ok)
        self.assertIn("your own", note)
        self.assertEqual(self.win.input.toPlainText(), "")

    def test_resend_never_overwrites_a_draft(self):
        self.win.input.setPlainText("keep me")
        ok, _note = self.win.resend_message(0)
        self.assertFalse(ok)
        self.assertEqual(self.win.input.toPlainText(), "keep me")

    def test_resend_refused_for_summary_and_missing_index(self):
        self.win.messages.append(
            {"role": "user", "summary": True, "content": "folded"})
        ok, _note = self.win.resend_message(3)
        self.assertFalse(ok)
        ok, _note = self.win.resend_message(99)
        self.assertFalse(ok)
        self.assertEqual(self.win.input.toPlainText(), "")

    # ---------- Reply ----------

    def test_reply_quotes_a_user_block_at_the_head_of_a_draft(self):
        self.win.input.setPlainText("my draft")
        ok, _note = self.win.reply_to_message(0)
        self.assertTrue(ok)
        quote = "> first line\n> second line"
        self.assertEqual(self.win.input.toPlainText(),
                         quote + "\n\nmy draft")
        # The cursor sits where the typing belongs: right after
        # the quote, ahead of the preserved draft.
        self.assertEqual(self.win.input.textCursor().position(),
                         len(quote) + 2)
        self.assertIsNone(self.win.worker)
        self.assertEqual(self.persist_calls, [])

    def test_reply_quotes_an_assistant_block_with_no_draft(self):
        ok, _note = self.win.reply_to_message(1)
        self.assertTrue(ok)
        expected = "> the agent's answer\n\n"
        self.assertEqual(self.win.input.toPlainText(), expected)
        self.assertEqual(self.win.input.textCursor().position(),
                         len(expected))

    def test_reply_refused_for_summary_and_missing_index(self):
        self.win.messages.append(
            {"role": "assistant", "summary": True, "content": "folded"})
        ok, _note = self.win.reply_to_message(3)
        self.assertFalse(ok)
        ok, _note = self.win.reply_to_message(99)
        self.assertFalse(ok)
        self.assertEqual(self.win.input.toPlainText(), "")

    def test_quote_block_cap_and_blank_lines(self):
        from forge.main import QUOTE_MAX_CHARS, quote_block_for
        self.assertEqual(quote_block_for("one\n\nthree"),
                         "> one\n>\n> three")
        quoted = quote_block_for("a" * 1000)
        self.assertTrue(quoted.startswith("> "))
        self.assertIn("…", quoted)
        self.assertLessEqual(len(quoted), QUOTE_MAX_CHARS + 4)

    # ---------- the rendered affordance ----------

    def test_bubbles_carry_the_anchors(self):
        self.win.render()
        html = self.win.chat.document().toHtml()
        self.assertIn("forge-resend:0", html)
        self.assertIn("forge-reply:0", html)
        self.assertIn("forge-reply:1", html)
        self.assertIn("forge-resend:2", html)
        # The agent's bubble offers Reply only — never Resend.
        self.assertNotIn("forge-resend:1", html)

    def test_anchor_clicks_dispatch(self):
        from PySide6.QtCore import QUrl
        self.win._on_chat_anchor(QUrl("forge-resend:2"))
        self.assertEqual(self.win.input.toPlainText(), "a later ask")
        self.win.input.clear()
        self.win._on_chat_anchor(QUrl("forge-reply:1"))
        self.assertTrue(self.win.input.toPlainText().startswith(
            "> the agent's answer"))

    # ---------- side chats ----------

    def test_side_chat_fork_acts_on_the_fork_and_restores(self):
        main = self.win.messages
        snapshot = [dict(m) for m in main]
        self.win.open_side_chat()
        self.assertIsNotNone(self.win._side_chat)
        self.assertIsNot(self.win.messages, main)
        ok, _note = self.win.resend_message(0)
        self.assertTrue(ok)
        self.assertEqual(self.win.input.toPlainText(),
                         "first line\nsecond line")
        self.win.close_side_chat()
        self.assertIs(self.win.messages, main)
        self.assertEqual(self.win.messages, snapshot)
        self.assertEqual(self.persist_calls, [])
